  ui_story_5036_50360101_50_dialog_content = "「한때 이 콜로서스는 북방 상공에 갑작스럽게 나타났고,\n어둠의 밑바닥에서 온 것으로 추정됐다.」",
  ui_story_5036_50360101_51_dialog_content = "「이는 한 익명의 과학자에 의해 사실로 인정되었고, 온 아스트라 대륙을 충격에 빠트렸다.」",
  ui_story_5036_50360101_52_dialog_content = "「소식통에 따르면 이 콜로서스에는 조종사 또는 승객은 물론,\n그 어떤 살상 무기도 존재하지 않는다고 한다.」",
  ui_story_5036_50360101_53_dialog_content = "「그러나 콜로서스의 외부 아래쪽에는 고대 기술로 만들어진\n거대한 스크린과 음향 장치가 설치돼 있다고 한다.」",
  ui_story_5036_50360101_54_dialog_content = "「현재 일루미나와 백야성에서는 이 표류하는 콜로서스를\n멈추기 위한 방법을 조사하고 있으며...」",
  ui_story_5036_50360101_55_dialog_content = "「이 콜로서스에 대한 후속 조치를 논의 중이라고 밝혔다.」",
