  ui_story_5036_50360101_126_dialog_content = "맨날 기사 하나도 제대로 못 적는다, 정규 채용은 꿈도 꾸지 말아라...\n이런 말만 하는 편집장님은 죽었다 깨도 상상도 못 하겠죠?",
  ui_story_5036_50360101_127_dialog_content = "움브라톤에서 아이테르에 대한 이야기를 취재하려는 그 많은 기자들 중에서,\n직접 콜로서스에 타 본 건 저밖에 없다는 걸요.",
  ui_story_5036_50360101_128_dialog_content = "이번 기회에 편집장님한테 누가 이 움브라톤에서 제일\n대단한 기자인지 똑똑히 보여 줄 거예요!",
  ui_story_5036_50360101_129_dialog_content = "저기... 브랜디?",
  ui_story_5036_50360101_130_dialog_content = "앗, 실수했네요! 인터뷰 대상 앞에서 속마음을 이렇게 많이 늘어놓으면 안 되는데 말이에요.",
  ui_story_5036_50360101_131_dialog_content = "크흠, 그래도 여러분 모두 걱정 놓으세요! 전 프로예요. 일할 때는 그 누구보다 차분해요.",
  ui_story_5036_50360101_132_dialog_content = "아니, 그 얘기가 아니야.",
  ui_story_5036_50360101_133_dialog_content = "혹시 움브라톤에 돌아갈 생각이면 내가 가는 길에 데려다줄게.",
  ui_story_5036_50360101_134_dialog_content = "아니에요, 괜찮아요. 아직 인터뷰가 안 끝났는걸요.",
  ui_story_5036_50360101_135_dialog_content = "저도 여러분과 함께 표류하는 콜로서스를 보러 갈 수 있도록 허락해 주세요.",
  ui_story_5036_50360101_136_dialog_content = "데려가 주신다면, 생생하고 눈물 없이는 못 읽을 정도로\n감동적인 특별 인터뷰 기사를 쓸게요!",
  ui_story_5036_50360101_137_dialog_content = "저 백야성과 일루미나 사람들이 아이테르의 소유인 콜로서스에\n손을 댈 엄두도 못 내게 말이에요!",
  ui_story_5036_50360101_138_dialog_content = "아... 그, 그렇게까지 할 필요가 있을까? 하하하.",
  ui_story_5036_50360101_139_dialog_content = "어라?",
  ui_story_5036_50360101_140_dialog_content = "브랜디 씨, 가방에서 포스터 같은 게 떨어졌어.",
  ui_story_5036_50360101_141_dialog_content = "아하하하, 정말이네요. 지금 바로 주울게요. 알려줘서 고마워요!",
  ui_story_5036_50360101_142_dialog_content = "음? 왠지 어디서 많이 본 사람이 포스터에 나와 있는데?",
  ui_story_5036_50360101_143_dialog_content = "어? 진짜네! 골디 씨 아니야?",
  ui_story_5036_50360101_144_dialog_content = "《비명의 집 탐험》이 상영되고 나서 「안데르센 비명의 집」에\n갔다가 입구에서 한 번 마주쳤었잖아.",
  ui_story_5036_50360101_145_dialog_content = "그 영화가 엄청 인기 있었는데도 다시 영화에 나올 생각은 없다고 했었는데.",
  ui_story_5036_50360101_146_dialog_content = "요즘은 뭘 하고 있으려나?",
  ui_story_5036_50360101_147_dialog_content = "그래도 어딜 가나 골디 씨 포스터가 붙어 있는 걸 보면,\n갈수록 움브라톤에서 인기가 많아지고 있는 것 같긴 해.",
  ui_story_5036_50360101_148_dialog_content = "제 건 거리에 붙어 있는 포스터들과는 달라요.",
  ui_story_5036_50360101_149_dialog_content = "이건 한정판 컬렉터 에디션이거든요!",
  ui_story_5036_50360101_150_dialog_content = "브랜디 씨도 골디 씨의 팬이었어?",
  ui_story_5036_50360101_151_dialog_content = "저, 전 「골디락스」까진 아니에요.",
  ui_story_5036_50360101_152_dialog_content = "「골디락스」?",
  ui_story_5036_50360101_153_dialog_content = "골디 씨의 팬들을 「골디락스」라고 해요. 근데 전 진짜 「골디락스」가 아니에요!",
  ui_story_5036_50360101_154_dialog_content = "그냥 저번에 《비명의 집 탐험》이 상영되고 다서 골디 씨를 인터뷰하러 갔었거든요.",
  ui_story_5036_50360101_155_dialog_content = "그때 골디 씨가 정말 친절하고 낙천적인 사람이라는 걸 느꼈어요.\n제 삶에 드리운 어두운 그림자들이 산뜻하게 날아가 버린 것 같았다고나 할까요.",
  ui_story_5036_50360101_156_dialog_content = "그날의 경험이 아니었다면 제가 《데일리 스쿠프 속보》에서 이렇게\n오랫동안 수습기자를 할 일도 없었을 거예요.",
  ui_story_5036_50360101_157_dialog_content = "그래서 그때부터 전 골디 씨가 신곡을 내면 조금 신경을 쓰는 것뿐이에요.",
  ui_story_5036_50360101_158_dialog_content = "아하하, 그게 바로 팬 아닌가?",
  ui_story_5036_50360101_159_dialog_content = "그, 그런가요?\n근데 요즘은 골디 씨가 폭력적인 사람이란 소문이 꽤 많이 들려오고 있어요.",
  ui_story_5036_50360101_160_dialog_content = "유명인들은 남모를 면모를 하나쯤은 가지고 있는 걸지도 모르겠지만요.",
  ui_story_5036_50360101_161_dialog_content = "전... 폭력을 쓰는 사람을 좋아하고 싶진 않아요.",
  ui_story_5036_50360101_162_dialog_content = "골디 씨가 폭력적이라고? 에이, 설마.",
  ui_story_5036_50360101_163_dialog_content = "요즘 도는 소문 중에는 진짜 말도 안 되는 얘기들도 많던데, 누가 지어낸 거 아닐까?",
  ui_story_5036_50360101_164_dialog_content = "PlayerName만 해도 《움브라톤 신문》에선 무슨 머리랑 팔이\n여러 개 달린 괴물인 것처럼 적어 놨는걸.",
  ui_story_5036_50360101_165_dialog_content = "맞아, 그거 때문에 내가 얼마나 피해를 보고 있는데!",
  ui_story_5036_50360101_166_dialog_content = "브랜디 넌 그런 사람들처럼 내 얘길 날조해서 적진 말아 줘.",
  ui_story_5036_50360101_167_dialog_content = "그건 걱정 마세요!",
  ui_story_5036_50360101_168_dialog_content = "저는 제가 직접 본 진실만 적으니까요.",
  ui_story_5036_50360101_169_dialog_content = "움브라톤의 기자들이 다 브랜디처럼 좋은 기자라면 참 좋을 텐데...",
  ui_story_5036_50360101_170_dialog_content = "좋은 기자요? 제, 제가요? 헤헤헤...",
  ui_story_5036_50360101_171_dialog_content = "<color=#e8d9bb>「경고! 경고! 전방에 미확인 비행체가 감지되었습니다.」</color>",
  ui_story_5036_50360101_172_dialog_content = "<color=#e8d9bb>「즉시 회피해야 합니다! 지시를 내려 주십시오.」</color>",
  ui_story_5036_50360101_173_dialog_content = "미확인... 비행체?",
  ui_story_5036_50360101_174_dialog_content = "생긴 건 스카이워커호랑 많이 다르지만...",
  ui_story_5036_50360101_175_dialog_content = "햇빛 아래서 반짝이는 재질도 그렇고, 구조 같은 건 누가 봐도 콜로서스잖아?!",
  ui_story_5036_50360101_176_dialog_content = "스크린이...",
  ui_story_5036_50360101_177_dialog_content = "아, 보인다! 저기 저 사각형 모양의 커다란 게 스크린 맞죠?",
  ui_story_5036_50360101_178_dialog_content = "역시 우리 시대의 산물이 아니라니까요!",
  ui_story_5036_50360101_179_dialog_content = "바로 저거예요! 저게 바로 신문 기사에 나온 표류하는 콜로서스예요!",
  ui_story_5036_50360101_180_dialog_content = "근데 왜 스카이워커호가 저 콜로서스의 이름을 식별하지 못하는 거지?",
  ui_story_5036_50360101_181_dialog_content = "그리고 저 콜로서스에선 조종사가 느껴지질 않아.",
  ui_story_5036_50360101_182_dialog_content = "저게 정말 백여 년 전에 사라졌다던 그 칸타토르호인 걸까?",
  ui_story_5036_50360101_183_dialog_content = "♪라랄라... 라라라...♪",
  ui_story_5036_50360101_184_dialog_content = "(누구지? 노래를 부르는 소리인가?)",
  ui_story_5036_50360101_185_dialog_content = "저기, 다들 들려?",
  ui_story_5036_50360101_186_dialog_content = "들리냐니? 뭐가?",
  ui_story_5036_50360101_187_dialog_content = "♪우우우우...♪",
  ui_story_5036_50360101_188_dialog_content = "노랫소리 말이야... 누가 노래를 부르고 있어.",
  ui_story_5036_50360101_189_dialog_content = "뭐? 노랫소리는 안 들리는데?",
  ui_story_5036_50360101_190_dialog_content = "♪라랄라라...♪",
  ui_story_5036_50360101_191_dialog_content = "(당신이... 「칸타토르호」의 조종사야?)",
  ui_story_5036_50360101_192_dialog_content = "♪우우우우...♪",
  ui_story_5036_50360101_193_dialog_content = "(어째서 자기 콜로서스를 버린 거야?)",
  ui_story_5036_50360101_194_dialog_content = "♪라라... 라라라라...♪",
  ui_story_5036_50360101_195_dialog_content = "(대체 왜...)",
  ui_story_5036_50360101_196_dialog_content = "<color=#e8d9bb>「경고! 경고! 전방에 미확인 비행체가 감지되었습니다.」</color>",
  ui_story_5036_50360101_197_dialog_content = "<color=#e8d9bb>「충돌 위험에서 벗어나기 위해, 콜로서스는 3초 후 자동으로 항로를 변경합니다.」</color>",
  ui_story_5036_50360101_198_dialog_content = "<color=#e8d9bb>「3...」</color>",
  ui_story_5036_50360101_199_dialog_content = "<color=#e8d9bb>「2...」</color>",
  ui_story_5036_50360101_200_dialog_content = "노선 변경을 중지해.",
  ui_story_5036_50360101_201_dialog_content = "그리고 「미확인 비행체」랑 같은 속도로, 같은 방향을 향해 이동해.",
  ui_story_5036_50360101_202_dialog_content = "실시간으로 계속 조정해 줘.",
  ui_story_5036_50360201_1_dialog_content = "<color=#e8d9bb>「경고! 경고! 미확인 비행체에 접근 중입니다.」</color>",
  ui_story_5036_50360201_2_dialog_content = "콜로서스가 엄청난 기세로 흔들리고 있어요! 설마 표류하는 콜로서스와 충돌한 건가요?!",
  ui_story_5036_50360201_3_dialog_content = "속도를 줄이고 있는 것뿐이니까, 그렇게 겁먹을 필요 없어.",
  ui_story_5036_50360201_4_dialog_content = "앗? 아쉽네요! 두 콜로서스가 충돌하는 순간을 찍을 수 있을지도 모른다고 기대했거든요.",
  ui_story_5036_50360201_5_dialog_content = "그 놀라운 장면을 촬영했다면, 모든 신문의 1면 톱기사를 장식했을 게 분명해요!",
  ui_story_5036_50360201_6_dialog_content = "정말 그런 일이 벌어진다면 당신이 사진 같은 걸 촬영할 틈도 없을걸.",
  ui_story_5036_50360201_7_dialog_content = "그냥 어디까지나 가정만 해 본 거예요!",
  ui_story_5036_50360201_8_dialog_content = "그나저나 브랜디 씨 카메라는 엄청 특별하게 생겼네.",
  ui_story_5036_50360201_9_dialog_content = "보는 눈이 있으시네요, 바이스 씨!",
  ui_story_5036_50360201_10_dialog_content = "카메라는 고급 장비라 누구나 가질 수 있는 게 아니에요.",
  ui_story_5036_50360201_11_dialog_content = "그리고 전 더 놀라운 촬영 효과를 얻기 위해서 항상 카메라의 부품도 교체해 주고 있거든요.",
  ui_story_5036_50360201_12_dialog_content = "신문사에 수습기자로 들어갈 수 있었던 것도 이 카메라 덕이 커요.",
  ui_story_5036_50360201_13_dialog_content = "우와! 그럼 혹시 실물보다 더 예뻐 보이게 찍을 수도 있는 거야?",
  ui_story_5036_50360201_14_dialog_content = "그건 제가 확답을 드릴 수 없지만, 이 카메라는 가장 사실에 가까운 현장을\n촬영할 수 있다고 보증할 수 있어요!",
  ui_story_5036_50360201_15_dialog_content = "<color=#e8d9bb>「조정에 성공했습니다. 이제 비행 속도와 방향이 미확인 비행체와 일치합니다.」</color>",
  ui_story_5036_50360201_16_dialog_content = "그럼 가자.",
  ui_story_5036_50360201_17_dialog_content = "어라? 표류하는 콜로서스하곤 아직 거리가 꽤 되지 않나요?",
  ui_story_5036_50360201_18_dialog_content = "거기까지 어떻게 이동해야 하죠?!",
  ui_story_5036_50360201_19_dialog_content = "당연히 날아서 가야지.",
  ui_story_5036_50360201_20_dialog_content = "<anim type=Shake>꺄아아!</anim>",
  ui_story_5036_50360201_21_dialog_content = "저, 정말 날아가고 있어요!",
  ui_story_5036_50360201_22_dialog_content = "비공정엔 처음 타 보는데, 굉장히 스릴 넘치네요!",
  ui_story_5036_50360201_23_dialog_content = "게다가 이제부터 표류하는 콜로서스에 착륙할 거잖아요?",
  ui_story_5036_50360201_24_dialog_content = "세상에! 수많은 기자들이 꿈에서도 바라던 최초 현장 방문이네요!",
  ui_story_5036_50360201_25_dialog_content = "앗! 그렇지만 프로 기자라면 아무리 흥분되는 상황에서도\n자신의 인터뷰 대상을 잊어버리면 안 되겠죠?",
  ui_story_5036_50360201_26_dialog_content = "그러니까 지금 PlayerName 씨는 어떤 심경인지 물어봐야겠네요!",
  ui_story_5036_50360201_27_dialog_content = "PlayerName 씨, 지금 심경이...?",
  ui_story_5036_50360201_28_dialog_content = "......",
  ui_story_5036_50360201_29_dialog_content = "어라? 표정이 안 좋으시네요?\n혹시 일루미나와 백야성을 향한 소리 없는 항의인가요?",
  ui_story_5036_50360201_30_dialog_content = "다크매터야! 갑자기 다크매터가 잔뜩 느껴져!",
  ui_story_5036_50360201_31_dialog_content = "으앗?! 설마 저희가 장소를 잘못 찾아온 건가요?",
  ui_story_5036_50360201_32_dialog_content = "그럴 리 없어. 이 좌표는 이리돈 대심판관이 내게 직접 알려준 거야. 좌표는 정확해.",
  ui_story_5036_50360201_33_dialog_content = "그런 건 나중에 생각하고, 일단 눈앞의 문제부터 해결하자!",
  ui_story_5036_50360201_34_dialog_content = "<size=45>크오오!</size>",
  ui_story_5036_50360202_1_dialog_content = "♪라랄라... 라라라...♪",
  ui_story_5036_50360202_2_dialog_content = "(또 이 노랫소리가 들리잖아?)",
  ui_story_5036_50360202_3_dialog_content = "(이런 멜로디는 들어 본 적이 없는데, 왠지 모르게 익숙하네.)",
  ui_story_5036_50360202_4_dialog_content = "(마치 태어나면서부터 알고 있던 건데, 이제야 기억난 것 같은 느낌이야.)",
  ui_story_5036_50360202_5_dialog_content = "♪우우우우...♪",
  ui_story_5036_50360202_6_dialog_content = "♪라랄라라...♪",
  ui_story_5036_50360202_7_dialog_content = "너, 넌?",
  ui_story_5036_50360202_8_dialog_content = "...일개 아이테르 주제에 감히 이 마티외 심판관님의 이름을 잊어버린 거냐?",
  ui_story_5036_50360202_9_dialog_content = "백야성엔 감히 이렇게 내 존재를 무시하는 자는 없단 말이다!\n치욕, 그야말로 치욕이다!",
  ui_story_5036_50360202_10_dialog_content = "뢰베, 내 말이 맞... 으음? 뢰베, 뭐 하냐?",
  ui_story_5036_50360202_11_dialog_content = "카렌 전하, 괜찮으십니까?",
  ui_story_5036_50360202_12_dialog_content = "난 괜찮아. 이 정도 암귀는 아무것도 아니야.",
  ui_story_5036_50360202_13_dialog_content = "두 사람 모두 서둘러 와 줘서 고마워. 덕분에 암귀를 빨리 처리할 수 있었어.",
  ui_story_5036_50360202_14_dialog_content = "쳇, 이건 또 몰랐군.",
  ui_story_5036_50360202_15_dialog_content = "뢰베, 너 언제 남의 공을 가로채는 법을 배운 거냐?",
  ui_story_5036_50360202_16_dialog_content = "조사는 아직 안 끝났는데.",
  ui_story_5036_50360202_17_dialog_content = "벌써 집에 가고 싶은 사람이 있네.",
  ui_story_5036_50360202_18_dialog_content = "또냐!",
  ui_story_5036_50360202_19_dialog_content = "잘은 모르겠지만, 언제부터인가 뢰베가 동료는 제쳐놓고\n이렇게 알랑방귀나 뀌는 짓을 배웠더군요.",
  ui_story_5036_50360202_20_dialog_content = "카렌 전하, 그러니 뢰베의 저런 헛소리를 귀담아들으실 필요는 없습니다.",
  ui_story_5036_50360202_21_dialog_content = "며칠 동안 저는 아주 합당하고, 질서정연하게 백야성 조사단을 이끌고\n표류하는 콜로서스의 조사 작업을 진행해 왔습니다.",
  ui_story_5036_50360202_22_dialog_content = "그러니 전하께선 이제 곧 백야성에 있는 푹신한 백조 깃털 방석에 앉아\n제가 작성한 조사 보고서를 받아 보실 수 있을 겁니다.",
  ui_story_5036_50360202_23_dialog_content = "어? 너 계속 우리 바니한테 달라붙어 있던 게 공략 베껴서 클리어하려고 그랬던 거였어?",
  ui_story_5036_50360202_24_dialog_content = "연구원장님, 안심하세요.",
  ui_story_5036_50360202_25_dialog_content = "조사 자료 관리에 각별히 신경 쓸 테니까요.",
  ui_story_5036_50360202_26_dialog_content = "계획이 들통나서 못 쓰게 돼 버렸네.",
  ui_story_5036_50360202_27_dialog_content = "조사 데이터를 교차 검증하려고 했던 거야! 잘 알지도 못하면서 끼어들지 마!",
  ui_story_5036_50360202_28_dialog_content = "그로누 연구원장님, 시오반 선생님!",
  ui_story_5036_50360202_29_dialog_content = "두 분이 이 표류하는 콜로서스에서 임무를 수행하고 계셨던 거예요?",
  ui_story_5036_50360202_30_dialog_content = "어디 보자, 바이스, 그새 좀 마른 거 아니야?",
  ui_story_5036_50360202_31_dialog_content = "어? 그런가요?",
  ui_story_5036_50360202_32_dialog_content = "PlayerName, 자꾸 바이스를 이렇게 푸대접하면 내가 뺏어가 버릴 거라구.",
  ui_story_5036_50360202_33_dialog_content = "푸, 푸대접 같은 거 한 적 없어...",
  ui_story_5036_50360202_34_dialog_content = "그래? 에헤헷~",
  ui_story_5036_50360202_35_dialog_content = "그나저나 왜 이렇게 늦게 온 거야?",
  ui_story_5036_50360202_36_dialog_content = "난 또 PlayerName 네가 이 콜로서스 조사를 포기한 줄 알았잖아.",
  ui_story_5036_50360202_37_dialog_content = "그렇지만 제가 알기론...",
  ui_story_5036_50360202_38_dialog_content = "백야성과 일루미나 연방 모두 방금 전까지도 PlayerName 씨에게\n표류하는 콜로서스에 대한 공식적인 통지를 하지 않았을 텐데요?",
  ui_story_5036_50360202_39_dialog_content = "어라? 처음 보는 아가씨도 있네?",
  ui_story_5036_50360202_40_dialog_content = "안녕하세요, 저는 《데일리 스쿠프 속보》의 수습기자 브랜디라고 해요.",
  ui_story_5036_50360202_41_dialog_content = "지금은 PlayerName 씨를 밀착 취재하고 있어요.\n그러니 방금 전 질문에 대답해 주셨으면 좋겠네요.",
  ui_story_5036_50360202_42_dialog_content = "어째서 일루미나와 백야성 모두 PlayerName 씨에게\n표류하는 콜로서스에 대해 알리지 않은 건가요?",
  ui_story_5036_50360202_43_dialog_content = "양측 모두 아이테르 모르게 콜로서스를 나눠 가지려고 한다는 소문이 사실인가요?",
  ui_story_5036_50360202_44_dialog_content = "기자 아가씨, 내가 뭐 하나 물어볼게.\n우리 일루미나가 PlayerName한테 이 사실을 알려야 할 의무가 있어?",
  ui_story_5036_50360202_45_dialog_content = "그로누 선배?",
  ui_story_5036_50360202_46_dialog_content = "이런, 다들 놀랐어?",
  ui_story_5036_50360202_47_dialog_content = "후후후, 제대로 대답해 주면 되잖아.",
  ui_story_5036_50360202_48_dialog_content = "우린 표류하는 콜로서스에 대한 소식을 알게 된 즉시\n대인원으로 구성된 조사단을 파견했어.",
  ui_story_5036_50360202_49_dialog_content = "근처 공역은 물론이고, 지상에도 대규모의 지원 부대를 배치했고 말이야.",
  ui_story_5036_50360202_50_dialog_content = "하지만 우리의 최우선 목표는 네가 생각하는 것처럼\n콜로서스를 우리 걸로 만들려는 게 아니야.",
  ui_story_5036_50360202_51_dialog_content = "어둠의 밑바닥에서 표류해 온 이 콜로서스가 우리 일루미나에게\n어떤 위협이 될지 가늠하는 게 목적이라구.",
  ui_story_5036_50360202_52_dialog_content = "이게 어둠의 밑바닥에서 온 이상, 이 안에 어떤 <color=#FFB400>「승객」</color>이 타고 있을진 아무도 모르잖아.",
  ui_story_5036_50360202_53_dialog_content = "그 점에 대해선 백야성도 같은 견해를 가지고 있다.",
  ui_story_5036_50360202_54_dialog_content = "하지만 대체 왜 자꾸 날 이런 땀내 나는 일에 파견하는 건지 모르겠군.",
  ui_story_5036_50360202_55_dialog_content = "우린 표류하는 콜로서스가 나타났단 사실을 숨긴 적 없어.",
  ui_story_5036_50360202_56_dialog_content = "PlayerName 네가 왜 표류하는 콜로서스가 나타났단 걸\n모르고 있었는진 나도 궁금한걸.",
  ui_story_5036_50360202_57_dialog_content = "그, 그건 좀 사정이 있어.",
  ui_story_5036_50360202_58_dialog_content = "헤에?",
  ui_story_5036_50360202_59_dialog_content = "그래도 괜찮아. 우리가 그렇게 늦진 않은 것 같으니까.",
  ui_story_5036_50360202_60_dialog_content = "난 아직도 궁금한 게 있어. 이 콜로서스의 입구에 암귀가 나타난 이유가 뭐지?",
  ui_story_5036_50360202_61_dialog_content = "카렌 전하, 오시자마자 깜짝 놀라게 만들어 정말 죄송합니다.",
  ui_story_5036_50360202_62_dialog_content = "외람되오나 이 콜로서스는 카렌 전하께서 오래 머무실 곳이 못 됩니다.",
  ui_story_5036_50360202_63_dialog_content = "먼지투성이 거미줄이 가득할 뿐만 아니라, 더러운 암귀들이 수없이 잠복해 있으니 말이지요.",
  ui_story_5036_50360202_64_dialog_content = "그래도 안전에 대해 걱정하진 않으셔도 됩니다.",
  ui_story_5036_50360202_65_dialog_content = "며칠간 수고한 끝에 저흰 대부분의 암귀를 콜로서스 꼬리 쪽의\n<color=#FFB400>봉쇄 구역</color>으로 몰아냈습니다.",
  ui_story_5036_50360202_66_dialog_content = "그러니 안심하셔도 됩니다!",
  ui_story_5036_50360202_67_dialog_content = "이미 사람을 보내 암귀 처리에 박차를 가하고 있습니다. 제가 장담하겠습니다!",
  ui_story_5036_50360202_68_dialog_content = "저 지저분한 놈들은 두 번 다시 카렌 전하를 번거롭게 만들지 않을 겁니다.",
  ui_story_5036_50360202_69_dialog_content = "수고했어, 마티외 심판관.",
  ui_story_5036_50360202_70_dialog_content = "제 영광입니다.",
  ui_story_5036_50360202_71_dialog_content = "그럼 지금 이 콜로서스는 비교적 안전한 상태인 거네?",
  ui_story_5036_50360202_72_dialog_content = "<color=#FFB400>봉쇄 구역</color>이란 하드 스테이지에 들어가지만 않으면\n다들 라이프가 줄어들 일은 없을 거야~",
  ui_story_5036_50360202_73_dialog_content = "그로누, 이 콜로서스의...",
  ui_story_5036_50360202_74_option_content = "제어 시스템에 대해 알고 싶어.",
  ui_story_5036_50360202_75_dialog_content = "어쩌면 내가 이 콜로서스를 착륙시킬 수 있을지도 모르니까.",
  ui_story_5036_50360202_76_dialog_content = "나도 같은 생각이었어. 그래서 이 콜로서스의 함교를 자세히 조사해 봤어.",
  ui_story_5036_50360202_77_dialog_content = "근데 제어 시스템이랑 항법 시스템은 물론이고, 심지어 의식 모듈까지 몽땅 망가져 있더라구.",
  ui_story_5036_50360202_78_dialog_content = "그러니까 아무리 너라고 해도 이 콜로서스를 제어하진 못할 거야.",
  ui_story_5036_50360202_79_dialog_content = "어떻게 그럴 수가 있지? 그럼...",
  ui_story_5036_50360202_80_option_content = "동력 코어에 대해 알고 싶어.",
  ui_story_5036_50360202_81_dialog_content = "콜로서스가 아직 표류 중인 걸 보면 동력 코어는 아직 멀쩡한 거지?",
  ui_story_5036_50360202_82_dialog_content = "동력 코어가 멀쩡하다고 한다면 틀린 말은 아냐.",
  ui_story_5036_50360202_83_dialog_content = "이 콜로서스에 에너지 공급을 해서 비행 상태를 유지하고 있는 거니까.",
  ui_story_5036_50360202_84_dialog_content = "동력 코어가 안 멀쩡하냐고 한다면 그것도 맞아.",
  ui_story_5036_50360202_85_dialog_content = "왜냐면 암귀한테 공격을 받은 적이 있거든.",
  ui_story_5036_50360202_86_dialog_content = "갑자기 에너지가 끊겨 버리진 않겠지만,\n그래도 에너지 전환 효율은 어느 정도 영향을 받을 거야.",
  ui_story_5036_50360202_87_dialog_content = "그럼... 고칠 순 있는 거야?",
  ui_story_5036_50360202_88_dialog_content = "동력 코어를 수리하는 건 간단한 작업이 아니야.",
  ui_story_5036_50360202_89_dialog_content = "일단 이 콜로서스의 작동을 멈춘 다음에 동력 코어의 전원을 꺼야 해.",
  ui_story_5036_50360202_90_dialog_content = "그래야 충분히 시간을 들여서 조사랑 수리를 진행할 수 있거든.",
  ui_story_5036_50360202_91_dialog_content = "근데 아직까지 이 콜로서스를 멈출 방법은 못 찾았어.",
  ui_story_5036_50360202_92_dialog_content = "어떻게 그럴 수가 있지? 그럼...",
  ui_story_5036_50360202_93_option_content = "스크린과 음향 장치에 대해 알고 싶어.",
  ui_story_5036_50360202_94_dialog_content = "콜로서스의 외부에 스크린이랑 음향 장치로 보이는 게 달려 있더라고.",
  ui_story_5036_50360202_95_dialog_content = "후훗, 그건 확실히 스크린이랑 음향 장치가 맞아~",
  ui_story_5036_50360202_96_dialog_content = "게다가 현재의 기술 수준을 한참 뛰어넘는 오버 테크놀로지 설비야!",
  ui_story_5036_50360202_97_dialog_content = "엄청 노후되긴 했는데, 그래도 보존 상태는 거의 완벽에 가까워.",
  ui_story_5036_50360202_98_dialog_content = "시오반이 수고해 준 덕분에 우린 그 스크린이랑 음향 장치들을 켤 수 있게 됐어~",
  ui_story_5036_50360202_99_dialog_content = "그렇게 커다란 스크린으로 영화를 재생하면 엄청 박진감 있겠는데?",
  ui_story_5036_50360202_100_dialog_content = "그리고...",
  ui_story_5036_50360202_100X1_dialog_content = "또 무슨 문제 있어?",
  ui_story_5036_50360202_100X2_option_content = "있어.",
  ui_story_5036_50360202_100X3_option_content = "이젠 없어.",
  ui_story_5036_50360202_101_dialog_content = "참...",
  ui_story_5036_50360202_102_dialog_content = "혹시 이 콜로서스 안에서 아이테르나, 아이테르가 남긴 물건 같은 건 못 봤어?",
  ui_story_5036_50360202_103_dialog_content = "음, 지금까진 없었어.",
  ui_story_5036_50360202_104_dialog_content = "아, 맞다, 그렇지. 그러고 보니까...",
  ui_story_5036_50360202_105_dialog_content = "내 귀여운 조수 바니가 우릴 위해 이 콜로서스에 대한 기록이\n남아 있는 역사 자료들을 찾아 줬어.",
  ui_story_5036_50360202_106_dialog_content = "겉모습으로 보나, 규모로 보나, 이 콜로서스가 바로 백여 년 전에\n아이테르가 연락이 끊겼다고 보고했던 그...",
  ui_story_5036_50360202_107_dialog_content = "<color=#FFB400>칸타토르호</color>란 거지?",
  ui_story_5036_50360202_108_dialog_content = "뭐야? 벌써 알고 있었어?",
  ui_story_5036_50360202_109_dialog_content = "아쉽지만 이름을 안다고 해서 별 도움이 되진 않을 거다..",
  ui_story_5036_50360202_110_dialog_content = "사악한 기술이 가득 실린 콜로서스는 누가 뭐래도 파괴해야 하니까.",
  ui_story_5036_50360202_111_dialog_content = "파괴한다고? 누가 칸타토르호를 파괴한다는 거야?",
  ui_story_5036_50360202_112_dialog_content = "오해하지 마라. 나 혼자서 내린 결정이 아니니까.",
  ui_story_5036_50360202_113_dialog_content = "하지만 우리 사람들 대부분이 찬성한 최고의 방법이지.",
  ui_story_5036_50360202_114_dialog_content = "저기, 너 지금 엄청난 빌런처럼 보이거든...",
  ui_story_5036_50360202_115_dialog_content = "그리고 그렇게 결론짓긴 너무 이른 것 같은데? 난 아직 동의 안 했어.",
  ui_story_5036_50360202_116_dialog_content = "후후, 어차피 결국엔 동의하기 싫어도 동의하게 될 거다.",
  ui_story_5036_50360202_117_dialog_content = "마티외 심판관, 뭐가 어떻게 된 거지? 자세히 설명해 줘.",
  ui_story_5036_50360202_118_dialog_content = "카렌 전하께서도 방금 들으셨겠지요.",
  ui_story_5036_50360202_119_dialog_content = "이 콜로서스에는 아무런 이용 가치가 없습니다.\n되려 제어할 수도 없는 암귀들이나 잔뜩 들어 차 있죠.",
  ui_story_5036_50360202_120_dialog_content = "만약 이 콜로서스가 계속 표류하게 둔다면,\n아스트라 대륙에 거주하고 있는 모든 이들에게 분명 위협이 될 겁니다.",
  ui_story_5036_50360202_121_dialog_content = "그리고...",
  ui_story_5036_50360202_122_dialog_content = "만에 하나 이 콜로서스가 표류하다가 백야성과 충돌이라도 하면 어쩌시렵니까?",
  ui_story_5036_50360202_123_dialog_content = "이 콜로서스를 파괴하는 것은 바로 우리 백야성을 지키는 일입니다.",
  ui_story_5036_50360202_124_dialog_content = "성주님께서 이 자리에 계셨어도 아마 저와 같은 판단을 내리셨을 겁니다.\n그건 저보다도 카렌 전하께서 더 잘 알고 계시겠지요.",
  ui_story_5036_50360202_125_dialog_content = "우리 일루미나 수색팀은 지금도 황야에서 콜로서스 유적을 찾기 위해 힘쓰고 있어요.",
  ui_story_5036_50360202_126_dialog_content = "이렇게 아직 작동하고 있는 콜로서스를 겨우 찾았는데, 이걸 정말... 파괴할 생각인가요?",
  ui_story_5036_50360202_127_dialog_content = "바이스, 저 빌런이 하는 헛소리는 무시해 버려.",
  ui_story_5036_50360202_128_dialog_content = "벌써 다 계산해 봤거든. 이 콜로서스의 비행경로는 절대로 백야성이랑 충돌할 일 없어.",
  ui_story_5036_50360202_129_dialog_content = "이 콜로서스에 있는 암귀들도, 우리가 계속 처리하다 보면 언젠가는 다 없어질 거야.",
  ui_story_5036_50360202_130_dialog_content = "그리고 빌런 말처럼 이 칸타토르호에 아무런 가치가 없는 것도 아냐.",
  ui_story_5036_50360202_131_dialog_content = "모든 부분에 엄청난 과학적 연구 가치가 잠들어 있다구.",
  ui_story_5036_50360202_132_dialog_content = "파괴된 부분이 많아서 고치려면 애를 좀 먹긴 하겠지만...",
  ui_story_5036_50360202_133_dialog_content = "그래도 난 이 콜로서스에 그 정도 고생쯤은 얼마든지 해 줄 가치가 있다고 생각해!",
  ui_story_5036_50360202_134_dialog_content = "하지만 당신도 알고 있겠지. 어차피 당신들 입장에서도...",
  ui_story_5036_50360202_135_dialog_content = "필요한 부분만 따로 떼어 가서 연구를 진행하는 편이 훨씬 더 효율적인 게 아닌가?",
  ui_story_5036_50360202_136_dialog_content = "어째서 제어할 수도 없는 이 커다란 녀석이 하늘에서\n멋대로 날아다니게 놔두려는 거지?",
  ui_story_5036_50360202_137_dialog_content = "연구 샘플은 온전해야 더 가치가 있으니까!",
  ui_story_5036_50360202_138_dialog_content = "그렇다면 지금 당장 이 콜로서스가 수리를 통해 원래 상태로\n돌아갈 가능성이 있다는 증거를 제시할 수 있나?",
  ui_story_5036_50360202_139_dialog_content = "그, 그건 시간이 좀 더 필요해!",
  ui_story_5036_50360202_140_dialog_content = "시간은 사람을 기다려 주지 않는다.",
  ui_story_5036_50360202_141_dialog_content = "기다림이 길어질수록, 치러야 하는 대가만 점점 커질 뿐이지.",
  ui_story_5036_50360202_142_dialog_content = "콜로서스를 격추시켜 임무를 끝내고, 출장을 마무리한 다음,\n각자 집으로 돌아가면 좋은 게 아닌가?",
  ui_story_5036_50360202_143_dialog_content = "넌 그냥 집에 가고 싶었던 거구나.",
  ui_story_5036_50360202_144_dialog_content = "카렌 전하, 이건 제 협상 전략일 뿐이니 오해하지 말아 주셨으면 좋겠습니다만...",
  ui_story_5036_50360202_145_dialog_content = "칸타토르호는 우리 아이테르 일족의 소유야. 그 누구도 격추하게 두지 않아!",
  ui_story_5036_50360202_146_dialog_content = "나도 암귀 처치를 도울 수 있어!",
  ui_story_5036_50360202_147_dialog_content = "그리고 모두한테 이 칸타토르호의 가치를 증명해 보이겠어!",
  ui_story_5036_50360202_148_dialog_content = "그래, 나도 도울게.",
  ui_story_5036_50360202_149_dialog_content = "카렌 전하? 그...",
  ui_story_5036_50360202_150_dialog_content = "흐음~ 백야성의 공주님도 눈앞에서 칸타토르호가 격추되는 건 아쉬운 모양인걸.",
  ui_story_5036_50360202_151_dialog_content = "달링~ 이 세상에 「아쉬운 일」이 그렇게 많을 리가 없잖아요?",
  ui_story_5036_50360202_152_dialog_content = "있다고 한다면... 돈을 충분히 지불하지 못해서 그런 거겠죠.",
  ui_story_5036_50360202_153_dialog_content = "어라?",
  ui_story_5036_50360202_154_dialog_content = "여자애가 나한테 친근하게 구는 건 괜찮은데, 그래도 조금 닭살 돋았어.",
  ui_story_5036_50360202_155_dialog_content = "샤엘 씨?",
  ui_story_5036_50360202_156_dialog_content = "누군가 했더니 우리 단골, PlayerName 너였구나?",
  ui_story_5036_50360202_157_dialog_content = "우리 공중상회에 안 온 지도 꽤 됐지?",
  ui_story_5036_50360202_158_dialog_content = "그렇다고 상품을 홍보하러 이런 곳까지 절 찾아올 필요는 없지 않아요?",
  ui_story_5036_50360202_159_dialog_content = "아하하, 우리 귀여운 PlayerName, 갈수록... 재미있어지는구나.",
  ui_story_5036_50360202_160_dialog_content = "어떤 의미에선 네 말이 맞을 수도 있겠지만.",
  ui_story_5036_50360202_161_dialog_content = "이번엔 좀 색다른 걸 홍보하려고 해~",
  ui_story_5036_50360202_162_dialog_content = "달링, 이리 와!",
  ui_story_5036_50360202_163_dialog_content = "?",
  ui_story_5036_50360202_164_dialog_content = "♪실패도, 상처받는 것도 두렵지 않아.",
  ui_story_5036_50360202_165_dialog_content = "♪견뎌 내면 좋은 날이 올 테니까.",
  ui_story_5036_50360202_166_dialog_content = "♪그러니 가슴 아파하고, 풀 죽을 필요 없어.",
  ui_story_5036_50360202_167_dialog_content = "♪모두 골디를 바라봐 줘!",
  ui_story_5036_50360202_168_dialog_content = "콜로서스의 여러분, 안녕! 앞으로 잘 부탁해~",
  ui_story_5036_50360202_169_dialog_content = "고, 골디?",
  ui_story_5036_50360202_170_dialog_content = "와~ PlayerName 씨, 오랜만이야. 그동안 잘 지냈지?",
  ui_story_5036_50360202_171_dialog_content = "어라?",
  ui_story_5036_50360202_172_dialog_content = "골디 씨가 왜 여기 계시는 거죠?",
  ui_story_5036_50360202_173_dialog_content = "다들 서로 아는 사이면 얘기가 빠르겠네.",
  ui_story_5036_50360202_174_dialog_content = "샤엘 씨, 절 너무 과대평가하시는 것 같네요.",
  ui_story_5036_50360202_175_dialog_content = "전 대스타한테 공연을 의뢰할 만큼의 돈은 없거든요.",
  ui_story_5036_50360202_176_dialog_content = "내가 비싼 돈 주고 비공정까지 빌려서 지금 한창 인기인\n아이돌 가수를 데리고 여기까지 찾아온 건...",
  ui_story_5036_50360202_177_dialog_content = "너 한 사람과 거래를 하기 위해서가 아니야.",
  ui_story_5036_50360202_178_dialog_content = "이런 얘길 꺼내면, 다들 깜짝 놀랄 수도 있지만... 헤헷.",
  ui_story_5036_50360202_179_dialog_content = "난 이 표류하는 콜로서스에서 아스트라 대륙을 뒤흔들 유일무이한 콘서트를 열고 싶어.",
  ui_story_5036_50360202_180_dialog_content = "이 콜로서스가 골드리버를 따라 이동해 움브라톤 상공에 도착하면...",
  ui_story_5036_50360202_181_dialog_content = "내가 콜로서스 위에 서서 모두에게 내 노래와 축복을 들려주는 거지!",
  ui_story_5036_50360202_182_dialog_content = "그럼 움브라톤 전체랑 백야성까지 이 콜로서스에 달린 스크린으로\n내 공연을 감상할 수 있을 거야~",
  ui_story_5036_50360202_183_dialog_content = "하, 서민은 역시나 서민이군. 꿈도 아주 허무맹랑하게 꾸시는군그래.",
  ui_story_5036_50360202_184_dialog_content = "케이크 장식을 입고 다니는 아가씨,\n설마 말로만 노래를 잘한다고 자랑하려는 건 아니겠지?",
  ui_story_5036_50360202_185_dialog_content = "「아이돌」은 또 어디서 튀어나온 저질 단어야? 영문을 모르겠군.",
  ui_story_5036_50360202_186_dialog_content = "으휴~ 그러니까 백야성 사람들이 맨날 조그마한 섬에 틀어박혀\n있는 것도 좋은 게 아니라니까.",
  ui_story_5036_50360202_187_dialog_content = "「아이돌」이 뭔지도 모르면서 제멋대로 구시렁거리긴.",
  ui_story_5036_50360202_188_dialog_content = "너... 지금 내가 무식하다고 놀린 거냐?",
  ui_story_5036_50360202_189_dialog_content = "팩트로 두들겨 맞으니까, 정신을 못 차리네.",
  ui_story_5036_50360202_190_dialog_content = "시오반, 여기 이 심판관한테 「아이돌」에 대한 연구 보고를 좀 공유해 줄래?",
  ui_story_5036_50360202_191_dialog_content = "네, 연구원장님.",
  ui_story_5036_50360202_192_dialog_content = "「아이돌」은 움브라톤과 레디젤 사막 지역에 새롭게 대두되고 있는 직업이에요.",
  ui_story_5036_50360202_193_dialog_content = "노래, 춤, 연기, MC 등 다양한 엔터테인먼트 사업에 종사하고 있죠.",
  ui_story_5036_50360202_194_dialog_content = "전통적인 가수, 안무가, 배우와 비교했을 때, 아이돌은 공연을 관람해 주는 팬과\n더 가까워지고 싶어 하는 경향이 있어요.",
  ui_story_5036_50360202_195_dialog_content = "또한 아이돌은 개개인의 매력으로 팬들에게 사랑을 받고,\n팬들에게 긍정적인 에너지를 선사하죠.",
  ui_story_5036_50360202_196_dialog_content = "아하하, 얼추 그렇다고 할 수 있겠네.",
  ui_story_5036_50360202_197_dialog_content = "우리 골디가 여러 가지를 다 잘하는 건 맞아.\n근데 지금은 음악 사업 쪽에 집중하고 있어.",
  ui_story_5036_50360202_198_dialog_content = "그런 것이로군...",
  ui_story_5036_50360202_199_dialog_content = "아, 아니지, 난 그런 서민적인 것들엔 관심 없다고!",
  ui_story_5036_50360202_200_dialog_content = "내가 지금까지 잘해올 수 있던 건, 바로 꾸준히 날 격려해 준\n내 팬클럽 「골디락스」 덕분이야.",
  ui_story_5036_50360202_201_dialog_content = "그래서 난 우리 「골디락스」들한테 자신들이 응원하는 아이돌이\n가장 큰 무대에서 모두를 위해 공연하는 모습을 보여주고 싶어!",
  ui_story_5036_50360202_202_dialog_content = "헤헷, 난 아이돌이 콘서트를 한다는 거에 불만은 없어...",
  ui_story_5036_50360202_203_dialog_content = "근데 표류하는 콜로서스에서 공연을 하는 건 좀 엉뚱한 발상 아냐?",
  ui_story_5036_50360202_204_dialog_content = "연구원장 달링, 방금 이 콜로서스의 스크린과 음향 장치는 모두 멀쩡하다고 했었죠?",
  ui_story_5036_50360202_205_dialog_content = "달링처럼 콜로서스에 애정이 넘치는 사람이라면,\n분명히 이 기계들이 생명을 되찾는 모습을 직접 보고 싶겠죠?",
  ui_story_5036_50360202_206_dialog_content = "흐음...",
  ui_story_5036_50360202_207_dialog_content = "다들 생각해 보세요. 수많은 사람들이 골드리버 강변에 모여서,\n고개를 들어 하늘을 올려다보면...",
  ui_story_5036_50360202_208_dialog_content = "거대한 스크린으로 중계되는 무대의 모습이 펼쳐지는 거죠.",
  ui_story_5036_50360202_209_dialog_content = "비공정에 탄 사람들은 하늘에서 무대를 내려다볼 수도 있을 테고요.",
  ui_story_5036_50360202_210_dialog_content = "분위기가 꼭 아스트라 대륙의 카니발 같겠네요...",
  ui_story_5036_50360202_211_dialog_content = "맞아, 아스트라 대륙에서 열리는 카니발이지!\nPlayerName, 네가 방금 한 설명, 마음에 들었어~",
  ui_story_5036_50360202_212_dialog_content = "사실 아까 이 콜로서스의 이름이 「노래를 전한다」는 뜻의\n「칸타토르호」라는 걸 들었을 때, 정말 깜짝 놀랐어.",
  ui_story_5036_50360202_213_dialog_content = "어쩌면 이 아이도 한때 노래를 전하기 위해 만들어진 게 아니었을까?",
  ui_story_5036_50360202_214_dialog_content = "만약 이 콜로서스가 파괴될 운명을 피할 수 없다면...",
  ui_story_5036_50360202_215_dialog_content = "난 이 아이가 남은 시간 동안 세상을 향해 마지막 노래를 들려줄 수 있었으면 좋겠어!",
  ui_story_5036_50360202_216_dialog_content = "!!!",
  ui_story_5036_50360202_217_dialog_content = "그거 아쉽게 됐군.",
  ui_story_5036_50360202_218_dialog_content = "이 콜로서스는 내일이면 무인지대를 지나게 될 거다.\n거기라면 콜로서스를 격추시키기 가장 좋은 장소지.",
  ui_story_5036_50360202_219_dialog_content = "아마 콘서트를 열 시간은 없을 거다.",
  ui_story_5036_50360202_220_dialog_content = "여러분, 다들 그렇게 서두를 필요 없어요.",
  ui_story_5036_50360202_221_dialog_content = "콜로서스가 움브라톤을 지나고, 다시 골드리버를 따라 쭉 전진한다면...",
  ui_story_5036_50360202_222_dialog_content = "더 드넓고, 사람도 없는 곳에 도착하게 되잖아요, 그렇죠?",
  ui_story_5036_50360202_223_dialog_content = "바다... 말하는 거야?",
  ui_story_5036_50360202_224_dialog_content = "콜로서스를 격추시켜 바다에 빠트리겠단 건가요?",
  ui_story_5036_50360202_225_dialog_content = "연구원장님, 제 생각엔 좋은 기회 같아요.",
  ui_story_5036_50360202_226_dialog_content = "만약 콘서트가 성공한다면, 콜로서스의 가치를 증명해서 파괴를 막을 수 있겠죠.",
  ui_story_5036_50360202_227_dialog_content = "그럼 더 많은 시간을 얻어 콜로서스를 수리할 방법을 찾아낼 수도 있을 거예요.",
  ui_story_5036_50360202_228_dialog_content = "만약 콘서트에 실패한다고 해도, 바다라면 너무 늦지 않게 격추시킬 수 있어요.",
  ui_story_5036_50360202_229_dialog_content = "게다가 바다에서 격추시키는 거니까, 내륙 쪽에는 아무런 위험도 없을 테고요.",
  ui_story_5036_50360202_230_dialog_content = "그러니까 골디가 모두에게 진심으로 부탁할게!",
  ui_story_5036_50360202_231_dialog_content = "이 콜로서스를 파괴할 거라면, 시간을 조금만 늦춰줘...",
  ui_story_5036_50360202_232_dialog_content = "우리가 콜로서스에 무대를 세우고, 전대미문의 공연을 열 수 있게 말이야!",
  ui_story_5036_50360301_1_dialog_content = "<color=#e8d9bb>콘서트 개최 6일 전</color>",
  ui_story_5036_50360301_2_dialog_content = "음... 왼쪽이 조금 낮으니까 조금 더 위로 올려야 해.",
  ui_story_5036_50360301_3_dialog_content = "이렇게?",
  ui_story_5036_50360301_4_dialog_content = "지금은 또 오른쪽이 낮아졌어.",
  ui_story_5036_50360301_5_dialog_content = "음? 내가 볼 땐 약간 비스듬하게 붙이는 것도 꽤 멋있는 것 같은데.",
  ui_story_5036_50360301_6_dialog_content = "PlayerName, 넌 어떻게 생각해?",
  ui_story_5036_50360301_7_dialog_content = "아, 나, 난 전문가가 아니잖아. 저기... 그... 골디한테 물어볼까?",
  ui_story_5036_50360301_8_dialog_content = "멍!",
  ui_story_5036_50360301_9_dialog_content = "우와아아! 귀여워! 마시멜로는 정말 볼 때마다 조물조물하고 싶어진다니까~",
  ui_story_5036_50360301_10_dialog_content = "마시멜로도 사람이 마사지해 주는 걸 좋아해, 후훗.",
  ui_story_5036_50360301_11_dialog_content = "멍멍멍!",
  ui_story_5036_50360301_12_dialog_content = "그래, 알겠어. 착하지, 마시멜로. 이따 다시 놀아줄게.",
  ui_story_5036_50360301_13_dialog_content = "그러니까 지금은 모두랑 이야기부터 나누게 해줘, 알겠지?",
  ui_story_5036_50360301_14_dialog_content = "멍!",
  ui_story_5036_50360301_15_dialog_content = "그래서 다들 급하게 뭘 물어보러 온 거야?",
  ui_story_5036_50360301_16_dialog_content = "우린 지금 포스터 붙이는 걸 돕고 있었거든. 근데 어떻게 붙여야 좋을지 잘 모르겠어...",
  ui_story_5036_50360301_17_dialog_content = "어? 그런 건 내가 하면 돼~",
  ui_story_5036_50360301_18_dialog_content = "사양할 필요 없어, 골디.",
  ui_story_5036_50360301_19_dialog_content = "골디 네가 콘서트를 열겠다는 얘길 하지 않았다면,\n칸타토르호는 지금쯤 벌써 다른 사람들 손에 파괴됐을 테니까.",
  ui_story_5036_50360301_20_dialog_content = "음향 설비 같은 건 우리가 못 다루니까, 포스터 붙이는 거라도 도와야지.",
  ui_story_5036_50360301_21_dialog_content = "사실 이런 거 안 해줘도 다들 날 정말 많이 도와줬는걸.",
  ui_story_5036_50360301_22_dialog_content = "모두가 아니었다면 일루미나와 백야성이 내 제안을 안 들어줄까 정말 걱정했는걸.",
  ui_story_5036_50360301_23_dialog_content = "표류하는 콜로서스에 대한 문제는 대원수님이 나한테 전권을 맡기셨지만...",
  ui_story_5036_50360301_24_dialog_content = "네 질문에 답을 주려면 우리도 조금 더 연구할 시간이 필요해.",
  ui_story_5036_50360301_25_dialog_content = "연구? 또 뭘 연구한다는 거지? 애초에 말도 안 되는 일을 가지고 말이야.",
  ui_story_5036_50360301_26_dialog_content = "백야성의 귀족들이 이런 서민 「아이돌」을 거들떠나 볼 거라 생각하나?",
  ui_story_5036_50360301_27_dialog_content = "내 실력이 아직 한참 멀었다는 건 알고 있어.\n그래서 이번 공연은 나만의 단독 공연이 아니야.",
  ui_story_5036_50360301_28_dialog_content = "그래서 각지의 아이돌들한테 하늘에서 콘서트를 열 거니까\n참여해 달라고 부탁할 생각이야!",
  ui_story_5036_50360301_29_dialog_content = "백야성과 일루미나의 높으신 분들은 「아이돌」에 대한 우리의 생각을\n인정하지 않을 수도 있겠지만...",
  ui_story_5036_50360301_30_dialog_content = "그래도 괜찮아. 두 사람도 혹시 마음에 둔 아이돌이 있다면 불러와서 참가시켜 줘!",
  ui_story_5036_50360301_31_dialog_content = "난 그 의견에 찬성이야!",
  ui_story_5036_50360301_32_dialog_content = "뭐?",
  ui_story_5036_50360301_33_dialog_content = "난 골디가 콜로서스에서 콘서트를 여는 데 찬성해!",
  ui_story_5036_50360301_34_dialog_content = "골디 말이 맞아. 칸타토르호가 지닌 사명은 어쩌면 노래를 전하는 걸지도 몰라.",
  ui_story_5036_50360301_35_dialog_content = "난 아이테르로서 칸타토르호가 사명을 완수해 내는 모습을 보고 싶어.",
  ui_story_5036_50360301_36_dialog_content = "게다가 서로 다른 지역의 사람들이 편견을 버리고,\n함께 즐거운 시간을 보내는 모습도 무척 보고 싶거든!",
  ui_story_5036_50360301_37_dialog_content = "어쩌면 칸타토르호가 돌아온 건, 우리 모두에게 이런 걸 일깨워 주고 싶었던 걸지도 몰라...",
  ui_story_5036_50360301_38_dialog_content = "지역이나 신분에 관계없이, 우리 모두가 힘을 합치면 뭔가 해낼 수 있다는 걸 말이야!",
  ui_story_5036_50360301_39_dialog_content = "그러니까 골디랑 칸타토르호한테 조금만 시간을 줘.",
  ui_story_5036_50360301_40_dialog_content = "그리고 나한테도 조금만 더 시간을 줘. 어쩌면...",
  ui_story_5036_50360301_41_dialog_content = "내가 칸타토르호를 구할 수 있는 방법을 찾아낼 수 있을지도 모르잖아!",
  ui_story_5036_50360301_42_dialog_content = "지금 생각해 봐도, 그때 PlayerName 씨의 말은 정말 멋졌어!",
  ui_story_5036_50360301_43_dialog_content = "너무 감동해서 울어버릴 뻔했다니까~",
  ui_story_5036_50360301_44_dialog_content = "어쩐지, 「테르테르는 골디락스보다 훨씬 더 큰 팬클럽」이라고\n샤엘 사장님이 항상 감탄했던 이유가 있었네.",
  ui_story_5036_50360301_45_dialog_content = "에이, 뭘. 헤헤, 그땐 그냥 좀 감정이 격해졌던 것 같아.\n그럴 때면 멋대로 말이 나오곤 하거든.",
  ui_story_5036_50360301_46_dialog_content = "전 오히려 샤엘 씨가 제일 멋있던데요~",
  ui_story_5036_50360301_47_dialog_content = "미소를 지으면서 「모든 인건비는 자기가 부담하겠다」고 하는 그 순간!\n정말 온몸에서 빛이 나는 것 같더라니까요!",
  ui_story_5036_50360301_48_dialog_content = "상인은 손해 보는 장사는 하지 않는 법이야.",
  ui_story_5036_50360301_49_dialog_content = "지금 이렇게 많은 투자를 하는 건, 분명히 이 콘서트를 통해 벌어들일\n수익에 대해 진작부터 계산이 끝났다는 거겠지.",
  ui_story_5036_50360301_50_dialog_content = "근데 다들 골드리버 근처에 서 있기만 하면 무료로 공연을 볼 수 있는데,\n샤엘 씨가 어떻게 돈을 버는 걸까?",
  ui_story_5036_50360301_51_dialog_content = "으음, 샤엘 씨가 콘서트 홍보 활동 때문에 움브라톤으로 돌아가 버린 게 아쉽네.",
  ui_story_5036_50360301_52_dialog_content = "다음에 만나면 어떻게 투자금을 회수하는지 꼭 물어봐야겠어!",
  ui_story_5036_50360301_53_dialog_content = "바이스, 가끔 난 네가 움브라톤에서 지내는 게 더 잘 맞을 것 같단 생각이 들어.",
  ui_story_5036_50360301_54_dialog_content = "나이티움 얘기만 나오면, 백야성에 유학 왔을 때 수업에서\n보여 줬던 모습보다 훨씬 진지하잖아.",
  ui_story_5036_50360301_55_dialog_content = "하아? 이게 다 누구 씨 덕분인걸.",
  ui_story_5036_50360301_56_dialog_content = "으엑, 둘 다 왜 날 보는 건데?",
  ui_story_5036_50360301_57_dialog_content = "샤엘 사장님의 수완은 우리가 헤아릴 수 있는 수준이 아닐걸~",
  ui_story_5036_50360301_58_dialog_content = "우린 우리가 해야 할 일만 열심히 하면 돼~",
  ui_story_5036_50360301_59_dialog_content = "그리고 지금 골디가 맡은 임무는 바로 열심히 콘서트를 준비하는 거야!",
  ui_story_5036_50360301_60_dialog_content = "......",
  ui_story_5036_50360301_61_dialog_content = "PlayerName 씨, 무슨 걱정이라도 있어?",
  ui_story_5036_50360301_62_dialog_content = "아, 그게, 칸타토르호에 탑재된 스크린이랑 음향 장치에\n일단은 아무런 문제가 없다곤 해도...",
  ui_story_5036_50360301_63_dialog_content = "이 음향 장치들만으로 여기 노랫소리가 네 생각처럼 저 먼 지상까지 닿을까?",
  ui_story_5036_50360301_64_dialog_content = "PlayerName 씨는 아이테르면서 아이테르의 기술력을 못 믿는 거야?",
  ui_story_5036_50360301_65_dialog_content = "믿지, 당연히 믿어! 그치만...",
  ui_story_5036_50360301_66_dialog_content = "나도 알아, 다들 뭘 걱정하고 있는지. 날 믿어 줘.\n누구보다도 콘서트가 순조롭게 진행되길 바라는 건 바로 나잖아.",
  ui_story_5036_50360301_67_dialog_content = "시오반 씨한테도 설비에 대해 이것저것 가르쳐 달라고 해서, 제어 방법은 다 배워 놨어.",
  ui_story_5036_50360301_68_dialog_content = "이 설비들이라면 내 노래가 지면에 있는 관객들의 귀까지 100% 전해질 거야~",
  ui_story_5036_50360301_69_dialog_content = "벌써 다 준비해 뒀었구나, 역시 프로 아이돌은 다르네!",
  ui_story_5036_50360301_70_dialog_content = "참, 그건 그렇고, 칸타토르호를 구할 방법을 찾는다고 했었지?",
  ui_story_5036_50360301_71_dialog_content = "뭔가 좀 찾았어?",
  ui_story_5036_50360301_72_dialog_content = "전혀 단서가 없어.",
  ui_story_5036_50360301_73_dialog_content = "지금 생각해 보면 그땐 뭘 몰라서 용감했던 것 같아.",
  ui_story_5036_50360301_74_dialog_content = "일루미나의 연구원장도 방법이 없다고 한 건데,\n내가 무슨 배짱으로 할 수 있다고 생각했던 걸까?",
  ui_story_5036_50360301_75_dialog_content = "PlayerName 씨, 그렇게 힘 빠지는 얘긴 하지 말자~",
  ui_story_5036_50360301_76_dialog_content = "아니면 내 <color=#FFB400>행운의 탄환</color>에 물어봐 줄까?",
  ui_story_5036_50360301_77_dialog_content = "행운의 탄환?",
  ui_story_5036_50360301_78_dialog_content = "탄환아, 탄환아. PlayerName 씨가 칸타토르호를 구할 방법을 찾을 수 있을까?",
  ui_story_5036_50360301_79_dialog_content = "찾을 수 있다면 탄두 쪽부터 바닥에 떨어져 줘!",
  ui_story_5036_50360301_80_dialog_content = "PlayerName 씨, 자! 이제 탄환을 허공으로 던져 봐~",
  ui_story_5036_50360301_81_dialog_content = "허공으로 던지라고? 이렇게?",
  ui_story_5036_50360301_82_dialog_content = "<color=#e8d9bb>휙──</color>",
  ui_story_5036_50360301_83_dialog_content = "탄환이 공중으로 붕 떴어...",
  ui_story_5036_50360301_84_dialog_content = "<color=#e8d9bb>팅!</color>",
  ui_story_5036_50360301_85_dialog_content = "우와, PlayerName 씨! 이거 봐, 탄두가 바닥을 향해서 떨어졌어~",
  ui_story_5036_50360301_86_dialog_content = "행운의 탄환이 방법을 찾을 수 있다고 했으니까 분명히 괜찮을 거야!",
  ui_story_5036_50360301_87_dialog_content = "진짜?",
  ui_story_5036_50360301_88_dialog_content = "나한테 매번 어려운 일이 생길 때마다, 행운의 탄환이 내가 답을 찾을 수 있도록 도와줬거든.",
  ui_story_5036_50360301_89_dialog_content = "그러니까 행운의 탄환이 당신한테도 행운을 가져다줄 거야~",
  ui_story_5036_50360301_90_dialog_content = "응, 알겠어! 어쨌든 난 끝까지 포기 안 할 거야!",
  ui_story_5036_50360301_91_dialog_content = "매번 골디가 하는 말을 들으면 뭔가 기운이 샘솟는 것 같은 기분이 들어.",
  ui_story_5036_50360301_92_dialog_content = "이러다 나도 「골디락스」가 돼 버릴 것 같다니까~",
  ui_story_5036_50360301_93_dialog_content = "헤헤, 그럼 좀 빨리 결정해 줘~",
  ui_story_5036_50360301_94_dialog_content = "왜냐면 난 진작부터 열성 「테르테르」였거든~",
  ui_story_5036_50360301_95_dialog_content = "엥?",
  ui_story_5036_50360301_96_dialog_content = "<color=#e8d9bb>찰칵!</color>",
  ui_story_5036_50360301_97_dialog_content = "어머?",
  ui_story_5036_50360301_98_dialog_content = "미, 미안해요!",
  ui_story_5036_50360301_99_dialog_content = "다들 분위기가 좋아 보이길래 저도 모르게 기념사진을 찍어 드리고 싶었거든요...",
  ui_story_5036_50360301_100_dialog_content = "와아~ 고마워~ 브랜디!",
  ui_story_5036_50360301_101_dialog_content = "(지금 골디 씨가... 내 이름을 불러 준 거야?!)",
  ui_story_5036_50360301_102_dialog_content = "역시 움브라톤에 있는 신문사들은 뭐가 달라도 다르다니까.\n이렇게 빨리 콘서트 취재를 하러 온 거야?",
  ui_story_5036_50360301_103_dialog_content = "사실 이번에 전 PlayerName 씨를 따라온 거예요...",
  ui_story_5036_50360301_104_dialog_content = "응, 브랜디가 날 인터뷰하고 싶다고 그랬거든.",
  ui_story_5036_50360301_105_dialog_content = "그랬구나. 그럼 이번 인터뷰 대상은 PlayerName 씨인 거야?",
  ui_story_5036_50360301_106_dialog_content = "어머, 조금 질투 나는걸~",
  ui_story_5036_50360301_107_dialog_content = "어, 음, 그게, 저기...",
  ui_story_5036_50360301_108_dialog_content = "괜찮아, 브랜디. 그냥 농담해 본 거니까~",
  ui_story_5036_50360301_109_dialog_content = "...골디 씨가 절 아직 기억하고 계실 줄은 몰랐어요.",
  ui_story_5036_50360301_110_dialog_content = "당연히 기억하지.\n저번에 브랜디가 인터뷰한 기사도 잘 스크랩해서 보관 중인걸~",
  ui_story_5036_50360301_111_dialog_content = "하지만 그건 너무 못 써서 편집장님한테 욕을 잔뜩 먹었던 기사인걸요.",
  ui_story_5036_50360301_112_dialog_content = "브랜디, 스스로에 대해 그렇게 말하면 안 되는 거야.",
  ui_story_5036_50360301_113_dialog_content = "브랜디는 그 누구보다 인터뷰 사전 준비 작업을 열심히 하는 사람이잖아!",
  ui_story_5036_50360301_114_dialog_content = "다른 사람이 뭐라든, 자기 자신은 스스로가 내린 판단을 믿어야 하는 거라구~",
  ui_story_5036_50360301_115_dialog_content = "...스스로를 믿어야 한다는 건가요.",
  ui_story_5036_50360301_116_dialog_content = "역시 전 매번 골디 씨한테서 이 일을 계속해나갈 에너지를 얻어 가는 것 같아요.",
  ui_story_5036_50360301_117_dialog_content = "근데 신문사 선배들 말로는 골디 씨가 스타 시어터에서 콘서트를 열려고\n오랜 시간 준비해 오셨다고 하던데요.",
  ui_story_5036_50360301_118_dialog_content = "표류하는 콜로서스에서 콘서트를 개최한다면,\n스타 시어터 쪽 공연은 못 하게 되는 거 아닌가요?",
  ui_story_5036_50360301_119_dialog_content = "아, 그건...",
  ui_story_5036_50360301_120_dialog_content = "「칸타토르호」처럼 커다란 무대가 날 기다리고 있다면, 당연히 놓칠 수 없잖아?",
  ui_story_5036_50360301_121_dialog_content = "그리고 움브라톤에 있는 극장에서 콘서트를 열 기회는 앞으로도 아주 많을 테고 말이야.",
  ui_story_5036_50360301_122_dialog_content = "그런 건가요?",
  ui_story_5036_50360301_123_dialog_content = "아하하, 그래도 정말 다행이네!",
  ui_story_5036_50360301_124_dialog_content = "날 위해서 이렇게 훌륭한 기자를 불러와 주다니,\n역시 행운의 탄환은 틀리는 법이 없다니까!",
  ui_story_5036_50360301_125_dialog_content = "네?",
  ui_story_5036_50360301_126_dialog_content = "안 그래도 샤엘 사장님이 콘서트 소식을 취재할 기자를 찾아보라고 했는데,\n대체 어딜 가서 찾아야 하나 고민 중이었거든.",
  ui_story_5036_50360301_127_dialog_content = "브랜디만 괜찮다면, 이번 콘서트가 얼마나 성황리에 진행됐는지\n동행 취재를 해서 보도해 줬으면 좋겠어.",
  ui_story_5036_50360301_128_dialog_content = "혹시 내 부탁이 너무 갑작스러운 건 아니지?",
  ui_story_5036_50360301_129_dialog_content = "생각 좀 해 본 다음에 결정해 줘도 돼~",
  ui_story_5036_50360301_130_dialog_content = "(역시 내가 알고 있던 친절하고 상냥한 골디 씨야!)",
  ui_story_5036_50360301_131_dialog_content = "(골디 씨가 폭력적인 사람이라는 그 소문은 아마 거짓이 아닐까?)",
  ui_story_5036_50360301_132_dialog_content = "다들 여기 멍하니 서 있으면 안 돼.",
  ui_story_5036_50360301_133_dialog_content = "앞에 아직 포스터를 붙여야 할 곳이 더 있는 것 같으니까 얼른 가 보자!",
  ui_story_5036_50360301_134_dialog_content = "다들 뛰는 속도가 무슨 선수 해도 되겠군.",
  ui_story_5036_50360301_135_dialog_content = "이쪽 복도에도 알록달록한 포스터를 잔뜩 붙여 놨잖아.",
  ui_story_5036_50360301_136_dialog_content = "휴, 정말 모르겠어. 대체 아이돌이란 게 뭐라고 저러는 건지.",
  ui_story_5036_50360301_137_dialog_content = "무대 위에서 좀 웃어 주면서 귀여운 척이나 하면\n사람들한테 사랑과 박수를 받는다니.",
  ui_story_5036_50360301_138_dialog_content = "우리 같은 사람들은 여기서 아무리 성실하게 일한다고 한들\n아무도 칭찬 따윈 안 해주는데.",
  ui_story_5036_50360301_139_dialog_content = "그러게 말이야. 게다가 저런 이상한 옷을 입고 다니는 아이돌은 또 처음 본다고.",
  ui_story_5036_50360301_140_dialog_content = "춤이나 노래로 사람의 마음을 사로잡을 순 있지.\n그런데 사람의 마음을 구원한다? 어림도 없는 소리.",
  ui_story_5036_50360301_141_dialog_content = "내가 백야성 사람이랑 같은 생각을 하게 될 날이 올 줄은 꿈에도 몰랐네.",
  ui_story_5036_50360301_142_dialog_content = "휴, 우리 팔자를 탓해야지.",
  ui_story_5036_50360301_143_dialog_content = "누구는 콘서트를 여네 어쩌네 하면서 입만 떠들고,\n봉쇄 구역을 지키고 암귀를 처리하는 건 죄다 우리 몫이잖아!",
  ui_story_5036_50360301_144_dialog_content = "게다가 왠지는 몰라도 최근 이틀 동안에는 갈수록 기운이 빠지더라고.",
  ui_story_5036_50360301_145_dialog_content = "그러게 말이야.",
  ui_story_5036_50360301_146_dialog_content = "크흠...",
  ui_story_5036_50360301_147_dialog_content = "!!!",
  ui_story_5036_50360301_148_dialog_content = "충성! 바이스 중위님!",
  ui_story_5036_50360301_149_dialog_content = "평안하십니까, 카렌 전하!",
  ui_story_5036_50360301_150_dialog_content = "격식 차릴 거 없어. 여기서 근무한다고 고생이 많아.",
  ui_story_5036_50360301_151_dialog_content = "...방금 전에는 분수도 모르고 어리석은 말을 내뱉고 말았습니다!\n처벌을 받아 마땅합니다!",
  ui_story_5036_50360301_152_dialog_content = "처벌해 주십시오! 바이스 중위님!",
  ui_story_5036_50360301_153_dialog_content = "평민을 모욕하는 건 우리 기사들이 범해선 안 될 일이야.",
  ui_story_5036_50360301_154_dialog_content = "자신이 무엇을 해야 하는진, 내가 말하지 않아도 스스로 잘 알고 있으리라 믿겠어.",
  ui_story_5036_50360301_155_dialog_content = "골디 양, 결례를 범한 점 사과드립니다!",
  ui_story_5036_50360301_156_dialog_content = "너도 빨리 사과 안 하고 뭐 해?",
  ui_story_5036_50360301_157_dialog_content = "죄, 죄송합니다! 골디 씨!",
  ui_story_5036_50360301_158_dialog_content = "제가 불손한 언사로 기사의 정신을 욕보였으니, 부디 이 검으로 절 심판해 주십시오!",
  ui_story_5036_50360301_159_dialog_content = "좋아, 그럼 두 사람한테 벌을 내릴게...",
  ui_story_5036_50360301_160_dialog_content = "오늘은 빨리 가서 쉬고, 달콤한 꿈을 꿔!",
  ui_story_5036_50360301_161_dialog_content = "예?!",
  ui_story_5036_50360301_162_dialog_content = "에이, 일할 때 푸념 한두 마디 안 하는 사람이 어딨어.",
  ui_story_5036_50360301_163_dialog_content = "그리고 내가 여기 온 거 때문에 모두가 할 일이 늘어난 건 사실이잖아.",
  ui_story_5036_50360301_164_dialog_content = "그러니까 사과해야 할 사람은 오히려 나야~",
  ui_story_5036_50360301_165_dialog_content = "그래서 내가 샤엘 사장님한테 부탁해서 일을 분담해 줄\n움브라톤 용병단한테 연락해 뒀어.",
  ui_story_5036_50360301_166_dialog_content = "앞으론 다들 조금 더 오래 쉴 수 있을 거야!",
  ui_story_5036_50360301_167_dialog_content = "아...",
  ui_story_5036_50360301_168_dialog_content = "그리고 복도 끝에 있는 방에 가면 당분 보충용 음료가 있어.\n두 사람 다 여기서 당직 서느라 아직 못 받았지?",
  ui_story_5036_50360301_169_dialog_content = "얼른 가서 마셔 봐~",
  ui_story_5036_50360301_170_dialog_content = "마시고 나면 분명 기운이 마구 샘솟을 테니까!",
  ui_story_5036_50360301_171_dialog_content = "......",
  ui_story_5036_50360301_172_dialog_content = "아이, 참. 골디 씨가 이렇게까지 얘기해 줬는데 멍하니 뭐 하고 있는 거야?",
  ui_story_5036_50360301_173_dialog_content = "카렌 님...?",
  ui_story_5036_50360301_174_dialog_content = "골디 양이 이미 벌을 내렸으니, 가 보도록 해.",
  ui_story_5036_50360301_175_dialog_content = "감사합니다, 카렌 전하! 감사합니다, 골디 양!",
  ui_story_5036_50360301_176_dialog_content = "감사합니다, 바이스 중위님! 감사합니다, 골디 씨!",
  ui_story_5036_50360301_177_dialog_content = "역시 콘서트를 하나 열려면 신경 써야 할 게 한두 개가 아니라니까.",
  ui_story_5036_50360301_178_dialog_content = "같이 일하는 병사들의 마음도 생각해야 한다는 걸 까맣게 잊고 있었어...",
  ui_story_5036_50360301_179_dialog_content = "골디 양, 필요하다면 내가 백야성 기사단에서 사람을 조금 더 차출해 줄 수 있어.",
  ui_story_5036_50360301_180_dialog_content = "아니야, 그러면 내가 너무 미안한걸!",
  ui_story_5036_50360301_181_dialog_content = "진짜 괜찮아! 안 그래도 내가 벌써 백화 용병단에 자재 운송이랑\n무대 건설 의뢰를 맡겨 놨거든.",
  ui_story_5036_50360301_182_dialog_content = "용병단이 도착하면 의뢰 내용을 조금 추가하면 돼!",
  ui_story_5036_50360301_183_dialog_content = "백화 용병단에 의뢰를 넣었다면 비용이 만만치 않았을 텐데요.",
  ui_story_5036_50360301_184_dialog_content = "그 인건비도 샤엘 씨가 내주는 건가요?",
  ui_story_5036_50360301_185_dialog_content = "......",
  ui_story_5036_50360301_186_dialog_content = "골디 씨?",
  ui_story_5036_50360301_187_dialog_content = "응?",
  ui_story_5036_50360301_188_dialog_content = "아... 응, 샤엘 사장님은 대단한 사람이니까 그 정돈 문제없어.",
  ui_story_5036_50360301_189_dialog_content = "골디, 혹시 방금 무슨 걱정이라도 했던 거야?",
  ui_story_5036_50360301_190_dialog_content = "아니야~",
  ui_story_5036_50360301_191_dialog_content = "근데 백화 용병단이 진작 도착했어야 할 시간인데, 왜 아직도 소식이 없나 해서...",
  ui_story_5036_50360301_192_dialog_content = "<color=#e8d9bb>터벅... 터벅... 터벅...</color>",
  ui_story_5036_50360301_193_dialog_content = "발소리? 앞쪽에 사람들이 도착했나 본데?",
  ui_story_5036_50360301_194_dialog_content = "호랑이도 제 말 하면 온다더니, 백화 용병단 사람들이 온 걸까?",
  ui_story_5036_50360301_195_dialog_content = "굉장한 우연이네! 에헤헷.",
  ui_story_5036_50360301_196_dialog_content = "크오오오──!",
  ui_story_5036_50360301_197_dialog_content = "어머? 이런...",
  ui_story_5036_50360301_198_dialog_content = "내가 사람을 잘못 봤나 봐!",
  ui_story_5036_50360301_199_dialog_content = "내가 의뢰를 넣은 건 암귀가 아니라 용병인데?",
  ui_story_5036_50360302_1_dialog_content = "뒤를 조심해!",
  ui_story_5036_50360302_2_dialog_content = "엣?",
  ui_story_5036_50360302_3_dialog_content = "크오오!",
  ui_story_5036_50360302_4_dialog_content = "사라져라!",
  ui_story_5036_50360302_5_dialog_content = "백화 용병단, 도착했구나!",
  ui_story_5036_50360302_6_dialog_content = "골디 양! 괜찮으십니까?",
  ui_story_5036_50360302_7_dialog_content = "난 괜찮아. 제때 와 줘서 살았어.",
  ui_story_5036_50360302_8_dialog_content = "제때라고 하기엔 너무 늦게 도착했습니다.",
  ui_story_5036_50360302_9_dialog_content = "무대 자재를 싣는 데 예상보다 시간이 더 걸렸습니다.\n이제야 도착하게 되어 죄송합니다.",
  ui_story_5036_50360302_10_dialog_content = "하지만 이 콜로서스에도 암귀가 있을 줄은 몰랐네요.",
  ui_story_5036_50360302_11_dialog_content = "사실... 그건 나도 도착하고 나서야 알았어.",
  ui_story_5036_50360302_12_dialog_content = "그래도 일루미나랑 백야성 병사들이 대부분의 암귀를\n콜로서스 꼬리 쪽에 있는 봉쇄 구역으로 몰아내 버렸거든.",
  ui_story_5036_50360302_13_dialog_content = "덕분에 거기서 도망쳐 나온 암귀들은 방금 본 것처럼...",
  ui_story_5036_50360302_14_dialog_content = "살상력은 그다지 가지고 있지 않아.",
  ui_story_5036_50360302_15_dialog_content = "봉쇄 구역에서 도망치는 암귀들은 병사들이 이미 공세를 강화했어.",
  ui_story_5036_50360302_16_dialog_content = "거기다 백화 용병단의 도움이 있다면...",
  ui_story_5036_50360302_17_dialog_content = "도망 나온 암귀들뿐만 아니라, 봉쇄 구역 안의 암귀들도 금방 깔끔하게 처리될 거야.",
  ui_story_5036_50360302_18_dialog_content = "샤엘 사장님의 의뢰인만큼, 저희 모두 최선을 다하겠습니다.",
  ui_story_5036_50360302_19_dialog_content = "저희한테 맡겨 주세요!",
  ui_story_5036_50360302_20_dialog_content = "그럼 부탁할게~",
  ui_story_5036_50360302_21_dialog_content = "천만에요, 골디 양. 그나저나 움브라톤에서 듣기로는...",
  ui_story_5036_50360302_22_dialog_content = "벌써부터 많은 사람들이 콘서트에 참가 신청을 넣었다고 하더군요.",
  ui_story_5036_50360302_23_dialog_content = "소문이 벌써 퍼졌구나~",
  ui_story_5036_50360302_24_dialog_content = "맞아! 모두 내 생각보다 훨씬 더 열정적이었어.",
  ui_story_5036_50360302_25_dialog_content = "그래서 정식 공연 전에 <color=#FFB400>아이돌 오디션</color>을 몇 번 진행할 생각이야.",
  ui_story_5036_50360302_26_dialog_content = "진짜로 무대에 서서, 공연을 선보일 수 있는 아이돌들을 뽑는 거지.",
  ui_story_5036_50360302_27_dialog_content = "아이돌 오디션이요? 분위기가 굉장히 뜨거워지겠군요.",
  ui_story_5036_50360302_28_dialog_content = "내일이 바로 첫 번째 오디션 날이야.\n그러니까 현장 질서를 유지해 줄 사람을 몇 명 정도 배치해 줬으면 좋겠어.",
  ui_story_5036_50360302_29_dialog_content = "문제없습니다!",
  ui_story_5036_50360302_30_dialog_content = "얘들아, 일할 시간이다!",
  ui_story_5036_50360302_31_dialog_content = "좋아!",
  ui_story_5036_50360302_32_dialog_content = "골디 넌 행동력이 정말 대단하구나.",
  ui_story_5036_50360302_33_dialog_content = "아이돌 오디션? 신경 써야 할 게 이만저만이 아닐 것 같은데?",
  ui_story_5036_50360302_34_dialog_content = "이건 내가 쭉 꿈꿔 오던 일이야.\n내 꿈을 실현할 기회가 드디어 찾아온 거잖아.",
  ui_story_5036_50360302_35_dialog_content = "그러니까 하나도 안 힘들어~",
  ui_story_5036_50360302_36_dialog_content = "지금까지 계속 아이돌 오디션을 열고 싶었어?",
  ui_story_5036_50360302_37_dialog_content = "응. 난 무대를 정말 사랑하지만, 무대 아래에 있는 관객들도 정말 좋아하거든.",
  ui_story_5036_50360302_38_dialog_content = "내 사랑을 모두에게 전해 주고 싶어!",
  ui_story_5036_50360302_39_dialog_content = "그리고 더 많은 아이돌이 관객들한테 감동과 희망을 전했으면 좋겠어.",
  ui_story_5036_50360302_40_dialog_content = "그래서 내가 아직 능력이 될 때 나랑 같은 소년, 소녀들이\n아이돌이 되는 모습을 직접 보고 싶어!",
  ui_story_5036_50360302_41_dialog_content = "골디는 아이돌이란 직업을 정말 사랑하는구나.",
  ui_story_5036_50360302_42_dialog_content = "근데 있잖아...",
  ui_story_5036_50360302_43_dialog_content = "PlayerName 씨, 혹시 아이돌 오디션의 <color=#FFB400>심사위원</color> 해 볼 생각 없어?",
  ui_story_5036_50360302_44_dialog_content = "심사위원? 내가?",
  ui_story_5036_50360302_45_dialog_content = "응! 심사위원의 임무는 말하자면 무척 간단해.",
  ui_story_5036_50360302_46_dialog_content = "오디션 참가 신청자가 준비해 온 걸 본 다음에, 심사위원인 당신 기준에 따라\n그 사람이 최종 무대에 설 자격이 있는지 판단하는 거야.",
  ui_story_5036_50360302_47_dialog_content = "원래는 샤엘 사장님한테 부탁하려고 했었는데, 콘서트 홍보 일 때문에 바빠 보여서.",
  ui_story_5036_50360302_48_dialog_content = "곰곰이 생각해 보니까 PlayerName 씨 당신이 가장 적임자 같거든.",
  ui_story_5036_50360302_49_dialog_content = "근데 나 진짜 자신 없는데...",
  ui_story_5036_50360302_50_dialog_content = "맞다! 카렌, 바이스! 너희 둘도 노래 부르는 거 엄청 좋아하잖아!",
  ui_story_5036_50360302_51_dialog_content = "심사위원 해볼 생각 없어?",
  ui_story_5036_50360302_52_dialog_content = "으음...",
  ui_story_5036_50360302_53_dialog_content = "흐음...",
  ui_story_5036_50360302_54_dialog_content = "후후훗, PlayerName 씨, 아직 모르고 있었구나?",
  ui_story_5036_50360302_55_dialog_content = "바이스 씨랑 카렌 씨도 벌써 아이돌 오디션에 참가 신청을 했어~",
  ui_story_5036_50360302_56_dialog_content = "뭐?!",
  ui_story_5036_50360302_57_dialog_content = "왜 난 전혀 몰랐지?!",
  ui_story_5036_50360302_58_dialog_content = "이건 진짜 우리 탓하면 안 돼. 우린 진짜로 너한테 얘기했었단 말이야.",
  ui_story_5036_50360302_59_dialog_content = "그런데 계속 무슨 노랫소리가 들린다면서 우리 얘길 안 들어 줬잖아.",
  ui_story_5036_50360302_60_dialog_content = "바이스랑 상의해 봤는데, 만약 우리가 콘서트를 성황리에 개최한다면\n칸타토르호의 가치를 증명할 수 있을 것 같아.",
  ui_story_5036_50360302_61_dialog_content = "그래서 그 점을 들어서 아버님과 일루미나 상부에 칸타토르호를\n파괴하지 말아 달라고 설득할 생각이야.",
  ui_story_5036_50360302_62_dialog_content = "그렇게 하면 설령 우리가 콜로서스를 제어할 방법을 찾지 못한다 해도...",
  ui_story_5036_50360302_63_dialog_content = "칸타토르호가 적어도 지금처럼 자유롭게 하늘을 표류할 순 있을 테니까.",
  ui_story_5036_50360302_64_dialog_content = "어쩌면 백 년 정도 뒤에는 칸타토르호가 또다시 아스트라 대륙의\n하늘로 돌아올지도 모르는 일이잖아!",
  ui_story_5036_50360302_65_dialog_content = "두 사람은 벌써 거기까지 생각해 뒀던 거야?",
  ui_story_5036_50360302_66_dialog_content = "사실 네 신청서도 제출할까 했었는데, 생각 좀 해 보니까...",
  ui_story_5036_50360302_67_dialog_content = "음, 그냥 관두는 게 나을 것 같더라고.",
  ui_story_5036_50360302_68_dialog_content = "내가 춤이나 노래에 자신이 없는 건 사실이지만, 그렇다고 그렇게 말할 건 없잖아...",
  ui_story_5036_50360302_69_dialog_content = "심사위원은 춤이나 노래 실력이 뛰어나지 않아도 돼.",
  ui_story_5036_50360302_70_dialog_content = "숨겨져 있는 부분들을 잘 발견할 수 있는 눈썰미만 있다면, 자격을 갖췄다고 할 수 있어~",
  ui_story_5036_50360302_71_dialog_content = "으...",
  ui_story_5036_50360302_72_dialog_content = "음, 역시 이 방법밖엔 없겠어.",
  ui_story_5036_50360302_73_dialog_content = "정말 생각도 못 했네.",
  ui_story_5036_50360302_74_dialog_content = "내가 이 나이에 이런 일을 해야 한다니.",
  ui_story_5036_50360302_75_dialog_content = "캬오오!",
  ui_story_5036_50360302_76_dialog_content = "쉿!",
  ui_story_5036_50360302_77_dialog_content = "<size=35>크릉?</size>",
  ui_story_5036_50360302_78_dialog_content = "착하지, 우리 용용이. 벌써 시간이 늦었잖니.",
  ui_story_5036_50360302_79_dialog_content = "그렇게 큰 소릴 내면 다른 사람들이 놀라서 깨 버릴 거야.",
  ui_story_5036_50360302_80_dialog_content = "난 첫 등장부터 그렇게 눈에 띄고 싶진 않거든.",
  ui_story_5036_50360302_81_dialog_content = "크릉...",
  ui_story_5036_50360302_82_dialog_content = "자, 넌 얼른 돌아가서 피아를 찾아봐.",
  ui_story_5036_50360302_83_dialog_content = "대신 명심해...",
  ui_story_5036_50360302_84_dialog_content = "절대로 내가 어디 있는지 피아가 알게 만들면 안 돼.",
  ui_story_5036_50360401_1_dialog_content = "편집장님! 저예요!",
  ui_story_5036_50360401_2_dialog_content = "이름을 말해야 할 거 아냐. 안 그럼 네가 누군지 내가 어떻게 알아?",
  ui_story_5036_50360401_3_dialog_content = "...브랜디요.",
  ui_story_5036_50360401_4_dialog_content = "아, 기억났다.",
  ui_story_5036_50360401_5_dialog_content = "따분한 기사밖에 못 쓰는 수습기자 브랜디 맞지?",
  ui_story_5036_50360401_6_dialog_content = "난 네가 진작 짐 싸서 그만둔 줄 알았는데.",
  ui_story_5036_50360401_7_dialog_content = "저번에 저한테 마지막 기회를 주겠다고 하셨잖아요.",
  ui_story_5036_50360401_8_dialog_content = "아, 그랬던 것도 같네. 그래서, 뭐 좋은 소식이라도 있나?",
  ui_story_5036_50360401_9_dialog_content = "네! 편집장님, 그거 아세요?",
  ui_story_5036_50360401_10_dialog_content = "저 지금 사람들 사이에서 한창 화제가 되고 있는 그 표류하는 콜로서스...\n칸타토르호에 타고 있어요!",
  ui_story_5036_50360401_11_dialog_content = "그래서?",
  ui_story_5036_50360401_12_dialog_content = "이 콜로서스는 움브라톤 상공을 표류할 때, 대형 콘서트를 하나 진행할 예정이에요!",
  ui_story_5036_50360401_13_dialog_content = "난 바쁜 사람이야. 내가 모르고 있는 사실이나 좀 말해줄 순 없나?",
  ui_story_5036_50360401_14_dialog_content = "어, 그게...",
  ui_story_5036_50360401_15_dialog_content = "제가 이번 콘서트의 공식 파트너 기자로 선정됐어요.\n그리고 모두를 도와 아이돌 오디션의 진행을 돕기로도 했고요!",
  ui_story_5036_50360401_16_dialog_content = "흥, 그런 콘서트의 공식 뉴스를 보도하는 게 그렇게 자부심을 느낄 만한 일인가?",
  ui_story_5036_50360401_17_dialog_content = "넌 아직도 잘 모르는 모양이군.",
  ui_story_5036_50360401_18_dialog_content = "내가 원하는 건 사람들의 이목을 단번에 사로잡을 수 있는 쇼킹한 뉴스라고!",
  ui_story_5036_50360401_19_dialog_content = "어? 편집장님! 편집장님?",
  ui_story_5036_50360401_20_dialog_content = "쇼킹한 뉴스 말인가요...",
  ui_story_5036_50360401_21_dialog_content = "<color=#e8d9bb>콘서트 개최 5일 전</color>",
  ui_story_5036_50360401_22_dialog_content = "참가자 여러분~ 모두 오래 기다리셨어요!",
  ui_story_5036_50360401_23_dialog_content = "<color=#FFB400>별들이 빛나는 순간, 창공의 콘서트</color>의 오디션 현장에 오신 걸 환영합니다~",
  ui_story_5036_50360401_24_dialog_content = "참가 신청을 마치고, 참가자 전용 비공정에 탑승해\n이 콜로서스에 도착한 기분은 어떠신가요?",
  ui_story_5036_50360401_25_dialog_content = "감격하셨나요? 아니면 흥분되셨나요?\n그것도 아니라면 긴장하거나 짜릿함을 느끼셨나요?",
  ui_story_5036_50360401_26_dialog_content = "하지만 더 박진감 넘치고, 더 자극적인 부분은 앞으로 더 많이 있답니다.",
  ui_story_5036_50360401_27_dialog_content = "자, 그럼 첫 번째 오디션을 시작해 볼까요!",
  ui_story_5036_50360401_28_dialog_content = "우와아아! 드디어 시작됐어!",
  ui_story_5036_50360401_29_dialog_content = "여러분! 우선 오디션 규칙을 소개해 드릴 테니까, 잠시만 진정해 주세요.",
  ui_story_5036_50360401_30_dialog_content = "여러분도 보이시겠지만, 오디션 현장에는 심사위원 여섯 분이 나와 계십니다.",
  ui_story_5036_50360401_31_dialog_content = "나랑 육성 게임의 즐거움에 대해 이야기할 사람은 언제든 환영이야. 후후훗.",
  ui_story_5036_50360401_32_dialog_content = "노래, 춤, 비주얼, 몸매, 감성, 지성 총 여섯 항목이 제 평가 기준이에요.",
  ui_story_5036_50360401_33_dialog_content = "그중 한 가지 항목만 뛰어나더라도 제 주목을 받을 수 있을 거예요.",
  ui_story_5036_50360401_34_dialog_content = "난 순수하고 아름다우면서도 고상하고, 티 없이 맑으면서\n영혼을 정화하는 퍼포먼스를 보고 싶군...",
  ui_story_5036_50360401_35_dialog_content = "어디, 할 수 있겠나?",
  ui_story_5036_50360401_36_dialog_content = "다들 힘내.",
  ui_story_5036_50360401_37_dialog_content = "반짝이는 당신과 함께 천공의 무대에 올라 빛으로 세상을 물들이고 싶어~",
  ui_story_5036_50360401_38_dialog_content = "안녕하세요. 최선을 다해 여러분의 퍼포먼스를 감상할게요!",
  ui_story_5036_50360401_39_dialog_content = "오디션 규칙은 매우 간단해요. 심사위원 중 네 명에게 합격 표를 받으면...",
  ui_story_5036_50360401_40_dialog_content = "준결승에 진출해 무대 출전권을 놓고 마지막 각축을 벌이게 될 거예요.",
  ui_story_5036_50360401_41_dialog_content = "만약 참가자가 여섯 명의 심사위원에게 만장일치로 합격을 받는다면,\n준결승을 건너뛰고 곧바로 창공의 콘서트 무대 위에 오를 기회를 얻을 수 있어요!",
  ui_story_5036_50360401_42_dialog_content = "진출권을 따내지 못하더라도 너무 실망하진 마세요!\n모든 참가자에겐 오디션 참가 기회가 세 번 있으니까요.",
  ui_story_5036_50360401_43_dialog_content = "또한, 참가자 여러분 모두 칸타토르호에 준비된 연습실에서\n마음껏 기량을 갈고닦으실 수 있답니다.",
  ui_story_5036_50360401_44_dialog_content = "그럼 얼른 오늘의 오디션을 시작해 볼까요~",
  ui_story_5036_50360401_45_dialog_content = "지금부터 자신의 번호가 호명된 참가자님은 무대 위로 올라와\n자신의 실력을 뽐내 주세요!",
  ui_story_5036_50360401_46_dialog_content = "참가 번호 1번, 일루미나 합창단!",
  ui_story_5036_50360401_47_dialog_content = "오디션이 시작됐어. 안 가 볼 거야?",
  ui_story_5036_50360401_48_dialog_content = "응, 일단은 안 보려고.",
  ui_story_5036_50360401_49_dialog_content = "내 차례 때 뭘 할지 아직 못 정했거든.",
  ui_story_5036_50360401_50_dialog_content = "벌써부터 다른 사람들 무대를 보면 더 긴장할 것 같아.",
  ui_story_5036_50360401_51_dialog_content = "사실 나도 아직 못 정했어.",
  ui_story_5036_50360401_52_dialog_content = "처음에 참가 신청을 했을 땐, 그저 참가자 수가 부족해서\n행사 진행을 못 할까 봐 그랬던 건데.",
  ui_story_5036_50360401_53_dialog_content = "이렇게나 사람들이 많이 모여든 걸 보니까...",
  ui_story_5036_50360401_54_dialog_content = "난 안 나가도 될 것 같단 생각도 들어.",
  ui_story_5036_50360401_55_dialog_content = "어? 일루미나랑 백야성엔 내정된 참가자가 한 명씩 있다고 들었는데?",
  ui_story_5036_50360401_56_dialog_content = "일루미나는 일루미나 합창단을 참가시키기로 했고, 백야성은 카렌이 나가는 게 아니었어?",
  ui_story_5036_50360401_57_dialog_content = "감사합니다! 저희가 준비한 건 여기까지입니다!",
  ui_story_5036_50360401_58_dialog_content = "안무에서 절도와 힘을 느낄 수 있었어요. 마음을 고양시키는 가사 내용도\n일루미나 병사의 패기를 아주 잘 드러내 주었고요.",
  ui_story_5036_50360401_59_dialog_content = "이미 일루미나 각지를 돌며 순회공연까지 하고 있는 합창단이라\n전체적인 무대 구성이 잘 다듬어져 있고, 안정적이었습니다.",
  ui_story_5036_50360401_60_dialog_content = "저는 여러분의 합창이 정말 마음에 들었어요. 앞으로도 힘내 주셨으면 좋겠네요!",
  ui_story_5036_50360401_61_dialog_content = "심사평에 감사드려요.",
  ui_story_5036_50360401_62_dialog_content = "참가 번호 1번, 일루미나 합창단의 최종 득표수는...",
  ui_story_5036_50360401_63_dialog_content = "심사위원 만장일치로 여섯 표입니다!",
  ui_story_5036_50360401_64_dialog_content = "첫 번째로 무대에 오른다는 압박감을 이겨 내고, 순조롭게 콘서트 무대에\n오를 수 있는 기회를 거머쥐었네요! 축하합니다!",
  ui_story_5036_50360401_65_dialog_content = "감사합니다. 심사위원 여러분! 절대 여러분을 실망시키지 않겠습니다!",
  ui_story_5036_50360401_66_dialog_content = "자, 그러면 참가 번호 2번을 모시겠습니다! 백야성의 키팅 성가대!",
  ui_story_5036_50360401_67_dialog_content = "그런 거였구나.",
  ui_story_5036_50360401_68_dialog_content = "하지만 좀처럼 드문 기횐데, 포기해 버리면 아쉽지 않겠어?",
  ui_story_5036_50360401_69_dialog_content = "그렇게 드문 기회인 이상, 이 기회를 필요로 하는 사람한테 양보해 줘야겠지.",
  ui_story_5036_50360401_70_dialog_content = "에이, 그게 뭐야~",
  ui_story_5036_50360401_71_dialog_content = "응?",
  ui_story_5036_50360401_72_dialog_content = "결국 오디션에 나가는 건 나 혼자란 거잖아?",
  ui_story_5036_50360401_73_dialog_content = "아~ 왠지 알 것 같아!",
  ui_story_5036_50360401_74_dialog_content = "칸타토르호에서 열리는 콘서트 무대를 나중에 백야성에서도 보게 될 거잖아...",
  ui_story_5036_50360401_75_dialog_content = "자기 집 앞마당에서 공연하긴 부끄러워서 그러는 거 맞지?",
  ui_story_5036_50360401_76_dialog_content = "그런 뜻은 아니야...",
  ui_story_5036_50360401_77_dialog_content = "그럼 모두한테 보여 줘.",
  ui_story_5036_50360401_78_dialog_content = "카렌의 진짜 실력을!",
  ui_story_5036_50360401_79_dialog_content = "이게 바로♪",
  ui_story_5036_50360401_80_dialog_content = "우리의 공연♪",
  ui_story_5036_50360401_81_dialog_content = "시작해요♪",
  ui_story_5036_50360401_82_dialog_content = "여러분의 공연♪",
  ui_story_5036_50360401_83_dialog_content = "믿기 어려울 정도로 우아하군!",
  ui_story_5036_50360401_84_dialog_content = "역시 성주님께서 친히 선발하신 아이들답도다!",
  ui_story_5036_50360401_85_dialog_content = "하늘이 내린 목소리로 내 몸과 마음을 깨끗이 정화해 주고 있구나.",
  ui_story_5036_50360401_86_dialog_content = "다른 지역의 서민들이여, 고마운 줄 알아라.",
  ui_story_5036_50360401_87_dialog_content = "이처럼 신성한 노래를 들을 수 있다는 건 신이 내리신 은총이다!",
  ui_story_5036_50360401_88_dialog_content = "어른의 공연♪",
  ui_story_5036_50360401_89_dialog_content = "정말 우습네♪",
  ui_story_5036_50360401_90_dialog_content = "이러쿵 저러쿵♪",
  ui_story_5036_50360401_91_dialog_content = "많기도 해라♪",
  ui_story_5036_50360401_92_dialog_content = "봐라! 평소의 대화에까지 아름다운 멜로디를 더하고 있다!",
  ui_story_5036_50360401_93_dialog_content = "비꼬는 건데 전혀 이해를 못 하나?",
  ui_story_5036_50360401_94_dialog_content = "이게 대체 어떻게 된 일일까요?",
  ui_story_5036_50360401_95_dialog_content = "키팅 역시 만장일치로 여섯 표를 얻어 공연 무대에 바로 진출하게 됐습니다! 축하해요!",
  ui_story_5036_50360401_96_dialog_content = "첫 두 팀이 전부 여섯 표를 받는다고? 어이! 이거 짜고 치는 거 아냐?",
  ui_story_5036_50360401_97_dialog_content = "혹시 참가 번호 3번, 바바라 씨인가요?",
  ui_story_5036_50360401_98_dialog_content = "난 여기 있어!",
  ui_story_5036_50360401_99_dialog_content = "무대를 위해 태어난 아이돌은 바로 나니까,\n소음밖에 낼 줄 모르는 저 여자는 신경 쓸 거 없어!",
  ui_story_5036_50360401_100_dialog_content = "하아? 음정 연습이나 하고 무대에 오르지 그래?",
  ui_story_5036_50360401_101_dialog_content = "내 걱정할 시간에 가서 노래를 어떻게 부르는지나 좀 배워.",
  ui_story_5036_50360401_102_dialog_content = "참가자 두 분, 무대로 올라와 주세요.",
  ui_story_5036_50360401_103_dialog_content = "정말 인정할 수 없어.",
  ui_story_5036_50360401_104_dialog_content = "레디젤 렌치에 어떻게 너처럼 촌스러운 사랑 노래나 부르는 녀석이 있을 수 있지?",
  ui_story_5036_50360401_105_dialog_content = "아니지? 진짜 아니지?",
  ui_story_5036_50360401_106_dialog_content = "레디젤 렌치에 다 너처럼 목이 터져라 큰 소리를 지르는 걸\n좋아하는 사람만 있는 줄 아는 거 아니지?",
  ui_story_5036_50360401_107_dialog_content = "하아? 지금 뭐라고 했냐?",
  ui_story_5036_50360401_108_dialog_content = "다시 말해 봐!",
  ui_story_5036_50360401_109_dialog_content = "어? 왜 무대에서 다른 사람이 노랠 부르고 있는 거지?",
  ui_story_5036_50360401_110_dialog_content = "참가 번호 3번은 난데!",
  ui_story_5036_50360401_111_dialog_content = "죄송해요... 참가 번호 3번 바바라 씨, 그리고 참가 번호 4번 레지나 씨.",
  ui_story_5036_50360401_112_dialog_content = "두 분은 오디션 규정 위반으로 이번 오디션에서 탈락하셨어요.",
  ui_story_5036_50360401_113_dialog_content = "다음 오디션에 다시 신청해 주세요.",
  ui_story_5036_50360401_114_dialog_content = "뭐어어어?!",
  ui_story_5036_50360401_115_dialog_content = "아, 이제 알겠어.",
  ui_story_5036_50360401_116_dialog_content = "가, 갑자기 뭘?",
  ui_story_5036_50360401_117_dialog_content = "바이스 넌 혼자 오디션에 나가게 돼서 외로웠던 거지?",
  ui_story_5036_50360401_118_dialog_content = "쉬잇! 작게 얘기해...",
  ui_story_5036_50360401_119_dialog_content = "좋아, 인정할게.",
  ui_story_5036_50360401_120_dialog_content = "예전엔 항상 우리 셋이서 같이 움직였었잖아.",
  ui_story_5036_50360401_121_dialog_content = "근데 갑자기 나 혼자 단독 행동을 하게 되니까, 솔직히 조금은 쓸쓸하다고 생각했어.",
  ui_story_5036_50360401_122_dialog_content = "음, 좋아.",
  ui_story_5036_50360401_123_dialog_content = "그럼 어쩔 수 없이 내가 어느 외로움쟁이 씨 곁에 있어 줘야겠네.",
  ui_story_5036_50360401_124_dialog_content = "외로움쟁이 아니거든!",
  ui_story_5036_50360401_125_dialog_content = "후훗...",
  ui_story_5036_50360401_126_dialog_content = "휴, 그래도 혼자서 무대에 서는 것보단...",
  ui_story_5036_50360401_127_dialog_content = "바이스 너랑 같이 무대에 섰을 때 그 느낌이 그리운걸.",
  ui_story_5036_50360401_128_dialog_content = "뭐?",
  ui_story_5036_50360401_129_dialog_content = "뜬금없이 예전 일을 그리워하는 거야? 헤헷~",
  ui_story_5036_50360401_130_dialog_content = "음, 아무리 생각해도 그땐 공연을 잘해야겠단 마음이 지금보다 더 강했던 것 같거든.",
  ui_story_5036_50360401_131_dialog_content = "사실 나도 그래...",
  ui_story_5036_50360401_132_dialog_content = "정말 유감스러운 상황이 펼쳐지고 있네요.",
  ui_story_5036_50360401_133_dialog_content = "설마 오늘은 참가 번호 1번, 2번 외엔 콘서트 무대에 설 수 있는\n주인공이 등장하지 않는 걸까요?",
  ui_story_5036_50360401_134_dialog_content = "자, 그럼 이제 오늘의 마지막 참가자를 모시겠습니다!",
  ui_story_5036_50360401_135_dialog_content = "어떤 놀라운 공연을 선보여 주실지 모두 한번 지켜보도록 하죠!",
  ui_story_5036_50360401_136_dialog_content = "심사위원 여러분, 안녕하세요.",
  ui_story_5036_50360401_137_dialog_content = "전 비크라고 해요. 평소엔 환상동물 트레이너 일을 하고 있죠.",
  ui_story_5036_50360401_138_dialog_content = "비크 씨?!",
  ui_story_5036_50360401_139_dialog_content = "어? PlayerName?",
  ui_story_5036_50360401_140_dialog_content = "하하하, 심사위원 중에 아는 사람이 있었네.",
  ui_story_5036_50360401_141_dialog_content = "미리 밝히지만 난 PlayerName 네가 심사위원일 줄은 진짜 몰랐어.",
  ui_story_5036_50360401_142_dialog_content = "진짜 비크 씨야?",
  ui_story_5036_50360401_143_dialog_content = "난 또 내 눈이 잘못됐나 했네! 어쩌다 오디션에 참가한 거야?",
  ui_story_5036_50360401_144_dialog_content = "당연히 아이돌이 되고 싶어서지.\n이렇게 무대에 오를 수 있는 기회는 좀처럼 없잖아.",
  ui_story_5036_50360401_145_dialog_content = "비크 씨가 아이돌이 되고 싶어 하는 줄은 몰랐어.",
  ui_story_5036_50360401_146_dialog_content = "비크 씨는 환상동물 트레이너 쪽에선 업적이 꽤 많지 않아?",
  ui_story_5036_50360401_147_dialog_content = "에이, 환상동물 트레이너라고 아이돌을 하지 말란 법은 없잖아?",
  ui_story_5036_50360401_148_dialog_content = "그러니까 내 말은!",
  ui_story_5036_50360401_149_dialog_content = "지금 이 시대엔 누구나 아이돌이 될 기회가 있어...",
  ui_story_5036_50360401_150_dialog_content = "자신의 무대에서, 열정과 반짝임을 발산하는 거지.",
  ui_story_5036_50360401_151_dialog_content = "「지금 이 시대엔 누구나 아이돌이 될 기회가 있다」고?",
  ui_story_5036_50360401_152_dialog_content = "누구나 다 아이돌이 될 수 있다... 너무 좋은 말인걸.",
  ui_story_5036_50360401_153_dialog_content = "「아이돌」에 대한 마음가짐과 이해가 내 마음에 쏙 들어.\n오디션에서 어떤 모습을 보여줄지 기대하고 있을게!",
  ui_story_5036_50360401_154_dialog_content = "우와! 지금까지 골디 씨의 관심을 끈 참가자는 이분이 처음이네요!",
  ui_story_5036_50360401_155_dialog_content = "그럼 과연 어떤 놀라운 퍼포먼스를 보여 줄까요?",
  ui_story_5036_50360401_156_dialog_content = "비크 씨, 시작해 주세요.",
  ui_story_5036_50360401_157_dialog_content = "그럼 모두를 위해 좋은 글귀를 하나 읽어 드리죠. 크흠...",
  ui_story_5036_50360401_158_dialog_content = "아! 봄이 되었네. 만물이 소생하네~",
  ui_story_5036_50360401_159_dialog_content = "다시 찾아왔네. 환상동물이 생명을 뽐내는 계절이.",
  ui_story_5036_50360401_160_dialog_content = "(...이, 이런 것도 퍼포먼스로 쳐 주는 거였나?)",
  ui_story_5036_50360401_161_dialog_content = "(근데 뭔가 내용이 비크 씨가 쓴 《환상동물 대백과》 같은데?)",
  ui_story_5036_50360401_162_dialog_content = "보아라! 숲에도, 광야에도, 그 어떤 곳에도 생명의 환희가 가득한 모습을.",
  ui_story_5036_50360401_163_dialog_content = "그러나 이러한 순간에도, 유난히 냉정한 환상동물이 하나 있으니...",
  ui_story_5036_50360401_164_dialog_content = "아스트라 대륙에서 가장 <color=#FFB400>장수</color>하는 환상동물, <color=#FFB400>우로보로스</color>가 바로 그것이다.",
  ui_story_5036_50360401_165_dialog_content = "그들은 성숙한 상태가 될 때까지 성장한 후...",
  ui_story_5036_50360401_166_dialog_content = "실례합니다! 잠깐 끊었다가 다시 갈게요!",
  ui_story_5036_50360401_167_dialog_content = "심사위원분들이 물어보시는데요. 혹시 다른 퍼포먼스도 준비해 오셨나요?",
  ui_story_5036_50360401_168_dialog_content = "정말 미안하지만, 오늘 준비한 건 이 낭독이 다야.",
  ui_story_5036_50360401_169_dialog_content = "그래? 정말 아쉬운걸.",
  ui_story_5036_50360401_170_dialog_content = "표현력은 참 좋지만, 우리 콘서트랑은 형식이나 내용이 잘 안 맞는 것 같아.",
  ui_story_5036_50360401_171_dialog_content = "그렇지만 너무 풀 죽진 마!",
  ui_story_5036_50360401_172_dialog_content = "내 경험으로 봤을 때 당신은 음색도 좋고 비주얼도 훌륭한 편이니까.",
  ui_story_5036_50360401_173_dialog_content = "춤이랑 노래 쪽으로 장르를 바꾸면 틀림없이 상당한 성적을 거둘 수 있을 거야.",
  ui_story_5036_50360401_174_dialog_content = "지금 연예계에서 활약 중인 선배들만큼의 반응을 얻는 것도 무리가 아닐걸!",
  ui_story_5036_50360401_175_dialog_content = "그러니 앞으로 진행될 오디션에선 다른 퍼포먼스를 볼 수 있었으면 좋겠어.",
  ui_story_5036_50360401_176_dialog_content = "당신이 어떻게 발전할지 기대하고 있을게. 파이팅!",
  ui_story_5036_50360401_177_dialog_content = "아, 그럼 어쩔 수 없이 다른 쪽으로 도전해 볼 수밖에 없겠네.",
  ui_story_5036_50360401_178_dialog_content = "(골디가 무슨 보석을 발견하기라도 한 것처럼 비크 씨를 보고 있는데?)",
  ui_story_5036_50360401_179_dialog_content = "(설마 비크 씨가 진짜로 아이돌에 재능이 있는 건가?!)",
  ui_story_5036_50360401_180_dialog_content = "오늘 오디션은 여기까지입니다.\n참가자 여러분, 심사위원 여러분, 모두 수고 많으셨습니다~",
  ui_story_5036_50360401_181_dialog_content = "앞으로 진행될 오디션도 많이 기대해 주세요.",
  ui_story_5036_50360401_182_dialog_content = "그럼 내일 다시 뵙겠습니다!",
  ui_story_5036_50360401_183_dialog_content = "PlayerName, 오디션은 끝난 거야?",
  ui_story_5036_50360401_184_dialog_content = "응, 원래는 가벼운 마음으로 사람들 공연을 보기만 하면 될 줄 알았는데,\n하루 종일 보려니까 그것도 꽤 힘드네.",
  ui_story_5036_50360401_185_dialog_content = "그나저나 두 사람은 왜 안 나온 거야?",
  ui_story_5036_50360401_186_dialog_content = "조금 더 합을 맞춰 보고, 준비가 되면 다시 참가할 생각이야.",
  ui_story_5036_50360401_187_dialog_content = "합을 맞춘다고?",
  ui_story_5036_50360401_188_dialog_content = "응, 아무리 생각해도 둘이서 같이 공연하는 게 더 재미있을 것 같거든.",
  ui_story_5036_50360401_189_dialog_content = "그러다 눈 튀어나오겠어, PlayerName. 네가 들은 게 맞아.",
  ui_story_5036_50360401_190_dialog_content = "나랑 바이스는 2인조 그룹으로 같이 공연할 거야.",
  ui_story_5036_50360401_191_dialog_content = "2인조 그룹이라니, 정말 좋은 생각이네!",
  ui_story_5036_50360401_192_dialog_content = "무슨 퍼포먼스를 할진 정했어?",
  ui_story_5036_50360401_193_dialog_content = "노래를 부를 거예요. 벌써 몇 곡 정해 놨거든요.",
  ui_story_5036_50360401_194_dialog_content = "하지만 실제로 연습해 봐야 어느 곡을 부를지 선택할 수 있을 것 같아.",
  ui_story_5036_50360401_195_dialog_content = "시간 내에 준비할 수 있을지 모르겠네요...",
  ui_story_5036_50360401_196_dialog_content = "걱정하지 마~ 내 비밀을 하나 알려줄게~",
  ui_story_5036_50360401_197_dialog_content = "사실 나도 콘서트에서 어떤 곡을 부를지 아직 못 정했어. 헤헷.",
  ui_story_5036_50360401_198_dialog_content = "그래도 골디 씨는 자기 노래가 많으니까 그중에서 고르면 되는 거 아닌가요?",
  ui_story_5036_50360401_199_dialog_content = "그건 맞지만, 왠지 칸타토르호의 무대에 어울릴 만한 곡은 아직 없는 것 같거든.",
  ui_story_5036_50360401_200_dialog_content = "음, 그래도 괜찮아. 오늘이나 내일 영감이 샘솟을 수도 있는 거니까!",
  ui_story_5036_50360401_201_dialog_content = "그건 다시 말해서 칸타토르호의 무대를 위해 신곡을 만들겠다는 뜻이겠지?",
  ui_story_5036_50360401_202_dialog_content = "쉿~ 일단 생각은 그렇다는 거야. 후훗.",
  ui_story_5036_50360401_203_dialog_content = "만들 수 있을지 어떨지는 아직 몰라. 그러니까 다들 비밀 꼭 지켜 줘야 해~",
  ui_story_5036_50360401_204_dialog_content = "골디 씨 노래는 전부 직접 창작한 거였어요?",
  ui_story_5036_50360401_205_dialog_content = "진짜 대단하네요!",
  ui_story_5036_50360401_206_dialog_content = "모든 곡을 전부 내가 만든 건 아니야.",
  ui_story_5036_50360401_207_dialog_content = "그냥 가끔 머릿속에 갑자기 멜로디가 떠오를 때가 있거든.",
  ui_story_5036_50360401_208_dialog_content = "그걸 어떻게든 기록해 뒀다가, 구조가 좀 제대로 갖추어진 곡으로 재탄생시키곤 해.",
  ui_story_5036_50360401_209_dialog_content = "근데 머릿속에 떠오른 멜로디라고 해서, 항상 다 내 마음에 드는 건 아니야.",
  ui_story_5036_50360401_210_dialog_content = "머릿속에 떠오르는... 멜로디?",
  ui_story_5036_50360401_211_dialog_content = "♪우우우우...♪",
  ui_story_5036_50360401_212_dialog_content = "♪라랄라라...♪",
  ui_story_5036_50360401_213_dialog_content = "저기, 나 사실 칸타토르호에 가까이 온 뒤부터,\n자꾸 머릿속에 어떤 멜로디가 떠오르고 있거든.",
  ui_story_5036_50360401_214_dialog_content = "멜로디라기보다는, 꼭 누가 노래를 흥얼거리는 것 같은 소리가 들려.",
  ui_story_5036_50360401_215_dialog_content = "뭐?! 진짜?",
  ui_story_5036_50360401_216_dialog_content = "그러고 보면 아이테르는 음악을 사랑하는 종족이라고 들은 적 있어!",
  ui_story_5036_50360401_217_dialog_content = "어쩌면 PlayerName 씨 당신한테 선천적인 음악 창작의 재능이 있는 걸지도 몰라!",
  ui_story_5036_50360401_218_dialog_content = "그, 그래?",
  ui_story_5036_50360401_219_dialog_content = "설마 칸타토르호가 나한테 영감을 주고 있는 걸까?",
  ui_story_5036_50360401_220_dialog_content = "그럴 가능성이 높아!",
  ui_story_5036_50360401_221_dialog_content = "아, 참!",
  ui_story_5036_50360401_222_dialog_content = "칸타토르호는 애초에 아이테르 일족의 유물이잖아.",
  ui_story_5036_50360401_223_dialog_content = "만약 내가 칸타토르호의 무대에서 아이테르가 만든 곡을 부른다면,\n훨씬 더 뜻깊을 것 같아!",
  ui_story_5036_50360401_224_dialog_content = "PlayerName 씨!",
  ui_story_5036_50360401_225_dialog_content = "혹시 괜찮다면 머릿속에 떠오른다는 그 멜로디를 나한테 들려줄 수 있을까?",
  ui_story_5036_50360401_226_dialog_content = "당연히 괜찮지.",
  ui_story_5036_50360401_227_dialog_content = "거기 서라!",
  ui_story_5036_50360401_228_dialog_content = "어? 무슨 일이지?",
  ui_story_5036_50360401_229_dialog_content = "크오오!",
  ui_story_5036_50360401_230_dialog_content = "PlayerName 씨, 상황을 보니까 그 멜로디는 이따가 다시 들어야 될 것 같아!",
  ui_story_5036_50360402_1_dialog_content = "정말 죄송합니다!",
  ui_story_5036_50360402_2_dialog_content = "방금 용병단원 중 하나가 봉쇄 구역에서 암귀를 상대하다 기절해 버려서\n암귀 몇 마리가 도망쳐 나왔습니다.",
  ui_story_5036_50360402_3_dialog_content = "일루미나와 백야성의 병사들이 도움을 줘서 다행이었습니다.",
  ui_story_5036_50360402_4_dialog_content = "기절했다는 그 용병단원은 지금 상태가 어때? 다치진 않았어?",
  ui_story_5036_50360402_5_dialog_content = "골디 양, 안심하세요. 그 친구는 벌써 깨어났고, 크게 다치지도 않았습니다.",
  ui_story_5036_50360402_6_dialog_content = "봉쇄 구역 쪽 암귀를 처리하는 임무가 너무 힘들어서 그런 거야?",
  ui_story_5036_50360402_7_dialog_content = "골디 양의 조언에 따라 모두 충분히 쉬어 주면서 일을 하고 있습니다.\n그래서 그렇게 힘들진 않습니다.",
  ui_story_5036_50360402_8_dialog_content = "그 친구는 피곤해서가 아니라, 식사를 못 해서 쓰러졌던 겁니다.",
  ui_story_5036_50360402_9_dialog_content = "식사는 제공해 준 걸로 알고 있는데, 아니었어?",
  ui_story_5036_50360402_10_dialog_content = "그게 말이죠. 저희가 식사를 받기도 전에 누군가 식사를 훔쳐 가 버린 것 같습니다.",
  ui_story_5036_50360402_11_dialog_content = "누가 훔쳐 갔다구?",
  ui_story_5036_50360402_12_dialog_content = "말도 안 돼?! 설마 나도 당한 건가?",
  ui_story_5036_50360402_13_dialog_content = "병사, 어디 다쳤어?",
  ui_story_5036_50360402_14_dialog_content = "바이스 중위님! 보고드립니다! 다친 곳은 없습니다.",
  ui_story_5036_50360402_15_dialog_content = "그런데 제가 가지고 다니던 배급 식량도 사라져 버렸습니다.",
  ui_story_5036_50360402_16_dialog_content = "네 배급 식량「도」 사라져 버렸다고?",
  ui_story_5036_50360402_17_dialog_content = "네, 요즘 이런 일을 겪는 전우들이 부쩍 늘었습니다.",
  ui_story_5036_50360402_18_dialog_content = "모두의 배급 식량이 알 수 없는 이유로 많이 줄었습니다.",
  ui_story_5036_50360402_19_dialog_content = "그래서 가지고 다니면 조금은 안전하려니 했지만, 결국...",
  ui_story_5036_50360402_20_dialog_content = "암귀랑 싸울 때 실수로 흘렸을 수도 있지 않을까?",
  ui_story_5036_50360402_21_dialog_content = "저희도 그렇게 생각하고 아직 이 일을 상부에 보고하진 않았습니다.",
  ui_story_5036_50360402_22_dialog_content = "<color=#FFB400>「유령 도둑」</color>... 이건 분명 「유령 도둑」이 벌인 짓입니다!",
  ui_story_5036_50360402_23_dialog_content = "「유령 도둑」?",
  ui_story_5036_50360402_24_dialog_content = "카렌 전하, 아직 모르셨군요.\n이 콜로서스에는 「유령 도둑」이 하나 있습니다!",
  ui_story_5036_50360402_25_dialog_content = "「유령 도둑」은 사람을 쥐도 새도 모르게 기절시킬 수 있습니다.",
  ui_story_5036_50360402_26_dialog_content = "그리고 그 사람이 가지고 있던 값진 물건을 감쪽같이 훔쳐 가 버립니다!",
  ui_story_5036_50360402_27_dialog_content = "제가 가지고 다니던 보석 장식 회중시계도 그렇게 잃어버린 겁니다.",
  ui_story_5036_50360402_28_dialog_content = "음식과 보석을 훔친다?",
  ui_story_5036_50360402_29_dialog_content = "암귀의 소행이라는 생각은 안 드네.",
  ui_story_5036_50360402_30_dialog_content = "도둑이라...",
  ui_story_5036_50360402_31_dialog_content = "왜 그 도둑의 범행 방식이 뭔가 익숙하지?",
  ui_story_5036_50360402_32_dialog_content = "왠지 나도 어디서 그런 상황을 겪어 본 것 같은데...",
  ui_story_5036_50360402_33_dialog_content = "설마 표류하는 콜로서스에 상습 절도범이 섞여 들어왔단 거야?",
  ui_story_5036_50360402_34_dialog_content = "골디 양, 사실 저희 용병단 단원들도 비슷한 일을 겪었습니다.",
  ui_story_5036_50360402_35_dialog_content = "그리고 저희뿐만 아니라 사탕과 음료 등을 많이 잃어버렸다며\n불만을 표시하는 참가자들도 있었습니다.",
  ui_story_5036_50360402_36_dialog_content = "말도 안 돼! 대체 왜 하늘 위까지 와서 나쁜 짓을 하는 거야?!",
  ui_story_5036_50360402_37_dialog_content = "그 도둑 때문에 오디션 참가자들 사이에 안 좋은 분위기가 조성될 수도 있어.",
  ui_story_5036_50360402_38_dialog_content = "카렌 말이 맞아요. 좀도둑 때문에 참가자들이 주최 측에 대한\n신뢰를 잃지 않도록 얼른 조치를 취하는 게 좋을 것 같아요.",
  ui_story_5036_50360402_39_dialog_content = "용병 씨, 번거롭겠지만 움브라톤으로 사람을 보내서 음식이랑 음료를 좀 사다 줘.",
  ui_story_5036_50360402_40_dialog_content = "칸타토르호에 있는 참가자들이랑 병사들 모두 먹고 마실 수 있을 정도의 양이여야 해.",
  ui_story_5036_50360402_41_dialog_content = "그럼 양이 꽤 될 테니 사람을 몇 명 더 보내는 편이 좋겠군요.",
  ui_story_5036_50360402_42_dialog_content = "부탁해. 이 비용은 장부에 기록해 뒀다가 따로 청구하면 돼.",
  ui_story_5036_50360402_43_dialog_content = "알겠습니다!",
  ui_story_5036_50360402_44_dialog_content = "......",
  ui_story_5036_50360402_45_dialog_content = "골디, 괜찮아?",
  ui_story_5036_50360402_46_dialog_content = "......",
  ui_story_5036_50360402_47_dialog_content = "골디?",
  ui_story_5036_50360402_48_dialog_content = "어? ...응! 내 걱정은 안 해도 돼~",
  ui_story_5036_50360402_49_dialog_content = "카렌 씨랑 바이스 씨도 이 일엔 마음 쓰지 말고, 오디션 준비에 최선을 다해 줘~",
  ui_story_5036_50360402_50_dialog_content = "내가 꼭...",
  ui_story_5036_50360402_51_dialog_content = "아무도 이 콘서트를 방해하지 못하게 할 테니까!",
  ui_story_5036_50360501_1_dialog_content = "용병단 여러분.",
  ui_story_5036_50360501_2_dialog_content = "이게 대체 무슨 짓이야!",
  ui_story_5036_50360501_3_dialog_content = "무대를... 너무 환상적으로 잘 지어 줬잖아!",
  ui_story_5036_50360501_4_dialog_content = "칸타토르호에 있던 스크린들도 깨끗하게 다 닦아준 데다가,\n다양한 색상으로 바꿀 수 있는 조명까지 설치해 줬구나!",
  ui_story_5036_50360501_5_dialog_content = "이거 진짜로 빈말이 아냐.",
  ui_story_5036_50360501_6_dialog_content = "이 무대는 내가 움브라톤에서 봤던 그 어떤 무대들보다도\n가슴 벅차게 만드는 것 같아!",
  ui_story_5036_50360501_7_dialog_content = "인정해 주셔서 감사합니다, 골디 양.",
  ui_story_5036_50360501_8_dialog_content = "저희는 그저 샤엘 사장님의 지시에 따랐을 뿐입니다.",
  ui_story_5036_50360501_9_dialog_content = "그게 다가 아닌 거 알아.",
  ui_story_5036_50360501_10_dialog_content = "샤엘 사장님이 그랬었어. 일을 얼렁뚱땅 대충대충 처리하는 용병단이 많다고.",
  ui_story_5036_50360501_11_dialog_content = "근데 백화 용병단만큼은 매번 진지하고 꼼꼼하게 일을 처리해 줘서 믿음이 간다고 하셨어.",
  ui_story_5036_50360501_12_dialog_content = "정말 아쉽네...",
  ui_story_5036_50360501_13_dialog_content = "이렇게 예쁜 무대를 딱 한 번밖에 못 쓰다니 말이야.",
  ui_story_5036_50360501_14_dialog_content = "혹시 골디 양이 필요하시다면...",
  ui_story_5036_50360501_15_dialog_content = "나중에 움브라톤에도 이것과 똑같은 무대를 만들어 드릴 수 있습니다.",
  ui_story_5036_50360501_16_dialog_content = "나중에?",
  ui_story_5036_50360501_17_dialog_content = "그때도 내가 아이돌을 계속할 수 있다면...",
  ui_story_5036_50360501_18_dialog_content = "네?",
  ui_story_5036_50360501_19_dialog_content = "이 얘긴 그만하자. 도둑에 대한 새로운 단서는 없어?",
  ui_story_5036_50360501_20_dialog_content = "아직까진 없습니다.",
  ui_story_5036_50360501_21_dialog_content = "상당히 교활한 녀석인지, 지금까지 아무런 단서도 찾지 못했습니다.",
  ui_story_5036_50360501_22_dialog_content = "파악한 점이라곤 물건들이 대부분 밤에 사라졌다는 점 하나뿐입니다.",
  ui_story_5036_50360501_23_dialog_content = "그거면 됐어.",
  ui_story_5036_50360501_24_dialog_content = "나도 같이 야간 순찰에 참여해 경비를 강화할게.",
  ui_story_5036_50360501_25_dialog_content = "골디 양도 함께 순찰을 도실 생각입니까?",
  ui_story_5036_50360501_26_dialog_content = "후훗, 대세 아이돌인 날 달가워하지 않는 건 용병 씨가 처음인 것 같은데?",
  ui_story_5036_50360501_27_dialog_content = "그럴 리가요! 전 단지 골디 양이 곡을 만들 시간을 저희가 뺏는 게\n아닐까 걱정이 돼서 그런 겁니다.",
  ui_story_5036_50360501_28_dialog_content = "용병 씨, 대세 아이돌의 실력을 얕보지 말아 줘!",
  ui_story_5036_50360501_29_dialog_content = "난 무대 위에서 공연할 수 있는 곡은 아주 많이 가지고 있거든.",
  ui_story_5036_50360501_30_dialog_content = "아이테르의 멜로디로 신곡을 하나 만들고 싶긴 하지만...",
  ui_story_5036_50360501_31_dialog_content = "PlayerName 씨가 흥얼거린 멜로디도 딱 한 소절뿐이라서,\n나도 아직 어떻게 곡을 쓸지 잘 모르겠어.",
  ui_story_5036_50360501_32_dialog_content = "멜로디 말씀이십니까?",
  ui_story_5036_50360501_33_dialog_content = "궁금해?",
  ui_story_5036_50360501_34_dialog_content = "고, 골디 양이 그걸 부르는 걸 듣고 싶단 얘기는 아니었습니다!",
  ui_story_5036_50360501_35_dialog_content = "그래? 난 오히려 새로 만든 이 무대에 올라온 김에 몰래 조금 불러 보고 싶어졌는데.",
  ui_story_5036_50360501_36_dialog_content = "♪라랄라...♪",
  ui_story_5036_50360501_37_dialog_content = "♪라랄라... 라라라...♪",
  ui_story_5036_50360501_38_dialog_content = "크오오오──!",
  ui_story_5036_50360501_39_dialog_content = "전에 도망쳤다던 암귀들이 무대 아래에 숨어 있었던 거야?!",
  ui_story_5036_50360501_40_dialog_content = "지금 골디 양이 그 멜로디를 부르자마자 암귀가 나타난 겁니까?",
  ui_story_5036_50360501_41_dialog_content = "설마 암귀도 「골디락스」인 걸까요?",
  ui_story_5036_50360502_1_dialog_content = "오늘 밤이면 무대 세팅이 정식으로 끝난다고 하던데.",
  ui_story_5036_50360502_2_dialog_content = "누구보다도 먼저 여러 각도에서 전체적인 무대 화면을 촬영해야겠어!",
  ui_story_5036_50360502_3_dialog_content = "내가 원하는 건 사람들의 이목을 단번에 사로잡을 수 있는 쇼킹한 뉴스라고!",
  ui_story_5036_50360502_4_dialog_content = "정말이지, 편집장님은 항상 그렇게 어려운 요구만 하신다니까.",
  ui_story_5036_50360502_5_dialog_content = "대체 그런 쇼킹한 뉴스를 어디 가서 찾아오라는 거야?",
  ui_story_5036_50360502_6_dialog_content = "지금은 최대한 빨리 칸타토르호에 대한 독점 기사를 쓰는 수밖에 없어.",
  ui_story_5036_50360502_7_dialog_content = "어라? 무대에 누가 있나?",
  ui_story_5036_50360502_8_dialog_content = "만약 암귀가 진짜 「골디락스」가 돼 준다면 정말 좋을 텐데.",
  ui_story_5036_50360502_9_dialog_content = "골디 양에게 그런 취미가 있는 줄은 몰랐네요.",
  ui_story_5036_50360502_10_dialog_content = "무슨 생각을 하는 거야?!",
  ui_story_5036_50360502_11_dialog_content = "죄, 죄송합니다!",
  ui_story_5036_50360502_12_dialog_content = "후훗~ 자세히 말을 안 한 내 탓이야.",
  ui_story_5036_50360502_13_dialog_content = "내 말은 그러니까, 암귀들도 내 노래를 듣고 이해해 줬으면 좋았겠다는 뜻이었어.",
  ui_story_5036_50360502_14_dialog_content = "사랑과 평화를 간절히 바라는 노래 가사를 듣다 보면,\n암귀들한테도 이런 감정들이 전파돼서...",
  ui_story_5036_50360502_15_dialog_content = "지금처럼 야만적이고 잔인한 살육을 멈출 수도 있잖아.",
  ui_story_5036_50360502_16_dialog_content = "헤헷, 이렇게 말하면 너무 자신만만해 보이려나?",
  ui_story_5036_50360502_17_dialog_content = "「전파」, 「야만」, 「살육」?",
  ui_story_5036_50360502_18_dialog_content = "(골디 씨가 지금 무슨 얘길 하고 있는 거지? 너무 멀어서 잘 안 들려.)",
  ui_story_5036_50360502_19_dialog_content = "(들킬 위험이 좀 있지만 몇 걸음 더 가까이 가 봐야겠어!)",
  ui_story_5036_50360502_20_dialog_content = "<color=#e8d9bb>퍽!</color>",
  ui_story_5036_50360502_21_dialog_content = "(제발! 어떻게 운이 이렇게도 없는 거냐고...)",
  ui_story_5036_50360502_22_dialog_content = "(발걸음을 떼자마자 옆에 있는 상자를 차 버리는 건 뭔데?)",
  ui_story_5036_50360502_23_dialog_content = "(이 정도 소리면 무대 위에 있는 사람들한테도 들렸을까?)",
  ui_story_5036_50360502_24_dialog_content = "(휴우... 보니까 아직 안 들킨 것 같네.)",
  ui_story_5036_50360502_25_dialog_content = "누구야?!",
  ui_story_5036_50360502_26_dialog_content = "(어라?!)",
  ui_story_5036_50360502_27_dialog_content = "(여, 역시 들켰나?)",
  ui_story_5036_50360502_28_dialog_content = "(괜찮아... 골디 씨한테 우연히 지나가던 거라고 설명하면 분명히...)",
  ui_story_5036_50360502_29_dialog_content = "(날 믿어 주겠지?)",
  ui_story_5036_50360502_30_dialog_content = "<color=#e8d9bb>투둑!</color>",
  ui_story_5036_50360502_31_dialog_content = "어딜 도망가!",
  ui_story_5036_50360502_32_dialog_content = "(어? 어어? 어라?)",
  ui_story_5036_50360502_33_dialog_content = "(골디 씨가 다른 방향으로 보면서 소릴 치고 있잖아?)",
  ui_story_5036_50360502_34_dialog_content = "(근처에 나 말고 다른 사람도 숨어 있었던 건가?)",
  ui_story_5036_50360502_35_dialog_content = "골디 양, 정찰병보다도 훨씬 더 예리한 감각을 가지고 계시는군요!",
  ui_story_5036_50360502_36_dialog_content = "바닥 아래에 진짜로 누가 숨어 있을 줄은 몰랐습니다.",
  ui_story_5036_50360502_37_dialog_content = "아쉽지만 이 판자를 뜯어내는 사이에 그 누군가는 벌써 도망쳐 버렸어.",
  ui_story_5036_50360502_38_dialog_content = "여기 보시죠. 반 정도 먹은 건조식품이 남아 있습니다.",
  ui_story_5036_50360502_39_dialog_content = "포장지를 보니 일루미나 배급 식량 같군요.",
  ui_story_5036_50360502_40_dialog_content = "일루미나의 배급 식량?",
  ui_story_5036_50360502_41_dialog_content = "하지만 일루미나의 병사들한텐 무대 쪽 일을 맡긴 게 없을 텐데?",
  ui_story_5036_50360502_42_dialog_content = "네, 요즘 이런 일을 겪는 전우들이 부쩍 늘었습니다.",
  ui_story_5036_50360502_43_dialog_content = "모두의 배급 식량이 알 수 없는 이유로 많이 줄었습니다.",
  ui_story_5036_50360502_44_dialog_content = "설마...",
  ui_story_5036_50360502_45_dialog_content = "<color=#e8d9bb>휭──</color>",
  ui_story_5036_50360502_46_dialog_content = "음? 방금 그거, 생쥐인가요?",
  ui_story_5036_50360502_47_dialog_content = "아니! 쥐가 아니야!",
  ui_story_5036_50360502_48_dialog_content = "마시멜로, 방금 튀어나온 조그마한 거 봤지?",
  ui_story_5036_50360502_49_dialog_content = "얼른 쫓아가!",
  ui_story_5036_50360502_50_dialog_content = "멍! 멍멍멍!",
  ui_story_5036_50360502_51_dialog_content = "하이?",
  ui_story_5036_50360502_52_dialog_content = "하이하이!",
  ui_story_5036_50360502_53_dialog_content = "마시멜로, 붙잡지는 말고 바짝 따라가기만 하면 돼.\n우린 잔챙이를 낚는 게 목적이 아니니까.",
  ui_story_5036_50360502_54_dialog_content = "저 자그마한 녀석이 우리가 <color=#FFB400>「대어」</color>를 낚을 수 있게 도와줄지 한번 보자.",
  ui_story_5036_50360502_55_dialog_content = "하이──!",
  ui_story_5036_50360502_56_dialog_content = "어...라?",
  ui_story_5036_50360502_57_dialog_content = "비카, 너 아까 내가 찾을 때는 아는 척도 안 하더니.",
  ui_story_5036_50360502_58_dialog_content = "왜 갑자기 찰싹 달라붙는 거야?",
  ui_story_5036_50360502_59_dialog_content = "멍!",
  ui_story_5036_50360502_60_dialog_content = "콜록, 개를 멋대로 풀어놓으면 어떡해?",
  ui_story_5036_50360502_61_dialog_content = "우리 비카는 무척 예민해서 굉장히 쉽게 긴장해 버린다고.\n긴장해 버리면 위장 쪽에 쉽게 문제가...",
  ui_story_5036_50360502_62_dialog_content = "당신이 바로 유령 도둑이었어?",
  ui_story_5036_50360502_63_dialog_content = "유령? 그렇게 말하면 곤란하지.",
  ui_story_5036_50360502_64_dialog_content = "못 믿겠어? 그럼 내가 날 한 번 콱 물어볼게. 에잇!",
  ui_story_5036_50360502_65_dialog_content = "으윽... 아야야! 아파!",
  ui_story_5036_50360502_66_dialog_content = "봤지? 유령은 통증을 못 느끼잖아? 근데 난 멀쩡히 살아 있는 사람이라 아픔을 느껴.",
  ui_story_5036_50360502_67_dialog_content = "(이 사람이랑 얘기하는 건 피곤할 것 같네.)",
  ui_story_5036_50360502_68_dialog_content = "(근데 왠지 어디서 들어 본 목소리잖아?)",
  ui_story_5036_50360502_69_dialog_content = "유령이든 아니든, 내 콘서트를 방해하려는 나쁜 녀석은 절대 가만두지 않을 거야!",
  ui_story_5036_50360502_70_dialog_content = "그러니까 순순히 사실대로 말하는 게 좋을걸!",
  ui_story_5036_50360502_71_dialog_content = "<color=#e8d9bb>찰랑!</color>",
  ui_story_5036_50360502_72_dialog_content = "이건 그냥 장식이 아니라구!",
  ui_story_5036_50360502_73_dialog_content = "어, 음...",
  ui_story_5036_50360502_74_dialog_content = "우리 좋게 말로 하자. 네가 윽박지르니까 내가 내 발에 걸려서 넘어질 뻔했잖아.",
  ui_story_5036_50360502_75_dialog_content = "옷이 불룩한 걸 보니, 그 안에 훔친 물건들을 넣어 둔 모양이지?!",
  ui_story_5036_50360502_76_dialog_content = "이 안에 들은 건 내가 방금 막 길들인 환상동물이야. 지금은 쉬고 있는 중이고.",
  ui_story_5036_50360502_77_dialog_content = "전혀 못 믿겠는데?",
  ui_story_5036_50360502_78_dialog_content = "휴, 그럼 넌 타인에 대한 이해심을 더 길러 보는 게 좋을 것 같네.",
  ui_story_5036_50360502_79_dialog_content = "평소에 책도 읽고, 신문도 보고, 기회가 되면 가서 봉사 활동도 좀 하고...\n내가 해 줄 수 있는 조언은 이게 다야.",
  ui_story_5036_50360502_80_dialog_content = "하하, 그럼 다른 볼일 없으면 먼저 실례할게.",
  ui_story_5036_50360502_81_dialog_content = "그 옷 안에 뭐가 들었는지 당장 보여 줘!",
  ui_story_5036_50360502_82_dialog_content = "뭐?! 지금은 날도 어둡고 바람도 많이 불어서 제대로 보이지도 않을 텐데...",
  ui_story_5036_50360502_83_dialog_content = "그래도 난 결백하니까 체면에도 신경을 좀 쓰긴 해야겠지.",
  ui_story_5036_50360502_84_dialog_content = "마시멜로! 달려들어!",
  ui_story_5036_50360502_85_dialog_content = "멍멍!",
  ui_story_5036_50360502_86_dialog_content = "조, 조심해!",
  ui_story_5036_50360502_87_dialog_content = "<color=#e8d9bb>퍽!</color>",
  ui_story_5036_50360502_88_dialog_content = "으... 여, 역시 넘어져 버렸네.",
  ui_story_5036_50360502_89_dialog_content = "음? 이 사람은 오늘 오디션에 나왔던 참가자 아닙니까?",
  ui_story_5036_50360502_90_dialog_content = "역시 오디션 참가를 핑계로 몰래 숨어 들어왔던 거였어.",
  ui_story_5036_50360502_91_dialog_content = "으, 아야야야야...",
  ui_story_5036_50360502_92_dialog_content = "어라...? 당신이었어?",
  ui_story_5036_50360502_93_dialog_content = "구구구구!",
  ui_story_5036_50360502_94_dialog_content = "아? 저 사람 품에서 부엉이가 한 마리 나왔는데요?",
  ui_story_5036_50360502_95_dialog_content = "훔친 물건이 아니었네? 내가 괜한 의심을 한 거야?",
  ui_story_5036_50360502_96_dialog_content = "애초에 난 결백하다고 했었잖아.",
  ui_story_5036_50360502_97_dialog_content = "<color=#e8d9bb>후두두둑── 땡그랑...</color>",
  ui_story_5036_50360502_98_dialog_content = "어... 부엉이의 깃털에서 보석과 장신구들이 떨어졌네요.",
  ui_story_5036_50360502_99_dialog_content = "헤헤헤, 거봐, 난 도둑이 아니라고 했잖아.",
  ui_story_5036_50360502_100_dialog_content = "으이구, 가골빼미야. 왜 그랬어? 왜 물건들을 훔친 거야?",
  ui_story_5036_50360502_101_dialog_content = "구구...",
  ui_story_5036_50360502_102_dialog_content = "왜 훔쳤냐고? 지금 증거가 이렇게 확실한데도 변명을 하겠다는 거야?!",
  ui_story_5036_50360502_103_dialog_content = "마, 말로 하자니까!",
  ui_story_5036_50360502_104_dialog_content = "절대 용서 못 해!",
  ui_story_5036_50360502_105_dialog_content = "으악...",
  ui_story_5036_50360502_106_dialog_content = "골디 양?!",
  ui_story_5036_50360502_107_dialog_content = "걱정하지 마. 그냥 잠깐 기절하게 만든 거니까.",
  ui_story_5036_50360502_108_dialog_content = "이 사람은 밑도 끝도 없이 말을 돌리기만 하잖아.\n지금 우린 상대해 줄 기운도, 시간도 없어.",
  ui_story_5036_50360502_109_dialog_content = "일단 이 사람을 데려가 줘. 바쁜 일들이 마무리되고 나면 제대로 심문해 보자.",
  ui_story_5036_50360502_110_dialog_content = "<color=#e8d9bb>찰칵!</color>",
  ui_story_5036_50360502_111_dialog_content = "그렇구나...",
  ui_story_5036_50360502_112_dialog_content = "골디 씨가 폭력적인 사람이라는 소문이 가짜가 아니었던 건가?",
  ui_story_5036_50360502_113_dialog_content = "이 사진이 있으면 난...",
  ui_story_5036_50360601_1_dialog_content = "또 뭔데 그래?",
  ui_story_5036_50360601_2_dialog_content = "찾았어요! 사람들의 이목을 단번에 사로잡을 수 있는 쇼킹한 뉴스 말이에요!",
  ui_story_5036_50360601_3_dialog_content = "내 시간을 낭비하게 만들지 않는 게 좋을 거다.",
  ui_story_5036_50360601_4_dialog_content = "확실해요! 분명히 마음에 들어 하실 거예요!",
  ui_story_5036_50360601_5_dialog_content = "편집장님도 골디 씨가 폭력적이라는 소문 들어본 적 있으시죠?",
  ui_story_5036_50360601_6_dialog_content = "(여, 여긴 어디지...?)",
  ui_story_5036_50360601_7_dialog_content = "(어? 내가 언제 헤븐즈 밸리로 돌아온 거야? 분명히 아까까지만 해도...)",
  ui_story_5036_50360601_8_dialog_content = "(...내가 어디 있었더라?)",
  ui_story_5036_50360601_9_dialog_content = "♪라랄라... 라라라...♪",
  ui_story_5036_50360601_10_dialog_content = "(...이 멜로디! 이 멜로디 기억나!)",
  ui_story_5036_50360601_11_dialog_content = "♪우우우우...♪",
  ui_story_5036_50360601_12_dialog_content = "(누가 부르고 있는 거지?)",
  ui_story_5036_50360601_13_dialog_content = "<color=#e8d9bb>휘잉!</color>",
  ui_story_5036_50360601_14_dialog_content = "(뭔가 날아갔는데? 콜로서스인가?)",
  ui_story_5036_50360601_15_dialog_content = "(따라가 봐야겠어.)",
  ui_story_5036_50360601_16_dialog_content = "♪라랄라라...♪",
  ui_story_5036_50360601_17_dialog_content = "♪우우우우...♪",
  ui_story_5036_50360601_18_dialog_content = "♪라라... 라라라라...♪",
  ui_story_5036_50360601_19_dialog_content = "(앞에 어떤 소녀가 있네. 계속 노래를 부르던 게 바로 이 소녀였구나.)",
  ui_story_5036_50360601_20_dialog_content = "왔니?",
  ui_story_5036_50360601_21_dialog_content = "(어? 나한테 말 거는 건가?)",
  ui_story_5036_50360601_22_dialog_content = "츄우우!",
  ui_story_5036_50360601_23_dialog_content = "(콜로서스랑 엄청 닮은 동물한테 말을 걸고 있던 거였구나.)",
  ui_story_5036_50360601_24_dialog_content = "또 내 노래를 들으러 온 거니? 넌 내 공연을 정말 좋아하는구나.",
  ui_story_5036_50360601_25_dialog_content = "음, 그치만 이제 슬슬 이 멜로디에 가사를 붙여 줄 때가 된 것 같아.",
  ui_story_5036_50360601_26_dialog_content = "(입고 있는 옷이랑 분위기를 보면... 이 소녀는 아이테르야, 틀림없어!)",
  ui_story_5036_50360601_27_dialog_content = "(역시! 나 말고도 다른 아이테르를 찾아낼 줄 알았다니까!)",
  ui_story_5036_50360601_28_dialog_content = "음, 목이 조금 마르네.",
  ui_story_5036_50360601_29_dialog_content = "우리 가서 과일 좀 따다 먹을까?",
  ui_story_5036_50360601_30_dialog_content = "츄우우!",
  ui_story_5036_50360601_31_dialog_content = "저기, 잠깐만!",
  ui_story_5036_50360601_32_dialog_content = "잠깐만 기다려!",
  ui_story_5036_50360601_33_dialog_content = "응?",
  ui_story_5036_50360601_34_dialog_content = "<color=#e8d9bb>똑똑똑!</color>",
  ui_story_5036_50360601_35_dialog_content = "잠깐만!",
  ui_story_5036_50360601_36_dialog_content = "어?",
  ui_story_5036_50360601_37_dialog_content = "뭐야, 그냥 꿈이었잖아.",
  ui_story_5036_50360601_38_dialog_content = "<color=#e8d9bb>콘서트 개최 4일 전</color>",
  ui_story_5036_50360601_39_dialog_content = "<color=#e8d9bb>똑똑똑! 똑똑똑!</color>",
  ui_story_5036_50360601_40_dialog_content = "PlayerName, 괜찮아?",
  ui_story_5036_50360601_41_dialog_content = "아, 지금 나갈게!",
  ui_story_5036_50360601_42_dialog_content = "PlayerName, 너무 깊이 잔 거 아냐?",
  ui_story_5036_50360601_43_dialog_content = "한참 동안 문을 세게 두드렸는데, 하나도 안 들렸어?",
  ui_story_5036_50360601_44_dialog_content = "너무 반응이 없길래 혹시라도 암귀가 네 방에 들어갔나 해서...",
  ui_story_5036_50360601_45_dialog_content = "하마터면 바이스와 문을 부수고 들어갈 뻔했어.",
  ui_story_5036_50360601_46_dialog_content = "미안, 미안. 방금 꿈을 꿨거든. 그래서 잠깐 정신이 팔렸었어.",
  ui_story_5036_50360601_47_dialog_content = "휴, 또 꿈이었구나?",
  ui_story_5036_50360601_48_dialog_content = "꿈?",
  ui_story_5036_50360601_49_dialog_content = "응, 카렌, 기억 안 나?",
  ui_story_5036_50360601_50_dialog_content = "PlayerName 얘, 자주 괴상한 꿈을 꾸곤 했잖아.",
  ui_story_5036_50360601_51_dialog_content = "그러고 보니 갑자기 생각났어. 나도 오늘 아침에 기괴한 꿈을 하나 꿨어.",
  ui_story_5036_50360601_52_dialog_content = "꿈에서 헤븐즈 밸리를 봤던 것 같아.",
  ui_story_5036_50360601_53_dialog_content = "그런데 거기 살고 있던 건 PlayerName 네가 아니라, 처음 보는 어떤 소녀였어.",
  ui_story_5036_50360601_54_dialog_content = "뭐?! 나도 같은 꿈을 꿨어!",
  ui_story_5036_50360601_55_dialog_content = "카렌이랑 내가 벌써 이렇게 호흡이 잘 맞을 줄은 몰랐는데?",
  ui_story_5036_50360601_56_dialog_content = "며칠 동안 집중 훈련을 한 효과인가 봐!",
  ui_story_5036_50360601_57_dialog_content = "그치만 나도 두 사람이랑 비슷한 꿈을 꿨는걸.",
  ui_story_5036_50360601_58_dialog_content = "뭐?",
  ui_story_5036_50360601_59_dialog_content = "어떤 소녀가 헤븐즈 밸리에서 노래를 부르고 있는 걸 봤어.",
  ui_story_5036_50360601_60_dialog_content = "요즘 계속 내 머릿속에서 맴돌던 그 멜로디를 흥얼거리고 있더라고!",
  ui_story_5036_50360601_61_dialog_content = "내가 꿈에서 본 여자애는 평범하게 집에서 청소를 하고 있었어. 노래는 안 불렀고.",
  ui_story_5036_50360601_62_dialog_content = "내가 본 소녀는 계속 방에서 책을 읽고 있었어.",
  ui_story_5036_50360601_63_dialog_content = "꿈 내용은 조금씩 차이가 있는 것 같네.",
  ui_story_5036_50360601_64_dialog_content = "같은 경험을 한 사람들은 비슷한 꿈을 꿀 확률이 어느 정도\n존재한다는 이야기를 들은 적 있어.",
  ui_story_5036_50360601_65_dialog_content = "서로 비슷한 경험을 하다 보면 사고방식이 점차 비슷해져서,\n꿈에서 보이는 사물들도 점점 닮아간다는 거야.",
  ui_story_5036_50360601_66_dialog_content = "「낮에 무언가를 생각하면, 꿈에 그게 나타난다」고 하던데,\n바로 이런 경우를 말하는 거겠지.",
  ui_story_5036_50360601_67_dialog_content = "그리고 개개인의 성격은 다르니까, 비슷한 꿈을 꾼다고 해도\n세부적인 부분들은 다소 차이가 있을 거야.",
  ui_story_5036_50360601_68_dialog_content = "뭐야? 그냥 그런 거였어? 괜히 들떴네.",
  ui_story_5036_50360601_69_dialog_content = "그런데 PlayerName, 이렇게 계속 우리랑 얘기하고 있어도 되는 거야?",
  ui_story_5036_50360601_70_dialog_content = "오늘 2차 오디션에서도 심사위원을 맡기로 한 거 아니었어?",
  ui_story_5036_50360601_71_dialog_content = "으악! 깜빡할 뻔했네!",
  ui_story_5036_50360601_72_dialog_content = "♪우우우우...♪",
  ui_story_5036_50360601_73_dialog_content = "♪라라... 라라라라...♪",
  ui_story_5036_50360601_74_dialog_content = "드디어 처음부터 끝까지 알려줄 수 있었네!\n이게 바로 내 머릿속에서 맴돈다고 했던 멜로디야!",
  ui_story_5036_50360601_75_dialog_content = "하─암!",
  ui_story_5036_50360601_76_dialog_content = "내, 내가 너무 못 불렀어?",
  ui_story_5036_50360601_77_dialog_content = "그런 거 아니야~ 어제 잠을 좀 설쳤거든.\nPlayerName 씨 앞에서 안 좋은 모습을 보여버렸네.",
  ui_story_5036_50360601_78_dialog_content = "설마 꿈을 너무 많이 꿔서 잠을 제대로 못 잔 건 아니지?",
  ui_story_5036_50360601_79_dialog_content = "후훗, PlayerName 씨는 상상력이 풍부하구나~",
  ui_story_5036_50360601_80_dialog_content = "어젯밤엔 무대 상황을 체크하러 갔었거든.",
  ui_story_5036_50360601_81_dialog_content = "그리고 봉쇄 구역에도 가서 암귀 처리를 도와주느라 새벽쯤에야 일이 끝났어.",
  ui_story_5036_50360601_82_dialog_content = "그 일들은 백화 용병단한테 맡겼던 거 아니었어?",
  ui_story_5036_50360601_83_dialog_content = "헤헷~ 난 방에 가만히 있질 못하는 타입이거든.",
  ui_story_5036_50360601_84_dialog_content = "그리고 사실 방 안에 있어도 이런저런 걱정을 하곤 해서,\n차라리 직접 일을 좀 처리하는 편이 나아.",
  ui_story_5036_50360601_85_dialog_content = "움브라톤의 대세 아이돌이 될 수 있던 데는 다 이유가 있었구나.\n근데 너무 무리하는 거 아냐?",
  ui_story_5036_50360601_86_dialog_content = "그런 세세한 부분까지 신경 쓰고 말이야!",
  ui_story_5036_50360601_87_dialog_content = "세세한 부분 하나하나가 콘서트의 성공적인 개최에 영향을 주거든.",
  ui_story_5036_50360601_88_dialog_content = "나한테 이번 콘서트는 정말 중요해.\n그러니까 그 어떤 예상 밖의 문제도 용납할 수 없어.",
  ui_story_5036_50360601_89_dialog_content = "골디 넌 모든 콘서트를 꼭 마지막 콘서트처럼 최선을 다하는구나.",
  ui_story_5036_50360601_90_dialog_content = "그, 그런가? 아하하.",
  ui_story_5036_50360601_91_dialog_content = "아무튼, 본론으로 돌아와서!\nPlayerName 씨가 흥얼거린 멜로디는 뭐라고 할까...",
  ui_story_5036_50360601_92_dialog_content = "부드럽고, 편안하면서, 치유되는... 아이테르다운 스타일이었어.\n따라 부르기도 무척 쉬운 편이구!",
  ui_story_5036_50360601_93_dialog_content = "어느 쪽으로든 내가 바라던 그런 음악이야!",
  ui_story_5036_50360601_94_dialog_content = "정말로 내가 이 노래를 무대에서 불러도 괜찮겠어?",
  ui_story_5036_50360601_95_dialog_content = "내가 작곡가가 되는 날이 올 줄은 상상도 못 했어, 마음껏 불러 줘!",
  ui_story_5036_50360601_96_dialog_content = "대세 아이돌이 내 곡을 불러 준다면, 나야말로 영광이지.",
  ui_story_5036_50360601_97_dialog_content = "혹시 좋은 가사도 떠오르는 게 있으면 잊지 말고 알려 줘야 해~",
  ui_story_5036_50360601_98_dialog_content = "참, 그리고 PlayerName 씨한테 물어보고 싶은 게 또 있어.",
  ui_story_5036_50360601_99_dialog_content = "첫 번째 오디션에 나왔던 마지막 참가자 있잖아. 기억해?",
  ui_story_5036_50360601_100_dialog_content = "비크 씨 말하는 거야?",
  ui_story_5036_50360601_101_dialog_content = "그 사람이랑 PlayerName 씨랑 혹시 친구야?",
  ui_story_5036_50360601_102_dialog_content = "음, 난 비크 씨의 제자랑 나름 가까운 사이거든.\n그러니까 비크 씨랑도 아는 친구 사이라고 할 수 있겠지.",
  ui_story_5036_50360601_103_dialog_content = "근데 오디션에 참가할 줄은 진짜 몰랐어.\n그리고 오디션 때도 비크 씨한테 표를 주진 않았어.",
  ui_story_5036_50360601_104_dialog_content = "그러니까 비크 씨 편을 들진 않을까 걱정하진 않아도 돼!",
  ui_story_5036_50360601_105_dialog_content = "혹시 그 사람, 물건 훔치는 습관이 있었어?",
  ui_story_5036_50360601_106_dialog_content = "뭐? 물건을 훔쳐? 왜 그런 걸 물어보는 건데?",
  ui_story_5036_50360601_107_dialog_content = "실은 어젯밤에...",
  ui_story_5036_50360601_108_dialog_content = "살려줘!",
  ui_story_5036_50360601_109_dialog_content = "크오오오──!",
  ui_story_5036_50360601_110_dialog_content = "어딜 도망쳐!",
  ui_story_5036_50360601_111_dialog_content = "암귀가 비크 씨를 쫓고, 용병은 암귀를 쫓고 있네? 이게 대체 무슨 상황이야?",
  ui_story_5036_50360602_1_dialog_content = "골디 씨, PlayerName 씨, 다른 심사위원들은 모두 현장에 도착해서 준비 중이에요.",
  ui_story_5036_50360602_2_dialog_content = "두 분도 괜찮으시다면...",
  ui_story_5036_50360602_3_dialog_content = "살려줘어어어──!",
  ui_story_5036_50360602_4_dialog_content = "슬슬 2차 오디션 현장에 가 보셔야 할 것 같아요.",
  ui_story_5036_50360602_5_dialog_content = "크오오!",
  ui_story_5036_50360602_6_dialog_content = "받아라!",
  ui_story_5036_50360602_7_dialog_content = "아무래도 지금 현장으로 가기 좀 곤란한 상황인 거죠?",
  ui_story_5036_50360602_8_dialog_content = "살려줘어어어!",
  ui_story_5036_50360602_9_dialog_content = "암귀는 이미 쓰러트렸으니까, 더는 소리 안 질러도 돼.",
  ui_story_5036_50360602_10_dialog_content = "허억... 헉... 헉...",
  ui_story_5036_50360602_11_dialog_content = "난 네가 또 날 암귀들이랑 같이 가둬 놓을까 봐 소리 지른 거야!",
  ui_story_5036_50360602_12_dialog_content = "타래 발톱이 긴 덕분에 문에 걸린 자물쇠를 열 수 있긴 했지만 말이야.",
  ui_story_5036_50360602_13_dialog_content = "자칫하면 비명을 지를 기회조차 없었을 거라고.",
  ui_story_5036_50360602_14_dialog_content = "미안! 당신 목숨을 위험하게 만들 생각은 절대 없었어.",
  ui_story_5036_50360602_15_dialog_content = "내가 당신을 가둬 놓을 땐 방 안에 암귀가 없었거든.",
  ui_story_5036_50360602_16_dialog_content = "......",
  ui_story_5036_50360602_17_dialog_content = "골디 양, 암귀는 방 안에 있는 환기구를 통해 기어들어왔습니다.",
  ui_story_5036_50360602_18_dialog_content = "방에 있는 환기구와 봉쇄 구역에 있는 환기구가 서로 이어져 있는 모양입니다.",
  ui_story_5036_50360602_19_dialog_content = "환기구가? 근데 환기구 입구 쪽은 제대로 잠겨 있을 텐데?",
  ui_story_5036_50360602_20_dialog_content = "음, 어떻게 된 건지 알았어.",
  ui_story_5036_50360602_21_dialog_content = "당신, 환기구로 도망치려고 했던 거지? 그러다 암귀를 유인한 거겠지!",
  ui_story_5036_50360602_22_dialog_content = "윽... 하하하.",
  ui_story_5036_50360602_23_dialog_content = "난 방이 너무 더워서 바람을 좀 쐬고 싶었을 뿐이야.",
  ui_story_5036_50360602_24_dialog_content = "대체 무슨 일이야? 비크 씨는 또 왜 가둬 놨던 거고?",
  ui_story_5036_50360602_25_dialog_content = "미안해, PlayerName 씨.",
  ui_story_5036_50360602_26_dialog_content = "하지만 당신 친구 비크 씨가 요 며칠 동안 이곳저곳에서\n물건을 훔쳤던 「유령 도둑」이거든.",
  ui_story_5036_50360602_27_dialog_content = "비크 씨가? 도둑?",
  ui_story_5036_50360602_28_option_content = "그럴 수도 있겠네.",
  ui_story_5036_50360602_29_dialog_content = "책도 출판한 적 있는 환상동물 마스터긴 해도,\n벌써 한참 전에 있었던 일이니까.",
  ui_story_5036_50360602_30_dialog_content = "요즘엔 신간도 안 내서 벌이도 없을 테니,\n절도로 생활을 유지하는 수밖에 없었던 걸까?",
  ui_story_5036_50360602_31_dialog_content = "아무리 신세가 나빠졌다곤 해도, 직접 번 돈으로 생활할 생각을 해야지.",
  ui_story_5036_50360602_32_dialog_content = "남의 호주머니를 털어서 물건을 훔치는 건 절대 안 될 일이야!",
  ui_story_5036_50360602_33_option_content = "그럴 리가 없잖아?!",
  ui_story_5036_50360602_34_dialog_content = "비크 씨는 책도 출판한 적 있는 환상동물 마스터야. 그리고 제자들도 많고.",
  ui_story_5036_50360602_35_dialog_content = "아무리 신세가 나빠졌다곤 해도 이렇게 좀도둑질을 하진 않을걸?",
  ui_story_5036_50360602_36_dialog_content = "PlayerName 씨, 이 사실을 받아들이기 힘들 거란 건 잘 알아.",
  ui_story_5036_50360602_37_dialog_content = "사실 나도 믿을 수가 없어. 이번 일이 있기 전까지만 해도\n난 이 사람이 지닌 잠재력을 높이 평가하고 있었어.",
  ui_story_5036_50360602_38_dialog_content = "하지만 어제 이 사람 주머니에서 사람들이 도둑맞았다고 했던\n음식이랑 보석을 발견했어. 확실한 증거였지.",
  ui_story_5036_50360602_39_dialog_content = "다들 내 얘기 좀 들어 봐...",
  ui_story_5036_50360602_40_dialog_content = "당신의 교묘한 변명은 어제 지겹게 들었어.",
  ui_story_5036_50360602_41_dialog_content = "증거가 이렇게나 많은데, 아직도 잡아뗄 생각이야?",
  ui_story_5036_50360602_42_dialog_content = "그래, 그래. 최근 도난 사건이 전부 내 탓인 건 인정할게.",
  ui_story_5036_50360602_43_dialog_content = "비크 씨가 진짜로 그 「유령 도둑」이었어?!",
  ui_story_5036_50360602_44_dialog_content = "이번 사건이 내 탓은 맞는데, 꼭 짚고 넘어가야 할 점이 있어!",
  ui_story_5036_50360602_45_dialog_content = "나 비크는 저명한 환상동물 마스터로서, 좀도둑질을 한 적은 단 한 번도 없어.",
  ui_story_5036_50360602_46_dialog_content = "요즘 사람들이 말하는 「유령 도둑」은...\n사실 내가 데려온 환상동물이야.",
  ui_story_5036_50360602_47_dialog_content = "하이...",
  ui_story_5036_50360602_48_dialog_content = "구우...",
  ui_story_5036_50360602_49_dialog_content = "뀨우뀨우우, 뀨뀨뀨!",
  ui_story_5036_50360602_50_dialog_content = "당신 어깨 위에 있는 털이 복슬복슬한 녀석이 엄청 흥분한 것 같은데?",
  ui_story_5036_50360602_51_dialog_content = "타래가 「쟤네 둘이 한 거지, 난 아니야!」라고 하네.",
  ui_story_5036_50360602_52_dialog_content = "뀨우!",
  ui_story_5036_50360602_53_dialog_content = "평소엔 내가 매일 이 녀석들한테 다양한 음식들을 준비해 주고 있어.",
  ui_story_5036_50360602_54_dialog_content = "근데 이번엔 너무 바빠서 한 가지 음식밖에 가져오질 못했거든.",
  ui_story_5036_50360602_55_dialog_content = "이 두 녀석이 먹다가 질렸는지 갑자기 나한테 말도 없이 사라져 버렸어.",
  ui_story_5036_50360602_56_dialog_content = "그러다 콜로서스에 좀도둑이 나타났단 소문을 듣고,\n혹시 이 두 녀석이 한 짓이 아닐까 했어.",
  ui_story_5036_50360602_57_dialog_content = "그래서 고생 끝에 꽤 애써서 어젯밤에 드디어 이 두 녀석을 다시 잡아 왔던 거야.",
  ui_story_5036_50360602_58_dialog_content = "그 뒤에 나한테 딱 잡힌 거고?",
  ui_story_5036_50360602_59_dialog_content = "맞아, 솔직히 너무 절묘하지 않아? 하하하.",
  ui_story_5036_50360602_60_dialog_content = "동물들이니까 음식을 훔쳐 먹은 거까진 그렇다 쳐도,\n사람들한테서 보석은 왜 훔친 거야?",
  ui_story_5036_50360602_61_dialog_content = "가골빼미? 가골빼미가 그런 거지?",
  ui_story_5036_50360602_62_dialog_content = "맞아, 가골빼미는 사람을 잠에 빠져들게 만드는 기체를 내뿜을 수 있거든.\n그래서 호신용으로 같이 다녔어.",
  ui_story_5036_50360602_63_dialog_content = "근데 가골빼미는 반짝이는 보석을 모으는 걸 제일 좋아하거든.\n그래서 까딱 잘못해서 한눈이라도 팔면...",
  ui_story_5036_50360602_64_dialog_content = "「사람을 기절시키고 물건을 훔쳐 가는 도둑」으로 변해 버려.",
  ui_story_5036_50360602_65_dialog_content = "하지만 그건 어디까지나 환상동물의 습성 때문이지, 악의가 있어서 그런 건 아냐.",
  ui_story_5036_50360602_66_dialog_content = "잘못이 있는 건 관리를 제대로 하지 못한 나지.",
  ui_story_5036_50360602_67_dialog_content = "보석이랑 돈은 내가 책임지고 주인한테 돌려줄게!",
  ui_story_5036_50360602_68_dialog_content = "그걸로도 부족하다면, 내가 모두한테 정신적 피해 보상비도 낼 테니까.",
  ui_story_5036_50360602_69_dialog_content = "그러니까 이 환상동물은 처벌하지 말아 줘! 정말 고의로 그런 게 아니니까.",
  ui_story_5036_50360602_70_dialog_content = "하이하이하이.",
  ui_story_5036_50360602_71_dialog_content = "......",
  ui_story_5036_50360602_72_dialog_content = "알겠어. 하지만 말한 건 꼭 지키도록 해.",
  ui_story_5036_50360602_73_dialog_content = "물건도 돌려주고, 정중하게 사과하고, 비용도 배상해. 단 하나도 빼놓지 마.",
  ui_story_5036_50360602_74_dialog_content = "그럼 우리 이제 더는 좁고 어두컴컴함 방 안에 안 갇혀 있어도 되는 거지?",
  ui_story_5036_50360602_75_dialog_content = "갑갑해 죽겠어...",
  ui_story_5036_50360602_76_dialog_content = "나와도 좋아.",
  ui_story_5036_50360602_77_dialog_content = "대신 후속 조치를 모두 끝마치고 나면, 그 즉시 칸타토르호를 떠나겠다고 약속해.",
  ui_story_5036_50360602_78_dialog_content = "뭐? 여길 떠날 순 없어. 그럼 아이돌이 되겠다는 내 꿈을 이룰 수 없잖아!",
  ui_story_5036_50360602_79_dialog_content = "골디 씨도 전에 내가 앞으로의 오디션에서 어떤 모습을\n보여 줄지 기대된다고 했었잖아?",
  ui_story_5036_50360602_80_dialog_content = "당신이 아이돌로서 훌륭한 조건을 가지고 있는 건 맞아,\n지금 하고 있는 말도 틀린 건 아니고...",
  ui_story_5036_50360602_81_dialog_content = "근데 난 왠지 그런 느낌이 들어.\n당신이 칸타토르호에 탄 건 오디션을 위해서가 아닌 것 같아. 맞지?",
  ui_story_5036_50360602_82_dialog_content = "!!!",
  ui_story_5036_50360602_83_dialog_content = "...골디 씨가 그렇게 물어본 이상, 나도 숨기지 않고 대답할게.",
  ui_story_5036_50360602_84_dialog_content = "사실 난 우로보로스라는 환상동물을 찾기 위해 여기 온 거야.",
  ui_story_5036_50360602_85_dialog_content = "우로보로스는 어느 정도 성장하고 나면 알의 모습으로 변해.",
  ui_story_5036_50360602_86_dialog_content = "그리고 또 어느 정도 시간이 지나면, 그 알을 깨고 나와.\n계속 그런 방식을 반복하면서 영원히 사는 동물이야.",
  ui_story_5036_50360602_87_dialog_content = "뭐?! 세상에 영원히 살 수 있는 동물이 있단 말이야?!",
  ui_story_5036_50360602_88_dialog_content = "난 어려서부터 내가 우리 부모님의 친자식이 아니란 걸 알고 있었어...",
  ui_story_5036_50360602_89_dialog_content = "그러다 얼마 전에 내 출신과 우로보로스에 모종의 관계가 있다는 사실을 발견했어!\n그래서 난 반드시 우로보로스를 찾아야만 해.",
  ui_story_5036_50360602_89X1_dialog_content = "우로보로스를 찾으면 조사를 통해 내 출신을 확실히 파악하고,\n내 친부모님을 찾을 수 있을지도 몰라.",
  ui_story_5036_50360602_90_dialog_content = "하지만 우로보로스에 관한 기록은 거의 없어. 유일하게 알려진 사실은\n우로보로스가 콜로서스 근처에서 활동하는 걸 무척 좋아한다는 거야.",
  ui_story_5036_50360602_91_dialog_content = "사부, 왜 또 술을 인사불성이 되도록 거야! 빨리 정신 차려!",
  ui_story_5036_50360602_92_dialog_content = "피아는 벌써 PlayerName의 스카이워커호를 포함해서, 이 아스트라 대륙에 있는\n콜로서스 유적이란 유적은 다 뒤져 봤어.",
  ui_story_5036_50360602_93_dialog_content = "근데 우로보로스의 흔적은 쥐꼬리만큼도 없었다구.",
  ui_story_5036_50360602_94_dialog_content = "이 세상에 진짜로 우로보로스란 환상동물이 있긴 한 거야?",
  ui_story_5036_50360602_96_dialog_content = "설마 피아를 또 놀려 먹는 건 아니지?!",
  ui_story_5036_50360602_97_dialog_content = "흥! 앞으론 두 번 다시 우로보로스인지 뭔지 찾는 거 안 도와줄 거야!",
  ui_story_5036_50360602_98_dialog_content = "하지만 아스트라 대륙에 있는 모든 콜로서스 유적을 다 뒤져 봐도\n우로보로스의 흔적은 발견하지 못했어.",
  ui_story_5036_50360602_99_dialog_content = "그래서 하늘을 나는 이 콜로서스에 찾으러 와 볼 수밖에 없었던 거야.",
  ui_story_5036_50360602_100_dialog_content = "그럼 칸타토르호에선 우로보로스의 흔적을 발견했어?",
  ui_story_5036_50360602_101_dialog_content = "아니, 아직은. 하지만 예감이 들어, 아주 강한 예감이.",
  ui_story_5036_50360602_102_dialog_content = "우로보로스는 반드시 이 칸타토르호에 있어!",
  ui_story_5036_50360602_103_dialog_content = "제발 부탁이야! 계속 여기 남아서 우로보로스를 찾을 수 있게 해 줘!",
  ui_story_5036_50360602_104_dialog_content = "나한테 가족의 따뜻함을 느낄 기회를, 가족을 찾을 수 있는 기회를 줬으면 좋겠어!",
  ui_story_5036_50360602_105_dialog_content = "할 말은 다 끝났어?",
  ui_story_5036_50360602_106_dialog_content = "응, 끝났어.",
  ui_story_5036_50360602_107_dialog_content = "후훗, 움브라톤의 삼류 영화보다도 더 허황된 이야기네.",
  ui_story_5036_50360602_108_dialog_content = "덕분에 사물을 보는 시야가 넓어진 것 같아.",
  ui_story_5036_50360602_109_dialog_content = "에헤헤, 별말씀을. 골디 씨가 이렇게 이해심이 많은 사람인 줄은 몰랐네.",
  ui_story_5036_50360602_110_dialog_content = "이럴 줄 알았으면 처음부터 그냥 솔직하게 다 털어놓을걸.",
  ui_story_5036_50360602_111_dialog_content = "자, 그럼 할 말도 다 했으니까.",
  ui_story_5036_50360602_112_dialog_content = "이젠 칸타토르호를 떠날 수 있지?",
  ui_story_5036_50360602_113_dialog_content = "엥?",
  ui_story_5036_50360602_114_dialog_content = "이쪽으로 와, 내가 데려다줄게.",
  ui_story_5036_50360602_115_dialog_content = "잠깐만! 으앗, 아직 할 말이 남았어! 내 말 안 끝났어!",
  ui_story_5036_50360602_116_dialog_content = "방금 그건 그냥 농담 좀 해 본 거야. 하하하하.",
  ui_story_5036_50360602_116X1_dialog_content = "순간적인 센스라든가, 분위기를 조성하는 법이라든가,\n팬들의 마음을 따뜻하게 만들어 주는 것도 아이돌이 갖춰야 할 실력들이잖아.",
  ui_story_5036_50360602_116X2_dialog_content = "그래서 골디 씨한테 내가 이런 쪽에도 능력이 있단 걸 보여 줘서,\n내가 진심으로 오디션에 참가했단 걸 증명하려고 했던 거야~",
  ui_story_5036_50360602_117_dialog_content = "순간적인 센스랑 분위기를 조성하는 법?",
  ui_story_5036_50360602_118_dialog_content = "골디 씨도 내 이야기를 듣고 기쁘게 웃어 줬었잖아?",
  ui_story_5036_50360602_119_dialog_content = "그건...",
  ui_story_5036_50360602_120_dialog_content = "(확실히 그래, 비크 씨는 처음부터 끝까지 내 주의력을 사로잡긴 했어.)",
  ui_story_5036_50360602_121_dialog_content = "(샤엘 사장님이 항상 나한텐 아직 뭔가 부족한 점이 있다고 했었는데,\n그게 설마 비크 씨처럼 사람의 긴장을 풀어 주는 유머 감각이었던 걸까?)",
  ui_story_5036_50360602_124_dialog_content = "난 진심으로 아이돌이 되고 싶어. 그러니까 계속 여기 남아서 도전할 수 있게 해 줘.",
  ui_story_5036_50360602_125_dialog_content = "날 못 믿겠다고 쳐. 그럼 곁에 있는 PlayerName도 못 믿겠어?",
  ui_story_5036_50360602_126_dialog_content = "PlayerName 씨는 이번 콘서트의 VIP야. 당연히 무조건 믿지.",
  ui_story_5036_50360602_127_dialog_content = "그럼 아무 문제도 없겠네.",
  ui_story_5036_50360602_128_dialog_content = "PlayerName, 내가 너무나도 아끼는 제자 피아가\n널 몇 번이나 도와줬었잖아. 그렇지?",
  ui_story_5036_50360602_129_dialog_content = "어, 음... 그렇다고 할 수 있겠지.",
  ui_story_5036_50360602_130_dialog_content = "그럼 어떻게 보면 나도 PlayerName 네 은인인 거잖아?",
  ui_story_5036_50360602_131_dialog_content = "으, 은인?",
  ui_story_5036_50360602_132_dialog_content = "넌 이번에 심사위원도 하고 있으니까, 당연히 내 신원 보증인이 돼 주겠지?",
  ui_story_5036_50360602_133_dialog_content = "......",
  ui_story_5036_50360602_134_dialog_content = "골디 씨, PlayerName 얘가 내 신원 보증인이 돼 줄 거야.",
  ui_story_5036_50360602_135_dialog_content = "얘 체면을 봐서라도 날 쫓아내지 말아 줘. 응?",
  ui_story_5036_50360602_136_dialog_content = "PlayerName 씨, 당신 정말 비크 씨의 신원 보증인이 돼 줄 거야?",
  ui_story_5036_50360602_137_dialog_content = "나...난...",
  ui_story_5036_50360602_138_dialog_content = "PlayerName, 잠깐 귀 좀 빌려줘. 내 말 좀 들어 봐...",
  ui_story_5036_50360602_139_dialog_content = "(칸타토르호의 봉쇄 구역엔 엄청나게 강한 루미나가 있었어. 그걸 네가 못 느꼈단 말이야?)",
  ui_story_5036_50360602_140_dialog_content = "(뭐?!)",
  ui_story_5036_50360602_141_dialog_content = "알고 보니 골디 씨는 어젯밤에 그냥 좀도둑을 잡으려고 했던 거였네...",
  ui_story_5036_50360602_142_dialog_content = "그럼 내가 찍은 사진을 독자들이 보면 골디 씨를 오해하게 되지 않을까?",
  ui_story_5036_50360602_143_dialog_content = "<color=#e8d9bb>지이잉!</color>",
  ui_story_5036_50360602_144_dialog_content = "브랜디, 대체 언제쯤 네가 말한 그 사진을 보낼 거지?",
  ui_story_5036_50360602_145_dialog_content = "편집장님, 이번 일을 다시 제대로 조사해 봐야 할 것 같아요!",
  ui_story_5036_50360602_146_dialog_content = "다시 조사하긴 뭘 다시 조사해?",
  ui_story_5036_50360602_147_dialog_content = "진상이 뭐든 간에 독자의 눈을 사로잡을 수 있는 뉴스가 좋은 뉴스라고!",
  ui_story_5036_50360602_148_dialog_content = "하지만...",
  ui_story_5036_50360602_149_dialog_content = "사진 못 주겠으면, 앞으로 더는 출근하지 마!",
  ui_story_5036_50360602_150_dialog_content = "편집장님? 편집장님!",
  ui_story_5036_50360701_1_dialog_content = "PlayerName 씨, 오늘은 심사평에 점점 전문성이 드러나는 것 같아!",
  ui_story_5036_50360701_2_dialog_content = "진짜 아이돌 프로듀서가 될 수도 있겠어~",
  ui_story_5036_50360701_3_dialog_content = "그치만...",
  ui_story_5036_50360701_4_dialog_content = "비크 씨가 걱정되는 거야?",
  ui_story_5036_50360701_5_dialog_content = "응, 미안해!",
  ui_story_5036_50360701_6_dialog_content = "PlayerName 씨가 신원 보증인이 돼 주기로 했지만, 아무래도 마음이 안 놓여.",
  ui_story_5036_50360701_7_dialog_content = "게다가 근처에 있는 연습실을 배정해 줬는데, 가서 연습이나 제대로 했을지 모르겠어.",
  ui_story_5036_50360701_8_dialog_content = "혹시 다른 사람 연습을 방해하거나 하진 않겠지?",
  ui_story_5036_50360701_9_dialog_content = "안 되겠어. 역시 내가 직접 가서 확인해 보는 게 좋겠어.",
  ui_story_5036_50360701_10_dialog_content = "저기... 내가 가 볼게.",
  ui_story_5036_50360701_11_dialog_content = "내가 신원 보증인이 돼서 여기 계속 남게 된 거니까, 감독할 책임도 나한테 있어.",
  ui_story_5036_50360701_12_dialog_content = "그리고 골디 넌 어제부터 지금까지 쉬지도 못했으니까, 일단 가서 좀 쉬어.",
  ui_story_5036_50360701_13_dialog_content = "응, 그것도 그렇네. 그리고 PlayerName 씨가 알려준 보람이 있다고\n느낄 만한 가사를 적어야 하는데, 아직 다 못 적었거든~",
  ui_story_5036_50360701_14_dialog_content = "그럼 비크 씨에 관한 일은 PlayerName 씨한테 맡길게!",
  ui_story_5036_50360701_15_dialog_content = "하아암~ 뭐라고?",
  ui_story_5036_50360701_16_dialog_content = "오늘은 좀 어때?",
  ui_story_5036_50360701_17_dialog_content = "아주 좋아.",
  ui_story_5036_50360701_18_dialog_content = "잠도 푹 잤고!",
  ui_story_5036_50360701_19_dialog_content = "그게 아니라 연습 상황이 어떠냐고 물어본 거야.",
  ui_story_5036_50360701_20_dialog_content = "설마 하루 종일 잠만 자고 연습은 하나도 안 한 건 아니겠지?",
  ui_story_5036_50360701_21_dialog_content = "내가 설명 안 했었나? 그래, 그럼 다시 한번 얘기해 줄게.",
  ui_story_5036_50360701_22_dialog_content = "우로보로스 이야기는 거짓말이 아니야. 오디션에 참가한 건 그냥 핑계였어.",
  ui_story_5036_50360701_23_dialog_content = "난 그저 그걸 기회로 이 칸타토르호에 탑승해서\n우로보로스를 찾으려고 한 것뿐이야.",
  ui_story_5036_50360701_24_dialog_content = "나도 알아. 근데 칸타토르호의 봉쇄 구역에서 강한 루미나는 전혀 안 느껴졌어.",
  ui_story_5036_50360701_25_dialog_content = "있는 건 그저 잠에 푹 빠진 암귀들뿐이었다고.",
  ui_story_5036_50360701_26_dialog_content = "우로보로스는 알 상태일 땐 루미나를 그렇게 많이 발산하지 않아.",
  ui_story_5036_50360701_27_dialog_content = "그렇게 본다면... 우로보로스는 지금 알로 변한 상태일 게 확실해!",
  ui_story_5036_50360701_28_dialog_content = "근데 왜 「우로보로스는 칸타토르호에 있다」는 걸 전제로 얘기하는 거야?",
  ui_story_5036_50360701_29_dialog_content = "직감이야... 환상동물 마스터의 직감.",
  ui_story_5036_50360701_30_dialog_content = "휴, 결국 증거는 아무것도 없단 소리잖아.",
  ui_story_5036_50360701_31_dialog_content = "이제야 평소에 피아가 어떤 마음이었는지 이해가 가네.",
  ui_story_5036_50360701_32_dialog_content = "내가 봉쇄 구역에 들어갈 수 있게 말 좀 해 주면 안 될까?",
  ui_story_5036_50360701_33_dialog_content = "내, 내가 어떻게 말을 꺼내겠어.",
  ui_story_5036_50360701_34_dialog_content = "골디가 용병단한테 봉쇄 구역의 경비를 강화하라고 한 걸 보면,\n분명히 그 누구든 들어가서 문제를 일으키는 걸 막고 싶은 거겠지.",
  ui_story_5036_50360701_35_dialog_content = "비크 씨가 찾으려는 그 우로보로스가 만약 진짜로 칸타토르호에 있다면,\n콘서트가 끝나고 나서 찾아봐도 되는 거잖아.",
  ui_story_5036_50360701_36_dialog_content = "그럼 콘서트가 끝날 때까지 내가 칸타토르호에 남아 있어도 된다는 거야?",
  ui_story_5036_50360701_37_dialog_content = "그러려면 우선 비크 씨가 오디션에 통과해야지.",
  ui_story_5036_50360701_38_dialog_content = "오디션에서 탈락한 참가자는 바로 여기서 떠나야 해.\n참가 규칙에 다 쓰여 있었을걸.",
  ui_story_5036_50360701_39_dialog_content = "오디션 통과? 그 정돈 눈 감고도 할 수 있어.",
  ui_story_5036_50360701_40_dialog_content = "어? 무대에서 뭘 선보일지 정했어?",
  ui_story_5036_50360701_41_dialog_content = "타래로 묘기를 보여준 다음에 텀블링을 시켜 볼까 하는데, 어때?",
  ui_story_5036_50360701_42_dialog_content = "환상동물 공연? 그건 서커스에서 하는 거잖아요.",
  ui_story_5036_50360701_43_dialog_content = "여긴 아이돌 가수 선발 대회 아니었어요?",
  ui_story_5036_50360701_44_dialog_content = "대회를 잘못 찾아온 거 아니에요?",
  ui_story_5036_50360701_45_dialog_content = "참가자들 사이에 다툼이라도 일어난 건가?",
  ui_story_5036_50360701_46_dialog_content = "다툼이 있는 곳엔 뉴스가 있기 마련이지! 제대로 기록해 둬야겠어!",
  ui_story_5036_50360701_47_dialog_content = "어이, 뭘 두리번거려? 당신 말하는 거야!",
  ui_story_5036_50360701_48_dialog_content = "형씨, 혹시 나 알아?",
  ui_story_5036_50360701_49_dialog_content = "알지.",
  ui_story_5036_50360701_50_dialog_content = "드문 일이네. 이런 곳에서 내 책의 독자를 만나게 될 줄이야!",
  ui_story_5036_50360701_51_dialog_content = "당신이 바로 얼마 전에 잡혔다는 그 「유령 도둑」이잖아.",
  ui_story_5036_50360701_52_dialog_content = "어? 도둑이라면 갇혀 있어야 하는 거 아닌가요?\n근데 왜 여기서 오디션에 나갈 준비를 하고 있는 거죠?",
  ui_story_5036_50360701_53_dialog_content = "그거 완전 인원수 낭비잖아요...",
  ui_story_5036_50360701_54_dialog_content = "어이, 도둑. 잘 들어. 당신이 무슨 수를 쓴 건진 모르겠지만.",
  ui_story_5036_50360701_55_dialog_content = "여기 있는 모든 참가자는 당신이 우리의 무대와 꿈을 망치는 꼴은 절대 못 봐!",
  ui_story_5036_50360701_56_dialog_content = "그러니까 제대로 안 할 거라면, 차라리 일찌감치 꺼져 버려!",
  ui_story_5036_50360701_57_dialog_content = "윽, 다들 좀 진정해...",
  ui_story_5036_50360701_58_dialog_content = "전에 있던 일은 다 오해야. 이제부턴 진지하게 오디션에 참가할 생각이었어.",
  ui_story_5036_50360701_59_dialog_content = "그뿐만 아니라, 오디션에 통과해서 진짜 무대에 올라\n공연하겠다는 결심까지 했다니까~",
  ui_story_5036_50360701_60_dialog_content = "고작 그 서커스 공연 가지고요?",
  ui_story_5036_50360701_61_dialog_content = "에이, 방금 그건 친구끼리 농담 좀 한 거야.",
  ui_story_5036_50360701_62_dialog_content = "내가 믿을 수 있는 장기 하나도 없이 오디션에 신청서를 냈겠어~?",
  ui_story_5036_50360701_63_dialog_content = "그럼 어디 뭘 준비하셨는지 한 번 보여 주시지?",
  ui_story_5036_50360701_64_dialog_content = "맞아!",
  ui_story_5036_50360701_65_dialog_content = "우리한테 네가 뭘 준비했는지 보여 줘!",
  ui_story_5036_50360701_66_dialog_content = "그건...",
  ui_story_5036_50360701_67_dialog_content = "뭐야? 뭘 머뭇거리고 있는 건데!",
  ui_story_5036_50360701_68_dialog_content = "보여 줘! 시작해!",
  ui_story_5036_50360701_69_dialog_content = "재촉 좀 하지 마, 보여 주면 될 거 아냐.",
  ui_story_5036_50360701_70_dialog_content = "크, 크흠. 그럼 드라코리온 댄스를 보여 줄게.",
  ui_story_5036_50360701_71_dialog_content = "이건 드라코리온이 짝을 찾을 때 하늘을 나는 모습을 흉내 낸 춤이야.\n다들 잘 보라고~",
  ui_story_5036_50360701_72_dialog_content = "에잇!",
  ui_story_5036_50360701_73_dialog_content = "하앗!",
  ui_story_5036_50360701_74_dialog_content = "어... 그거 진짜 춤 맞아요?",
  ui_story_5036_50360701_75_dialog_content = "방금 다리 깁스를 푼 사람이 걷는 법을 다시 배우고 있는 것처럼 보이는데.",
  ui_story_5036_50360701_76_dialog_content = "잘 봐! 그럼 이제 텀블링을 할 테니까!",
  ui_story_5036_50360701_77_dialog_content = "이야압!",
  ui_story_5036_50360701_78_dialog_content = "<color=#e8d9bb>콰당!</color>",
  ui_story_5036_50360701_79_dialog_content = "으아아아아앗... 아파!",
  ui_story_5036_50360701_80_dialog_content = "하하하하하하하!",
  ui_story_5036_50360701_81_dialog_content = "텀블링을 한다더니, 오히려 허릴 다쳤잖아요?",
  ui_story_5036_50360701_82_dialog_content = "그렇게 뛰는 것도 재능이라면 재능이네!",
  ui_story_5036_50360701_83_dialog_content = "아이돌로 전향하려는 환상동물 마스터가 칸타토르호에서\n다른 참가자들에게 둘러싸여 비난을 당한다...",
  ui_story_5036_50360701_84_dialog_content = "이런 뉴스로 편집장님이 만족하실까?",
  ui_story_5036_50360701_85_dialog_content = "비크 씨, 괜찮아?",
  ui_story_5036_50360701_86_dialog_content = "으, 역시 노인네를 신경 써 주는 건 PlayerName 하나밖에 없구나.",
  ui_story_5036_50360701_87_dialog_content = "근데 뭐가 엉덩이랑 부딪힌 것 같아. 좀 일으켜 줄래?",
  ui_story_5036_50360701_88_dialog_content = "...알겠어.",
  ui_story_5036_50360701_89_dialog_content = "어? 엉덩이 뒤쪽에... 환기구 입구가 있는데?!",
  ui_story_5036_50360701_90_dialog_content = "<color=#e8d9bb>콰직!</color>",
  ui_story_5036_50360701_91_dialog_content = "어라? 이게 무슨 소리죠?",
  ui_story_5036_50360701_92_dialog_content = "하하하, 내가 또 환기구 입구를 부숴 버렸네.",
  ui_story_5036_50360701_93_dialog_content = "크오오!",
  ui_story_5036_50360701_94_dialog_content = "앗! 왜 환기구에도 암귀가 숨어 있는 거야?!",
  ui_story_5036_50360701_95_dialog_content = "얼른 도망쳐요!",
  ui_story_5036_50360702_1_dialog_content = "크오오!",
  ui_story_5036_50360702_2_dialog_content = "활짝 피어라!",
  ui_story_5036_50360702_3_dialog_content = "골디 씨가 암귀랑 싸우고 있는 것 같아...\n어떻게든 빨리 그 소문이 사실인지 제대로 조사해야 하는데...",
  ui_story_5036_50360702_4_dialog_content = "으앗, 큰일이야! 사진을 찍어 둔다는 걸 잊어버렸잖아...",
  ui_story_5036_50360702_5_dialog_content = "다들 다친 곳은 없어?",
  ui_story_5036_50360702_6_dialog_content = "다들 괜찮습니다. 그냥 몇 명이 조금 놀랐을 뿐이에요.",
  ui_story_5036_50360702_7_dialog_content = "구해주셔서 감사합니다, 골디 씨.",
  ui_story_5036_50360702_8_dialog_content = "골디 씨는 실물이 포스터처럼... 아니지, 포스터보다 훨씬 더 아름다우시군요!",
  ui_story_5036_50360702_9_dialog_content = "골디 씨?!",
  ui_story_5036_50360702_10_dialog_content = "전 골디 씨가 데뷔했을 때부터 「골디락스」였어요!",
  ui_story_5036_50360702_11_dialog_content = "골디 씨! 여기 사인 하나만 해 주실 수 있나요?",
  ui_story_5036_50360702_12_dialog_content = "골디! 골디! 골디! 골디!",
  ui_story_5036_50360702_13_dialog_content = "미안, 이따가 이 환기구 입구를 제대로 막아 두고,\n여러분한테 음식을 나눠 줄 사람을 보낼게.",
  ui_story_5036_50360702_14_dialog_content = "전부 이 도둑 때문입니다. 녀석이 환기구 입구만 부수지 않았어도\n번거롭게 이러실 필요는 없으셨을 겁니다!",
  ui_story_5036_50360702_15_dialog_content = "춤도 진짜 끔찍할 정도로 못 췄고 말이에요!",
  ui_story_5036_50360702_16_dialog_content = "탈락시켜요! 탈락! 탈락! 탈락!",
  ui_story_5036_50360702_17_dialog_content = "하지만...",
  ui_story_5036_50360702_18_dialog_content = "난 진짜 오디션에 합격하고 싶단 말이야.",
  ui_story_5036_50360702_19_dialog_content = "그래?",
  ui_story_5036_50360702_20_dialog_content = "정말로 끝까지 할 자신 있어?",
  ui_story_5036_50360702_21_dialog_content = "우로보로스를 위해서라도...",
  ui_story_5036_50360702_22_dialog_content = "반드시!",
  ui_story_5036_50360702_23_dialog_content = "끝까지 해내겠어!",
  ui_story_5036_50360702_24_dialog_content = "(이런 근거 없는 신념과 결심... 정말 그립네.)",
  ui_story_5036_50360702_25_dialog_content = "(아무런 트레이닝을 받지 않았던 나도, 그땐 자신만만하게\n앞으로 더 큰 무대에 설 거라고 장담했었는데.)",
  ui_story_5036_50360702_26_dialog_content = "(내 착각일까?)",
  ui_story_5036_50360702_27_dialog_content = "(왜 비크 씨한테서 예전의 내 모습이 보이는 걸까?)",
  ui_story_5036_50360702_28_dialog_content = "(나도, 비크 씨도 집착에 가까울 정도로 「믿음」의 힘을 믿고 있기 때문인 걸까?)",
  ui_story_5036_50360702_29_dialog_content = "난 끝까지 해낼 거야!",
  ui_story_5036_50360702_30_dialog_content = "......",
  ui_story_5036_50360702_31_dialog_content = "좋아, 그럼 마지막으로 딱 한 번만 더 믿어 줄게.",
  ui_story_5036_50360702_32_dialog_content = "탈락! 탈락! 탈락! 탈락!",
  ui_story_5036_50360702_33_dialog_content = "다들 내 얘길 들어 줘~",
  ui_story_5036_50360702_34_dialog_content = "이런저런 오해 때문에, 우리 모두 비크 씨를 유령 도둑으로 생각했었는데.",
  ui_story_5036_50360702_35_dialog_content = "이젠 오해도 풀렸고, 비크 씨도 물건들을 다 주인한테 돌려줬어.\n게다가 보상도 해 주기로 했어.",
  ui_story_5036_50360702_36_dialog_content = "그러니까 우리 모두 비크 씨가 계속 오디션에 참가할 수 있게 해 주자.",
  ui_story_5036_50360702_37_dialog_content = "하지만 비크 씨가 오디션 준비 과정에 어느 정도 방해가 된 것도 사실이야.",
  ui_story_5036_50360702_38_dialog_content = "그러니까 비크 씨한테는 기회를 딱 한 번만 줄 거야.",
  ui_story_5036_50360702_39_dialog_content = "그때 비크 씨가 탈락하면, 그 즉시 이 칸타토르호에서 내쫓는 거지.",
  ui_story_5036_50360702_40_dialog_content = "다음 오디션은 앞으로 하루 이틀 정도 남았으니,\n이제 와서 아무리 연습해 봤자 오디션 통과는 꿈도 못 꾸겠군.",
  ui_story_5036_50360702_41_dialog_content = "골디 씨가 그렇게까지 말한다면...",
  ui_story_5036_50360702_42_dialog_content = "전 골디 씨의 판단을 믿어요!",
  ui_story_5036_50360702_43_dialog_content = "흥, 이 녀석이 그때 가서 고작 이런 춤으로 오디션을 통과한다면...",
  ui_story_5036_50360702_44_dialog_content = "이 오디션에 대한 골디 씨의 마음을 의심하게 될지도 모릅니다.",
  ui_story_5036_50360702_45_dialog_content = "다들 걱정 마. 난 절대로 모두의 신뢰를 저버리는 일은 하지 않을 거니까~",
  ui_story_5036_50360702_46_dialog_content = "골디! 골디! 골디! 골디!",
  ui_story_5036_50360702_47_dialog_content = "크흠, 고마워, 골디 씨.",
  ui_story_5036_50360702_48_dialog_content = "계속 여기 있을 거야?",
  ui_story_5036_50360702_49_dialog_content = "뭐?",
  ui_story_5036_50360702_50_dialog_content = "빨리 연습실에 가서 연습해야지.",
  ui_story_5036_50360702_51_dialog_content = "근데 지금은 시간이 너무 늦었는데...",
  ui_story_5036_50360702_52_dialog_content = "내가 그랬지? 당신은 음색도 좋고, 비주얼도 훌륭한 편이라고.",
  ui_story_5036_50360702_53_dialog_content = "이 두 가지만 해도 당신은 다른 사람보다 훨씬 앞서 나가고 있는 거야.",
  ui_story_5036_50360702_54_dialog_content = "하지만 만약 진짜로 끝까지 해 볼 생각이라면...",
  ui_story_5036_50360702_55_dialog_content = "내 말대로 해.",
  ui_story_5036_50360801_1_dialog_content = "<color=#e8d9bb>콘서트 개최 3일 전</color>",
  ui_story_5036_50360801_2_dialog_content = "♪아~ 오오오~",
  ui_story_5036_50360801_3_dialog_content = "잠깐만!",
  ui_story_5036_50360801_4_dialog_content = "그게 당신이 오디션에서 부를 곡이야?",
  ui_story_5036_50360801_5_dialog_content = "후후, 내가 믿을 수 있는 장기를 준비했다고 했었잖아.\n아무도 안 믿어 줬지만.",
  ui_story_5036_50360801_6_dialog_content = "그게 믿을 수 있는 장기가 맞아?",
  ui_story_5036_50360801_7_dialog_content = "이 멜로디는 내가 특별히 북방의 깊은 밀림에 들어갔을 때 만난\n아주 희귀한 오로라밤꾀꼬리한테 배운 거야.",
  ui_story_5036_50360801_8_dialog_content = "가사는 환상동물 마스터인 내가 혼신을 담아 적은\n와일드함이 가득한 내용이라고...",
  ui_story_5036_50360801_9_dialog_content = "이 노래보다 믿음직한 곡이 또 어디 있겠어?",
  ui_story_5036_50360801_10_dialog_content = "크흠...",
  ui_story_5036_50360801_11_dialog_content = "곡은 별문제가 없는데, 노래 실력 쪽으로 정말 많은 노력이 필요할 것 같아.",
  ui_story_5036_50360801_12_dialog_content = "그 평가는 너무 완곡한 거 아냐? 골디!",
  ui_story_5036_50360801_13_dialog_content = "확실히 아주 완곡하긴 해요.",
  ui_story_5036_50360801_14_dialog_content = "PlayerName 네가 그러는 건 이해라도 가는데,\n왜 기자 아가씨까지 날 비웃는 거야?",
  ui_story_5036_50360801_15_dialog_content = "저, 전 그냥 사실을 얘기한 거예요.",
  ui_story_5036_50360801_16_dialog_content = "브랜디는 중립적인 입장에서 기사를 적는 마음씨 착한 프로 기자야.",
  ui_story_5036_50360801_17_dialog_content = "그러니까 당신의 노래가 브랜디에게 아무런 느낌도 주지 못했다면,\n어디에 문제가 있는 건지 곰곰이 생각해 봐야 할 거야.",
  ui_story_5036_50360801_18_dialog_content = "설마?! 기자 아가씨, 귀를 다친 거야?\n그래서 내 아름다운 목소리가 잘 안 들렸던 거구나?",
  ui_story_5036_50360801_19_dialog_content = "그 소리가 아니잖아!",
  ui_story_5036_50360801_20_dialog_content = "으음, 아무튼...",
  ui_story_5036_50360801_21_dialog_content = "노래를 잘 부르려면, 우선은 호흡법부터 제대로 배워야 해.",
  ui_story_5036_50360801_22_dialog_content = "호흡법이란 걸 따로 또 배워야 돼?",
  ui_story_5036_50360801_23_dialog_content = "오디션에 통과하고 싶다면, 내가 하라는 대로 해.",
  ui_story_5036_50360801_24_dialog_content = "네, 골디 선생님!",
  ui_story_5036_50360801_25_dialog_content = "숨을 들이마실 때는 복부를 부풀리고, 내쉴 때는 복부를 수축시켜.",
  ui_story_5036_50360801_26_dialog_content = "이게 바로 복식 호흡이야.",
  ui_story_5036_50360801_27_dialog_content = "일단 한 10분 정도 연습해 보자.",
  ui_story_5036_50360801_28_dialog_content = "설명만 들어서는 타래가 평소에 잘 때 숨 쉬는 거랑 비슷한데.",
  ui_story_5036_50360801_29_dialog_content = "스읍~ 후우~",
  ui_story_5036_50360801_30_dialog_content = "나쁘지 않아. 숨을 좀 더 길게 들이마셔 봐.",
  ui_story_5036_50360801_31_dialog_content = "스으으읍~ 후우우~",
  ui_story_5036_50360801_32_dialog_content = "좋아, 계속 그 호흡을 유지해.",
  ui_story_5036_50360801_33_dialog_content = "스읍... 후우...",
  ui_story_5036_50360801_34_dialog_content = "스읍... 후우...",
  ui_story_5036_50360801_35_dialog_content = "저기, 비크 씨 혹시 잠든 거 아냐?",
  ui_story_5036_50360801_36_dialog_content = "휴우우... 후우... 후...",
  ui_story_5036_50360801_37_dialog_content = "비크 씨!",
  ui_story_5036_50360801_38_dialog_content = "화내지 마, 피아! 어?",
  ui_story_5036_50360801_39_dialog_content = "아! 골디 씨... 아니지, 골디 선생님이었구나.",
  ui_story_5036_50360801_40_dialog_content = "호흡법을 연습하라고 했지, 자는 법을 연습하라곤 한 적 없어.",
  ui_story_5036_50360801_41_dialog_content = "<color=#e8d9bb>얼마 후</color>",
  ui_story_5036_50360801_42_dialog_content = "어떻게 호흡하는지 알았다면, 이제 발성 연습을 시작할 수 있어.",
  ui_story_5036_50360801_43_dialog_content = "비크 씨, 당신의 음색은 정말 좋은 편이지만, 그래도 꼭 명심해!",
  ui_story_5036_50360801_44_dialog_content = "제대로 된 발성 기교 없이 목을 혹사하면서 노래를 부르면,\n성대에 돌이킬 수 없는 상처를 입게 될 거야.",
  ui_story_5036_50360801_45_dialog_content = "근데 골디 선생님, 제대로 된 발성 기교를 터득하고 싶으면 어떻게 해야 돼?",
  ui_story_5036_50360801_46_dialog_content = "좋은 질문이야.",
  ui_story_5036_50360801_47_dialog_content = "선생님으로서 나만의 비법을 알려 줄게.\n그건 바로... 투레질을 하는 거야!",
  ui_story_5036_50360801_48_dialog_content = "유심히 잘 보도록 해~ 입술을 이렇게 앞으로 쭉 내민 다음에!",
  ui_story_5036_50360801_49_dialog_content = "투루루루루루루...",
  ui_story_5036_50360801_50_dialog_content = "투루루루루루루...",
  ui_story_5036_50360801_51_dialog_content = "어머? 아주 잘했어! 빨리 배우는구나!",
  ui_story_5036_50360801_52_dialog_content = "하하, 이 정도는 쉽지!",
  ui_story_5036_50360801_53_dialog_content = "야외에서 돌아다닐 때 가끔 발정기의 늪지코뿔소를 발견하면\n이런 소릴 내서 주의를 끌곤 하거든.",
  ui_story_5036_50360801_54_dialog_content = "투루루루루루루...",
  ui_story_5036_50360801_55_dialog_content = "상황이 괜찮을 땐 한 번에 열 마리 넘게 몰려온다니까.",
  ui_story_5036_50360801_56_dialog_content = "그, 그래?",
  ui_story_5036_50360801_57_dialog_content = "우리가 지금 하늘 위에 있는 게 천만다행이었네.",
  ui_story_5036_50360801_58_dialog_content = "아무튼, 이 연습을 통해 소리의 전달력을 기르고, 호흡 부족 문제까지 고칠 수 있어.",
  ui_story_5036_50360801_59_dialog_content = "마지막 오디션까지 시간은 이틀 정도밖에 안 남았지만.",
  ui_story_5036_50360801_60_dialog_content = "그래도 열심히 계속 연습한다면, 하루 정도로도 몸이 이 방법들을 기억해서\n당신이 노래를 부를 때 가지고 있는 문제들을 개선해 줄 거야.",
  ui_story_5036_50360801_61_dialog_content = "늪지코뿔소 울음소리를 흉내 내는 게 노래를 부를 때의\n문제들을 개선해 줄 수 있단 말이야?",
  ui_story_5036_50360801_62_dialog_content = "뭐, 난 좋은 학생이니까 하나를 배우면 열을 알거든.\n그러니까 다른 환상동물 울음소리도 내 볼게!",
  ui_story_5036_50360801_63_dialog_content = "하이, 하이하이!",
  ui_story_5036_50360801_64_dialog_content = "하이?",
  ui_story_5036_50360801_65_dialog_content = "구구, 구구구구.",
  ui_story_5036_50360801_66_dialog_content = "구구?",
  ui_story_5036_50360801_67_dialog_content = "뀨우~ 뀨우뀨우~",
  ui_story_5036_50360801_68_dialog_content = "뀨우?",
  ui_story_5036_50360801_69_dialog_content = "그, 그만하면 됐어.",
  ui_story_5036_50360801_70_dialog_content = "늪지코뿔소 울음소리만 연습하면 돼.",
  ui_story_5036_50360801_71_dialog_content = "그래? 내가 괜한 짓을 한 모양이네.",
  ui_story_5036_50360801_72_dialog_content = "그것보다 더 노력해야 할 일이 하나 더 있어. 바로 춤이야.",
  ui_story_5036_50360801_73_dialog_content = "노래를 부르는 건 퍼포먼스의 일부일 뿐이야.\n거기에 안무를 더하면 퍼포먼스가 더 매력적으로 변해.",
  ui_story_5036_50360801_74_dialog_content = "그러니까 비크 씨도 노래에 맞는 안무를 짜야 해.",
  ui_story_5036_50360801_75_dialog_content = "하지만 그전에 우선 비크 씨의 몸이 안무를 따라올 수 있을지 확인부터 해 볼게.",
  ui_story_5036_50360801_76_dialog_content = "내가 간단한 동작을 몇 개 해 볼 테니까, 옆에서 최대한 따라 해 봐.",
  ui_story_5036_50360801_77_dialog_content = "PlayerName 씨, 반주를 부탁할게~",
  ui_story_5036_50360801_78_dialog_content = "응, 피아노는 나한테 맡겨!",
  ui_story_5036_50360801_79_dialog_content = "음악이 시작됐어. 비크 씨, 리듬을 타 봐!",
  ui_story_5036_50360801_80_dialog_content = "하나, 둘! 스텝, 무빙!",
  ui_story_5036_50360801_81_dialog_content = "왼쪽 한 번 콕! 오른쪽 한 번 콕!",
  ui_story_5036_50360801_82_dialog_content = "윽, 왼쪽... 오른쪽... 나 왠지 좌우 구분이 안 되는 것 같은데?!",
  ui_story_5036_50360801_83_dialog_content = "계속해서, 손 머리 위로! 머리 위에서, 빙글빙글!",
  ui_story_5036_50360801_84_dialog_content = "왼손, 앞으로 쭉, 다시 안으로!",
  ui_story_5036_50360801_85_dialog_content = "오른손, 앞으로 쭉, 다시 안으로!",
  ui_story_5036_50360801_86_dialog_content = "왼발... 윽, 벌써 오른손이라고?!",
  ui_story_5036_50360801_87_dialog_content = "다리도 멈추지 말고 계속 움직여~",
  ui_story_5036_50360801_88_dialog_content = "(어? 지, 지금 내가 잘못 본 거 아니지?)",
  ui_story_5036_50360801_89_dialog_content = "(골디 씨가...)",
  ui_story_5036_50360801_90_dialog_content = "(움브라톤 최고의 인기 스타... 골디 씨가, 내 눈앞에서 춤을 추는 거야?!)",
  ui_story_5036_50360801_91_dialog_content = "(「골디락스」의 고참 회원이라도 이런 대우는 받기 힘들 텐데!)",
  ui_story_5036_50360801_X91_dialog_content = "(침착하자, 침착해야 돼. 아직 그 일을 제대로 조사하지 않았으니까...)",
  ui_story_5036_50360801_92_dialog_content = "(근데 비크 씨랑 비교가 되니까 골디 씨의 움직임이 더 가뿐하고 아름다워 보여.)",
  ui_story_5036_50360801_93_dialog_content = "(빨리 기록해 둬야겠어!)",
  ui_story_5036_50360801_94_dialog_content = "꿈을 붙잡겠다는 것처럼 팔을 길게 뻗어, 그리고 다시 가슴 앞으로 모아~",
  ui_story_5036_50360801_95_dialog_content = "하나, 둘! 스텝, 점프!",
  ui_story_5036_50360801_96_dialog_content = "손을 왼쪽으로 흔들고! 오른쪽으로 흔들고!",
  ui_story_5036_50360801_97_dialog_content = "헉헉... 끝나려면 멀었어?",
  ui_story_5036_50360801_98_dialog_content = "마지막으로, 양손을 높이 들고~",
  ui_story_5036_50360801_99_dialog_content = "한 바퀴 빙 돌아!",
  ui_story_5036_50360801_100_dialog_content = "한 바퀴... 빙!",
  ui_story_5036_50360801_101_dialog_content = "<color=#e8d9bb>우당탕!</color>",
  ui_story_5036_50360801_102_dialog_content = "아야, 아파아아...",
  ui_story_5036_50360801_103_dialog_content = "비크 씨, 이걸로 오늘 벌써 몇 번째 넘어진 거야?",
  ui_story_5036_50360801_104_dialog_content = "괜찮아, 이런 건 이미 익숙하거든. 하하하.",
  ui_story_5036_50360801_105_dialog_content = "믿기지가 않네. 당신의 움직임은 막 걸음마를 뗀 아기보다도 못해.",
  ui_story_5036_50360801_106_dialog_content = "그리고 겨우 몇 동작만 해도 호흡이 다 흐트러져 버리잖아.\n평소에 체력 단련은 하나도 안 해?",
  ui_story_5036_50360801_107_dialog_content = "잠자기도 체력 단련으로 쳐 주나?",
  ui_story_5036_50360801_108_dialog_content = "큰일이네. 몸치는 하루아침에 고칠 수 있는 게 아니거든.",
  ui_story_5036_50360801_109_dialog_content = "<color=#e8d9bb>또 얼마 후</color>",
  ui_story_5036_50360801_110_dialog_content = "이 안무들은 어때? 기억해 둘 수 있겠어?",
  ui_story_5036_50360801_111_dialog_content = "아무튼 왔다 갔다 하면서 손을 휘둘러 주면 되는 거잖아?\n하하, 기억했어!",
  ui_story_5036_50360801_112_dialog_content = "간단한 안무인 건 맞지만...",
  ui_story_5036_50360801_113_dialog_content = "곡에 모든 열정을 쏟은 상태에서, 비크 씨의 감정을 담아서 춤을 춰야 해.",
  ui_story_5036_50360801_114_dialog_content = "춤에 감정을 담으라고? 그건 이해가 잘 안 되는데.",
  ui_story_5036_50360801_115_dialog_content = "비크 씨, 당신 생각엔 아이돌한테 가장 필요한 능력이 뭘 것 같아?",
  ui_story_5036_50360801_116_dialog_content = "춤을 잘 추는 거? 그리고 노래를 잘하는 거?",
  ui_story_5036_50360801_117_dialog_content = "아니, 둘 다 아니야.",
  ui_story_5036_50360801_118_dialog_content = "아이돌이라면 춤이랑 노래 실력은 당연히 갖추고 있어야 해.\n이건 의심의 여지 없이 당연한 거야.",
  ui_story_5036_50360801_119_dialog_content = "그렇지만 춤이랑 노래는 신호를 전달해 주는 일종의 매개체일 뿐이거든.",
  ui_story_5036_50360801_120_dialog_content = "그러니까 아이돌한테 가장 중요한 건,\n절대 꺾이지 않고 물러서지 않는 신념과 열정을 가지는 거야.",
  ui_story_5036_50360801_121_dialog_content = "그리고 춤이랑 노래를 통해 그 신념과 열정을 모두에게 전하는 거지.",
  ui_story_5036_50360801_122_dialog_content = "음...",
  ui_story_5036_50360801_123_dialog_content = "<size=35>이 부분은 이미 해냈다고 볼 수 있겠지만.</size>",
  ui_story_5036_50360801_124_dialog_content = "응? 선생님, 뭐라고?",
  ui_story_5036_50360801_125_dialog_content = "크흠, 아무튼 일단 자기 마음을 움직일 수 있어야 돼.\n그래야 다른 사람의 마음도 움직일 수 있는 거야.",
  ui_story_5036_50360801_126_dialog_content = "설명해 줄 수 있는 건 다 설명해 줬어.\n이제 남은 건 비크 씨가 스스로 노력하는 수밖에 없어.",
  ui_story_5036_50360801_127_dialog_content = "정식 오디션 현장에선 절대 안 봐 줄 거야~",
  ui_story_5036_50360801_128_dialog_content = "넉넉잡으면 오디션까지 하루 반나절 정도 남았네.",
  ui_story_5036_50360801_129_dialog_content = "이 하루 반나절만 노력하면 계속 여기 남아서 우로보로스를 찾을 수 있어!",
  ui_story_5036_50360801_130_dialog_content = "음, 골디!",
  ui_story_5036_50360801_131_dialog_content = "정말 너무 고마워. 결국엔 골디 널 번거롭게 만들어 버렸네.",
  ui_story_5036_50360801_132_dialog_content = "천만에. 참가자에게 아이디어를 주는 것도 내가 해야 할 일인걸.\n그렇게 신경 쓸 필요 없어~",
  ui_story_5036_50360801_133_dialog_content = "솔직히 말하면 난 비크 씨가 저지른 일들도 있고 해서,\n골디 네가 더는 안 도와줄 거라고 생각했어.",
  ui_story_5036_50360801_134_dialog_content = "비크 씨가 골치 아픈 건 맞아~",
  ui_story_5036_50360801_135_dialog_content = "그래도 헤아릴 수 없을 정도의 잠재력이 있는 것도 맞고.",
  ui_story_5036_50360801_136_dialog_content = "만약 비크 씨가 진짜로 아이돌을 하게 된다면, 나한테도 일종의 자극이 될 거야~",
  ui_story_5036_50360801_137_dialog_content = "어? 둘이 지금 내 칭찬하고 있는 거야?",
  ui_story_5036_50360801_138_dialog_content = "나한테도 좀 들려줄래?",
  ui_story_5036_50360801_139_dialog_content = "참, 가장 중요한 걸 깜빡할 뻔했네.",
  ui_story_5036_50360801_140_dialog_content = "아이돌한테 탄탄한 체력은 모든 활동의 기본이야.",
  ui_story_5036_50360801_141_dialog_content = "마침 나한테 체력을 기르는 비결이 하나 있는데, 궁금하지 않아?",
  ui_story_5036_50360801_142_dialog_content = "어어어? 대체 어디서 암귀들을 이렇게 잔뜩 끌고 온 거야?!",
  ui_story_5036_50360801_143_dialog_content = "후후, 당연히 잡아 온 거지.",
  ui_story_5036_50360801_144_dialog_content = "크오오!",
  ui_story_5036_50360801_145_dialog_content = "방금 말한 그 비결이란 게, 설마 암귀랑 싸우는 건 아니지?",
  ui_story_5036_50360801_146_dialog_content = "환상동물들은 쉬게 해 줘.",
  ui_story_5036_50360801_147_dialog_content = "이번엔 비크 씨 자기 힘으로 싸워야 해~",
  ui_story_5036_50360801_148_dialog_content = "뭐?",
  ui_story_5036_50360801_149_dialog_content = "크오오!",
  ui_story_5036_50360801_150_dialog_content = "오지 마!",
  ui_story_5036_50360801_151_dialog_content = "역시 비크 씨도 직접 암귀랑 싸울 힘이 있을 줄 알았다니까!",
  ui_story_5036_50360801_152_dialog_content = "하지만 난 이렇게 힘든 건 사절이라고!",
  ui_story_5036_50360801_153_dialog_content = "멈추면 안 돼!",
  ui_story_5036_50360801_154_dialog_content = "암귀랑 싸우면서, 노래도 부르고 안무도 해야지!",
  ui_story_5036_50360801_155_dialog_content = "뭐어어어?",
  ui_story_5036_50360801_156_dialog_content = "진짜 악마... 진짜 악마가 여기 있었잖아?!",
  ui_story_5036_50360801_157_dialog_content = "크오오오──!",
  ui_story_5036_50360802_1_dialog_content = "<color=#e8d9bb>콘서트 개최 2일 전</color>",
  ui_story_5036_50360802_2_dialog_content = "현장에 있는 친구들~ 모두 손 머리 위로! 우리 같이...",
  ui_story_5036_50360802_3_dialog_content = "한 번 더!",
  ui_story_5036_50360802_4_dialog_content = "저, 저게 진짜 우리가 며칠 전에 만난 그 도둑 맞아요?",
  ui_story_5036_50360802_5_dialog_content = "그런 것 같기도 하고, 아닌 것 같기도 한데?",
  ui_story_5036_50360802_6_dialog_content = "♪또다시 찾아온 만물이 소생하는 봄♪",
  ui_story_5036_50360802_7_dialog_content = "♪동물들은 바삐 자신들의 터전을 떠나지♪",
  ui_story_5036_50360802_8_dialog_content = "♪숲이든 저 멀리 있는 황야든♪",
  ui_story_5036_50360802_9_dialog_content = "♪어디에나 달콤한 사랑이 가득해♪",
  ui_story_5036_50360802_10_dialog_content = "가사가 전혀 이해가 안 되긴 하지만...",
  ui_story_5036_50360802_11_dialog_content = "몸은 나도 모르게 저 녀석 노래에 맞춰 리듬을 타게 되잖아?",
  ui_story_5036_50360802_12_dialog_content = "♪자, 여길 봐, 이건 누굴까?♪",
  ui_story_5036_50360802_13_dialog_content = "♪복슬복슬한 비카야~ 「하이」라고 하는 걸 좋아해♪",
  ui_story_5036_50360802_14_dialog_content = "하이하이하이~",
  ui_story_5036_50360802_15_dialog_content = "하이하이하이!",
  ui_story_5036_50360802_16_dialog_content = "♪자, 여길 봐, 이건 누굴까?♪",
  ui_story_5036_50360802_17_dialog_content = "♪코너를 돌다 가골빼미를 만났구나~ 주머니를 조심해♪",
  ui_story_5036_50360802_18_dialog_content = "구구구~",
  ui_story_5036_50360802_19_dialog_content = "구구구!",
  ui_story_5036_50360802_20_dialog_content = "골디, 저 비크 씨는 골디가 분장시켜서 올려보낸 다른 사람이지?",
  ui_story_5036_50360802_21_dialog_content = "응?",
  ui_story_5036_50360802_22_dialog_content = "내 말은 그러니까... 하루 반나절이 그렇게 긴 시간도 아닌데,\n실력이 저렇게 갑자기 확 늘 수도 있는 거야?!",
  ui_story_5036_50360802_23_dialog_content = "내 눈앞에 있는 게 비크 씨란 게 전혀 믿기질 않아.",
  ui_story_5036_50360802_24_dialog_content = "완전히 다른 사람이 된 것 같아!",
  ui_story_5036_50360802_25_dialog_content = "내가 처음부터 그랬잖아. 비크 씨한텐 아이돌이 될 잠재력이 있다니까.",
  ui_story_5036_50360802_26_dialog_content = "다듬어지지 않은 원석 같아서, 조금만 갈고 닦아 주면 눈부시게 반짝일 수 있는 거야.",
  ui_story_5036_50360802_27_dialog_content = "육성의 즐거움!",
  ui_story_5036_50360802_28_dialog_content = "그런 게 바로 육성의 즐거움이란 거지. 다들 알겠어?",
  ui_story_5036_50360802_29_dialog_content = "노래, 춤, 비주얼, 몸매, 감성, 지성, 총 여섯 항목에서 거의 만점에 가까워요.",
  ui_story_5036_50360802_30_dialog_content = "오디션에 드디어 유일한 만능 밸런스형 선수가 등장했네요!",
  ui_story_5036_50360802_31_dialog_content = "내가 이따위 공연을 보고 빠져들다니?!",
  ui_story_5036_50360802_32_dialog_content = "...빛의 신이시여, 부디 절 용서하십시오.",
  ui_story_5036_50360802_33_dialog_content = "음, 많이 늘었네.",
  ui_story_5036_50360802_34_dialog_content = "♪투루루루루루루...♪",
  ui_story_5036_50360802_35_dialog_content = "♪우로보로스의 알껍데기를 본 적 있어?♪",
  ui_story_5036_50360802_36_dialog_content = "♪투루루루루루루...♪",
  ui_story_5036_50360802_37_dialog_content = "♪최선을 다해 널 찾을 거야♪",
  ui_story_5036_50360802_38_dialog_content = "자, 내가 준비한 건 여기까지야. 다들 고마워~",
  ui_story_5036_50360802_39_dialog_content = "비크! 비크! 비크! 비크!",
  ui_story_5036_50360802_40_dialog_content = "여러분도 보이시죠? 오디션장이 이 노래 하나로 후끈 달아올랐네요!",
  ui_story_5036_50360802_41_dialog_content = "놀라운 퍼포먼스를 선보여주신 비크 씨께 감사드립니다!",
  ui_story_5036_50360802_42_dialog_content = "하지만 까다로운 우리 심사위원 여러분께선 과연 어떤 평가를 내리셨을까요?",
  ui_story_5036_50360802_43_dialog_content = "그럼 골디 씨의 심사평부터 들어 볼까요!",
  ui_story_5036_50360802_44_dialog_content = "딱히 코멘트할 게 없어.",
  ui_story_5036_50360802_45_dialog_content = "하아? 엊그제 밤부터 지금까지 잠도 안 자고 계속 연습했는데도 탈락이란 말이야?",
  ui_story_5036_50360802_46_dialog_content = "진작 이럴 줄 알았으면 그냥 누워서 잠이나 잤을 텐데.",
  ui_story_5036_50360802_47_dialog_content = "내 말은 비크 씨가 너무 잘해 줘서 딱히 조언해 줄 게 없단 얘기야.",
  ui_story_5036_50360802_48_dialog_content = "투표 결과가 모든 걸 말해 줄 거야.",
  ui_story_5036_50360802_49_dialog_content = "자! 최종 투표 결과가 나왔네요.",
  ui_story_5036_50360802_50_dialog_content = "과연 이번 참가자는 무대에 오를 수 있는 다이렉트 진출권을 손에 넣었을까요?",
  ui_story_5036_50360802_51_dialog_content = "결과는...",
  ui_story_5036_50360802_52_dialog_content = "결과는?",
  ui_story_5036_50360802_53_dialog_content = "<size=45>만장일치</size>로 합격입니다!",
  ui_story_5036_50360802_54_dialog_content = "하아? 저런 풋내기도 오디션에 합격해 버렸네?\n누구 씨가 스트레스를 많이 받겠는걸?",
  ui_story_5036_50360802_55_dialog_content = "힘이라도 나게 내가 응원가라도 좀 불러 줄까?",
  ui_story_5036_50360802_56_dialog_content = "뭘 우쭐거리는 거야. 공장에서 찍어 낸 것 같은 네 뻔한 노랜 됐어.",
  ui_story_5036_50360802_57_dialog_content = "네가 오디션에서 탈락해 버리면, 나 진짜 쓸쓸할 거야.",
  ui_story_5036_50360802_58_dialog_content = "네가 먼저 합격한 건, 그냥 네 순서가 나보다 앞에 있어서 그런 거거든.",
  ui_story_5036_50360802_59_dialog_content = "기다리고 있어. 심사위원들이 내 퍼포먼스를 보고 나면,\n너랑 저 녀석 같은 풋내기들을 괜히 뽑았나 싶어서 후회하게 될 거니까!",
  ui_story_5036_50360802_60_dialog_content = "비크 씨, 지금 소감이 어떠세요?",
  ui_story_5036_50360802_61_dialog_content = "이제 드디어... 푹 잘 수 있겠어...",
  ui_story_5036_50360802_62_dialog_content = "일어나고 나면... 그땐...",
  ui_story_5036_50360802_63_dialog_content = "가서... 우로보...로...",
  ui_story_5036_50360802_64_dialog_content = "비크 씨?",
  ui_story_5036_50360802_65_dialog_content = "비크 씨?! 왜 그러세요?",
  ui_story_5036_50360802_66_dialog_content = "휴우우... 후우... 후...",
  ui_story_5036_50360802_67_dialog_content = "으, 비크 씨.",
  ui_story_5036_50360802_68_dialog_content = "오디션 현장에서 주무시면 어떻게 해요!",
  ui_story_5036_50360802_69_dialog_content = "비크 씨도 참, 너무 깊이 잠든 거 아냐?",
  ui_story_5036_50360802_70_dialog_content = "어떻게 시끄러운 오디션 현장에서 하루 종일 잘 수가 있지?",
  ui_story_5036_50360802_71_dialog_content = "그러게, 아까 용병들이 방으로 업고 갈 때도 전혀 안 깨더라.",
  ui_story_5036_50360802_72_dialog_content = "그 사람 실력은 확실히 달라졌어.",
  ui_story_5036_50360802_73_dialog_content = "아마 이틀 동안 사력을 다해 연습하고 지친 거겠지.",
  ui_story_5036_50360802_74_dialog_content = "내가 볼 땐 너희 둘도 엄청 열심히 연습한 것 같던데?",
  ui_story_5036_50360802_75_dialog_content = "안 그러면 어떻게 만장일치로 오디션에 합격했겠어.",
  ui_story_5036_50360802_76_dialog_content = "휴~ 이 정도는 우리가 예상한 결과야.",
  ui_story_5036_50360802_77_dialog_content = "근데 진짜 힘들긴 해.",
  ui_story_5036_50360802_78_dialog_content = "오늘은 우리도 일찍 쉬어야겠어.",
  ui_story_5036_50360802_79_dialog_content = "내일은 리허설 때문에 하루 종일 바쁠 테니까.",
  ui_story_5036_50360802_80_dialog_content = "오늘은 꿈 안 꾸고 푹 잘 수 있었으면 좋겠어.",
  ui_story_5036_50360802_81_dialog_content = "그러게, 잘 자.",
  ui_story_5036_50360802_82_dialog_content = "어? 바이스? 카렌?",
  ui_story_5036_50360802_83_dialog_content = "다들 왜 이렇게 빨리 가 버린 거야?",
  ui_story_5036_50360802_84_dialog_content = "그럼...",
  ui_story_5036_50360802_85_dialog_content = "나도 일찍 쉬어야겠네.",
  ui_story_5036_50360901_1_dialog_content = "여긴 어디지...?",
  ui_story_5036_50360901_2_dialog_content = "콜로서스인 것 같은데... 저기 있는 건 저번에 꿈에서 본 그 아이테르잖아?",
  ui_story_5036_50360901_3_dialog_content = "나 지금 또 꿈꾸고 있는 건가?",
  ui_story_5036_50360901_4_dialog_content = "네가 바로 「칸타토르호」구나?",
  ui_story_5036_50360901_5_dialog_content = "그렇습니다. 당신이 제 새로운 조종사입니까?",
  ui_story_5036_50360901_6_dialog_content = "응! 난 샤미나드라고 해. 앞으로 잘 부탁해!",
  ui_story_5036_50360901_7_dialog_content = "(장소가 바뀌었어. 이번엔 콜로서스의 함교인 것 같은데?)",
  ui_story_5036_50360901_8_dialog_content = "칸타토르, 넌 왜 이렇게 많은 스크린이랑 이상한 음향 설비를 가지고 있는 거야?",
  ui_story_5036_50360901_9_dialog_content = "다른 동료들한테 물어봤는데, 너처럼 이런 설비를 가진 콜로서스는\n다들 본 적이 없다고 하더라고.",
  ui_story_5036_50360901_10_dialog_content = "저도 이 이유에 대해서는 알지 못합니다.",
  ui_story_5036_50360901_11_dialog_content = "오래전의 기억들은 바람에 실린 노랫소리처럼,\n지금은 모두 흔적도 없이 사라진 상태입니다.",
  ui_story_5036_50360901_12_dialog_content = "그거 아쉽네...",
  ui_story_5036_50360901_13_dialog_content = "그치만 다들 칸타토르를 엄청 좋아해!",
  ui_story_5036_50360901_14_dialog_content = "헤븐즈 밸리 전체에 음악을 울려 퍼지게 할 수 있는 건 칸타토르뿐이니까.",
  ui_story_5036_50360901_15_dialog_content = "감사합니다. 그렇게 이야기해 주시니 무척 기쁩니다.",
  ui_story_5036_50360901_16_dialog_content = "칸타토르! 우리 같이 여행 가자!",
  ui_story_5036_50360901_17_dialog_content = "네? 이렇게 갑자기 말입니까?",
  ui_story_5036_50360901_18_dialog_content = "오늘 선생님한테 들었어.\n아스트라 대륙에는 아직도 전쟁과 암귀 때문에 힘들어하는 사람들이 많대.",
  ui_story_5036_50360901_19_dialog_content = "그 사람들은 희망도 없이 어렵게 지내고 있다고 해.\n난 가서 그 사람들한테 노래를 불러 주고 싶어!",
  ui_story_5036_50360901_20_dialog_content = "내 노랫소리론 암귀를 쓰러트리거나,\n그 사람들한테 뭔가 해 줄 수 있는 건 아니지만...",
  ui_story_5036_50360901_21_dialog_content = "그래도 최소한 그 사람들한테 총이나 대포 소리가 아닌\n다른 소리를 듣게 해 주고 싶어.",
  ui_story_5036_50360901_22_dialog_content = "그런 곳은 당신에게 너무 위험합니다.",
  ui_story_5036_50360901_23_dialog_content = "나도 알아. 그치만 만약 내 노랫소리가 그 사람들한테 조금이라도\n위안과 희망이 돼 줄 수 있다면, 난 그 어떤 위험도 두렵지 않아.",
  ui_story_5036_50360901_24_dialog_content = "이해했습니다.",
  ui_story_5036_50360901_25_dialog_content = "그렇다면 출발하겠습니다.",
  ui_story_5036_50360901_26_dialog_content = "또 꿈인가? 이번엔 전이랑 다르게 뭔가 좀 더... 기억 같은데?",
  ui_story_5036_50360901_27_dialog_content = "샤미나드, 이게 그 아이테르 소녀의 이름인가...?",
  ui_story_5036_50360901_28_dialog_content = "설마 방금 전 꿈은 내가 무의식중에 이 아이테르가 남긴\n과거의 감정과 감응한 건가?",
  ui_story_5036_50360901_29_dialog_content = "콜로서스를 타고 아스트라 대륙을 순회하면서\n노래를 부르는 아이테르라니, 왠지 골디 같은 느낌이네.",
  ui_story_5036_50360901_30_dialog_content = "하암~ 꿈을 너무 많이 꿔서 결국 한 시간밖에 못 잤잖아.",
  ui_story_5036_50360901_31_dialog_content = "방금 막 깨서 잠도 안 오니까, 뭐라도 좀 먹을까...",
  ui_story_5036_50360901_32_dialog_content = "<color=#e8d9bb>똑똑똑──!</color>",
  ui_story_5036_50360901_33_dialog_content = "(이렇게 늦은 시간에 누구지?)",
  ui_story_5036_50360901_34_dialog_content = "갑니다, 가요!",
  ui_story_5036_50360901_35_dialog_content = "PlayerName 씨, 미안. 내가 쉬는 거 방해했어?",
  ui_story_5036_50360901_36_dialog_content = "골디? 무슨 일이야? 지금 막 잠에서 깬 참이라 괜찮아.",
  ui_story_5036_50360901_37_dialog_content = "도움이 좀 필요해. 콘서트의 성공적인 개최 여부가 달린 일이야!",
  ui_story_5036_50360901_38_dialog_content = "뭐? 그렇게 중요한 일이라고?! 설마 칸타토르호가 추락하려는 건 아니지?",
  ui_story_5036_50360901_39_dialog_content = "그 정도로 심각한 일까진 아니고...\n아무튼, 혹시 요즘 계속 이상한 꿈을 꾸고 있진 않아?",
  ui_story_5036_50360901_40_dialog_content = "탁 트인 골짜기가 나오고, 거기서 어떤 소녀가 노래를 부르는 그런 꿈 말이야.",
  ui_story_5036_50360901_41_dialog_content = "꾸고 있지. 이유는 모르겠지만 매일 밤마다 그 꿈을 꿔.",
  ui_story_5036_50360901_42_dialog_content = "헤븐즈 밸리에서 모르는 아이테르 소녀가 노래를 부르는 꿈 말이야.",
  ui_story_5036_50360901_43_dialog_content = "그 소녀가 아이테르였어?!",
  ui_story_5036_50360901_44_dialog_content = "딱 보면 알 수 있지 않아? 우리 아이테르의 복장은 꽤 특별하니까.",
  ui_story_5036_50360901_45_dialog_content = "계속 그 꿈을 꾸는 게 이상하긴 했는데,\n어차피 악몽도 아니니까 그렇게 신경 쓰진 않았어.",
  ui_story_5036_50360901_46_dialog_content = "잠깐만, 저번에 이 얘기가 나왔을 땐 다들 그냥 우연이라고 생각했었는데?",
  ui_story_5036_50360901_47_dialog_content = "나도 그런 줄 알았는데, 지금은 콜로서스에 타고 있는 모두가 그 꿈을 꾸고 있어!",
  ui_story_5036_50360901_48_dialog_content = "여기 있는 사람이 다?!",
  ui_story_5036_50360901_49_dialog_content = "응, 한두 명이라면 그냥 우연이라고 여기겠지만,\n모든 사람이 똑같은 꿈을 꾼다는 건 너무 이상하잖아!",
  ui_story_5036_50360901_50_dialog_content = "그래서 지금 다들 불안해하고 있어.",
  ui_story_5036_50360901_51_dialog_content = "엊그제부터 이상한 꿈 때문에 제대로 쉬질 못하겠다는 불만이\n점점 더 많이 접수되고 있거든.",
  ui_story_5036_50360901_52_dialog_content = "제대로 휴식을 못 취하면 콘서트에서 최고의 기량을 발휘할 수 없잖아.",
  ui_story_5036_50360901_53_dialog_content = "그래서 그 이상한 꿈의 원인을 찾아서 모두가 푹 쉴 수 있게 해주고 싶단 거지?",
  ui_story_5036_50360901_54_dialog_content = "응... 그래서 혼자 조사해 보긴 했는데,\n나한텐 아이테르의 감응 능력이 없으니까 아무런 소득도 없었어.",
  ui_story_5036_50360901_55_dialog_content = "PlayerName 씨, 날 좀 도와줄 수 있을까?",
  ui_story_5036_50360901_56_dialog_content = "물론이지! 콘서트의 순조로운 개최를 위해서라면 당연히 나서야지!",
  ui_story_5036_50360901_57_dialog_content = "고마워!",
  ui_story_5036_50360901_58_dialog_content = "그렇긴 한데 칸타토르호는 너무 넓어서, 내 감응 능력이라도 한 번에\n콜로서스 전체를 다 감응할 순 없어.",
  ui_story_5036_50360901_59_dialog_content = "일단 어디부터 조사를 시작할까?",
  ui_story_5036_50360901_60_dialog_content = "그건 나도 잘 모르겠는데...",
  ui_story_5036_50360901_61_dialog_content = "콜로서스의 꼬리 부분에서 시작하는 편이 좋지 않겠어~?",
  ui_story_5036_50360901_62_dialog_content = "비크 씨?! 어디 있다 나타난 거야?",
  ui_story_5036_50360901_63_dialog_content = "내일모레면 콘서트가 열릴 텐데, 가서 연습 좀 더 하는 게 좋지 않겠어?",
  ui_story_5036_50360901_64_dialog_content = "에이, 다들 이상한 꿈 때문에 고민 중이라면서?",
  ui_story_5036_50360901_65_dialog_content = "잠을 잘 자야 연습할 정신도 생기지.",
  ui_story_5036_50360901_66_dialog_content = "일리 있는 말이긴 한데, 비크 씨가 그런 얘길 하니까 영 믿음이 안 가.",
  ui_story_5036_50360901_67_dialog_content = "하하, 그건 네 착각이야~",
  ui_story_5036_50360901_68_dialog_content = "비크 씨가 이렇게 적극적으로 나올 리가 없는데, 아무래도 수상해.",
  ui_story_5036_50360901_69_dialog_content = "기억났어! 저번에 콜로서스 꼬리 쪽에 가서 우로보로스를 찾고 싶다고 했잖아!\n이걸 핑계로 가서 우로보로스를 찾으려는 거 맞지?",
  ui_story_5036_50360901_70_dialog_content = "그렇게 말하면 섭섭하지~ 사람이 하나 더 있으면 도움이 될 거잖아?\n날 데려가도 절대 손해는 아닐 거야.",
  ui_story_5036_50360901_71_dialog_content = "알겠어. 대신 내일 연습 때 내가 지켜볼 테니까 게으름 피우면 안 돼.",
  ui_story_5036_50360901_72_dialog_content = "환상동물 마스터는 거짓말 같은 거 안 해.",
  ui_story_5036_50360901_73_dialog_content = "아무튼 지금은 그 이상한 꿈을 해결하는 데 집중하자고..",
  ui_story_5036_50360901_74_dialog_content = "(비크 씨가 이 일에 이렇게나 적극적이라니, 역시 수상해.)",
  ui_story_5036_50360901_75_dialog_content = "(대체 무슨 꿍꿍이지?)",
  ui_story_5036_50360901_76_dialog_content = "콜로서스의 꼬리 부분은... 암귀들이 점거하고 있는 봉쇄 구역이지?",
  ui_story_5036_50360901_77_dialog_content = "하필이면 그렇게 위험한 곳부터 조사를 시작하자니, 무슨 근거라도 있어?",
  ui_story_5036_50360901_78_dialog_content = "없어~",
  ui_story_5036_50360901_79_option_content = "비크 씨는 그냥 무시하는 게 좋을 것 같아.",
  ui_story_5036_50360901_80_dialog_content = "PlayerName, 아무리 그래도 우린 전에 같이 협력했던 동료잖아.\n그렇게 매정하게 말하지 말아줘!",
  ui_story_5036_50360901_81_option_content = "......",
  ui_story_5036_50360901_82_dialog_content = "......",
  ui_story_5036_50360901_83_dialog_content = "역시 젊은 친구들은 어쩔 수가 없다니까.\n별것도 아닌 일에 놀라고 그래?",
  ui_story_5036_50360901_84_dialog_content = "근거가 없는 건 맞지만, 대신 그만한 이유는 있어.",
  ui_story_5036_50360901_85_dialog_content = "콜로서스의 머리 쪽에 있던 암귀들은 이미 다 소탕해서,\n다들 그 구역을 자유롭게 돌아다니고 있잖아.",
  ui_story_5036_50360901_86_dialog_content = "그럼 그쪽은 사람들이 이미 다 살펴봤을 거 아냐?",
  ui_story_5036_50360901_87_dialog_content = "하긴 그렇네. 뭔가 이상한 점이 있었다면 일루미나랑\n백야성 사람들이 진작에 알아챘을 거야.",
  ui_story_5036_50360901_88_dialog_content = "그러니까 꼬리쪽이 훨씬 더 의심스럽지?",
  ui_story_5036_50360901_89_dialog_content = "근데 콜로서스 꼬리 쪽엔 아직 암귀들이 잔뜩 모여 있는데,\n딸랑 우리 셋만 가면 아무래도 좀 위험하지 않아?",
  ui_story_5036_50360901_90_dialog_content = "그 생각은 나도 했지.\n그 부분은 가골빼미한테 도움을 받으면 해결할 수 있어.",
  ui_story_5036_50360901_91_dialog_content = "일단 암귀들을 잠들게 만든 다음에 몰래 들어가면\n대부분의 전투 상황은 피할 수 있을 거야.",
  ui_story_5036_50360901_92_dialog_content = "전에 물건들을 훔칠 때도 그런 방법을 썼던 거구나?",
  ui_story_5036_50360901_93_dialog_content = "당연히... 아니거든!",
  ui_story_5036_50360901_94_dialog_content = "누가 뭐래도 저번 일은 가골빼미의 습성 때문에 비롯된 오해일 뿐이라고.",
  ui_story_5036_50360901_95_dialog_content = "그러니까 이번에 가골빼미한테 저번의 잘못을 만회하는 뜻에서\n우릴 돕도록 하면 되는 거잖아. 어때?",
  ui_story_5036_50360901_96_dialog_content = "됐어, 그건 콘서트 다 끝나고 나서 다시 얘기해.",
  ui_story_5036_50360901_97_dialog_content = "비크 씨 말도 확실히 일리는 있으니까,\n우선은 콜로서스의 꼬리 쪽부터 조사를 시작하자.",
  ui_story_5036_50360901_98_dialog_content = "응, 그럼 가자.",
  ui_story_5036_50360901_99_dialog_content = "(원래는 골디 씨를 만나서 골디 씨가 폭력적이라는 소문에 대해 물어보려고 했는데...)",
  ui_story_5036_50360901_100_dialog_content = "(본의 아니게 세 사람이 함께 행동하는 걸 봐 버렸잖아!)",
  ui_story_5036_50360901_101_dialog_content = "(거리가 좀 떨어져 있어서 다행이지, 아니었으면 PlayerName 씨가\n감응 능력으로 내가 있단 걸 알아차렸을 거야.)",
  ui_story_5036_50360901_102_dialog_content = "(하지만 너무 멀리 떨어져 있어서 세 사람이 구체적으로\n무슨 이야기를 나눴는진 못 들었어.)",
  ui_story_5036_50360901_103_dialog_content = "(저 방향은... 설마 콜로서스의 꼬리 쪽으로 가려는 건가?)",
  ui_story_5036_50360901_104_dialog_content = "(뭔가 수상해! 얼른 따라가 봐야겠어!)",
  ui_story_5036_50360901_105_dialog_content = "여긴 너무 어두워... 언제든 암귀가 튀어나올 것 같아서 불안한 느낌이야.",
  ui_story_5036_50360901_106_dialog_content = "걱정 붙들어 매. 다 가골빼미한테 맡기면 되니까. 자, 봐 봐.",
  ui_story_5036_50360901_107_dialog_content = "구구──!",
  ui_story_5036_50360901_108_dialog_content = "『노, 노라 님?!』",
  ui_story_5036_50360901_109_dialog_content = "구구구!",
  ui_story_5036_50360901_110_dialog_content = "『과찬이십니다! 앞으로는 배로 더 노력하겠습니다!』",
  ui_story_5036_50360901_111_dialog_content = "『노라 님께 칭찬받을 줄이야. 그런데... 이상하게... 잠이...』",
  ui_story_5036_50360901_112_dialog_content = "『하아암...』",
  ui_story_5036_50360901_113_dialog_content = "봤지? 엄청 잘 먹히잖아.",
  ui_story_5036_50360901_114_dialog_content = "이거 진짜 환상동물의 능력을 남용하는 거 아냐?",
  ui_story_5036_50360901_115_dialog_content = "가골빼미는 내 친구니까, 자기가 원해서 날 도와주는 거야. 분명히 그럴걸.",
  ui_story_5036_50360901_116_dialog_content = "근데 여기 진짜 어둡네...",
  ui_story_5036_50360901_117_dialog_content = "으... 안 돼, 이겨내야 해!",
  ui_story_5036_50360901_118_dialog_content = "골디, 너 괜찮아?",
  ui_story_5036_50360901_119_dialog_content = "어?! 괘, 괜찮아!",
  ui_story_5036_50360901_120_dialog_content = "아이돌인데 무슨 일이 있을 리가 없잖아~\n그냥 좀 피곤해서 그런 거야. 좀 쉬고 싶어.",
  ui_story_5036_50360901_121_dialog_content = "마시멜로, 잠깐만 껴안고 있을게.",
  ui_story_5036_50360901_122_dialog_content = "멍멍!",
  ui_story_5036_50360901_123_dialog_content = "보들보들, 폭신폭신... 좋아! 다 회복됐어!",
  ui_story_5036_50360901_124_dialog_content = "그럼 계속 가 볼까!",
  ui_story_5036_50360901_125_dialog_content = "(골디의 상태가 엄청 이상한데, 설마 어두운 걸 무서워하나...?)",
  ui_story_5036_50360901_126_dialog_content = "한참 걸었으니까, 이제 콜로서스의 꼬리에 거의 다 왔을 거야.",
  ui_story_5036_50360901_X126_dialog_content = "PlayerName 씨, 이 근처에서 뭔가 감응되는 거 없어?",
  ui_story_5036_50360901_127_dialog_content = "한번 해볼게.",
  ui_story_5036_50360901_128_option_content = "[감응한다]",
  ui_story_5036_50360901_129_dialog_content = "(잠든 암귀들밖에 없는 것 같네.)",
  ui_story_5036_50360901_130_dialog_content = "(근데 이유는 모르겠지만 자꾸 음산한 느낌이 들어. 기분 탓인가?)",
  ui_story_5036_50360901_131_dialog_content = "(잠깐만, 이 느낌...)",
  ui_story_5036_50360901_132_dialog_content = "(헤븐즈 밸리에 처음으로 돌아갔을 때랑 분위기가 거의 똑같아!\n과거의 아이테르가 감정을 남겨 둔 것 같아!)",
  ui_story_5036_50360901_133_dialog_content = "(한번 감응해 봐야겠어.)",
  ui_story_5036_50360901_134_dialog_content = "우와아아?! 카, 칸타토르, 이게 뭐야?!",
  ui_story_5036_50360901_135_dialog_content = "놀라지 마십시오, 샤미나드. 이건 암귀가 아닙니다.",
  ui_story_5036_50360901_136_dialog_content = "자료에 따르면 이 생물은 우로보로스라는 동물입니다.\n오로리안과 아이테르에게 무척 우호적이라고 합니다.",
  ui_story_5036_50360901_137_dialog_content = "암귀가 아니었구나! 다행이야.",
  ui_story_5036_50360901_138_dialog_content = "츄우우!",
  ui_story_5036_50360901_139_dialog_content = "아하하, 자꾸 얼굴 핥지 마~",
  ui_story_5036_50360901_140_dialog_content = "어때, PlayerName 씨. 뭔가 느껴져?",
  ui_story_5036_50360901_141_dialog_content = "역시 샤미나드라고 하는구나...",
  ui_story_5036_50360901_142_dialog_content = "샤미나드? 꿈속에 나오는 그 아이테르 소녀의 이름이 샤미나드야?",
  ui_story_5036_50360901_143_dialog_content = "응, 그 아이가 남긴 감정과 감응했거든. 그리고...",
  ui_story_5036_50360901_144_dialog_content = "우로보로스도 느껴졌어!",
  ui_story_5036_50360901_145_dialog_content = "뭐?!",
  ui_story_5036_50360901_146_dialog_content = "우로보로스를 감응했단 말이야? 빨리 자세히 얘기해 봐!",
  ui_story_5036_50360901_147_dialog_content = "잠깐만, 스톱! 일단 그만 흔들고 나 좀 놔 줘! 이러다 토할 것 같으니까!",
  ui_story_5036_50360901_148_dialog_content = "일단 말해 봐, 다 말하고 나면 놔 줄게~",
  ui_story_5036_50360901_149_dialog_content = "내가 감응한 우로보로스는 현재의 우로보로스가 아니라,\n과거에 여기 있던 우로보로스야! 과거라고!",
  ui_story_5036_50360901_150_dialog_content = "과거?",
  ui_story_5036_50360901_151_dialog_content = "이 콜로서스의 옛 주인은 모두가 꿈속에서 본 그 아이테르야.\n이름은 샤미나드라고 해.",
  ui_story_5036_50360901_152_dialog_content = "샤미나드는 과거에 여기서 우로보로스를 만났고,\n그 우로보로스를 콜로서스에 머물게 했어.",
  ui_story_5036_50360901_153_dialog_content = "근데 여러 가지로 살펴봤더니, 이 일은 아마 적어도 백 년 전에 있었던 일 같아.",
  ui_story_5036_50360901_154_dialog_content = "비크 씨가 찾으려고 하는 우로보로스도 진작에 여기서 떠났을 거야.",
  ui_story_5036_50360901_155_dialog_content = "흐음...",
  ui_story_5036_50360901_156_dialog_content = "일단 나 좀 놔 주면 안 될까?",
  ui_story_5036_50360901_157_dialog_content = "음~ 우로보로스의 위치는 아니지만, 그래도 간과할 수 없는 정보네.",
  ui_story_5036_50360901_158_dialog_content = "조금만 더 감응해 봐, 꼬마 아이테르!",
  ui_story_5036_50360901_159_dialog_content = "내가 아끼는 제자 피아랑 같이 모험도 했었으니까,\n이번엔 나한테 신세 진 보답을 해야지!",
  ui_story_5036_50360901_160_dialog_content = "내가 언제 비크 씨한테 신세를 졌다고 그래?!",
  ui_story_5036_50360901_161_dialog_content = "잠깐만! 우리가 우선적으로 해결해야 하는 건\n모두가 똑같은 꿈을 꾸는 이유를 찾는 거 아니었어?",
  ui_story_5036_50360901_162_dialog_content = "근데 왜 갑자기 우로보로스를 찾는 게 된 거야?",
  ui_story_5036_50360901_163_dialog_content = "아, 그랬지! 잘못하다 비크 씨의 페이스에 말려들 뻔했잖아!",
  ui_story_5036_50360901_164_dialog_content = "그건 아니지, 젊은 친구.",
  ui_story_5036_50360901_165_dialog_content = "아까 우로보로스랑 만난 아이테르가 모두의 꿈속에 나오는\n바로 그 소녀라고 했잖아?",
  ui_story_5036_50360901_166_dialog_content = "그건 맞아... 계속 조사를 한다고 해도, 그 소녀를 단서로 삼아야 할 테니까.",
  ui_story_5036_50360901_167_dialog_content = "그럼 조사하면서 우로보로스에 관련된 다른 정보가 보이면 그쪽에도 신경 좀 써 줘.",
  ui_story_5036_50360901_168_dialog_content = "뭔가 내가 비크 씨한테 돈도 못 받고 부려 먹히고 있는 것 같은데...",
  ui_story_5036_50360901_169_dialog_content = "괜히 부려 먹히고 있는 게 아니라, 경로사상이 투철한 거지.\n칭찬받아 마땅한 행동이야.",
  ui_story_5036_50360901_170_dialog_content = "진짜 핑곗거리 찾는 덴 선수라니까...",
  ui_story_5036_50360901_171_dialog_content = "천만에, 과찬이야.",
  ui_story_5036_50360901_172_dialog_content = "역시 기묘한 꿈에 대해 조사하는 건 PlayerName 씨한테 맡겨야겠어.",
  ui_story_5036_50360901_173_dialog_content = "PlayerName 씨, 다른 곳에도 여기처럼 남겨진 감정이 있는지 감응해 줄래?",
  ui_story_5036_50360901_174_dialog_content = "그 감정들에 남아 있는 정보에서 모두가 이상한 꿈을 꾸는\n원인을 찾을 수 있을지도 몰라.",
  ui_story_5036_50360901_175_dialog_content = "응! 한번 해 볼게!",
  ui_story_5036_50360901_176_dialog_content = "여긴 전에 와 본 적 없는 곳이네.",
  ui_story_5036_50360901_177_dialog_content = "아까 우리가 있던 복도보다 콜로서스 꼬리 쪽에 더 가까운 곳이니까,\n어쩌면 새로운 단서를 발견할 수도 있을 거야.",
  ui_story_5036_50360901_178_dialog_content = "골디, 비크 씨, 여기 말인데, 공기가 좀 싸하지 않아?",
  ui_story_5036_50360901_179_dialog_content = "확실히 좀 쌀쌀한 건 있네, 설마 다크매터 때문인가?",
  ui_story_5036_50360901_180_dialog_content = "아닐 거야. 다크매터가 많이 느껴지진 않거든.\n그냥 이상하게 자꾸 긴장되길래 해 본 얘기야.",
  ui_story_5036_50360901_181_dialog_content = "어라, 설마 너 어두운 걸 무서워하는 거야?",
  ui_story_5036_50360901_182_dialog_content = "아, 아니거든!",
  ui_story_5036_50360901_183_dialog_content = "괜찮아, 괜찮아. 부끄러워할 필요 없어.",
  ui_story_5036_50360901_184_dialog_content = "시라도 어렸을 땐 어두운 걸 무서워했었거든.\n밤이 되면 바람 소리에 놀라서 엉엉 울고 그랬다니까~",
  ui_story_5036_50360901_185_dialog_content = "드라코리온은 조류를 사냥할 뿐만 아니라... 엣취!",
  ui_story_5036_50360901_186_dialog_content = "재채기도 해?",
  ui_story_5036_50360901_187_dialog_content = "아, 아니야... 엣취!",
  ui_story_5036_50360901_188_dialog_content = "그냥 갑자기 재채기가 튀어나온 거야.",
  ui_story_5036_50360901_189_dialog_content = "시라 선배, 혹시 감기 걸렸어?",
  ui_story_5036_50360901_190_dialog_content = "아니야. 아마 비크 그 녀석이 또 어디서 몰래 내 흉을 보고 있는 거겠지.",
  ui_story_5036_50360901_191_dialog_content = "나중에 돌아오면 「차분한 대화」를 좀 나눠 봐야겠어.",
  ui_story_5036_50360901_192_dialog_content = "또 거짓말하는 거지?",
  ui_story_5036_50360901_193_dialog_content = "거짓말이 아냐. 못 믿겠으면 시라한테 물어보면 되잖아~",
  ui_story_5036_50360901_194_dialog_content = "됐어. 일단 할 일부터 하자.",
  ui_story_5036_50360901_X194_dialog_content = "이 근처에도 감정이 남아 있는 것 같으니까, 감응해 볼게.",
  ui_story_5036_50360901_195_option_content = "[감응한다]",
  ui_story_5036_50360901_196_dialog_content = "♪아침햇살을 머금은 이슬♪",
  ui_story_5036_50360901_197_dialog_content = "♪반짝이며 아른거리는 햇살♪",
  ui_story_5036_50360901_198_dialog_content = "(...이건 콜로서스를 기동할 때 사용하는 선율이잖아?!)",
  ui_story_5036_50360901_199_dialog_content = "츄우츄우─ 츄우─!",
  ui_story_5036_50360901_200_dialog_content = "으앗?! 우로보로스, 너 아직 안 잤어? 왜 여기 온 거야?!",
  ui_story_5036_50360901_201_dialog_content = "츄우─♪ 츄우─♪",
  ui_story_5036_50360901_202_dialog_content = "지금 노래 부르는 거야? 심지어 방금 내가 부르던 거잖아?!",
  ui_story_5036_50360901_203_dialog_content = "우로보로스! 너 설마 내 노래를 알아듣는 거야?!",
  ui_story_5036_50360901_204_dialog_content = "츄우─♪ 츄우츄우츄우─♪",
  ui_story_5036_50360901_205_dialog_content = "그렇게 흥얼거리는 걸 보면, 내 말이 맞다는 거지?!",
  ui_story_5036_50360901_206_dialog_content = "아이테르가 콜로서스를 조종할 때 사용하는 선율로\n이런 생명체와 교류할 수 있다니, 정말 놀랍군요.",
  ui_story_5036_50360901_207_dialog_content = "방금 감응해서 또 어떤 장면을 봤어...",
  ui_story_5036_50360901_208_dialog_content = "근데 다른 장면이랑 이어지는 게 아닌 데다가, 굉장히 짧아.",
  ui_story_5036_50360901_209_dialog_content = "그래? 어떤 장면이었는데?",
  ui_story_5036_50360901_210_dialog_content = "이상한 꿈에 대한 얘기도 나왔어?",
  ui_story_5036_50360901_211_dialog_content = "꿈에 대한 내용은 아니었어.",
  ui_story_5036_50360901_212_dialog_content = "샤미나드가 우연히 우로보로스의 비밀을 발견해서 깜짝 놀라는 장면이었어.",
  ui_story_5036_50360901_213_dialog_content = "우로보로스라는 녀석은 아이테르가 콜로서스를 조종할 때 사용하는 선율로\n자기 감정을 표현하고 사람과 교류할 수 있는 것 같아.",
  ui_story_5036_50360901_214_dialog_content = "오? 그건 우로보로스에 대한 새로운 발견인걸!",
  ui_story_5036_50360901_215_dialog_content = "정말 큰 공을 세웠네, PlayerName.\n내가 돈이 많았으면 상금이라도 주는 거였는데.",
  ui_story_5036_50360901_216_dialog_content = "......",
  ui_story_5036_50360901_217_dialog_content = "그러고 보니까 고서에서도 본 적 있는 것 같아.\n우로보로스와 콜로서스는 뭔가 설명하기 어려운 관계가 있다고 말이야.",
  ui_story_5036_50360901_218_dialog_content = "이런 걸 보면 우로보로스는 정신 쪽과 관련된 능력을 가지고 있는 게 아닐까 싶어.",
  ui_story_5036_50360901_219_dialog_content = "예를 들면... 사람한테 특정한 꿈을 꾸게 한다든지.",
  ui_story_5036_50360901_220_dialog_content = "그게 가능해?!",
  ui_story_5036_50360901_221_dialog_content = "이번에도 거짓말이면 정의의 이름으로 당신을 용서하지 않겠어!",
  ui_story_5036_50360901_222_dialog_content = "다, 당연히 아니지! 내가 어떻게 거짓말을 하겠어!",
  ui_story_5036_50360901_223_dialog_content = "그렇지만 내 추측일 뿐이라 100% 확신은 못 해~",
  ui_story_5036_50360901_224_dialog_content = "수상한데...",
  ui_story_5036_50360901_225_dialog_content = "PlayerName 씨, 어떻게 생각해?",
  ui_story_5036_50360901_226_option_content = "난 비크 씨를 믿어.",
  ui_story_5036_50360901_227_dialog_content = "비크 씨가 거짓말도 자주 하고, 일도 영 못 미덥게 처리하긴 하지만...",
  ui_story_5036_50360901_228_dialog_content = "환상동물에 대해서만큼은 반박의 여지 없이 엄청 잘 알고 있어.",
  ui_story_5036_50360901_229_dialog_content = "살짝 믿어도 별 문젠 없을 거야.",
  ui_story_5036_50360901_230_dialog_content = "맞아, 맞아. 어른 말을 들으면 자다가도 떡이 생긴다잖아~",
  ui_story_5036_50360901_231_dialog_content = "알겠어, 그럼 PlayerName 씨의 판단을 믿을게.",
  ui_story_5036_50360901_232_option_content = "난 비크 씨를 믿지 않아.",
  ui_story_5036_50360901_233_dialog_content = "개인적인 조언을 하자면, 비크 씨 말은 안 믿는 편이 좋아.\n사실을 얘기한 적이 손에 꼽을 정도거든.",
  ui_story_5036_50360901_234_dialog_content = "그렇게 말하면 이 노인네 정말 속상해, 으흑...",
  ui_story_5036_50360901_235_dialog_content = "지금도 이거 봐. 자기가 영원한 18세라더니 이젠 또 노인네라잖아.",
  ui_story_5036_50360901_236_dialog_content = "마음만은 이팔청춘이란 소리지! 젊은애들은 이런 걸 몰라요.",
  ui_story_5036_50360901_237_dialog_content = "확실히 믿음이 안 가!",
  ui_story_5036_50360901_238_dialog_content = "으윽!",
  ui_story_5036_50360901_239_dialog_content = "그렇지만 지금은 이 단서를 따라 조사하는 거 말곤 다른 방법도 없어.",
  ui_story_5036_50360901_240_dialog_content = "어쩔 수 없이 계속 조사해야 하는 걸까? 휴...\n아니지, 이렇게 쉽게 포기하면 안 돼.",
  ui_story_5036_50360901_241_dialog_content = "계속 이동하자. 다른 데도 가 봐야겠어.",
  ui_story_5036_50360901_242_dialog_content = "(왜 계속 가다가 멈췄다 가다가 멈췄다하는 거지? 셋이서 대체 뭐 하는 걸까?)",
  ui_story_5036_50360901_243_dialog_content = "(계속 따라오다 보니까 나도 모르게 봉쇄 구역까지 와 버렸잖아.\n분위기가 으스스해서 무서운걸...)",
  ui_story_5036_50360901_244_dialog_content = "<color=#e8d9bb>휘이잉──</color>",
  ui_story_5036_50360901_245_dialog_content = "(히익?! 바, 바람 소린가? 그냥 이쯤에서 돌아가고\n내일 골디 씨를 만나서 물어보는 게 나으려나...?)",
  ui_story_5036_50360901_246_dialog_content = "(아니, 안 돼! 브랜디, 넌 진실을 추구하는 기자잖아!\n어떻게 이런 곳에서 포기할 수 있어!)",
  ui_story_5036_50360901_247_dialog_content = "(얼른 따라가자!)",
  ui_story_5036_50360901_248_dialog_content = "우리가 얼마나 걸었지? 한 20분 걸었나?",
  ui_story_5036_50360901_249_dialog_content = "복도가 꽤 복잡하게 생겨서 꼭 같은 곳을 빙빙 돌고 있는 것 같아.",
  ui_story_5036_50360901_250_dialog_content = "PlayerName, 넌 콜로서스에서 오래 생활했잖아?\n차라리 네가 길 안내를 하는 게 어때?",
  ui_story_5036_50360901_251_dialog_content = "내가 잘 아는 건 스카이워커뿐이야.\n칸타토르호의 구조를 내가 어떻게 알아...",
  ui_story_5036_50360901_252_dialog_content = "그렇겠네... 그럼 감응 능력을 사용해 보는 건 어때?",
  ui_story_5036_50360901_253_dialog_content = "이 근처에 그 아이테르 소녀의 감정이 남아 있다면,\n혹시 길 안내를 해 줄 수도 있잖아?",
  ui_story_5036_50360901_254_dialog_content = "그럴 수도 있겠네. 그럼 해 볼게!",
  ui_story_5036_50360901_255_option_content = "[감응한다]",
  ui_story_5036_50360901_256_dialog_content = "칸타토르, 큰일 났어!",
  ui_story_5036_50360901_257_dialog_content = "우로보로스가 이렇게 변해 버렸어!",
  ui_story_5036_50360901_258_dialog_content = "으아앙...! 대체 왜 이렇게 변한 거지? 설마 영원히 우리 곁을 떠난 거야?",
  ui_story_5036_50360901_259_dialog_content = "우로보로스 덕분에 지금까지 암귀한테 공격받지 않고\n여기까지 올 수 있었던 건데...",
  ui_story_5036_50360901_260_dialog_content = "걱정하지 마십시오, 샤미나드.",
  ui_story_5036_50360901_261_dialog_content = "우로보로스는 장수하는 생명체입니다.\n나이가 들면 알로 변했다가 다시 부화해 새로운 생명을 얻는 것입니다.",
  ui_story_5036_50360901_262_dialog_content = "이 우로보로스는 자신이 가장 무방비할 때, 샤미나드가 자신을 보호해 줄 거라\n믿었기 때문에 이곳에서 알로 변한 것입니다.",
  ui_story_5036_50360901_263_dialog_content = "그러니 어느 정도 시간이 지나면 다시 함께 여행할 수 있을 겁니다.",
  ui_story_5036_50360901_264_dialog_content = "그런 거였어?",
  ui_story_5036_50360901_265_dialog_content = "우로보로스가 우릴 떠난 게 아니라 진짜 다행이야!\n앞으로도 같이 여행할 수 있겠네!",
  ui_story_5036_50360901_266_dialog_content = "그럼 내가 우로보로스를 잘 보호해 줘야지. 이렇게 하면 되겠다!\n이 알을 벽이 가장 튼튼한 그 방에 보관해 두는 거야!",
  ui_story_5036_50360901_267_dialog_content = "거기 두면, 암귀가 아무리 많이 와도 이 알에 접근할 순 없을 테니까!",
  ui_story_5036_50360901_268_dialog_content = "봤어! 이번엔 아주 선명하게 보였어!",
  ui_story_5036_50360901_269_dialog_content = "샤미나드가 우로보로스의 알을 콜로서스에서 가장 튼튼한 방에 놔두겠다고 했어.",
  ui_story_5036_50360901_X269_dialog_content = "그러고는 이쪽으로 뛰어갔어.",
  ui_story_5036_50360901_270_dialog_content = "그럼 얼른 가 보자. 새로운 단서를 찾을 수 있을지도 모르잖아.",
  ui_story_5036_50360901_271_dialog_content = "그때부터 시간이 많이 지났는데, 아직도 거기 단서가 남아 있을까?",
  ui_story_5036_50360901_272_dialog_content = "그거야 모르지. 일단 가 보자.",
  ui_story_5036_50361001_1_dialog_content = "벌써 10분도 넘게 걸은 것 같은데, 왜 아직도 그 방이 안 보이는 거지?",
  ui_story_5036_50361001_2_dialog_content = "칸타토르호가 아무리 커다랗다고 해도, 이쯤 걸었으면 도착해야 하는 건데.",
  ui_story_5036_50361001_3_dialog_content = "설마... 우리 진짜 아까부터 계속 같은 자리를 맴돌고 있는 거 아니야?",
  ui_story_5036_50361001_4_dialog_content = "모르겠어... 근데 갈수록 견디기가 너무 힘들어.",
  ui_story_5036_50361001_5_dialog_content = "음침하고 으스스해서 자꾸 소름 돋아.",
  ui_story_5036_50361001_6_dialog_content = "방향을 못 찾아서, 자꾸 같은 자리를 빙글빙글 도는 건\n내가 다니면서 많이 겪어 본 일이야.",
  ui_story_5036_50361001_7_dialog_content = "이럴 땐 표시를 해 둬야 한다고~",
  ui_story_5036_50361001_8_dialog_content = "좋은 방법이네. 혹시 펜 가지고 있는 사람?",
  ui_story_5036_50361001_9_dialog_content = "난 없어~",
  ui_story_5036_50361001_10_dialog_content = "나도 없어. 가져온 거라곤 이게 다야.",
  ui_story_5036_50361001_11_dialog_content = "이건 콘서트 포스터잖아? 조사하러 나오는 건데 이런 것도 챙긴 거야?",
  ui_story_5036_50361001_12_dialog_content = "만나면 사인해 달라는 팬들이 많은데, 사인지를 안 가져오는 경우가 많더라고.",
  ui_story_5036_50361001_13_dialog_content = "그래서 팬들의 사랑을 저버리지 않기 위해서\n항상 사인지용으로 쓸 포스터를 가지고 다녀.",
  ui_story_5036_50361001_14_dialog_content = "정말 세심하네!",
  ui_story_5036_50361001_15_dialog_content = "아이돌이라면 기본적으로 언제 어디서든 팬들을 배려해야 하는 거니까!",
  ui_story_5036_50361001_16_dialog_content = "포스터? 음, 확실히 눈에 확 띄는 표시가 되겠네~",
  ui_story_5036_50361001_17_dialog_content = "아무튼 일단 포스터 한 장을 여기 붙여 두고, 계속 앞으로 가 보자!",
  ui_story_5036_50361001_18_dialog_content = "<color=#e8d9bb>얼마 후</color>",
  ui_story_5036_50361001_19_dialog_content = "몇 분이나 걸었는데도 주변이 전혀 달라진 게 없어.",
  ui_story_5036_50361001_20_dialog_content = "어? 저거 아까 붙여 둔 포스터 아냐?",
  ui_story_5036_50361001_21_dialog_content = "진짜네! 우리 정말 같은 곳에서 빙빙 헤매고 있었어!",
  ui_story_5036_50361001_22_dialog_content = "잠깐만, 포스터가 좀 이상해...",
  ui_story_5036_50361001_23_dialog_content = "이 포스터에 있는 골디 말인데, 머리색이 왜 검은색이지? 표정도 뭔가 어색하고...",
  ui_story_5036_50361001_24_dialog_content = "뭐, 뭐야? 왜 이렇게 변한 건데? 누가 장난치는 거야?!",
  ui_story_5036_50361001_25_dialog_content = "근데 여긴 아직 사람들이 탐색하지 않은 콜로서스의 꼬리 쪽인걸.\n우리 셋 말곤 여기 온 사람은 없을 거야~",
  ui_story_5036_50361001_26_dialog_content = "그럼 설마...",
  ui_story_5036_50361001_27_option_content = "누가 우릴 미행하고 있는 건가?!",
  ui_story_5036_50361001_28_dialog_content = "설마 사생팬? 아니면 설마 콘서트를 망치러 온 악당 녀석인가?",
  ui_story_5036_50361001_29_dialog_content = "어느 쪽이든 좀 끔찍한데...",
  ui_story_5036_50361001_30_dialog_content = "우리 그냥 빨리 여기서 떠나자.",
  ui_story_5036_50361001_31_option_content = "암귀인가?!",
  ui_story_5036_50361001_32_dialog_content = "하지만 암귀라면 아까 전부 가골빼미의 최면에 걸렸을 텐데?",
  ui_story_5036_50361001_33_dialog_content = "아직 깨어나진 못했을 거야.",
  ui_story_5036_50361001_34_dialog_content = "계속 여기 있는 건 아무래도 아닌 것 같아. 그냥 빨리 떠나자!",
  ui_story_5036_50361001_35_dialog_content = "근데 떠나려면 대체 어느 쪽으로 가야 하는 거지?",
  ui_story_5036_50361001_36_dialog_content = "아까부터 계속 빙빙 돈 거라면, 이번엔 한 방향으로 쭉 전진만 하면 되겠지!",
  ui_story_5036_50361001_37_dialog_content = "이쪽으로 가자!",
  ui_story_5036_50361001_38_dialog_content = "좀 천천히 가~ 나이 든 사람 생각도 좀 해 줘!",
  ui_story_5036_50361001_39_dialog_content = "골디! 너무 빨리 뛰지 마!",
  ui_story_5036_50361001_40_dialog_content = "(화, 확실히 좀 묘한 게 있는 포스터인걸.)",
  ui_story_5036_50361001_41_dialog_content = "(으앗! 나, 나도 같이 갈래!)",
  ui_story_5036_50361001_42_dialog_content = "휴... 휴우... 여긴 왠지 아까 그 복도랑 좀 다른 것 같아.",
  ui_story_5036_50361001_43_dialog_content = "혹시 여기가 바로 샤미나드가 말했던 그 방인가?",
  ui_story_5036_50361001_44_dialog_content = "튼튼해 보이긴 하지만, 오랫동안 수리도 안 하고\n방치돼 있던 탓인지 벽이 꽤 낡았어.",
  ui_story_5036_50361001_45_dialog_content = "게다가 음침한 기운도 갈수록 심해지고 있고. 진짜 계속 여기 있기 싫은데...",
  ui_story_5036_50361001_46_dialog_content = "이 근처는 파손된 부분이 많아서 언제든 암귀가 불쑥 튀어나올 것 같아.",
  ui_story_5036_50361001_47_dialog_content = "부스럭부스럭...",
  ui_story_5036_50361001_48_dialog_content = "뭔가 움직이고 있어! 거기 누구야?",
  ui_story_5036_50361001_49_dialog_content = "당장 나와!",
  ui_story_5036_50361001_50_dialog_content = "으앗?! 그, 그러지 마세요! 저예요!",
  ui_story_5036_50361001_51_dialog_content = "브랜디 너한테 한 얘기가 아니야!",
  ui_story_5036_50361001_52_dialog_content = "네?",
  ui_story_5036_50361001_53_dialog_content = "브랜디? 네가 왜 여기 있어? 아니지! 뒤를 조심해!",
  ui_story_5036_50361001_54_dialog_content = "크어어──!",
  ui_story_5036_50361001_55_dialog_content = "빨리 피해!",
  ui_story_5036_50361001_56_dialog_content = "앗! 골디 씨?!",
  ui_story_5036_50361001_57_dialog_content = "(골디 씨가 날 구해 줬어!)",
  ui_story_5036_50361001_58_dialog_content = "내 눈앞에서 다른 사람을 해치려고 하다니! 그건 절대 용납 못해!",
  ui_story_5036_50361001_59_dialog_content = "내가 내리는 정의의 심판을 받아라!",
  ui_story_5036_50361001_60_dialog_content = "멍멍! 멍!",
  ui_story_5036_50361002_1_dialog_content = "으아앗! 정말 위험했어요!",
  ui_story_5036_50361002_2_dialog_content = "이젠 괜찮아. 마지막 암귀까지 다 처치했으니까!",
  ui_story_5036_50361002_3_dialog_content = "괜찮아? 어디 다치진 않았지?",
  ui_story_5036_50361002_4_dialog_content = "다리가 좀 풀린 거 빼곤 멀쩡해요...",
  ui_story_5036_50361002_5_dialog_content = "자꾸 누군가 지켜 보고 있는 것 같은 묘한 느낌이 들었는데,\n이 아가씨가 계속 우릴 쫓아 오고 있었던 거구나.",
  ui_story_5036_50361002_6_dialog_content = "여긴 어떻게 왔어? 설마 우릴 따라 온 거야?",
  ui_story_5036_50361002_7_dialog_content = "미행은 안 돼, 브랜디. 그건 처벌받아야 할 범죄라구!",
  ui_story_5036_50361002_8_dialog_content = "전... 으윽, 그런 거 아니에요!",
  ui_story_5036_50361002_9_dialog_content = "전 진상을 조사하려고 온 거라구요!",
  ui_story_5036_50361002_10_dialog_content = "진상을 조사해? 설마 브랜디도 이상한 꿈에 대해 조사하러 온 거야?",
  ui_story_5036_50361002_11_dialog_content = "그, 그게 아니라 다른 일을 말하는 거예요. 원래는 몰래 조사하려고 했지만,\n이렇게 발견된 이상 그냥 단도직입적으로 물어봐야겠어요.",
  ui_story_5036_50361002_12_dialog_content = "골디 씨, 스타 시어터의 소유주를 아직 기억하고 계신가요?",
  ui_story_5036_50361002_13_dialog_content = "응? 생각 좀 해 볼게. 네가 말하니까 왠지 기억이 나는 것 같기도 해.",
  ui_story_5036_50361002_14_dialog_content = "그 사람도 골디 씨한테 혼쭐이 났던 적이 있나 보네?",
  ui_story_5036_50361002_15_dialog_content = "비크 씨, 잠깐만 말 끊지 말아 봐.",
  ui_story_5036_50361002_16_dialog_content = "짧은 시간 동안이지만 같이 일하긴 했어. 결국엔 서로 안 좋게 갈라섰지만.",
  ui_story_5036_50361002_17_dialog_content = "갈라섰다고요? 그럼 왜 다른 공연장을 찾지 않고, 굳이 이런저런 어려움을 무릅쓰고\n이 표류하는 콜로서스 위에서 콘서트를 개최하시려는 거죠?",
  ui_story_5036_50361002_18_dialog_content = "그 사람과 갈라서고 나선 나한테 공연장을 빌려주겠다는 사람이 없었거든.",
  ui_story_5036_50361002_19_dialog_content = "그럼 다른 사람들이 왜 골디 씨의 제안을 거절했는지는 알고 계신가요?",
  ui_story_5036_50361002_20_dialog_content = "그건 말하자면 길어.",
  ui_story_5036_50361002_21_dialog_content = "그 스타 시어터의 소유주는 전에 골디 씨한테 폭행을 당했다며\n저희 《데일리 스쿠프 속보》의 편집장님한테 제보를 해 왔어요.",
  ui_story_5036_50361002_X21_dialog_content = "그게 무슨 소리야? 골디 씨가 폭력을 휘두르는 사람이란 얘기야?",
  ui_story_5036_50361002_22_dialog_content = "심지어 골디 씨한테 맞아서 다친 거라면서 편집장님한테\n새파랗게 멍든 코와 퉁퉁 부은 얼굴까지 보여 줬어요. 정말 아파 보였죠...",
  ui_story_5036_50361002_23_dialog_content = "난 그 사람을 때린 적 없어. 사람을 때린 건 오히려 그 사람이야!\n아무 죄 없는 아이한테 손찌검을 하려고 했다구!",
  ui_story_5036_50361002_24_dialog_content = "솔직히 저는 지금도 골디 씨가 그런 짓을 했다고 믿고 싶지 않지만,\n기자로서 전 반드시 증거를 찾아야 해요.",
  ui_story_5036_50361002_25_dialog_content = "골디 씨의 결백을 증명하거나, 스타 시어터 소유주의 범죄 사실을\n밝힐 수 있는 무언가가 있나요?",
  ui_story_5036_50361002_26_dialog_content = "물론 진상을 얘기해 줄 수 있어. 그래야 내 억울함도 풀 수 있을 테니까.",
  ui_story_5036_50361002_27_dialog_content = "사건은 열흘 정도 전에 일어났어.\n그 무렵 난 콘서트를 개최할 장소를 찾고 있었어.",
  ui_story_5036_50361002_28_dialog_content = "여러 가지를 고려해 보니 스타 시어터가 가장 좋을 것 같아서, 거길 대관하기로 했었어.",
  ui_story_5036_50361002_29_dialog_content = "그리고 공연장 환경을 파악해 둬야 하니까, 거기서 리허설을 한번 했었고.",
  ui_story_5036_50361002_30_dialog_content = "라라~♪ 라랄라♪",
  ui_story_5036_50361002_31_dialog_content = "<color=#e8d9bb>퍼억──!</color>",
  ui_story_5036_50361002_32_dialog_content = "으아아악!",
  ui_story_5036_50361002_33_dialog_content = "살려주세요!",
  ui_story_5036_50361002_34_dialog_content = "어라? 무슨 소리지?",
  ui_story_5036_50361002_35_dialog_content = "네까짓 게 여기가 어딘 줄 알고 기어들어 와? 썩 꺼져! 썩 꺼지란 말이야!",
  ui_story_5036_50361002_36_dialog_content = "더러운 쥐새끼들 주제에 감히 내 극장을 더럽히려고 해?!",
  ui_story_5036_50361002_37_dialog_content = "으악!",
  ui_story_5036_50361002_38_dialog_content = "안 돼요! 제 동생 때리지 마세요!",
  ui_story_5036_50361002_39_dialog_content = "지금 뭐 하시는 거죠?!",
  ui_story_5036_50361002_40_dialog_content = "어이쿠, 이거 인기 스타 골디 양 아니십니까?\n별거 아닙니다. 골디 양이 신경 쓰실 거 없어요.",
  ui_story_5036_50361002_41_dialog_content = "그냥 티켓 살 돈도 없는 거지 녀석들이 노래를 들으려고 하길래\n바로 쫓아내 버린 것뿐이니까요.",
  ui_story_5036_50361002_42_dialog_content = "지금은 정식 콘서트도 아니고 그냥 리허설만 하는 건데,\n우리가 여기서 저 누나 노래 좀 듣는 게 그렇게 큰 잘못이야?",
  ui_story_5036_50361002_43_dialog_content = "노래를 듣고 싶으면, 나한테 돈을 내야 하는 거다.",
  ui_story_5036_50361002_44_dialog_content = "잘못을 저지른 게 누군데 감히 날 들이받아?\n아주 제대로 혼이 나야겠구나!",
  ui_story_5036_50361002_45_dialog_content = "으아아악!",
  ui_story_5036_50361002_X45_dialog_content = "살려주세요!",
  ui_story_5036_50361002_46_dialog_content = "그만두세요!",
  ui_story_5036_50361002_47_dialog_content = "<color=#e8d9bb>콰당!</color>",
  ui_story_5036_50361002_48_dialog_content = "으윽! 콜록콜록...",
  ui_story_5036_50361002_49_dialog_content = "감히 스타 시어터의 주인인 날 건드리다니!",
  ui_story_5036_50361002_50_dialog_content = "아무리 극장의 소유주라고 해도, 죄 없는 아이들한테 폭력을 휘두르면 안 되죠!",
  ui_story_5036_50361002_51_dialog_content = "지금 당신이 무슨 짓을 하고 있는 건지는 알고 있습니까?",
  ui_story_5036_50361002_52_dialog_content = "콜록콜록...",
  ui_story_5036_50361002_53_dialog_content = "아무래도 당신이 스타 시어터에서 콘서트를 열게 해 줄 순 없을 것 같군요, 골디 양.",
  ui_story_5036_50361002_54_dialog_content = "...그거 참 유감이네요.",
  ui_story_5036_50361002_55_dialog_content = "골디 씨는 폭력을 휘두른 게 아니라, 그 두 아이를 보호하기 위해서 손을 뻗다가\n실수로 스타 시어터의 주인을 밀어 쓰러트린 거였군요?",
  ui_story_5036_50361002_56_dialog_content = "왜 떠돌고 있는 소문이랑 전혀 다른 거죠?!",
  ui_story_5036_50361002_57_dialog_content = "그 소문들은 다 근거도 없는 날조일 뿐이야!",
  ui_story_5036_50361002_58_dialog_content = "게다가 그 사람은 넘어질 때 엉덩이 쪽부터 바닥에 닿았어. 절대로 얼굴이 아니었다구!",
  ui_story_5036_50361002_59_dialog_content = "못 믿겠다면 그 두 아이를 만나서 그날 무슨 일이 있었는지 직접 물어봐.",
  ui_story_5036_50361002_60_dialog_content = "(골디 씨는 처음부터 쭉 일관되게 정의감을 보여 왔어.\n그러니까 제멋대로 폭력을 행사하는 사람은 아닐 거야.)",
  ui_story_5036_50361002_61_dialog_content = "하지만 왜 처음부터 모두에게 이 사실을 알리지 않았나요?",
  ui_story_5036_50361002_62_dialog_content = "난 아이돌이니까. 사람들한테 약한 면을 보여줄 순 없어.",
  ui_story_5036_50361002_63_dialog_content = "그 사람이 다른 극장주들과 함께 나한테 공연장을 빌려주지 않은 목적은 뻔해.\n내 명성에 흠집을 내겠단 거지.",
  ui_story_5036_50361002_64_dialog_content = "난 팬들한테 움브라톤에서 콘서트를 열겠다고 약속했고,\n그 사람들은 어떻게든 내가 그 약속을 못 지키게 만들고 싶어 했어.",
  ui_story_5036_50361002_65_dialog_content = "팬들하고 한 약속을 지키지 못한다면, 팬들이 나한테 실망하게 될 테니까.",
  ui_story_5036_50361002_X65_dialog_content = "팬들한테서 신뢰를 잃는다면, 그건 아이돌로서 죽은 거나 다름없어!",
  ui_story_5036_50361002_X66_dialog_content = "그러니까 무슨 수를 써서라도 난 이번 콘서트를 계획대로 진행해야 했어.",
  ui_story_5036_50361002_X67_dialog_content = "난 모두의 응원과 사랑을 저버리지 않을 거란 사실을 알려야 하니까!",
  ui_story_5036_50361002_66_dialog_content = "뭐 그런 나쁜 녀석들이 다 있어!",
  ui_story_5036_50361002_67_dialog_content = "그리고 내게 남은 방법은 모두가 날 볼 수 있도록\n사상 초유의 콘서트를 개최하는 것뿐이었어.",
  ui_story_5036_50361002_68_dialog_content = "지명도를 높여야만, 누군가 내 말에 귀를 기울여 주고, 내 말을 믿어 줄 테니까!",
  ui_story_5036_50361002_69_dialog_content = "그래서 그때 난 모두한테 내가 어려움에 빠진 모습을 보이고 싶지 않아서\n그 사건을 잠깐 묻어 두기로 한 거야.",
  ui_story_5036_50361002_70_dialog_content = "(골디 씨는 이런 생각을 가지고 있었구나...)",
  ui_story_5036_50361002_71_dialog_content = "(거짓말을 하는 사람의 눈빛은 아니야.\n게다가 아깐 암귀들한테서 날 구해주기도 했고.)",
  ui_story_5036_50361002_72_dialog_content = "(휴... 정말 다행이야. 하마터면 경솔하게 헛소문을 퍼트려서\n골디 씨를 악당으로 만들 뻔했잖아.)",
  ui_story_5036_50361002_73_dialog_content = "이 일에 대해선 나중에 그 두 아이를 찾아서 확실하게 물어볼게요.",
  ui_story_5036_50361002_X73_dialog_content = "그리고 골디 씨 말이 사실이라는 게 확실해지면,\n제가 골디 씨의 소문에 대한 반박 기사를 낼게요!",
  ui_story_5036_50361002_74_dialog_content = "그래 주면 정말 고맙지!",
  ui_story_5036_50361002_75_dialog_content = "감사는 모험이 끝날 때까지 미뤄 둬. 우리한텐 아직 할 일이 남아 있잖아.",
  ui_story_5036_50361002_76_dialog_content = "참! PlayerName 씨, 우리 지금 어디까지 왔어?",
  ui_story_5036_50361002_77_dialog_content = "내가 감응했을 때 느껴진 방향은 이쪽이었으니까,\n아마 샤미나드가 알을 숨겨 둔 곳에 거의 다 도착했을 거야.",
  ui_story_5036_50361002_78_dialog_content = "다시 감응해 볼게.",
  ui_story_5036_50361002_79_option_content = "[감응한다]",
  ui_story_5036_50361002_80_dialog_content = "크오오──!",
  ui_story_5036_50361002_81_dialog_content = "<color=#e8d9bb>쿵──!</color>",
  ui_story_5036_50361002_82_dialog_content = "으아아악!",
  ui_story_5036_50361002_83_dialog_content = "어떡하지! 암귀들이 조금 있으면 이 안으로 들어올 거야...",
  ui_story_5036_50361002_84_dialog_content = "콜로서스에서 가장 튼튼한 방이라도 암귀는 막지 못하는 걸까?",
  ui_story_5036_50361002_85_dialog_content = "칸타토르? 칸타토르!",
  ui_story_5036_50361002_86_dialog_content = "<color=#e8d9bb>.........</color>",
  ui_story_5036_50361002_87_dialog_content = "흑흑... 설마 칸타토르는 벌써...",
  ui_story_5036_50361002_88_dialog_content = "...이러면 안 돼! 내가 힘을 내야지! 난 우로보로스를 지켜야 하니까!",
  ui_story_5036_50361002_89_dialog_content = "적어도 우로보로스의 알을 어딘가에 숨겨야만 해!",
  ui_story_5036_50361002_90_dialog_content = "벽에 있는 비밀 사물함에 넣어 두면 아마 암귀들도 못 찾을 거야...",
  ui_story_5036_50361002_91_dialog_content = "우로보로스야, 함부로 움직이지 말고 여기 잘 숨어 있어야 해...",
  ui_story_5036_50361002_92_dialog_content = "내가... 내가 꼭 널 지켜 줄게!",
  ui_story_5036_50361002_93_dialog_content = "<color=#e8d9bb>쿵! 쿵!</color>",
  ui_story_5036_50361002_94_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5036_50361002_95_dialog_content = "크오오...",
  ui_story_5036_50361002_96_dialog_content = "암귀...",
  ui_story_5036_50361002_97_dialog_content = "...전부 나한테 와!",
  ui_story_5036_50361002_98_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5036_50361002_99_dialog_content = "아파...",
  ui_story_5036_50361002_100_dialog_content = "너무... 추워...",
  ui_story_5036_50361002_101_dialog_content = "칸타토르... 우로보로스... 다들... 아직 여기 있어?",
  ui_story_5036_50361002_102_dialog_content = "나... 집에 가고 싶어...",
  ui_story_5036_50361002_103_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5036_50361002_104_dialog_content = "츄우우──!",
  ui_story_5036_50361101_1_dialog_content = "......",
  ui_story_5036_50361101_2_dialog_content = "PlayerName?",
  ui_story_5036_50361101_3_dialog_content = "............",
  ui_story_5036_50361101_4_dialog_content = "PlayerName 씨, 괜찮아? 이번에는 뭘 봤어?",
  ui_story_5036_50361101_5_dialog_content = "샤미나드의... 마지막 기억을 봤어.",
  ui_story_5036_50361101_6_dialog_content = "우로보로스가 알로 변한 다음에, 샤미나드와 칸타토르호는 암귀의 공격을 받았어.",
  ui_story_5036_50361101_7_dialog_content = "그래서 샤미나드는 우로보로스의 알을 지키기 위해\n저쪽 벽에 있는 비밀 사물함 안에 그걸 숨겨 뒀어.",
  ui_story_5036_50361101_8_dialog_content = "그리고 암귀를 여기서 떼어 놓으려고 했지만 결국...",
  ui_story_5036_50361101_9_dialog_content = "...더는 말 안 해도 돼.",
  ui_story_5036_50361101_10_dialog_content = "그 꼬마 아가씨는 마지막 순간까지도 우로보로스의 알을 지켜 줬던 거구나.",
  ui_story_5036_50361101_11_dialog_content = "아주 잘 지켜줬어. 조금 과할 정도로 말이야.",
  ui_story_5036_50361101_12_dialog_content = "비크 씨, 이럴 땐 말 좀 가려서 하면 안 돼?",
  ui_story_5036_50361101_13_dialog_content = "이상한 소리한 거 아니야. 못 믿겠으면 저기 벽의 틈 안을 좀 봐.",
  ui_story_5036_50361101_14_dialog_content = "안에 뭐가 있어?",
  ui_story_5036_50361101_15_dialog_content = "어머!",
  ui_story_5036_50361101_16_dialog_content = "골디, 왜 그래?",
  ui_story_5036_50361101_17_dialog_content = "저게 뭐야? 왜 벽 무늬랑 다르지?",
  ui_story_5036_50361101_18_dialog_content = "재질이 콜로서스 기재나 금속이 아니라... 알껍데기랑 닮았어.",
  ui_story_5036_50361101_19_dialog_content = "알껍데기? 그러고 보니까 저 무늬, 우로보로스의 알처럼 생겼잖아?",
  ui_story_5036_50361101_20_dialog_content = "어떻게 지금까지 계속 저기 있었지? 게다가 왜 저렇게 커?\n너무 커서 벽에 금까지 갔잖아?!",
  ui_story_5036_50361101_21_dialog_content = "여자애가 들고 뛰어다닐 수 있을 정도였으면,\n아무리 커 봤자 수박 정도 크기여야 하는 거 아냐?",
  ui_story_5036_50361101_22_dialog_content = "우로보로스의 알이요? 그거 비크 씨가 장난으로 꺼낸 이야기 아니었어요?\n그게 왜 실제로 존재하는 건데요?!",
  ui_story_5036_50361101_23_dialog_content = "비크 씨, 이게 대체 어떻게 된 거야?",
  ui_story_5036_50361101_24_dialog_content = "나야 모르지~",
  ui_story_5036_50361101_25_dialog_content = "뭐어? 맨날 환상동물 마스터라면서 왜 몰라?",
  ui_story_5036_50361101_26_dialog_content = "바로 내가 환상동물 마스터이기 때문에 함부로 결론을 내리지 않는 거야.",
  ui_story_5036_50361101_27_dialog_content = "지금 확실하게 말해 줄 수 있는 건, 저 알은 진작 부화했어야 했지만\n어째선지 지금까지 그러지 않았다는 거야.",
  ui_story_5036_50361101_28_dialog_content = "게다가 저 안의 우로보로스는 아직 살아 있는 데다가, 계속 성장하고 있어.\n그래서 알이 이렇게 커다래진 거고.",
  ui_story_5036_50361101_29_dialog_content = "나머지 부분에 대해선 모르니까 모른다고 한 거야~",
  ui_story_5036_50361101_30_dialog_content = "우로보로스는 아주 희귀한 생물이라서 기록으로 남아 있는 게\n거의 없다고 해도 될 수준이거든.",
  ui_story_5036_50361101_31_dialog_content = "다시 말해서, 우로보로스는 수수께끼 그 자체라고 할 수 있지!",
  ui_story_5036_50361101_32_dialog_content = "난 비크 씨가 지금까지 아무 말이나 지어낸 건 줄 알았는데,\n그런 게 아니라 진짜였구나.",
  ui_story_5036_50361101_33_dialog_content = "그럼 저 알이 모두가 같은 꿈을 꾸게 만든 원인일까요?",
  ui_story_5036_50361101_34_dialog_content = "그럴 수도 있을걸~",
  ui_story_5036_50361101_35_dialog_content = "그럴 수도 있다고?",
  ui_story_5036_50361101_36_dialog_content = "딱히 그렇다고 확신할 증거가 없거든. 내가 한 말도 다 추측일 뿐이고.",
  ui_story_5036_50361101_37_dialog_content = "전에 난 우로보로스 같은 환상동물은 알로 변해 있을 동안\n대체 어떻게 지내는 걸까 쭉 궁금했었어.",
  ui_story_5036_50361101_38_dialog_content = "알로 변한 상태에선 외부로부터 공격을 받아도 반격하거나\n도망갈 방법이 아예 없잖아.",
  ui_story_5036_50361101_39_dialog_content = "근데 지금 난 새로운 가설을 세웠어.\n녀석은 알이 되었을 때 어떤 정신 계통의 능력을 갖고 있을지도 몰라.",
  ui_story_5036_50361101_40_dialog_content = "예를 들면 이상한 꿈을 꾸게 한다거나, 환각이랑 환청을 겪게 만든다거나 해서,\n상대가 위험을 느끼게 만들고, 자신에게 다가오지 않게 만드는 거지.",
  ui_story_5036_50361101_41_dialog_content = "그런 방법을 통해 자신을 위험에서 보호하는 게 아닐까 해.",
  ui_story_5036_50361101_42_dialog_content = "그러니까 비크 씨 말은, 우리가 이상한 꿈을 꾸고 불편함을 느끼는 거랑...",
  ui_story_5036_50361101_43_dialog_content = "아까 본 이상한 포스터까지 전부 우로보로스의 능력 때문이라는 거야?!",
  ui_story_5036_50361101_44_dialog_content = "응, 그게 지금 내가 도출할 수 있는 가장 합리적인 해석이야~",
  ui_story_5036_50361101_45_dialog_content = "그럼 이제부터 해야 할 일은 딱 하나네. 어떻게든 저 알을 가지고 가는 거야!",
  ui_story_5036_50361101_46_option_content = "저 알을?",
  ui_story_5036_50361101_47_option_content = "가지고 간다고?",
  ui_story_5036_50361101_48_dialog_content = "응!",
  ui_story_5036_50361101_49_dialog_content = "얼른 안 옮기면 우로보로스의 능력 때문에 모두가 힘들어질 거야.",
  ui_story_5036_50361101_50_dialog_content = "그렇게 되면 콘서트 개최에도 영향이 갈 거잖아.",
  ui_story_5036_50361101_51_dialog_content = "아~ 그 의견엔 반대야~",
  ui_story_5036_50361101_52_dialog_content = "당신 진짜!",
  ui_story_5036_50361101_53_dialog_content = "저렇게 커다란 데다가, 벽에 콕 박혀 있는데.",
  ui_story_5036_50361101_54_dialog_content = "어떻게 꺼내고, 뭐로 옮길 건데?",
  ui_story_5036_50361101_55_dialog_content = "백화 용병단한테 부탁해서 벽에서 꺼낸 다음에, 비공정으로 옮길 거야.",
  ui_story_5036_50361101_56_dialog_content = "저렇게 단단한 벽에서 알을 파내려면, 콘서트 끝날 때쯤에나 작업이 끝날걸?",
  ui_story_5036_50361101_57_dialog_content = "그건...",
  ui_story_5036_50361101_58_dialog_content = "게다가 저건 희귀종인 우로보로스의 알이야.\n전 세계에 이거 하나밖에 없을 수도 있어.",
  ui_story_5036_50361101_59_dialog_content = "만약에 파내다가 실수해서 깨지기라도 하면, 우로보로스의 생명이 위험해져.",
  ui_story_5036_50361101_60_dialog_content = "그렇게 되면 아가씨가 그 모든 책임을 질 수 있겠어?",
  ui_story_5036_50361101_61_dialog_content = "......",
  ui_story_5036_50361101_62_dialog_content = "그러니까 내 말대로 이 콘서트는 그냥 취소해 버려.",
  ui_story_5036_50361101_63_dialog_content = "어쨌든 콘서트는 어디서든 열 수 있잖아. 기회가 이번 한 번뿐인 것도 아니고.\n그러니까 차라리 우로보로스가 부화하길 기다렸다가...",
  ui_story_5036_50361101_64_dialog_content = "그럴 순 없어!",
  ui_story_5036_50361101_65_dialog_content = "이 콘서트는 나한테 <color=#FFB400>특별한 의미</color>가 있어. 절대로 이렇게 포기 못 해.",
  ui_story_5036_50361101_66_dialog_content = "다른 건 몰라도, 이것만큼은 절대 양보할 수 없어!",
  ui_story_5036_50361101_67_dialog_content = "확실히 그렇겠네요. 이 콘서트는 팬들을 향한 골디 씨의 약속이니까요...",
  ui_story_5036_50361101_68_dialog_content = "(특별한 의미? 골디가 많이 곤란해 보이는데, 대체 왜 그러는 거지?)",
  ui_story_5036_50361101_69_dialog_content = "에이, 그럼 곤란한데.",
  ui_story_5036_50361101_70_dialog_content = "......",
  ui_story_5036_50361101_71_dialog_content = "(아무도 의견을 굽히질 않잖아. 내가 뭐라도 해야 할 것 같아.)",
  ui_story_5036_50361101_72_dialog_content = "다른 방법은 없는 거야?",
  ui_story_5036_50361101_73_dialog_content = "알을 여기 그대로 둔 채로 정신 쪽의 영향을 없앨 방법 같은 거 말이야.",
  ui_story_5036_50361101_74_dialog_content = "맞아요, 비크 씨. 환상동물 마스터라면서요? 어떻게 방법이 없을까요?",
  ui_story_5036_50361101_75_dialog_content = "에휴, 결국 이 노인네를 이렇게 힘들게 만든다니까.\n요즘 젊은것들은 정말 갈수록 왜 이러는지~",
  ui_story_5036_50361101_76_dialog_content = "뭐, 상관없어. 내 제자들도 자주 나한테 도와달라고 하니까.",
  ui_story_5036_50361101_77_dialog_content = "내가 그 말 그대로 시라랑 피아한테 말해 줘도 괜찮지?",
  ui_story_5036_50361101_78_dialog_content = "아이고, 내가 방금 뭐라고 했더라? 갑자기 기억이 안 나네!",
  ui_story_5036_50361101_79_dialog_content = "장난 그만 치고 제대로 말해 봐.",
  ui_story_5036_50361101_80_dialog_content = "크, 크흠, 방법이 아예 없는 건 아니야. 좀 번거롭고, 소용이 없을 수도 있지만.",
  ui_story_5036_50361101_81_dialog_content = "일단 말해 봐. 콘서트를 문제없이 진행할 수만 있다면,\n얼마나 번거롭든 상관없으니까!",
  ui_story_5036_50361101_82_dialog_content = "PlayerName, 네가 봤던 과거의 기억들 속에서,\n샤미나드가 우로보로스의 알 때문에 불편해했었어?",
  ui_story_5036_50361101_83_dialog_content = "음, 왠지 안 그랬던 것 같아.",
  ui_story_5036_50361101_84_dialog_content = "그게 바로 키 포인트야.",
  ui_story_5036_50361101_85_dialog_content = "정신 쪽에 영향을 주는 우로보로스의 능력은 일종의 자기방어 수단이야.\n그러니까 자기가 위험에 처했다고 생각했을 때만 발동할 가능성이 높아.",
  ui_story_5036_50361101_86_dialog_content = "만약 우리가 콜로서스 안의 위협을 제거해서 녀석이 안전하다고 느끼게 만들면,\n지금 일어나고 있는 이런 현상들도 사라질지도 몰라.",
  ui_story_5036_50361101_87_dialog_content = "한 마디로 콜로서스 안에 있는 암귀들을 전부 없애야 한다는 거네?",
  ui_story_5036_50361101_88_dialog_content = "그렇다고 할 수 있겠지~",
  ui_story_5036_50361101_89_dialog_content = "별거 아니네! 문제없어!",
  ui_story_5036_50361101_90_dialog_content = "자, 잠깐만요.",
  ui_story_5036_50361101_91_dialog_content = "이 커다란 콜로서스에 있는 모든 암귀를 우리 네 사람이\n전부 처치하는 건 아무리 봐도 무리 아닌가요?!",
  ui_story_5036_50361101_92_dialog_content = "그건 그래...",
  ui_story_5036_50361101_93_dialog_content = "게다가 별 효과가 없을 수도 있다며?",
  ui_story_5036_50361101_94_dialog_content = "응, 그러니까 일단 해 보는 수밖에 없어.",
  ui_story_5036_50361101_95_dialog_content = "아니면 이 근처에 있는 암귀들만 처치한 다음에, 벽에 생긴 이 틈을 메워서\n암귀들이 우로보로스의 알 근처에 접근하지 못하게 만들면?",
  ui_story_5036_50361101_96_dialog_content = "음, 그렇게 해도 비슷한 효과를 얻을 수 있지 않을까?",
  ui_story_5036_50361101_97_dialog_content = "한번 해 봐도 좋을 것 같아.",
  ui_story_5036_50361101_98_dialog_content = "그럼 시작하자!",
  ui_story_5036_50361101_99_dialog_content = "콘서트를 위해!",
  ui_story_5036_50361102_1_dialog_content = "PlayerName 씨, 조금만 도와줘.",
  ui_story_5036_50361102_2_dialog_content = "저 틈을 메우려고 하거든. 그러니까 이 돌 좀 저쪽으로 밀어줘.",
  ui_story_5036_50361102_3_dialog_content = "응!",
  ui_story_5036_50361102_4_dialog_content = "에잇──!",
  ui_story_5036_50361102_5_dialog_content = "됐어. 여기가 마지막이겠지?",
  ui_story_5036_50361102_6_dialog_content = "응, 예쁘게 잘 완성됐네.",
  ui_story_5036_50361102_7_dialog_content = "역시 내가 지도한 덕분이라니까~",
  ui_story_5036_50361102_8_dialog_content = "비크 씨는 옆에서 응원밖에 안 했잖아...",
  ui_story_5036_50361102_9_dialog_content = "나처럼 나이 들어서 팔다리가 후들거리는 사람이 어떻게 이런 중노동을 하겠어.",
  ui_story_5036_50361102_10_dialog_content = "으스스한 느낌이 좀 줄어든 것 같아요...",
  ui_story_5036_50361102_11_dialog_content = "응, 그래도 조금은 느껴지지만, 아까랑 비교하면 훨씬 나아졌어.",
  ui_story_5036_50361102_12_dialog_content = "내 추측이 맞았던 모양이네.",
  ui_story_5036_50361102_13_dialog_content = "그럼 이제부턴 어떡하지? 계속 암귀를 처치해야 할까?",
  ui_story_5036_50361102_14_dialog_content = "이 정도면 괜찮을 거야. 이제 남은 건...",
  ui_story_5036_50361102_15_dialog_content = "돌아가서 한숨 자면서 또 이상한 꿈을 꾸는지 확인해 보는 거지!",
  ui_story_5036_50361102_16_dialog_content = "결론은 돌아가서 자자는 거잖아!",
  ui_story_5036_50361102_17_dialog_content = "어쩔 수 없어. 우로보로스에 관한 기록은 거의 없으니까,\n직접 겪으면서 확인해 보는 수밖에!",
  ui_story_5036_50361102_18_dialog_content = "맞는 말이야.",
  ui_story_5036_50361102_19_dialog_content = "시간이 늦었어. 그리고 다들 피곤해 보여.",
  ui_story_5036_50361102_20_dialog_content = "이렇게 한 효과가 있는지 확인도 해 볼 겸, 우선 돌아가서 좀 쉬자.",
  ui_story_5036_50361102_21_dialog_content = "효과가 없다면... 다른 방법을 생각해 봐야 할 테니까.",
  ui_story_5036_50361102_22_dialog_content = "골디 씨가 이렇게나 노력했으니까, 분명히 아무런 문제도 없을 거예요!",
  ui_story_5036_50361102_23_dialog_content = "응! 고마워!",
  ui_story_5036_50361102_24_dialog_content = "그럼 일단 가서 쉬고 내일 아침에 다시 만나자!",
  ui_story_5036_50361102_25_dialog_content = "<color=#e8d9bb>다음 날 아침, 콘서트 개최 1일 전</color>",
  ui_story_5036_50361102_26_dialog_content = "후암~ 오랜만에 푹 잤네.",
  ui_story_5036_50361102_27_dialog_content = "어젠 너무 피곤에서 방에 돌아오자마자 곯아떨어져 버리는 바람에 꿈도 안 꿨어.",
  ui_story_5036_50361102_28_dialog_content = "누군가 했더니 패배자잖아?",
  ui_story_5036_50361102_29_dialog_content = "방금 일어난 거면, 오늘의 빨리 일어나기 게임에서 또 나한테 진 거야!",
  ui_story_5036_50361102_30_dialog_content = "그로누구나. 어젯밤엔 잘 잤어?",
  ui_story_5036_50361102_31_dialog_content = "별 3개짜리 고품질 수면이었어!",
  ui_story_5036_50361102_32_dialog_content = "그리고 며칠 전처럼 아이테르 소녀가 꿈에 나오는 일도 없었고 말이야.",
  ui_story_5036_50361102_33_dialog_content = "그래? 그거 잘됐네!",
  ui_story_5036_50361102_34_dialog_content = "난 오히려 좀 아쉬운데. 이상한 꿈을 꾸는 것도 일종의 희귀 업적이잖아!",
  ui_story_5036_50361102_35_dialog_content = "하, 하하... 아무튼 푹 잤다니 다행이네.",
  ui_story_5036_50361102_36_dialog_content = "그럼 난 리허설하는 거 보러 가야 하니까, 나중에 봐.",
  ui_story_5036_50361102_37_dialog_content = "응, 이따 봐!",
  ui_story_5036_50361102_38_dialog_content = "다행이야! 어젯밤에 했던 노력이 쓸모가 없진 않았어!",
  ui_story_5036_50361102_39_dialog_content = "골디가 안심할 수 있게 얼른 가서 이 사실을 알려줘야지.",
  ui_story_5036_50361102_40_dialog_content = "이 시간이면... 음, 연습실에 있겠지?",
  ui_story_5036_50361102_41_dialog_content = "PlayerName 씨! 왔구나!",
  ui_story_5036_50361102_42_dialog_content = "어젠 늦게까지 바빴을 텐데, 좀 더 쉬지 그랬어?",
  ui_story_5036_50361102_43_dialog_content = "잠은 벌써 충분히 잤으니까 걱정 안 해도 돼.",
  ui_story_5036_50361102_44_dialog_content = "참, 어제 우리가 헛수고를 한 게 아니었어.\n아까 그로누한테 물어봤는데, 어젯밤엔 이상한 꿈을 안 꿨다고 하더라고.",
  ui_story_5036_50361102_45_dialog_content = "응! 나도 다른 참가자들한테 물어봤는데, 다들 푹 잤다고 했어.",
  ui_story_5036_50361102_46_dialog_content = "정말 다행이야!",
  ui_story_5036_50361102_47_dialog_content = "정말... 잘됐어.",
  ui_story_5036_50361102_48_option_content = "골디, 너 괜찮아?",
  ui_story_5036_50361102_49_dialog_content = "되게 피곤해 보이는데?",
  ui_story_5036_50361102_50_dialog_content = "응? 아닌데?",
  ui_story_5036_50361102_51_dialog_content = "아이돌은 언제나 활기차고 절대 피곤해지지 않는걸!",
  ui_story_5036_50361102_52_option_content = "왜 그렇게 지쳤어?",
  ui_story_5036_50361102_53_dialog_content = "응? 아닌데?",
  ui_story_5036_50361102_54_dialog_content = "잘못 본 거야~ 난 지금 기운이 넘치는걸!",
  ui_story_5036_50361102_55_dialog_content = "(아까 그 표정은 절대로 내가 잘못 본 게 아니야. 설마...)",
  ui_story_5036_50361102_56_dialog_content = "골디 너 계속 억지로 텐션을 높이고 있는 거 아니야?",
  ui_story_5036_50361102_57_dialog_content = "......!",
  ui_story_5036_50361102_58_dialog_content = "조금만 생각해 봐도 바로 알 수 있어. 너 어제도 엄청 늦게 잤잖아.",
  ui_story_5036_50361102_59_dialog_content = "더군다나 오늘도 일찍 일어나서 트레이닝 준비랑 오디션 일도 준비했잖아.\n아무리 봐도 푹 쉰 사람 모습이 아니야.",
  ui_story_5036_50361102_60_dialog_content = "괜찮아~ 난 아이돌인걸. 아이돌은...",
  ui_story_5036_50361102_61_option_content = "아이돌도 사람이잖아?",
  ui_story_5036_50361102_62_dialog_content = "사람은 피곤해져, 그래서 쉬어 줘야 하는 거고.",
  ui_story_5036_50361102_63_dialog_content = "골디 네가 무슨 이유로 이 콘서트를 이렇게까지 중요하게 여기는 건진 모르겠지만...",
  ui_story_5036_50361102_64_dialog_content = "일을 좀 내려놓고 제대로 휴식을 취해 줘야 해.",
  ui_story_5036_50361102_65_dialog_content = "휴...",
  ui_story_5036_50361102_66_dialog_content = "PlayerName 씨한텐 지금까지 도움을 많이 받았으니까,\n진실을 얘기해 줘도 괜찮겠지.",
  ui_story_5036_50361102_67_dialog_content = "뭐? 방금 「진실」이라고 한 거야?",
  ui_story_5036_50361102_X67_dialog_content = "이 콘서트는 내가 팬들한테 한 약속이기도 하지만, 샤엘 사장님한테 한 약속이기도 해.",
  ui_story_5036_50361102_68_dialog_content = "사실, 난 샤엘 씨랑 계약을 하나 했어.",
  ui_story_5036_50361102_69_dialog_content = "계약? 샤엘 씨랑?!",
  ui_story_5036_50361102_70_dialog_content = "샤엘 씨는 아이돌이란 직업의 잠재성에 주목했고,\n내 능력을 높이 사서 나한테 투자를 해 줬어.",
  ui_story_5036_50361102_71_dialog_content = "샤엘 씨한테 받고 있는 자금 지원이 가장 큰 만큼,\n난 반드시 샤엘 씨의 요구 사항을 들어 줘야 해.",
  ui_story_5036_50361102_72_dialog_content = "그래서 난 정해진 기간 안에 움브라톤에서 콘서트를 진행해야 돼.\n게다가 그 콘서트를 통해...",
  ui_story_5036_50361102_73_dialog_content = "「아이돌」이란 개념과 내 이름을 백야성과 움브라톤의 모든 사람들에게 알려야 해.",
  ui_story_5036_50361102_74_dialog_content = "아무래도 샤엘 씨한테 당한 것 같은데? 그게 가능하긴 해?!",
  ui_story_5036_50361102_75_dialog_content = "내가 인기가 없는 편은 아니니까, 기획만 잘했으면 조금 힘들긴 해도\n문제없이 목표를 전부 달성할 수 있었을 거야.",
  ui_story_5036_50361102_76_dialog_content = "하지만 중간에 일어난 뜻밖의 문제 때문에 콘서트장을 빌릴 수 없게 돼 버렸어.",
  ui_story_5036_50361102_77_dialog_content = "그렇게 막다른 골목에서 어쩔 줄 모르고 있을 때,\n갑자기 표류하는 콜로서스가 나타난 거야! 정말 행운이었지!",
  ui_story_5036_50361102_78_dialog_content = "샤엘 씨랑 맺은 계약의 마지막 기한이자, 내 마지막 기회는 바로 내일이야.\n그러니까 이번 콘서트는 반드시 제대로 해내야 해.",
  ui_story_5036_50361102_79_dialog_content = "실패한다면 샤엘 씨의 투자금을 배상해 줘야 해서 엄청난 채무를 떠안게 될 거야.",
  ui_story_5036_50361102_80_dialog_content = "그렇게 되면 내 아이돌 인생도 거기서 끝이겠지.",
  ui_story_5036_50361102_81_dialog_content = "골디 네가 그렇게까지 스트레스를 받고 있는 줄은 몰랐어.\n너무 애쓰는 거 아냐?!",
  ui_story_5036_50361102_82_dialog_content = "괜찮아, 그게 내 의무인걸.",
  ui_story_5036_50361102_83_dialog_content = "아이돌로서 내가 존재하는 의미는, 날 응원해 주는 팬들한테\n노래와 기쁨, 그리고 희망을 선물하는 거니까.",
  ui_story_5036_50361102_84_dialog_content = "팬들의 사랑과 응원이 없다면, 아이돌은 존재할 수 없어.",
  ui_story_5036_50361102_85_dialog_content = "난 수많은 팬한테 사랑받고 있어.\n그러니까 온 힘을 다해 모두의 마음에 보답해 줘야만 해.",
  ui_story_5036_50361102_86_dialog_content = "이 콘서트를 통해 더 많은 사람이 내 노랠 들을 수 있다면,\n난 반드시 최선을 다할 거야!",
  ui_story_5036_50361102_87_dialog_content = "그래...! 힘내!",
  ui_story_5036_50361102_88_dialog_content = "골디 넌 혼자가 아니야! 나도 같이 노력할게!",
  ui_story_5036_50361102_89_dialog_content = "내가 도울 수 있는 거라면, 나랑 같이 하자!",
  ui_story_5036_50361102_90_dialog_content = "고마워, PlayerName 씨!",
  ui_story_5036_50361102_91_dialog_content = "우리 같이 콘서트를 성공적으로 개최해서, 소중한 이 칸타토르호를 지켜 내는 거야!",
  ui_story_5036_50361201_1_dialog_content = "<color=#e8d9bb>다음 날, 콘서트 시작 15분 전</color>",
  ui_story_5036_50361201_2_dialog_content = "콘서트가 곧 시작될 거야. 다들 준비됐어?",
  ui_story_5036_50361201_3_dialog_content = "네!",
  ui_story_5036_50361201_4_dialog_content = "드디어 시작입니까? 무척 기대되는군요.",
  ui_story_5036_50361201_5_dialog_content = "(맙소사, 내가 언제까지 이런 서민들과 어울려서 시간 낭비를 해야 하는 건지.)",
  ui_story_5036_50361201_6_dialog_content = "표정, 망가졌어.",
  ui_story_5036_50361201_7_dialog_content = "속마음이, 얼굴에 다 티나.",
  ui_story_5036_50361201_8_dialog_content = "조용히 좀 해!",
  ui_story_5036_50361201_9_dialog_content = "최고야! 드디어 게임이 시작될 시간이야!",
  ui_story_5036_50361201_10_dialog_content = "바니~ 나랑 같이 응원 게임할 준비됐지?",
  ui_story_5036_50361201_11_dialog_content = "준비... 됐어요...",
  ui_story_5036_50361201_12_dialog_content = "시작 안 하고 뭐 하는 거야?\n록으로 모든 관객을 정복하고 싶어서 몸이 근질거린다고!",
  ui_story_5036_50361201_13_dialog_content = "이 돌머리야! 이건 아이돌 콘서트잖아. 포인트는 아이돌이야!",
  ui_story_5036_50361201_14_dialog_content = "당연히 너보단 레디젤의 연인인 이 바바라 님이 분위기에 더 잘 어울리지 않겠어?",
  ui_story_5036_50361201_15_dialog_content = "너 같은 꼬맹이가 하는 소꿉장난 같은 음악이 사람들의 마음을 움직일 리가 있겠냐!",
  ui_story_5036_50361201_16_dialog_content = "야!",
  ui_story_5036_50361201_17_dialog_content = "두 사람은 참 여전하구나. 괜히 문제를 일으키지 않았으면 좋겠는데.",
  ui_story_5036_50361201_18_dialog_content = "그러게. 둘이 같이 오프닝 공연을 해야 하는데!",
  ui_story_5036_50361201_19_dialog_content = "그랬구나... 어? 뭐? 저 둘이? 같이?!",
  ui_story_5036_50361201_20_dialog_content = "그래도 되는 거야?!",
  ui_story_5036_50361201_21_dialog_content = "솔직히 걱정은 좀 되지만, 둘 다 자기가 상대보다 먼저 나가야 한다고 우기길래.",
  ui_story_5036_50361201_22_dialog_content = "어쩔 수 없이 같이 한 무대에서 공연하게 했어.",
  ui_story_5036_50361201_23_dialog_content = "그래도 너무 걱정하진 마. 두 사람 다 그 누구한테도 뒤지지 않는\n멋진 오프닝 곡을 불러 준다고 진지하게 맹세했거든.",
  ui_story_5036_50361201_24_dialog_content = "진지하게 맹세한 거 확실해? 서로 잡아먹을 듯 그랬던 거 아니고?",
  ui_story_5036_50361201_25_dialog_content = "두 사람을 믿어 보자! 서로 사이는 별로일 수도 있지만,\n공연을 하겠다는 마음만큼은 진심이었으니까.",
  ui_story_5036_50361201_26_dialog_content = "좋아, 제발 저 둘이 무대에서 서로 잘 좀 했으면 좋겠어.",
  ui_story_5036_50361201_27_dialog_content = "이번 콘서트엔 칸타토르호의 미래가 달려 있으니까!",
  ui_story_5036_50361201_28_dialog_content = "PlayerName 씨는 칸타토르호를 무척 중요하게 생각하는구나.",
  ui_story_5036_50361201_29_dialog_content = "그럴 수밖에. 이 칸타토르호는 스카이워커와 트래블러호를 제외하면,\n지금 유일하게 정상적으로 가동하는 콜로서스니까.",
  ui_story_5036_50361201_30_dialog_content = "모든 콜로서스는 아이테르와 뗄 수 없는 깊은 관계가 있어.\n콜로서스의 존재가 곧 과거에 아이테르가 존재했었다는 증거거든.",
  ui_story_5036_50361201_31_dialog_content = "그래서 난 모든 콜로서스를 원래 모습 그대로 잘 보존하고 싶어.\n그러면 먼저 떠나간 동족들도 기뻐할 테니까...",
  ui_story_5036_50361201_32_dialog_content = "게다가 칸타토르호를 고칠 수 있다면, 스카이워커한테도 새 동료가 생기는 거니까\n더는 그렇게 외롭지 않을 테고.",
  ui_story_5036_50361201_33_dialog_content = "걱정 마, PlayerName 씨. 내가 꼭 도와줄게!",
  ui_story_5036_50361201_34_dialog_content = "우리도 널 도와줄게!",
  ui_story_5036_50361201_35_dialog_content = "만약 정말로 무슨 일이 일어난다면, 내가 가서 상황을 정리할게.",
  ui_story_5036_50361201_36_dialog_content = "역시 카렌이 제일 믿음직스럽다니까!",
  ui_story_5036_50361201_37_dialog_content = "둘 다 준비를 충분히 한 모양이네.",
  ui_story_5036_50361201_38_dialog_content = "당연하지. 이 콘서트를 위해 우리 둘이 비밀 무기도 준비했어!",
  ui_story_5036_50361201_39_dialog_content = "어떤 노랠 부를 거야?",
  ui_story_5036_50361201_40_dialog_content = "처음엔 학교 다닐 때 학생 모임에서 같이 불렀던 노랠 부를 생각이었어.\n하지만 리허설 때 뭔가 부족하단 느낌이 들었거든.",
  ui_story_5036_50361201_41_dialog_content = "같이 여행할 때의 감동이라든가, 함께 어려움을 극복했을 때 느껴지는\n안도 같은 여러 가지 비슷한 감정들 말이야.",
  ui_story_5036_50361201_42_dialog_content = "맞아, 맞아. 뭔가 부족한 것 같아서 카렌한테 물어봤더니,\n카렌도 나랑 똑같은 느낌을 받았다고 하더라고.",
  ui_story_5036_50361201_43_dialog_content = "그래서 결국엔 둘이서 노래를 하나 새로 만들기로 했어!",
  ui_story_5036_50361201_44_dialog_content = "그거 벌써부터 기대되네!",
  ui_story_5036_50361201_45_dialog_content = "레지나 씨, 바바라 씨, 카렌 씨, 바이스 씨, 비크 씨...",
  ui_story_5036_50361201_46_dialog_content = "어라? 비크 씨가 없는데요?",
  ui_story_5036_50361201_47_dialog_content = "비크 씨가 없다고? 아까 올 때 보니까 자기 방에도 없던데.",
  ui_story_5036_50361201_48_dialog_content = "진작 도착했던 거 아냐?",
  ui_story_5036_50361201_49_dialog_content = "PlayerName 씨도 비크 씨 못 봤어?",
  ui_story_5036_50361201_50_dialog_content = "어휴, 정말! 조금 있으면 공연이 시작되는데 대체 어디 간 거야?",
  ui_story_5036_50361201_51_dialog_content = "설마 또 우로보로스의 알을 보러 간 건 아니겠지?",
  ui_story_5036_50361201_52_dialog_content = "비크 씨는 사람보다 환상동물에 신경을 더 많이 쓰는 데다가,\n아무 데서나 쿨쿨 자 버리는 경우가 꽤 있거든.",
  ui_story_5036_50361201_53_dialog_content = "아마 거기 갔다가 잠들어 버렸을지도 몰라.",
  ui_story_5036_50361201_54_dialog_content = "내가 가서 데려올게.",
  ui_story_5036_50361201_55_dialog_content = "정말 괜찮겠어?",
  ui_story_5036_50361201_56_dialog_content = "물론이지, 나한테 맡겨.",
  ui_story_5036_50361201_57_dialog_content = "무슨 일 있었는지 나도 들었어. 근데 거긴 봉쇄 구역 안에 있는 곳 아냐?",
  ui_story_5036_50361201_58_dialog_content = "위험할 테니까 나랑 같이 가자!",
  ui_story_5036_50361201_59_dialog_content = "그래, 나도 도와줄게.",
  ui_story_5036_50361201_60_dialog_content = "무대 쪽이랑 거리가 상당해서 한 번만 왔다 갔다 해도 시간이 꽤 걸릴 거야.",
  ui_story_5036_50361201_61_dialog_content = "바이스랑 카렌은 이따가 무대에 올라가서 공연도 해야 하잖아?\n그러니까 여기서 공연 준비를 하는 게 나을 것 같아.",
  ui_story_5036_50361201_62_dialog_content = "너 혼자서 암귀들을 상대할 수 있겠어?",
  ui_story_5036_50361201_63_dialog_content = "그 부분은 걱정 안 해도 돼. 엊그제 내가 골디랑 비크 씨하고 같이\n그쪽 길에 있는 암귀들을 다 처치해 뒀거든.",
  ui_story_5036_50361201_64_dialog_content = "그러니까 혼자 가도 별일 없을 거야.",
  ui_story_5036_50361201_65_dialog_content = "알겠어. 그럼 조심해서 빨리 갔다 빨리 와.",
  ui_story_5036_50361201_66_dialog_content = "걱정하지 마~",
  ui_story_5036_50361201_67_dialog_content = "그럼 우리도 공연을 시작할 준비를 해 보자!",
  ui_story_5036_50361201_68_dialog_content = "비크 씨가 시간에 맞춰 도착하지 못하면, 두 사람이 먼저 무대에 서 줬으면 좋겠어.",
  ui_story_5036_50361201_69_dialog_content = "네, 알겠어요!",
  ui_story_5036_50361201_70_dialog_content = "나도 문제없어.",
  ui_story_5036_50361201_71_dialog_content = "아직 시작하려면 멀었나?",
  ui_story_5036_50361201_72_dialog_content = "조금 있으면 시작할 거야. 저기! 무대 위를 봐!",
  ui_story_5036_50361201_73_dialog_content = "드디어 시간이 됐네요. 여러분, 오래 기다리셨어요!",
  ui_story_5036_50361201_74_dialog_content = "별들이 빛나는 순간, 창공의 콘서트가 마침내 시작됩니다!",
  ui_story_5036_50361201_75_dialog_content = "와아아아아!",
  ui_story_5036_50361201_76_dialog_content = "<color=#e8d9bb>같은 시간</color>",
  ui_story_5036_50361201_77_dialog_content = "어? 저게 뭐지?",
  ui_story_5036_50361201_78_dialog_content = "구름 사이로 뭔가 반짝이는 게... 콜로서스잖아?!",
  ui_story_5036_50361201_79_dialog_content = "소리도 들리는 것 같은데? 설마 창공의 콘서트라고 하던 그건가?",
  ui_story_5036_50361201_80_dialog_content = "아가씨, 모르고 계셨을 수도 있습니다만,\n저건 최근 영원한 밤의 땅에서 날아 온 표류하는 콜로서스입니다.",
  ui_story_5036_50361201_81_dialog_content = "골디라는 아이돌이 저 콜로서스 위에서 콘서트를 연다고 하더군요.",
  ui_story_5036_50361201_82_dialog_content = "움브라톤에서 발행되는 여러 신문에선 이미 다뤄진 적 있는 내용입니다.",
  ui_story_5036_50361201_83_dialog_content = "그래? 그거 재미있네.",
  ui_story_5036_50361201_84_dialog_content = "우리도 잘 보이는 자릴 하나 찾아서, 대체 뭘 보여줄지 한번 구경해 보자.",
  ui_story_5036_50361201_85_dialog_content = "예.",
  ui_story_5036_50361201_86_dialog_content = "누나! 하늘 좀 봐! 콜로서스야!",
  ui_story_5036_50361201_87_dialog_content = "진짜 콜로서스네!",
  ui_story_5036_50361201_88_dialog_content = "콜로서스에 달린 저건 뭐지? 스크린인가? 스크린에 뭔가 나오고 있는데...?",
  ui_story_5036_50361201_89_dialog_content = "어! 저거 그날 우릴 지켜줬던 그 언니잖아?!",
  ui_story_5036_50361201_90_dialog_content = "정말이네! 그 누나가 콘서트장을 찾았나 봐! 근데 그게 콜로서스였구나!",
  ui_story_5036_50361201_91_dialog_content = "티켓을 못 샀어도 노랠 들을 수 있어! 저 누나 진짜 대단하다!",
  ui_story_5036_50361201_92_dialog_content = "콜로서스가 저쪽으로 날아갔어. 우리도 빨리 쫓아가자!",
  ui_story_5036_50361201_93_dialog_content = "강을 따라 가면 될 거야. 가서 저 언니를 응원해 줘야지!",
  ui_story_5036_50361201_94_dialog_content = "여러분의 열정을 확실히 느낄 수 있었어요!",
  ui_story_5036_50361201_95_dialog_content = "그럼 이제 레디젤 사막에서 먼 걸음 해 준 두 아이돌이\n여러분께 불꽃처럼 열정적인 오프닝 무대를 선보입니다!",
  ui_story_5036_50361201_96_dialog_content = "모두 환영해 주세요! 레지나와 바바라입니다!",
  ui_story_5036_50361201_97_dialog_content = "♪잿더미가 될 때까지! 타올라♪",
  ui_story_5036_50361201_98_dialog_content = "♪너에게 바치는~ 나의 사랑~♪",
  ui_story_5036_50361201_99_dialog_content = "<size=40>♪끓어오르고 터져 버려, 망가져 버려♪</size>",
  ui_story_5036_50361201_100_dialog_content = "<size=45>♪설레는 두근거림을 가지고~ 너와 만나~♪</size>",
  ui_story_5036_50361201_101_dialog_content = "(이 자식... 목소리가 왜 이렇게 커?)",
  ui_story_5036_50361201_102_dialog_content = "(나도 질 순 없지!)",
  ui_story_5036_50361201_103_dialog_content = "<size=40>♪이게 바로 내♪</size>",
  ui_story_5036_50361201_104_dialog_content = "<size=45>♪속마음~ 그건 바로~♪</size>",
  ui_story_5036_50361201_105_dialog_content = "<size=50>♪로큰롤!♪</size>",
  ui_story_5036_50361201_106_dialog_content = "<size=50>♪아이돌!♪</size>",
  ui_story_5036_50361201_107_dialog_content = "대체 위에서 뭐라는 거야? 가사도 꼬이고, 목소린 또 왜 저렇게 커?",
  ui_story_5036_50361201_108_dialog_content = "시끄럽기만 하고 뭐라는 건지 하나도 모르겠네. 이러다 고막 터지겠어!",
  ui_story_5036_50361201_109_dialog_content = "(큰일이야! 어떻게 무대 위에서도 싸울 수 있지?\n제대로 합동 공연을 하겠다고 했었잖아?!)",
  ui_story_5036_50361201_110_dialog_content = "(안 되겠어. 계속 저대로 뒀다간 공연 사고가 날 거야.\n빨리 두 사람이 제대로 하게 만들어야 해!)",
  ui_story_5036_50361201_111_dialog_content = "♪뜨겁게 일렁이는 사막처럼, 내 마음도 두근대고 있어~♪",
  ui_story_5036_50361201_112_dialog_content = "(잠깐만, 왜 사회자가 갑자기 무대에 올라와서 노랠 부르는 거지?!)",
  ui_story_5036_50361201_113_dialog_content = "(리허설 땐 이런 연출은 없었잖아!)",
  ui_story_5036_50361201_114_dialog_content = "(내가 왜 이러는 건지 제발 눈치채 줘! 제발! 부탁이야!)",
  ui_story_5036_50361201_115_dialog_content = "♪네게 전하고 싶은 이 마음, 그 이름은 바로~♪",
  ui_story_5036_50361201_116_dialog_content = "♪바로~♪",
  ui_story_5036_50361201_117_dialog_content = "♪바로~♪",
  ui_story_5036_50361201_118_dialog_content = "<size=45>♪사랑~♪</size>",
  ui_story_5036_50361201_119_dialog_content = "♪영원히 사라지지 않고!♪",
  ui_story_5036_50361201_120_dialog_content = "♪절대 멈추지 않아!♪",
  ui_story_5036_50361201_121_dialog_content = "<size=50>♪레디젤처럼, 뜨겁게 불타올라~♪</size>",
  ui_story_5036_50361201_122_dialog_content = "(됐다! 두 사람이 다시 호흡을 맞추기 시작했어!)",
  ui_story_5036_50361201_123_dialog_content = "(그럼 나도 슬슬 내려가야지.)",
  ui_story_5036_50361201_124_dialog_content = "♪로큰롤, 마음의 울림, 돌이킬 수 없어♪",
  ui_story_5036_50361201_125_dialog_content = "♪이 두 손에, 네 진심을 모으면♪",
  ui_story_5036_50361201_126_dialog_content = "<size=50>♪우리의 노래가 울려 퍼지네~♪</size>",
  ui_story_5036_50361201_127_dialog_content = "어? 갈수록 나쁘지 않은데!",
  ui_story_5036_50361201_128_dialog_content = "골디 씨의 모습이 정말 멋져! 많이 찍어 둬야지!",
  ui_story_5036_50361201_129_dialog_content = "전혀 다른 두 음색이 한 곡에 어우러지고, 이렇게나 많은 관객에게 주목받다니...",
  ui_story_5036_50361201_130_dialog_content = "정말 재미있네! 지금껏 백야성에는 이런 콘서트가 열린 적 없어!",
  ui_story_5036_50361201_131_dialog_content = "아가씨, 콜로서스가 떠나려 하고 있습니다.",
  ui_story_5036_50361201_132_dialog_content = "내 비공정을 가져와.",
  ui_story_5036_50361201_133_dialog_content = "?!",
  ui_story_5036_50361201_134_dialog_content = "이렇게 재미있는 콘서트인데, 일등석에서 봐줘야지!",
  ui_story_5036_50361201_135_dialog_content = "콜로서스에서 열리는 콘서트라니! 정말 파격적이고 참신한 발상이야!",
  ui_story_5036_50361201_136_dialog_content = "사람이 점점 더 많아지고 있어.",
  ui_story_5036_50361201_137_dialog_content = "이 콘서트를 보겠다고 골드리버를 따라 운행할 선박을 대여한 상인들도 꽤 있고.",
  ui_story_5036_50361201_138_dialog_content = "후훗, 저 아가씨한테 투자하기로 한 건 역시나 옳은 선택이었어.",
  ui_story_5036_50361201_139_dialog_content = "비크 씨랑 PlayerName 씨는 아직 안 돌아왔지?",
  ui_story_5036_50361201_140_dialog_content = "아직 안 돌아왔어.",
  ui_story_5036_50361201_141_dialog_content = "그 둘, 정말 사람 걱정하게 만드네...",
  ui_story_5036_50361201_142_dialog_content = "어쩔 수 없지. 그럼 두 사람이 먼저 무대에서 공연해 줘.",
  ui_story_5036_50361201_143_dialog_content = "응!",
  ui_story_5036_50361201_144_dialog_content = "열정적인 노래로 콘서트의 막을 올려 준 레지나 씨와 바바라 씨, 감사합니다!",
  ui_story_5036_50361201_145_dialog_content = "분위기가 후끈 달아올라서인지, 제 마음도 두근대기 시작했어요!",
  ui_story_5036_50361201_146_dialog_content = "그런데 말이죠~ 제가 이번에 엄~청 유명한 인기인 두 분을 모셨어요!",
  ui_story_5036_50361201_147_dialog_content = "한 분은 백야성의 기사고, 다른 한 분은 일루미나의 장교예요.",
  ui_story_5036_50361201_148_dialog_content = "하지만 서로의 소속이 달라도 갈등 없이 최고의 친구가 되었고,\n전설의 아이테르와 함께 여행을 하고 있다고 하네요~",
  ui_story_5036_50361201_149_dialog_content = "그리고~ 오늘 그 두 분이 여행을 하면서 겪었던 가장 아름다운 기억을\n바탕으로 자작곡을 만들었는데, 그 노랠 여러분께 전하고 싶대요.",
  ui_story_5036_50361201_150_dialog_content = "그럼 무대 위로 모시겠습니다! 카렌과 바이스!",
  ui_story_5036_50361201_151_dialog_content = "사람 진짜 많네. 조종사가 없어서 좀 아쉽긴 하지만...",
  ui_story_5036_50361201_152_dialog_content = "긴장하지 마, 우리 둘이라면 분명히 괜찮을 거야.",
  ui_story_5036_50361201_153_dialog_content = "응! 그럼 시작하자!",
  ui_story_5036_50361201_154_dialog_content = "♪예상하지 못한 여행처럼♪",
  ui_story_5036_50361201_155_dialog_content = "♪지도엔 없는 길이 나타났어♪",
  ui_story_5036_50361201_156_dialog_content = "♪이 앞엔 뭐가 있을까♪",
  ui_story_5036_50361201_157_dialog_content = "♪이런 두근거림을 안고♪",
  ui_story_5036_50361201_158_dialog_content = "♪너와 만나, 함께 나아가며♪",
  ui_story_5036_50361201_159_dialog_content = "♪짧은 이별을 겪고, 또다시 만나♪",
  ui_story_5036_50361201_160_dialog_content = "♪말하지 않아도 마음이 통하는 동료♪",
  ui_story_5036_50361201_161_dialog_content = "♪낯선 사이에서 마음이 맞는♪",
  ui_story_5036_50361201_162_dialog_content = "♪영원한 동료가 돼 서로를 비추고♪",
  ui_story_5036_50361201_163_dialog_content = "♪궤적에서 다시 만난 별이 되었지♪",
  ui_story_5036_50361201_164_dialog_content = "그로누가 미리 신호 전송 장치를 설치해 둬서 다행이었어요.\n덕분에 여기서도 콜로서스에서 열리고 있는 콘서트를 볼 수 있으니 말이에요.",
  ui_story_5036_50361201_165_dialog_content = "이건 일종의 새로운 오락거리네요. 참고할 가치가 있겠어요.",
  ui_story_5036_50361201_166_dialog_content = "대원수님, 추후 지하성 내부에서 소규모로 실험을 조금 진행해\n효과를 테스트해 봐도 될까요?",
  ui_story_5036_50361201_167_dialog_content = "좋아. 허락하지.",
  ui_story_5036_50361201_168_dialog_content = "네? 아, 알겠습니다!",
  ui_story_5036_50361201_169_dialog_content = "왜 그러지? 꽤 놀란 모양이다만?",
  ui_story_5036_50361201_170_dialog_content = "대원수님께서는 이런 오락거리에 조금 더 신중하실 줄 알았거든요.",
  ui_story_5036_50361201_171_dialog_content = "하하하, 물론 신중하지. 허나, 잘 들어 봐라.",
  ui_story_5036_50361201_172_dialog_content = "난 노래는 소질이 없지만, 듣는 것쯤은 할 수 있다.\n그리고 지금 이 순간, 바이스는 꽤 즐거워하고 있지.",
  ui_story_5036_50361201_173_dialog_content = "저런 감정이야말로 지금 우리에게 필요한 것이 아니겠나.",
  ui_story_5036_50361201_174_dialog_content = "여기서도 카렌 언니랑 바이스 언니가 부르는 노랠 들을 수 있다니...",
  ui_story_5036_50361201_175_dialog_content = "역시 카렌 언니야! 노래도 엄청 잘 부르네!",
  ui_story_5036_50361201_176_dialog_content = "라파엘, 너는 이곳에서 경비를 강화하도록.",
  ui_story_5036_50361201_177_dialog_content = "그리고 사람을 시켜 조용히 비공정 한 대를 준비해라.",
  ui_story_5036_50361201_178_dialog_content = "어라? 성주님, 지금 외출하시려구요?",
  ui_story_5036_50361201_179_dialog_content = "저 콜로서스에 어떤 위험이 있는지는 아직 확실히 알 수 없다.\n그러니 성주로서 만일의 사태에 대비해 직접 조사해 봐야겠다.",
  ui_story_5036_50361201_180_dialog_content = "아, 알겠습니다!",
  ui_story_5036_50361201_181_dialog_content = "에이...",
  ui_story_5036_50361201_182_dialog_content = "성주님도 참, 언제쯤 돼야 카렌 언니를 아끼고 있단 걸 솔직히 말씀하실 수 있게 될까?",
  ui_story_5036_50361201_183_dialog_content = "<color=#e8d9bb>같은 시간, 표류하는 콜로서스 안</color>",
  ui_story_5036_50361201_184_dialog_content = "이 목소리... 바이스랑 카렌이 노래를 부르고 있나 보네!",
  ui_story_5036_50361201_185_dialog_content = "벌써 두 사람 차례가 된 거야? 큰일이네... 더 빨리 뛰었어야 했어!",
  ui_story_5036_50361201_186_dialog_content = "근데 벌써 도착하고도 남았을 시간인데...",
  ui_story_5036_50361201_187_dialog_content = "역시 함께 모험하는 동료답게, 완벽한 호흡이었네요!",
  ui_story_5036_50361201_188_dialog_content = "사실 아이돌이라는 단어는 하나지만, 이 아이돌이란 단어가 여러분의\n마음속에서 가지고 있는 정의는 다 달라요.",
  ui_story_5036_50361201_189_dialog_content = "어떤 사람들은 아이돌이 사람들의 힘을 한데 모으기 위해 존재한다고 여기죠.",
  ui_story_5036_50361201_190_dialog_content = "그럼 이제 일루미나에서 온 합창단의 무대를 만나 볼까요!",
  ui_story_5036_50361201_191_dialog_content = "여러분 모두에게 파워풀한 군가를 들려 드리겠다고 하네요!",
  ui_story_5036_50361201_192_dialog_content = "와아아아아아!",
  ui_story_5036_50361201_193_dialog_content = "휴우... 바이스 씨, 카렌 씨. 정말 고생 많았어!",
  ui_story_5036_50361201_194_dialog_content = "아니에요! 별로 안 힘들었어요!",
  ui_story_5036_50361201_195_dialog_content = "근데 시간도 꽤 지났는데, PlayerName하고 비크 씨는 아직도 안 돌아왔네요.",
  ui_story_5036_50361201_196_dialog_content = "그러게, 콜로서스가 크긴 해도 사람 하나 찾는 데\n이 정도로 오래 걸리진 않을 텐데.",
  ui_story_5036_50361201_197_dialog_content = "으음...",
  ui_story_5036_50361201_198_dialog_content = "카렌, 아무래도 우리가 두 사람을 찾으러 가는 게 좋을 것 같아.",
  ui_story_5036_50361201_199_dialog_content = "나도 그렇게 생각해. 마침 우리 공연도 끝났으니까\n두 사람의 안전을 위해서라도 가서 찾아보자.",
  ui_story_5036_50361201_200_dialog_content = "알겠어! 두 사람도 조심하구, 앙코르 무대 전까진 돌아와야 해!",
  ui_story_5036_50361201_201_dialog_content = "네.",
  ui_story_5036_50361201_202_dialog_content = "그럼 가자.",
  ui_story_5036_50361201_203_dialog_content = "<color=#e8d9bb>얼마 후</color>",
  ui_story_5036_50361201_204_dialog_content = "(일루미나 합창단의 무대도 끝났고, 백야성 성가대의 공연도 거의 다 끝나 가는데...)",
  ui_story_5036_50361201_205_dialog_content = "(PlayerName 씨랑 다들 왜 아직 안 돌아오는 거지?\n혹시 무슨 문제라도 생긴 건가?)",
  ui_story_5036_50361201_206_dialog_content = "(걱정돼 죽겠네! 근데 조금 있으면 내가 무대에 올라가야 해서 자리도 못 비우는데!)",
  ui_story_5036_50361201_207_dialog_content = "(그 노랜 무슨 일이 있어도 모두에게 들려줘야 해.)",
  ui_story_5036_50361201_208_dialog_content = "(내가 오늘 공연에서 그 노랠 부르지 않으면...\n모두와 PlayerName 씨, 그리고 내 노력을 배신하게 돼.)",
  ui_story_5036_50361201_209_dialog_content = "(그러니까 무대에서 노랠 부르고 난 다음에, 모두를 찾으러 가는 거야.)",
  ui_story_5036_50361201_210_dialog_content = "이제 마지막 무대만 남겨 놓고 있네요. 여러분 설마 지쳐버린 건 아니시죠?",
  ui_story_5036_50361201_211_dialog_content = "아니요──!",
  ui_story_5036_50361201_212_dialog_content = "모두 감사해요! 여러분의 열정! 제게 다 전해졌어요!",
  ui_story_5036_50361201_213_dialog_content = "그럼 이제 제가 여러분께 마지막 곡을 들려 드릴게요!",
  ui_story_5036_50361201_214_dialog_content = "우와아아아아! 드디어 골디가 노래한대!",
  ui_story_5036_50361201_215_dialog_content = "오늘은 골디가 모두를 위해 특별한 노래 한 곡을 준비했어요.\n이 노래의 선율은 아이테르들이 콜로서스와 소통하는 데 썼던 거예요.",
  ui_story_5036_50361201_216_dialog_content = "아이테르들은 이 선율로 콜로서스를 조종해 세계를 여행했던 거죠.",
  ui_story_5036_50361201_217_dialog_content = "그리고 지금, 백 년이라는 시간을 거슬러 드디어 귀환한 콜로서스에서\n이 선율이 다시금 울려 퍼질 거예요!",
  ui_story_5036_50361201_218_dialog_content = "와아아아아!",
  ui_story_5036_50361201_219_dialog_content = "(바로 지금이야. 드디어 제일 중요한 순간이 됐어.)",
  ui_story_5036_50361201_220_dialog_content = "우리 골디 하고 싶은 거 다 해! 골디락스가 영원히 함께할게!",
  ui_story_5036_50361201_221_dialog_content = "(이 노래로 팬들의 사랑이랑 PlayerName 씨의 노력에 보답하는 거야!)",
  ui_story_5036_50361201_222_dialog_content = "♪아른거리는 별♪",
  ui_story_5036_50361201_223_dialog_content = "♪날개를 펴고 날아오르는 철새♪",
  ui_story_5036_50361201_224_dialog_content = "♪희망의 항해가♪",
  ui_story_5036_50361201_225_dialog_content = "♪가야 할 방향을 알려주네♪",
  ui_story_5036_50361201_226_dialog_content = "골디! 골디!",
  ui_story_5036_50361201_227_dialog_content = "우와... 현장에서 직접 골디 씨가 부르는 노랠 듣게 되다니...",
  ui_story_5036_50361201_228_dialog_content = "힘든 일도 많았지만, 그만한 가치가 있었어!",
  ui_story_5036_50361201_229_dialog_content = "♪기대 가득한 만남에♪",
  ui_story_5036_50361201_230_dialog_content = "♪두근거리며 용기를 내♪",
  ui_story_5036_50361201_231_dialog_content = "(어라... 갑자기... 너무 졸려...)",
  ui_story_5036_50361201_232_dialog_content = "(안 돼! 버텨야 해! 아직 콘서트 중인걸!)",
  ui_story_5036_50361201_233_dialog_content = "♪앞으로 나아가자, 앞으로♪",
  ui_story_5036_50361201_234_dialog_content = "♪너를 만날 그곳까지♪",
  ui_story_5036_50361201_235_dialog_content = "(왜 이러지... 너무... 어지러워...)",
  ui_story_5036_50361201_236_dialog_content = "츄우우─!",
  ui_story_5036_50361201_237_dialog_content = "(이 소린... 대체 어디서 들려오는 거지?)",
  ui_story_5036_50361201_238_dialog_content = "(너무 졸린데, 자면 안 돼... 콘서트가 아직...)",
  ui_story_5036_50361301_1_dialog_content = "<color=#e8d9bb>같은 시간, 콜로서스 봉쇄 구역</color>",
  ui_story_5036_50361301_2_dialog_content = "대체 뭐가 어떻게 된 거야? 왜 또 빙빙 돌고 있는 것 같은 느낌이 드는 거지?",
  ui_story_5036_50361301_3_dialog_content = "분명히 이쪽 길로 왔던 게 맞는데, 왜 걸어도 걸어도 끝이 안 보이는 건데?",
  ui_story_5036_50361301_4_dialog_content = "설마 우로보로스의 능력이 또 영향을 주기 시작한 건가?",
  ui_story_5036_50361301_5_dialog_content = "너무 오래 걸었는데... 설마 콘서트가 벌써 다 끝나 버린 건 아니겠지?",
  ui_story_5036_50361301_6_dialog_content = "아, 저 앞에 있는 건... 찾았다! 드디어 맞게 찾아왔어!",
  ui_story_5036_50361301_7_dialog_content = "어? PlayerName, 여긴 왜 왔어?",
  ui_story_5036_50361301_8_dialog_content = "공연이 너무 따분해서 몰래 여기서 눈이나 붙이러 온 건 아니겠지?",
  ui_story_5036_50361301_9_dialog_content = "난 그렇게 무책임한 사람이 아니거든!",
  ui_story_5036_50361301_10_dialog_content = "아니, 근데 비크 씨야말로 왜 여기 온 거야? 다들 비크 씨의 공연을 기다리고 있어!",
  ui_story_5036_50361301_11_dialog_content = "내 공연? 아, 내가 무대에 올라가서 노래 부르는 거?",
  ui_story_5036_50361301_12_dialog_content = "나한테 그런 건 무리야.",
  ui_story_5036_50361301_13_dialog_content = "무슨 소릴 하는 거야! 재능도 있고, 골디가 트레이닝도 시켜 주고\n안무까지 짜 줬는데, 이제 와서 못 하겠다고?",
  ui_story_5036_50361301_14_dialog_content = "하하하, 나한테 재능이 있는 건 맞지만, 그래도 진짜 무리야.",
  ui_story_5036_50361301_15_dialog_content = "너도 다른 사람들이 트레이닝하는 거 봤지?",
  ui_story_5036_50361301_16_dialog_content = "무대 위에 올라가서 공연을 하려면, 오랜 시간 트레이닝도 받아야 하고\n열정도 있어야 하는데, 나한테는 그 두 가지가 다 없거든.",
  ui_story_5036_50361301_17_dialog_content = "난 콘서트랑 아이돌에 별 관심 없어.\n나이 때문에 팔다리가 후들후들해서 안무 같은 것도 무리고.",
  ui_story_5036_50361301_18_dialog_content = "무대에 올라갔다고 하더라도, 젊은 친구들 발목이나 잡을 게 뻔해.",
  ui_story_5036_50361301_19_dialog_content = "그러니까 노력의 결실을 망쳐 버리기보단, 내가 잘하는 일을 하는 편이 낫잖아?\n예를 들면 콘서트가 진행될 동안 저 알이 사고 치지 않게 여기서 잘 지켜보는 거.",
  ui_story_5036_50361301_20_dialog_content = "콘서트에 별 관심 없다더니, 사실은 엄청 신경 쓰고 있었잖아?",
  ui_story_5036_50361301_21_dialog_content = "젊은 친구들한테 신세 지고 싶지 않은 것뿐이야~",
  ui_story_5036_50361301_22_dialog_content = "신세는 이미 잔뜩 지고 있거든...",
  ui_story_5036_50361301_23_dialog_content = "크, 크흠. 내 제자들은 나한테 트레이닝을 받고 있는 거니까, 그건 논외야.",
  ui_story_5036_50361301_24_dialog_content = "그런데 너도 오면서 느꼈지? 우로보로스의 능력이 또다시 발동되기 시작했어.",
  ui_story_5036_50361301_25_dialog_content = "응, 그래서 오늘 길에 한참 헤맸다니까.",
  ui_story_5036_50361301_26_dialog_content = "이건 우로보로스가 또 위험을 느껴서 자신을 보호하려고 하고 있단 거야.",
  ui_story_5036_50361301_27_dialog_content = "근데 이 근처에 있는 암귀는 우리가 다 처치했고, 벽에 있던 틈도 다 메웠잖아?",
  ui_story_5036_50361301_28_dialog_content = "아마 오로리안이 너무 멀리 떨어져 있어서 이러는 걸 수도 있어.",
  ui_story_5036_50361301_29_dialog_content = "지금은 콘서트 중이라, 모든 오로리안이 콜로서스의 머리 쪽 무대에\n몰려 있잖아. 여기서 제일 먼 곳 말이야.",
  ui_story_5036_50361301_30_dialog_content = "그러니까 무슨 일이 생기면, 너랑 나 말곤 제시간에 와서 도와줄 사람이 없어.",
  ui_story_5036_50361301_31_dialog_content = "그래서 우로보로스가 불안함을 느꼈다는 거야?",
  ui_story_5036_50361301_32_dialog_content = "그럴 수도 있다는 거야~",
  ui_story_5036_50361301_33_dialog_content = "우로보로스는 참 겁이 많은 생물이네.\n콜로서스에서 이렇게 오래 지냈으면서도 뭘 이렇게까지 두려워하는 걸까.",
  ui_story_5036_50361301_34_dialog_content = "만남의 기쁨을 알아 버려서, 헤어짐을 두려워하는 거겠지.",
  ui_story_5036_50361301_35_dialog_content = "나도 혼자서 콜로서스에서 17년 동안 생활했었지만,.\n스카이워커호가 있어서 외롭단 느낌은 없었거든.",
  ui_story_5036_50361301_36_dialog_content = "그런데 이젠 동료들이랑 떨어져야 하는 상황이 온다 하더라도,\n분명 그러고 싶지 않을 거야.",
  ui_story_5036_50361301_37_dialog_content = "그렇긴 하겠구나.",
  ui_story_5036_50361301_38_dialog_content = "근데, 아직도 이해가 잘 안되는 게 있어.\n아까 저 알이 「문제를 일으킨다」고 그랬잖아?",
  ui_story_5036_50361301_39_dialog_content = "콘서트도 벌써 시작됐는데, 저 알이 뭐 어떻게 문제를 일으킬 수 있단 거야?",
  ui_story_5036_50361301_40_dialog_content = "어? 관찰력이 꽤 예리하네.",
  ui_story_5036_50361301_41_dialog_content = "전에 내가 말해 줬었지? 저 알은 진작 부화했어야 하는데도 모종의 이유 때문에\n알 상태를 유지하고 있다 보니 저렇게 커진 거라고.",
  ui_story_5036_50361301_42_dialog_content = "바로 그래서 나도 저 알이 언제 부화할지 알 수 없어.",
  ui_story_5036_50361301_43_dialog_content = "그렇지만 알의 크기로 봤을 때, 이 알이 부화해서 우로보로스가\n활동을 시작하게 된다면, 콜로서스 전체에 영향을 줄 가능성이 있어.",
  ui_story_5036_50361301_44_dialog_content = "뭐...?!",
  ui_story_5036_50361301_45_dialog_content = "그럼 저 알이 언제 터질지 모르는 시한폭탄이랑 똑같다는 거잖아?!",
  ui_story_5036_50361301_46_dialog_content = "정답~",
  ui_story_5036_50361301_47_dialog_content = "그래서 콘서트가 문제없이 진행되는 것뿐만 아니라,\n우리 목숨을 생각해서라도 저 알을 잘 지켜보고 있어야 하는 거야.",
  ui_story_5036_50361301_48_dialog_content = "이런 맹점을 파악해 버릴 줄이야.\nPlayerName 너 사실 환상동물 마스터 쪽으로 꽤 재능이 있는 것 같은데?",
  ui_story_5036_50361301_49_dialog_content = "어때? 내 제자가 돼 보지 않을래?",
  ui_story_5036_50361301_50_option_content = "좋아.",
  ui_story_5036_50361301_51_dialog_content = "환상동물들은 재미있기도 하고, 멸종 위기에 처한 것들도 많으니까.",
  ui_story_5036_50361301_52_dialog_content = "제대로 보호해 줄 수 있다면, 무척 뜻깊을 거야.",
  ui_story_5036_50361301_53_dialog_content = "좋은 생각이야, PlayerName.\n아니지, 이제부턴 제자 군이라고 불러야 하려나?",
  ui_story_5036_50361301_54_dialog_content = "미리 말해 두지만, 공짜 일꾼으로 여기저기 끌고 다닐 생각은 마.",
  ui_story_5036_50361301_55_dialog_content = "으흑... 자기 사부를 그렇게 비양심적인 사람으로 생각하는 거야?",
  ui_story_5036_50361301_56_option_content = "역시 됐어.",
  ui_story_5036_50361301_57_dialog_content = "난 환상동물에 관심은 많지만, 피아랑 시라만 봐도 비크 씨 제자가 되면\n고생길이 훤히 열린다는 건 알아...",
  ui_story_5036_50361301_58_dialog_content = "동물 돌보랴, 사부 돌보랴, 경비도 안 주고 야외 조사 보내지...",
  ui_story_5036_50361301_59_dialog_content = "정말 해도 너무하잖아?!",
  ui_story_5036_50361301_60_dialog_content = "우린 환상동물을 향한 사랑으로 움직이는 거라서 보답은 굳이 바라지 않아~",
  ui_story_5036_50361301_61_dialog_content = "뭐 네가 싫다고 한다면 억지로 하라고 할 생각은 없어.",
  ui_story_5036_50361301_62_dialog_content = "여기서 시간을 이렇게 많이 허비해 버렸잖아.\n콘서트가 지금쯤 어디까지 진행됐을지 모르겠네.",
  ui_story_5036_50361301_63_dialog_content = "이렇게 하자. 일단 내가 돌아가서 골디랑 다른 사람들한테\n비크 씨 얘길 전해 줄게. 안 그러면 계속 걱정할 테니까.",
  ui_story_5036_50361301_64_dialog_content = "좋아, 그럼 난 계속 여길 지키고 있을게...",
  ui_story_5036_50361301_65_dialog_content = "츄우우─!",
  ui_story_5036_50361301_66_dialog_content = "이 소린 뭐지?",
  ui_story_5036_50361301_67_dialog_content = "소리? 무슨 소리? 설마 환청이 들리는 거야?",
  ui_story_5036_50361301_68_dialog_content = "카렌, 방금 이상한 소리 못 들었어?",
  ui_story_5036_50361301_69_dialog_content = "무슨 동물 울음소리 같았는데...",
  ui_story_5036_50361301_70_dialog_content = "으윽...",
  ui_story_5036_50361301_71_dialog_content = "카렌?! 괜찮아? 왜...",
  ui_story_5036_50361301_72_dialog_content = "왜 이렇게... 졸리지...",
  ui_story_5036_50361301_73_dialog_content = "방금 그거... 우로보로스의 울음소리 같았어...",
  ui_story_5036_50361301_74_dialog_content = "(어? 갑자기... 너무... 졸려...)",
  ui_story_5036_50361301_75_dialog_content = "PlayerName? 왜 그래? 얼른 일어나 봐!",
  ui_story_5036_50361301_76_dialog_content = "어쩔 수 없지. 그 방법을 쓸 수밖에! 비카, 지금이야!\nPlayerName 주머니에 있는 나이티움을 다 먹어 치워버려!",
  ui_story_5036_50361301_77_dialog_content = "하이!",
  ui_story_5036_50361301_78_dialog_content = "히익?! 그만, 안 돼, 당장 멈춰!",
  ui_story_5036_50361301_79_dialog_content = "내가 진짜 힘들게 모은 비상금이란 말이야!",
  ui_story_5036_50361301_80_dialog_content = "휴, 다행이야. 정신을 차렸구나.",
  ui_story_5036_50361301_81_dialog_content = "어제 밤이라도 새웠어? 방금 기절해 버리는 줄 알았잖아.",
  ui_story_5036_50361301_82_dialog_content = "밤을 새웠냐고? 아니, 어젠 일찍 잤어.",
  ui_story_5036_50361301_83_dialog_content = "이상하네. 아까 우로보로스의 울음소리 같은 걸 듣고 나자마자\n나도 모르게 갑자기 엄청 졸렸는데...",
  ui_story_5036_50361301_84_dialog_content = "우로보로스의 울음소리를 들었다고? 난 못 들었는데?",
  ui_story_5036_50361301_85_dialog_content = "진짜 들었어! 못 믿겠으면 자세히 들어 봐. 그럼 들릴지도 모르니까.",
  ui_story_5036_50361301_86_dialog_content = "그래, 그럼 한 번 들어 볼게.",
  ui_story_5036_50361301_87_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5036_50361301_88_dialog_content = "아무 소리도 안 들리잖아. 네가 잘못 들은 거겠지.",
  ui_story_5036_50361301_89_dialog_content = "그치만...",
  ui_story_5036_50361301_90_dialog_content = "<color=#e8d9bb>두근──</color>",
  ui_story_5036_50361301_91_dialog_content = "또 무슨 소리가 들려! 근데 우로보로스의 울음소리는 아니야.",
  ui_story_5036_50361301_92_dialog_content = "이 소리는...?!",
  ui_story_5036_50361301_93_dialog_content = "비크 씨도 들었어?",
  ui_story_5036_50361301_94_dialog_content = "<color=#e8d9bb>두근── 두근──</color>",
  ui_story_5036_50361301_95_dialog_content = "나도 들었어. 이번에는 아주 선명히.",
  ui_story_5036_50361301_96_dialog_content = "이건... 심장이 뛰는 소리야.",
  ui_story_5036_50361301_97_dialog_content = "알에서 들리고 있어.",
  ui_story_5036_50361301_98_dialog_content = "뭐?! 그럼 우로보로스가 곧 부화한단 거야?",
  ui_story_5036_50361301_99_dialog_content = "하필이면 이 타이밍이라니, 진짜 난감하네.",
  ui_story_5036_50361301_100_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5036_50361301_101_dialog_content = "이번엔 또 뭐야?",
  ui_story_5036_50361301_102_dialog_content = "조심해, PlayerName!",
  ui_story_5036_50361301_103_dialog_content = "우리가 막아 둔 벽 틈을 뚫고 뭔가가 이 안으로 들어오려고 해!",
  ui_story_5036_50361301_104_dialog_content = "<color=#e8d9bb>콰르릉──!</color>",
  ui_story_5036_50361301_105_dialog_content = "크어어──!",
  ui_story_5036_50361301_106_dialog_content = "비크 씨! 암귀야!",
  ui_story_5036_50361301_107_dialog_content = "타래! 우리 좀 살려줘!",
  ui_story_5036_50361302_1_dialog_content = "왜 여기 암귀가 이렇게 많은 거야?!",
  ui_story_5036_50361302_2_dialog_content = "저번에 이 근처에 있는 암귀들은 싹 다 없앴었잖아?",
  ui_story_5036_50361302_3_dialog_content = "이 근처가 아니라 더 멀리서 온 녀석들일 수도 있어.",
  ui_story_5036_50361302_4_dialog_content = "그리고 놈들이 갑자기 이렇게 날뛰는 건 우로보로스의 부화와 관계가 있을지도 몰라.",
  ui_story_5036_50361302_5_dialog_content = "어쨌든 빨리 가서 골디랑 다른 사람들한테 이 사실을 알려야 해!",
  ui_story_5036_50361302_6_dialog_content = "녀석이 진짜로 부화한다면, 다들 이 콜로서스에 있어선 안 돼!\n모두가 위험해질 거야!",
  ui_story_5036_50361302_7_dialog_content = "얼른 모두를 여기서 대피시켜야 한다고!",
  ui_story_5036_50361302_8_dialog_content = "그래, 확실히 계속 여기 있는 건 좋은 방법이 아니야.",
  ui_story_5036_50361302_9_dialog_content = "우로보로스가 부화해 버리면 방이 다 무너져 내릴지도 모르니까.",
  ui_story_5036_50361302_10_dialog_content = "아무래도 도망칠 때가 된 모양이네~",
  ui_story_5036_50361302_11_dialog_content = "이쪽으로 가면 되겠지. PlayerName, 잘 따라와.",
  ui_story_5036_50361302_12_dialog_content = "잠깐만, 저쪽에 사람이 두 명 쓰러져 있는 것 같은데?",
  ui_story_5036_50361302_13_dialog_content = "바이스랑 카렌이잖아?!",
  ui_story_5036_50361302_14_dialog_content = "바이스! 카렌! 정신 차려!",
  ui_story_5036_50361302_15_dialog_content = "어떻게 된 거지? 둘 다 안 일어나는데?!",
  ui_story_5036_50361302_16_dialog_content = "설마 이것도 우로보로스의 능력 때문인가?",
  ui_story_5036_50361302_17_dialog_content = "두 사람을 데리고 여길 빠져나가자. 계속 여기 있으면 위험해.",
  ui_story_5036_50361302_18_dialog_content = "응, 그건 나한테 맡겨. 두 사람은 내가 부축할게.",
  ui_story_5036_50361302_19_dialog_content = "으라차차차차차!",
  ui_story_5036_50361302_20_dialog_content = "PlayerName, 너 운동 좀 더 해야겠다.",
  ui_story_5036_50361302_21_dialog_content = "이런 상황에 얄밉게 그러지 말고 좀 도와줘!",
  ui_story_5036_50361302_22_dialog_content = "내가 힘이 좋은 편은 아니라 별 도움은 안 될 거야. 그러니까...",
  ui_story_5036_50361302_23_dialog_content = "타래! 네가 나설 차례야!",
  ui_story_5036_50361302_24_dialog_content = "뀨우!",
  ui_story_5036_50361302_25_dialog_content = "이렇게 커질 수도 있었어?!",
  ui_story_5036_50361302_26_dialog_content = "물론이지. 게다가 덩치가 커져도 털은 항상 보들보들해.",
  ui_story_5036_50361302_27_dialog_content = "이 위에서 낮잠을 자면 진짜 너무 편해.\n너도 만져 봐, 처음이니까 공짜로 만지게 해 줄게.",
  ui_story_5036_50361302_28_dialog_content = "그건 다음에 기회에 할게...",
  ui_story_5036_50361302_29_dialog_content = "아무튼, 타래! 아니지, 큰 타래야! 바이스랑 카렌을 네 등에 태워 줘.",
  ui_story_5036_50361302_30_dialog_content = "뀨우──!",
  ui_story_5036_50361302_31_dialog_content = "그럼 얼른 돌아가자! 모두에게 빨리 이 사실을 알려야 해!",
  ui_story_5036_50361302_32_dialog_content = "이건...",
  ui_story_5036_50361302_33_dialog_content = "다들 잠들어 버렸네.",
  ui_story_5036_50361302_34_dialog_content = "저 아가씨도 혼자서 무대 위에 쓰러져 있고.",
  ui_story_5036_50361302_35_dialog_content = "......",
  ui_story_5036_50361302_36_dialog_content = "골디! 눈 좀 떠 봐!",
  ui_story_5036_50361302_37_dialog_content = "아무리 깨워도 일어나질 않아...",
  ui_story_5036_50361302_38_dialog_content = "상태가 뭔가 이상한데? 루미나틱스의 흔적이 남아 있어.",
  ui_story_5036_50361302_39_dialog_content = "이거도 우로보로스 때문이야?",
  ui_story_5036_50361302_40_dialog_content = "우로보로스 때문이라면 왜 우리 둘은 아무렇지도 않고,\n다른 사람들은 전부 잠들어 버린 거지?",
  ui_story_5036_50361302_41_dialog_content = "우리 둘은 특별하니까.",
  ui_story_5036_50361302_42_dialog_content = "넌 신비로운 감응 능력을 지닌 아이테르잖아.",
  ui_story_5036_50361302_43_dialog_content = "그리고 내 혈통은 우로보로스와 깊은 관계가 있으니까,\n뭔가 저항 능력 같은 게 있는 걸지도 몰라.",
  ui_story_5036_50361302_44_dialog_content = "모두가 눈을 뜨게 할 방법이 없을까?",
  ui_story_5036_50361302_45_dialog_content = "그건 나도 몰라.",
  ui_story_5036_50361302_46_dialog_content = "왜 모른다는 거야... 우로보로스랑 관계가 있는 혈통이라면서?",
  ui_story_5036_50361302_47_dialog_content = "아쉽지만 혈통상 관계가 있는 거랑 좀 오래 살았다는 거 빼곤,\n나한테 특별한 능력은 없거든.",
  ui_story_5036_50361302_48_dialog_content = "하지만 시도해 볼 만한 방법이 있긴 해.",
  ui_story_5036_50361302_49_dialog_content = "넌 아이테르니까, 네 감응 능력을 사용하면 내가 모르는 걸 알아낼 수도 있어.",
  ui_story_5036_50361302_50_dialog_content = "알겠어. 어차피 다른 방법도 없으니까 해 볼게.",
  ui_story_5036_50361401_1_dialog_content = "나... 잠들어 버린 모양이네...",
  ui_story_5036_50361401_2_dialog_content = "여긴... 헤븐즈 밸리? 설마 내가 또 꿈을 꾸고 있는 거야?",
  ui_story_5036_50361401_3_dialog_content = "이번에는 저번 꿈들이랑 다르게 훨씬 더 선명하게 보이는걸.",
  ui_story_5036_50361401_4_dialog_content = "저쪽에 있는 하얀 탑까지 엄청 잘 보여.",
  ui_story_5036_50361401_5_dialog_content = "잠깐, 저 탑 위에 있는 하늘에 뭔가...",
  ui_story_5036_50361401_6_dialog_content = "용?!",
  ui_story_5036_50361401_7_dialog_content = "이건 꿈일 거야!",
  ui_story_5036_50361401_8_dialog_content = "말도 안 돼! 빨리 눈 떠, 골디! 콘서트는 아직 끝나지 않았단 말이야!",
  ui_story_5036_50361401_9_dialog_content = "맞아. 허벅지를 세게 꼬집으면 꿈에서 깰 수 있단 얘길 들은 적 있어.",
  ui_story_5036_50361401_10_dialog_content = "에잇!",
  ui_story_5036_50361401_11_dialog_content = "아야야! 아파!",
  ui_story_5036_50361401_12_dialog_content = "근데 왜 아직도 꿈속이지? 더 세게 꼬집어야 하려나?",
  ui_story_5036_50361401_13_dialog_content = "♪라라~ 라라라라~♪",
  ui_story_5036_50361401_14_dialog_content = "익숙한 노래야... 저 아이가 샤미나드라는 아이테르 소녀인 걸까?",
  ui_story_5036_50361401_15_dialog_content = "♪촉촉이 젖은... 날개♪",
  ui_story_5036_50361401_16_dialog_content = "이번에는 가사도 들리네?",
  ui_story_5036_50361401_17_dialog_content = "전에는 간신히 멜로디만 들을 수 있었는데.",
  ui_story_5036_50361401_18_dialog_content = "♪...고향♪",
  ui_story_5036_50361401_19_dialog_content = "노랫소리는 저쪽에서 들려오는 것 같아.",
  ui_story_5036_50361401_20_dialog_content = "♪기억 속의 순간만이 남았네♪",
  ui_story_5036_50361401_21_dialog_content = "♪우뚝 솟은 하얀 탑♪",
  ui_story_5036_50361401_22_dialog_content = "♪인도하는 빛이 보이지 않아♪",
  ui_story_5036_50361401_23_dialog_content = "(아름다운 멜로디지만, 소녀가 정말 슬퍼하고 있단 게 느껴져...)",
  ui_story_5036_50361401_24_dialog_content = "♪방황하고 또 배회하지♪",
  ui_story_5036_50361401_25_dialog_content = "♪꿈속의 고향을 그리워하며♪",
  ui_story_5036_50361401_26_dialog_content = "어? 여기 나 말고 다른 사람도 있었네?",
  ui_story_5036_50361401_27_dialog_content = "(어?! 지, 지금 나한테 말을 건 거야?!)",
  ui_story_5036_50361401_28_dialog_content = "(전에 꾼 꿈에선 이런 경우는 없었는데? 설마 꿈이 아닌가?)",
  ui_story_5036_50361401_29_dialog_content = "아, 안녕! 넌 샤미나드지? 난 골디라고 해, 아이돌을 하고 있어!",
  ui_story_5036_50361401_30_dialog_content = "어라? 어떻게 내 이름을 아는 거야?",
  ui_story_5036_50361401_31_dialog_content = "당연히 알지! 내 친구 PlayerName 씨도 아이테르거든.\n네가 남겨 둔 기억들을 그 친구가 감응했었어.",
  ui_story_5036_50361401_32_dialog_content = "그래? 후후, 그렇다니까 뭔가 좀 쑥스러운걸.",
  ui_story_5036_50361401_33_dialog_content = "근데, 아이돌이 뭐야?",
  ui_story_5036_50361401_34_dialog_content = "아이돌은 노래로 다른 사람들한테 기쁨과 희망을 주는 직업이야!\n그리고 난 프로 아이돌이구!",
  ui_story_5036_50361401_35_dialog_content = "정말 대단해! 나도 아이돌이 되고 싶어!",
  ui_story_5036_50361401_36_dialog_content = "내가 가르쳐 줄게! 그렇지만 지금 바로는 안 돼.\n콘서트 중이라서 빨리 돌아가서 공연을 계속해야 하거든!",
  ui_story_5036_50361401_37_dialog_content = "샤미나드, 어떻게 하면 여기서 나갈 수 있는지 알아?",
  ui_story_5036_50361401_38_dialog_content = "미안해, 어떻게 해야 널 내보내 줄 수 있는지는 나도 몰라...",
  ui_story_5036_50361401_39_dialog_content = "나도 여기서 나갈 수 없거든.",
  ui_story_5036_50361401_40_dialog_content = "나갈 수 없다구?",
  ui_story_5036_50361401_41_dialog_content = "(그렇구나, 그도 그럴 게 진짜 샤미나드는 이미...)",
  ui_story_5036_50361401_42_dialog_content = "(하지만 샤미나드가 오래전에 죽었다면, 내 눈앞에 있는 이 사람은 대체 누구지?)",
  ui_story_5036_50361401_43_dialog_content = "음, 괜찮아!",
  ui_story_5036_50361401_44_dialog_content = "찾다 보면 어떻게든 방법이 생길 테니까!",
  ui_story_5036_50361401_45_dialog_content = "<color=#e8d9bb>콰쾅──!</color>",
  ui_story_5036_50361401_46_dialog_content = "어? 방금 무슨 소리지?",
  ui_story_5036_50361401_47_dialog_content = "녀석들이야!",
  ui_story_5036_50361401_48_dialog_content = "빨리 도망쳐! 녀석들이 곧 올 거야!",
  ui_story_5036_50361401_49_dialog_content = "녀석들? 누구 말하는 거야?",
  ui_story_5036_50361401_50_dialog_content = "암귀들!",
  ui_story_5036_50361401_51_dialog_content = "크어어──!",
  ui_story_5036_50361401_52_dialog_content = "세상에! 진짜 암귀들이네? 그런데 왜 이렇게 많은 거야?!",
  ui_story_5036_50361401_53_dialog_content = "크오오오──!",
  ui_story_5036_50361401_54_dialog_content = "대체 어디서 자꾸 나오는 거지?!",
  ui_story_5036_50361401_55_dialog_content = "또 왔어, 녀석들이 또 왔어! 골디, 빨리 숨어!",
  ui_story_5036_50361401_56_dialog_content = "녀석들이 너무 많아서 숨을 곳이 없어. 그러니까 맞서 싸워야만 해!",
  ui_story_5036_50361401_57_dialog_content = "모든 걸 엉망으로 만드는 암귀 녀석들. 너희 마음대로 하게 두진 않을 거야!",
  ui_story_5036_50361402_1_dialog_content = "윽──!",
  ui_story_5036_50361402_2_dialog_content = "이런! 아무리 쓰러트려도 자꾸 나와서 끝이 안 보여!",
  ui_story_5036_50361402_3_dialog_content = "크오오!",
  ui_story_5036_50361402_4_dialog_content = "으윽!",
  ui_story_5036_50361402_5_dialog_content = "내 신경은 쓰지 말고 얼른 도망쳐! 녀석들은 조금 있으면 사라질 거야!\n그러니까 내버려 둬도 괜찮아!",
  ui_story_5036_50361402_6_dialog_content = "뭐? 사라진다구?",
  ui_story_5036_50361402_7_dialog_content = "츄우─",
  ui_story_5036_50361402_8_dialog_content = "츄우우─!",
  ui_story_5036_50361402_9_dialog_content = "저 용... 빛나고 있어?!",
  ui_story_5036_50361402_10_dialog_content = "너무 눈부셔서 앞이 안 보여!",
  ui_story_5036_50361402_11_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5036_50361402_12_dialog_content = "암귀들한테서 멀리 떨어져야 하는데... 어? 암귀들이 다 어디 갔지?",
  ui_story_5036_50361402_13_dialog_content = "암귀들은 다 사라졌어, 이제 괜찮아.",
  ui_story_5036_50361402_13X1_dialog_content = "우로보로스가 녀석들을 다 없애 줬거든!",
  ui_story_5036_50361402_13X2_dialog_content = "참, 그러고 보니까 아직 소개를 안 해 줬었네?\n저기 하늘을 날고 있는 애가 바로 우로보로스야!",
  ui_story_5036_50361402_14_dialog_content = "사라져? 설마 우로보로스가 방금 내뿜은 빛이 암귀들을 사라지게 했단 거야?",
  ui_story_5036_50361402_15_dialog_content = "아니, 우로보로스한테 그렇게 강력한 힘은 없어. 그냥 이 꿈을 재구축한 거야.",
  ui_story_5036_50361402_16_dialog_content = "그러니까 여긴 정말 꿈속이었구나!",
  ui_story_5036_50361402_17_dialog_content = "응, 여긴 우로보로스가 날 위해 만들어 준 꿈이야.",
  ui_story_5036_50361402_18_dialog_content = "네 친구가 아이테르라면, 내가 마지막에 어떤 일을 겪었는지 봤겠구나...",
  ui_story_5036_50361402_19_dialog_content = "응...",
  ui_story_5036_50361402_20_dialog_content = "내가 자기를 보호하다가 죽었다는 걸 느낀 우로보로스는 깊은 슬픔에 빠졌어.",
  ui_story_5036_50361402_21_dialog_content = "우로보로스는 내가 집으로 돌아가고 싶어 한다는 소망을 느끼곤,\n자기 꿈속에 이 헤븐즈 밸리랑 지금 골디가 보고 있는 날 만들었어.",
  ui_story_5036_50361402_22_dialog_content = "근데 이 헤븐즈 밸리의 존재를 유지하기 위해서,\n우로보로스는 긴 잠에 빠져 있어야만 하게 돼 버린 거야.",
  ui_story_5036_50361402_23_dialog_content = "그럼 방금 그 암귀들은 뭐야?",
  ui_story_5036_50361402_24_dialog_content = "내 공포야.",
  ui_story_5036_50361402_25_dialog_content = "내가 그 암귀들을 두려워하기 때문에, 녀석들이 자꾸 이 꿈에 나타나고 날 공격하는 거지.",
  ui_story_5036_50361402_26_dialog_content = "그치만 괜찮아. 우로보로스가 날 지켜 주니까.\n우로보로스가 이 꿈을 재구축해주면 저 끔찍한 암귀들이 전부 다 사라져 버리거든!",
  ui_story_5036_50361402_27_dialog_content = "어쩌면 우로보로스한테 부탁하면 골디를 꿈 밖으로 데려가 주지 않을까?",
  ui_story_5036_50361402_28_dialog_content = "좋은 생각이야! 지금 바로 가서 물어볼게.",
  ui_story_5036_50361402_29_dialog_content = "응! 참! 떠나기 전에 나랑 좀 더 얘기할 수 있을까?",
  ui_story_5036_50361402_30_dialog_content = "나도 더 이야기를 나누고 싶지만, 관객들이 내가 돌아오길 기다리고 있을 거야.",
  ui_story_5036_50361402_31_dialog_content = "길게는 안 물어볼게! 딱 하나만! 응?",
  ui_story_5036_50361402_32_dialog_content = "하나라면 당연히 문제없어! 물어봐!",
  ui_story_5036_50361402_33_dialog_content = "헤븐즈 밸리는 지금 어떻게 됐어?",
  ui_story_5036_50361402_34_dialog_content = "부탁이야! 진짜 너무 궁금해서 그래! 꼭 좀 알려줘!",
  ui_story_5036_50361402_35_dialog_content = "어? 헤븐즈 밸리?",
  ui_story_5036_50361402_36_dialog_content = "미안해... 내가 헤븐즈 밸리에는 안 가봐서...",
  ui_story_5036_50361402_37_dialog_content = "힝...",
  ui_story_5036_50361402_38_dialog_content = "그래도 너무 슬퍼하진 마! 내가 헤븐즈 밸리에 가 본 적은 없어도,\n진짜 믿음직한 아이테르 동료는 하나 있으니까!",
  ui_story_5036_50361402_39_dialog_content = "아까 말했던 그 동료?",
  ui_story_5036_50361402_40_dialog_content = "응, 걔 이름은 PlayerName인데, 정말 대단한 친구야!",
  ui_story_5036_50361402_41_dialog_content = "직접 만나기 전까진 그냥 콜로서스를 조종해서 여기저기\n여행을 다니는 아이테르라고만 들었어.",
  ui_story_5036_50361402_42_dialog_content = "여행을 하면서 여러 사람과 친구가 되고, 함께 재미있는 시간도 보내고\n암귀도 쓰러트리고 그런다고 말이야.",
  ui_story_5036_50361402_43_dialog_content = "그래서 그런 생활을 하면 고민도 없고 자유로울 것 같아서 마냥 부러워만 했었어.",
  ui_story_5036_50361402_44_dialog_content = "근데 그 애를 만나고 나서 알았어. 사실은 무척 힘든 과거가 있었다고 말이야.",
  ui_story_5036_50361402_45_dialog_content = "그 애는 다시 이 세상에 나와 친구들을 사귀기 전까진, 계속 지하에서 혼자 생활해 왔었대.",
  ui_story_5036_50361402_46_dialog_content = "하지만 유일한 아이테르로서 끊임없이 앞으로 나아가고,\n파괴됐던 헤븐즈 밸리도 재건했어.",
  ui_story_5036_50361402_47_dialog_content = "뭐?",
  ui_story_5036_50361402_48_dialog_content = "방금... 헤븐즈 밸리가 파괴됐다고 한 거야?\n게다가... 그 애가 유일한 아이테르라고...?",
  ui_story_5036_50361402_49_dialog_content = "앗! 아, 아니, 그게 아니라. 내 말은...",
  ui_story_5036_50361402_50_dialog_content = "우리 집이... 파괴돼 버린 거구나...",
  ui_story_5036_50361402_51_dialog_content = "우리 집에도... 헤븐즈 밸리에도... 이제 더는 돌아갈 수 없게 된 거야?",
  ui_story_5036_50361402_52_dialog_content = "그럴 리 없어... 어떻게 그럴 수가!",
  ui_story_5036_50361402_53_dialog_content = "<color=#e8d9bb>콰르릉!</color>",
  ui_story_5036_50361402_54_dialog_content = "<color=#e8d9bb>콰지직──!</color>",
  ui_story_5036_50361402_55_dialog_content = "꿈이 붕괴하기 시작했어! 샤미나드의 감정이 격해져서 그런 건가?",
  ui_story_5036_50361402_56_dialog_content = "샤, 샤미나드! 진정해!",
  ui_story_5036_50361402_57_dialog_content = "우리 집... 집에 가고 싶어... 흑흑!",
  ui_story_5036_50361402_58_dialog_content = "전혀 진정시킬 수가 없잖아...",
  ui_story_5036_50361402_59_dialog_content = "<color=#e8d9bb>콰르릉──!</color>",
  ui_story_5036_50361402_60_dialog_content = "츄우─ 츄우─!",
  ui_story_5036_50361402_61_dialog_content = "붕괴 범위가 너무 넓어... 게다가 재구축도 할 수 없어...",
  ui_story_5036_50361402_62_dialog_content = "어떻게 하면 좋지?\n지금부터 7을 건너 뛰고 숫자를 세도 너무 늦지 않았으려나?",
  ui_story_5036_50361402_63_dialog_content = "아니... 여기 아무것도 안 하고 가만히 서 있을 수만은 없어!\n최소한 무너져 내리고 있는 여기서 멀리 도망치기라도 해야 돼!",
  ui_story_5036_50361402_64_dialog_content = "왠지 저 탑은 튼튼할 것 같아.\n게다가 탑 꼭대기는 우로보로스가 있는 상공이랑 가깝기도 하고.",
  ui_story_5036_50361402_65_dialog_content = "샤미나드, 우리 일단 저기로... 앗!",
  ui_story_5036_50361402_66_dialog_content = "흑흑...",
  ui_story_5036_50361402_67_dialog_content = "아얏! 날 밀어낸 거야?!",
  ui_story_5036_50361402_68_dialog_content = "샤미나드? 샤미나드! 조금만 진정해!",
  ui_story_5036_50361402_69_dialog_content = "내 얘길 전혀 안 듣잖아...",
  ui_story_5036_50361402_70_dialog_content = "계속 이 상태라면 샤미나드와 이 꿈 전체가 모두 위험에 빠질 거야!",
  ui_story_5036_50361402_71_dialog_content = "어떻게든 이 꿈을 원래 상태대로 되돌릴 방법을 찾아야 해!",
  ui_story_5036_50361402_72_dialog_content = "제발 저 우로보로스가 그 방법을 알고 있었으면 좋겠는데...",
  ui_story_5036_50361402_73_dialog_content = "탑이 너무 높아서 이렇게 오래 뛰었는데도 아직 정상까지 한참 남았어!",
  ui_story_5036_50361402_74_dialog_content = "어둡고 텅 비어 있는데, 대체 뭐 하는 곳일까?",
  ui_story_5036_50361402_75_dialog_content = "...안 돼! 어둠을 두려워하면 안 돼!",
  ui_story_5036_50361402_76_dialog_content = "크오오...",
  ui_story_5036_50361402_77_dialog_content = "이젠 암귀들까지 이쪽으로 오는 거야?",
  ui_story_5036_50361402_78_dialog_content = "하긴, 이 탑은 이 꿈 전체의 중심일 테니까 붕괴가 일어나도 가장 끄떡없는 곳이겠지.",
  ui_story_5036_50361402_79_dialog_content = "그러니까 암귀라도 여기로 몸을 피하려는 거야.",
  ui_story_5036_50361402_80_dialog_content = "그렇지만 지금은 녀석들한테 쏟을 시간은 없어.\n서둘러 탑 꼭대기까지 뛰어 올라가야 해!",
  ui_story_5036_50361402_81_dialog_content = "저쪽에 빛이 보여. 출구인가?!",
  ui_story_5036_50361402_82_dialog_content = "드디어 도착했어!",
  ui_story_5036_50361402_83_dialog_content = "츄우─ 츄우─!",
  ui_story_5036_50361402_84_dialog_content = "우로보로스! 여기 좀 봐! 우로보로스!",
  ui_story_5036_50361402_85_dialog_content = "샤미나드가 진정할 수 있게, 이 꿈을 원래대로 되돌려 줘!",
  ui_story_5036_50361402_86_dialog_content = "츄우...",
  ui_story_5036_50361402_87_dialog_content = "(뭔가 곤란해 보이는데? 지금 이 상황은 우로보로스도 어쩔 수 없단 건가?)",
  ui_story_5036_50361402_88_dialog_content = "(그럼 이제 어떻게 하지?!)",
  ui_story_5036_50361402_89_dialog_content = "<color=#e8d9bb>우르르!</color>",
  ui_story_5036_50361402_90_dialog_content = "하늘까지 무너져 내리기 시작했잖아?!",
  ui_story_5036_50361402_91_dialog_content = "츄우! 츄우─!",
  ui_story_5036_50361402_92_dialog_content = "우로보로스도 엄청 고통스러워 보여...",
  ui_story_5036_50361402_93_dialog_content = "<color=#e8d9bb>쿠구구구──!</color>",
  ui_story_5036_50361402_94_dialog_content = "어어어? 탑이 무너지는 거야?!",
  ui_story_5036_50361402_95_dialog_content = "으아아악──!",
  ui_story_5036_50361402_96_dialog_content = "골디! 얼른 내 손을 잡아!",
  ui_story_5036_50361402_97_dialog_content = "PlayerName?!",
  ui_story_5036_50361402_98_dialog_content = "당신이 어떻게 여기 있어?!",
  ui_story_5036_50361402_99_dialog_content = "비크 씨랑 같이 있다가 우로보로스의 알이 뭔가 심상치 않길래,\n무대 쪽에 문제가 생기진 않을까 해서 확인하러 왔어!",
  ui_story_5036_50361402_100_dialog_content = "근데 보니까 다들 잠들어 있더라고!\n게다가 넌 우로보로스의 알의 루미나틱스에 영향을 받은 것 같아 보였어!",
  ui_story_5036_50361402_101_dialog_content = "우로보로스의 알에 문제가 생긴 거야? 갑자기 왜?!",
  ui_story_5036_50361402_102_dialog_content = "골디 씨의 노래를 들어서 그런 걸지도 몰라!",
  ui_story_5036_50361402_103_dialog_content = "콜로서스를 기동하는 데 사용하는 선율로 노래를 만든 거니까,\n우로보로스한테는 알람 소리처럼 들렸을 수도 있어!",
  ui_story_5036_50361402_104_dialog_content = "뭐?!",
  ui_story_5036_50361402_105_dialog_content = "계속 이렇게 잡담하고 있다간 내 손이 풀려버릴지도 몰라~",
  ui_story_5036_50361402_106_dialog_content = "좀 버텨 봐!",
  ui_story_5036_50361402_107_dialog_content = "하하하, 내가 그렇게 못 미더운 어른이야?",
  ui_story_5036_50361402_108_dialog_content = "자, 그럼 우리가 골디 씨를 여기서 꺼내자!",
  ui_story_5036_50361402_109_dialog_content = "골디! 꽉 잡아!",
  ui_story_5036_50361402_110_dialog_content = "으앗!",
  ui_story_5036_50361402_111_dialog_content = "깨, 깨어났네?!",
  ui_story_5036_50361402_112_dialog_content = "몸은 좀 괜찮아?",
  ui_story_5036_50361402_113_dialog_content = "머리가 좀 어지러운 거 빼곤 괜찮아...",
  ui_story_5036_50361402_114_dialog_content = "정직원 전환이라니... 드디어 내가 정직원이... 어라? 꾸, 꿈이었네?",
  ui_story_5036_50361402_115_dialog_content = "으... 나 뭐가 어떻게 된 거지?",
  ui_story_5036_50361402_116_dialog_content = "잠들었던 건가? 머리가 깨질 것 같아.",
  ui_story_5036_50361402_117_dialog_content = "하암~ 좋은 아침? 아니지, 좋은 저녁인가?",
  ui_story_5036_50361402_118_dialog_content = "내가 관객석에서 잠들었던 건가?!\n돌아가고 나면 이 옷은 제대로 깨끗하게 씻어야겠어...",
  ui_story_5036_50361402_119_dialog_content = "호오, 다들 정신을 차린 것 같네.",
  ui_story_5036_50361402_120_dialog_content = "꿈의 영역이 원래대로 돌아가서 그런 걸까?",
  ui_story_5036_50361402_121_dialog_content = "아니, 그게 아니라...",
  ui_story_5036_50361402_122_dialog_content = "우로보로스가 곧 부화하려고 하니까 그런 거야.",
  ui_story_5036_50361501_1_dialog_content = "<color=#e8d9bb>움브라톤, 골드리버 강변</color>",
  ui_story_5036_50361501_2_dialog_content = "어이, 대체 뭐가 어떻게 된 거야? 왜 가수가 노래를 부르다가 잠들어 버리는 건데?",
  ui_story_5036_50361501_3_dialog_content = "누나한테 무슨 일이 있는 건 아니겠지?",
  ui_story_5036_50361501_4_dialog_content = "저 언니는 강하니까 분명히 괜찮을 거야!",
  ui_story_5036_50361501_5_dialog_content = "근데 갑자기 무대에 나타난 저 두 녀석은 뭐 하는 거야?",
  ui_story_5036_50361501_6_dialog_content = "뭐 이런 어처구니없는 경우가 다 있어. 시간만 버렸네, 가자.",
  ui_story_5036_50361501_7_dialog_content = "조금만 더 지켜보는 건 어떨까요?",
  ui_story_5036_50361501_8_dialog_content = "그렇게 서둘러 결론을 내릴 필요는 없잖아요. 저건... 다 계획된 연출이거든요.",
  ui_story_5036_50361501_9_dialog_content = "네?",
  ui_story_5036_50361501_10_dialog_content = "저건 저희 쪽에서 특별히 준비한 코너예요.\n그냥 춤만 추고 노래만 하면 좀 지루할 수 있으니까요.",
  ui_story_5036_50361501_11_dialog_content = "그래서 관객들을 깜짝 놀라게 해 주려고 공연 외에 다른 볼거리도 준비한 거예요.",
  ui_story_5036_50361501_12_dialog_content = "그러니까 다들 참을성 있게 봐 줬으면 좋겠어요. 다 보고 나면 모두 만족할 거예요.",
  ui_story_5036_50361501_13_dialog_content = "그러죠, 뭐. 한 번 정돈 믿어볼게요.",
  ui_story_5036_50361501_14_dialog_content = "고마워요! 여러분의 신뢰에 대한 감사의 뜻으로 음료와 간식을 준비했어요.",
  ui_story_5036_50361501_15_dialog_content = "부디 즐거운 마음으로 받아 주길 바랄게요.",
  ui_story_5036_50361501_16_dialog_content = "(어떻게든 관객들이 동요하지 않게 붙들어 두긴 했지만...)",
  ui_story_5036_50361501_17_dialog_content = "(골디, 거기서 대체 무슨 일이 벌어지고 있는 거니?)",
  ui_story_5036_50361501_18_dialog_content = "(그리고 저 콜로서스에 있는 PlayerName 일행도... 부디 무사해야 할 텐데...)",
  ui_story_5036_50361501_19_dialog_content = "<color=#e8d9bb>같은 시간, 칸타토르호 안</color>",
  ui_story_5036_50361501_20_dialog_content = "지금 뭐라고 했어? 우로보로스가 곧 부화한다구?!",
  ui_story_5036_50361501_21_dialog_content = "갑작스럽게 일어난 일이라, 자세히 설명해 줄 시간은 없어.",
  ui_story_5036_50361501_22_dialog_content = "아무튼 우로보로스가 부화하면 이 콜로서스 전체의 균형이 무너져서 엄청 위험해져.",
  ui_story_5036_50361501_23_dialog_content = "지금 이 상황에서 가장 먼저 해야 할 건 모두를 여기서 떠나게 하는 거야.",
  ui_story_5036_50361501_24_dialog_content = "게다가 최대한 빨리 말이야. 그렇지 않으면... 아, 이미 늦었나 보네.",
  ui_story_5036_50361501_25_dialog_content = "크오오──!",
  ui_story_5036_50361501_26_dialog_content = "콜로서스 안에서 암귀가 몰려오고 있잖아?!",
  ui_story_5036_50361501_27_dialog_content = "모두 정신 차려! 최대한 빨리 방어 대형을 구축해!",
  ui_story_5036_50361501_28_dialog_content = "예!",
  ui_story_5036_50361501_29_dialog_content = "크어어!",
  ui_story_5036_50361501_30_dialog_content = "어딜 감히!",
  ui_story_5036_50361501_31_dialog_content = "젠장! 더러운 것들이 계속 늘어나고 있잖아!",
  ui_story_5036_50361501_32_dialog_content = "방어가 더 급해. 쓸데없는 데 신경 쓰지 마.",
  ui_story_5036_50361501_33_dialog_content = "말 안 해도 안다고!",
  ui_story_5036_50361501_34_dialog_content = "<color=#e8d9bb>쿠르릉...</color>",
  ui_story_5036_50361501_35_dialog_content = "콜로서스 전체가 흔들리고 있잖아?\n최종 보스가 등장할 때 쓰는 연출이랑 완전 똑같아!",
  ui_story_5036_50361501_36_dialog_content = "여러분, 모두 넘어지지 않게 잘 붙잡으세요! 콜로서스 안에 뭔가 있어요!",
  ui_story_5036_50361501_37_dialog_content = "츄우우─!",
  ui_story_5036_50361501_38_dialog_content = "엄청나게 커다란 용이야!",
  ui_story_5036_50361501_39_dialog_content = "정말 부화했잖아!",
  ui_story_5036_50361501_40_dialog_content = "크오오!",
  ui_story_5036_50361501_41_dialog_content = "저 암귀들이 우로보로스를 공격하기 시작하는데?!",
  ui_story_5036_50361501_42_dialog_content = "츄우─ 츄우─!",
  ui_story_5036_50361501_43_dialog_content = "누나! 콜로서스 위를 봐!",
  ui_story_5036_50361501_44_dialog_content = "콜로서스 위에... 용이 나타났잖아?!",
  ui_story_5036_50361501_45_dialog_content = "앗! 콜로서스가 금방이라도 떨어질 것처럼 막 흔들리고 있어!",
  ui_story_5036_50361501_46_dialog_content = "<color=#e8d9bb>쿠구구구!</color>",
  ui_story_5036_50361501_47_dialog_content = "아차! 우로보로스는 방금 막 알에서 나온 상태라 아직 못 날아!",
  ui_story_5036_50361501_48_dialog_content = "이대로 계속 암귀한테 공격받았다간 지금보다 훨씬 더 격렬하게 버둥댈 거야!",
  ui_story_5036_50361501_49_dialog_content = "우로보로스를 진정시키려면 어떻게 해야 하는데?",
  ui_story_5036_50361501_50_dialog_content = "감응 능력이라면 가능하지 않을까?",
  ui_story_5036_50361501_51_dialog_content = "해볼게!",
  ui_story_5036_50361501_52_option_content = "「우로보로스! 멈춰!」",
  ui_story_5036_50361501_53_dialog_content = "츄우─!",
  ui_story_5036_50361501_54_dialog_content = "<color=#e8d9bb>콰아아앙!</color>",
  ui_story_5036_50361501_55_dialog_content = "으악!",
  ui_story_5036_50361501_56_dialog_content = "안 돼, 내 말을 전혀 안 들어!",
  ui_story_5036_50361501_57_dialog_content = "무대가... 암귀들한테 포위당했어.",
  ui_story_5036_50361501_58_dialog_content = "콘서트가... 전부 엉망이 돼 버렸어...",
  ui_story_5036_50361501_59_dialog_content = "골디, 아직도 많이 위험한 상태야! 지금은 기운을 내야 해!",
  ui_story_5036_50361501_60_dialog_content = "나도 알아, 아는데...",
  ui_story_5036_50361501_61_dialog_content = "머뭇거릴 시간 없어.\n모두 대형을 다시 갖추고, 최대한 암귀가 저 용에 접근하지 못하게 해!",
  ui_story_5036_50361501_62_dialog_content = "예!",
  ui_story_5036_50361501_63_dialog_content = "우리 일루미나도 질 수 없지! 보스전 시작이야!",
  ui_story_5036_50361501_64_dialog_content = "예!",
  ui_story_5036_50361501_65_dialog_content = "바이스, PlayerName. 두 사람은 일반인들을 데리고 전투 구역에서 멀리 이탈해.",
  ui_story_5036_50361501_66_dialog_content = "그리고 스카이워커호와 백야성의 비공정에 연락해서,\n사람들을 여기서 대피시키는 작업을 지원해 달라고 전해 줘!",
  ui_story_5036_50361501_67_dialog_content = "응, 맡겨 줘!",
  ui_story_5036_50361501_68_dialog_content = "응!",
  ui_story_5036_50361501_69_dialog_content = "백야성의 기사님은 역시 결정적인 순간에 가장 믿음직하네!",
  ui_story_5036_50361501_70_dialog_content = "당신도 가만히 있지 말고 어떻게든 저 용을 진정시킬 방법을 생각해 내.",
  ui_story_5036_50361501_71_dialog_content = "난 빼 줘~ 싸우는 건 잘 못한단 말이야...",
  ui_story_5036_50361501_72_dialog_content = "당신 정말... 휴, 그럼 사람들과 같이 대피하도록 해.",
  ui_story_5036_50361501_73_dialog_content = "맡겨 줘! 얌전히 잘 대피할게!",
  ui_story_5036_50361501_74_dialog_content = "다들 이쪽으로 오세요!",
  ui_story_5036_50361501_75_dialog_content = "PlayerName, 스카이워커호는 어때?",
  ui_story_5036_50361501_76_dialog_content = "우로보로스가 너무 심하게 날뛰고 있어서 가까이 접근할 수가 없어!",
  ui_story_5036_50361501_77_dialog_content = "진짜 아주 잠깐이라도 좋으니까, 우로보로스가 좀 얌전히 있어 준다면...",
  ui_story_5036_50361501_78_dialog_content = "당분간은 달랠 방법이 없어 보이는걸.",
  ui_story_5036_50361501_79_dialog_content = "백야성의 비공정은?",
  ui_story_5036_50361501_80_dialog_content = "물론 네가 말하지 않아도 벌써 연락해 뒀지.",
  ui_story_5036_50361501_81_dialog_content = "비공정을 타고 콘서트를 보러 온 귀족들이 몇 있었는데,\n그중 몇 척은 벌써 구조에 투입된 상태다.",
  ui_story_5036_50361501_82_dialog_content = "성주님께서도 이미 백야성 전체의 비공정을 징집하고 계신다.\n하지만 시간은 좀 걸리겠지.",
  ui_story_5036_50361501_83_dialog_content = "게다가 백야성의 비공정은 대부분이 소형이라,\n이렇게 많은 인원을 이동시키려면 몇 번 가지고는 턱도 없을 거다.",
  ui_story_5036_50361501_84_dialog_content = "그럼 더더욱 시간을 벌어야겠네.",
  ui_story_5036_50361501_85_dialog_content = "으윽──!",
  ui_story_5036_50361501_X85_dialog_content = "버텨야 해!",
  ui_story_5036_50361501_87_dialog_content = "<color=#e8d9bb>덜커덩──!</color>",
  ui_story_5036_50361501_88_dialog_content = "카렌 님! 암귀가 너무 많아서 방어선이 더는 버틸 수 없습니다!",
  ui_story_5036_50361501_89_dialog_content = "으앗! 백야성 여러분~ 우리 여기서 좀 멀리 떨어져 있는 게 좋겠어!",
  ui_story_5036_50361501_90_dialog_content = "이 용이 심하게 날뛰고 있는 것도 있지만, 이 콜로서스가 낡고 오래돼서...",
  ui_story_5036_50361501_91_dialog_content = "이곳저곳의 부품이 진동을 못 버티고 부서지기 시작했거든!",
  ui_story_5036_50361501_92_dialog_content = "비공정 쪽 상황은?",
  ui_story_5036_50361501_93_dialog_content = "보고드립니다! 스카이워커호는 접근이 어렵다고 합니다.\n대신 백야성의 비공정은 이미 이곳으로 이동 중입니다!",
  ui_story_5036_50361501_94_dialog_content = "어쩔 수 없지. 모두에게 알린다! 방어선을 최소한으로 축소하고,\n우로보로스 보호를 잠시 포기한다! 지금부터는 사람들을 한곳에 모으도록!",
  ui_story_5036_50361501_95_dialog_content = "예!",
  ui_story_5036_50361501_96_dialog_content = "카렌!",
  ui_story_5036_50361501_97_dialog_content = "난 괜찮아. 다들 모였어?",
  ui_story_5036_50361501_98_dialog_content = "카렌 전하께 보고드립니다. 사람들은 모두 여기 모였습니다!",
  ui_story_5036_50361501_99_dialog_content = "첫 비공정 선단도 이미 도착한 상태로, 모두 질서정연하게 대피하는 중입니다만...",
  ui_story_5036_50361501_100_dialog_content = "시간이 더 필요합니다.",
  ui_story_5036_50361501_101_dialog_content = "비공정은 작고, 사람은 많으니까요.",
  ui_story_5036_50361501_102_dialog_content = "내가 최대한 시간을 벌겠어.",
  ui_story_5036_50361501_103_dialog_content = "하지만 서둘러야 해! 이 콜로서스는 언제라도 전복될 수 있으니까!",
  ui_story_5036_50361501_104_dialog_content = "......",
  ui_story_5036_50361501_105_dialog_content = "골디, 너 괜찮아?",
  ui_story_5036_50361501_106_dialog_content = "이젠 괜찮아. 콘서트는 실패했지만 말이야...",
  ui_story_5036_50361501_107_dialog_content = "하지만 난 팬들을 지켜야 돼. 내 콘서트 때문에 팬들이 다치게 만들 순 없으니까.",
  ui_story_5036_50361501_108_dialog_content = "설령... 이게 내 마지막 콘서트가 된다 해도 말이야!",
  ui_story_5036_50361501_109_dialog_content = "응! 그럼 일단 눈앞에 있는 문제부터 해결하자!",
  ui_story_5036_50361501_110_dialog_content = "참, 비크 씨. 우로보로스 말인데,\n진짜로 진정시킬 방법이 아무것도 없... 비크 씨?",
  ui_story_5036_50361501_111_dialog_content = "또 어디로 가 버린 거야?",
  ui_story_5036_50361501_112_dialog_content = "아까 너희와 같이 대피한 거 아니었어?",
  ui_story_5036_50361501_113_dialog_content = "계속 따라오고 있는 줄 알고 신경 안 썼는데!",
  ui_story_5036_50361501_114_dialog_content = "으아... 역시 난 전투엔 영 재능이 없다니까.",
  ui_story_5036_50361501_115_dialog_content = "뭔가 비크 씨 목소리 같은 게 들린 것 같은데?",
  ui_story_5036_50361501_116_dialog_content = "저기 있어!",
  ui_story_5036_50361501_117_dialog_content = "그래도 환상동물 마스터로서 어느 정도는 전문가다운 모습을 보여 줘야겠지.",
  ui_story_5036_50361501_118_dialog_content = "근데 왜 혼자 저기 있는 거야?",
  ui_story_5036_50361501_119_dialog_content = "거긴 위험해! 어서 돌아와!",
  ui_story_5036_50361501_120_dialog_content = "신경 써 줘서 정말 고마워. 하지만 지금은 안 돼.",
  ui_story_5036_50361501_121_dialog_content = "거기 있는 시커먼 녀석들! 여기 좀 봐!",
  ui_story_5036_50361501_122_dialog_content = "뀨우, 우우──!",
  ui_story_5036_50361501_123_dialog_content = "크오오...",
  ui_story_5036_50361501_124_dialog_content = "그래, 바로 그거야...",
  ui_story_5036_50361501_125_dialog_content = "여기 반격은 꿈도 못 꾸는 수준의 오로리안이 있어.\n우로보로스보다 훨씬 쉬운 상대지.",
  ui_story_5036_50361501_126_dialog_content = "(조금만 더 이쪽으로 오게 만들어서, 우로보로스한테서 떨어지게 해야 돼.)",
  ui_story_5036_50361501_127_dialog_content = "(가골빼미의 능력이라면 이 암귀들을 잠재워서 충분히 시간을 끌 수 있을 거야.)",
  ui_story_5036_50361501_128_option_content = "비크 씨! 얼른 돌아와!",
  ui_story_5036_50361501_129_dialog_content = "하하하, 괜찮아! 전혀 문제없어! 걱정하지 마.",
  ui_story_5036_50361501_130_dialog_content = "최고의 환상동물 마스터라면...\n환상동물 동료들을 믿고 목숨을 맡길 수 있거든!",
  ui_story_5036_50361501_131_dialog_content = "크오오오──!",
  ui_story_5036_50361501_132_dialog_content = "(좋아! 걸려들었어)",
  ui_story_5036_50361501_133_dialog_content = "(이제 가골빼미만 부르면 돼!)",
  ui_story_5036_50361501_134_dialog_content = "가골빼미!",
  ui_story_5036_50361501_135_dialog_content = "구──구구!",
  ui_story_5036_50361501_136_dialog_content = "가골빼미? 왜 도망치는 거야?! 도망치면 안 되지!",
  ui_story_5036_50361501_137_dialog_content = "<color=#e8d9bb>콰르릉!</color>",
  ui_story_5036_50361501_138_dialog_content = "츄우─!",
  ui_story_5036_50361501_139_dialog_content = "뭐야?!",
  ui_story_5036_50361501_140_dialog_content = "<color=#e8d9bb>부웅──!</color>",
  ui_story_5036_50361501_141_dialog_content = "비크 씨?!",
  ui_story_5036_50361501_142_dialog_content = "아파아아아아!",
  ui_story_5036_50361501_143_dialog_content = "(당황한 우로보로스가 꼬리를 휘둘러서 비크 씨를 날려 버렸어!\n잠깐만, 저 위치는...!)",
  ui_story_5036_50361501_144_dialog_content = "비크 씨! 빨리 도망쳐!",
  ui_story_5036_50361501_145_dialog_content = "쳇, 이 용은 적당히라는 걸 전혀 모르는 녀석이구만.",
  ui_story_5036_50361501_146_dialog_content = "PlayerName, 방금 뭐라고? 못 들었어.",
  ui_story_5036_50361501_147_dialog_content = "크오오!",
  ui_story_5036_50361501_148_dialog_content = "아이고... 포, 포위당해 버렸네?!",
  ui_story_5036_50361501_149_dialog_content = "암귀 여러분, 난 이미 늙었어! 나이 많은 사람 고기는 맛이 없다고!",
  ui_story_5036_50361501_150_dialog_content = "저기, 저 아이테르 좀 봐. 쟤는 젊어서 살도 야들야들해. 나보다 훨씬 맛있을걸!",
  ui_story_5036_50361501_151_dialog_content = "크오오!",
  ui_story_5036_50361501_152_dialog_content = "타래! 나 좀 살려 줘!!!",
  ui_story_5036_50361501_153_dialog_content = "PlayerName!!!",
  ui_story_5036_50361502_1_dialog_content = "다행이야... 어떻게든 살았네!",
  ui_story_5036_50361502_2_dialog_content = "암귀의 주의를 끌겠다는 작전은 완전히 실패해 버렸지만 말이야.",
  ui_story_5036_50361502_3_dialog_content = "지금 웃음이 나와?!",
  ui_story_5036_50361502_4_dialog_content = "계획이 있었으면, 저지르기 전에 모두랑 상의부터 해야 할 거 아냐!",
  ui_story_5036_50361502_5_dialog_content = "미안, 미안. 우로보로스만 너무 걱정하느라 미리 얘기하는 걸 깜빡했지 뭐야.",
  ui_story_5036_50361502_6_dialog_content = "우로보로스가 갑자기 날 꼬리로 날려 버리지만 않았어도 계획은 성공했을 거야~",
  ui_story_5036_50361502_7_dialog_content = "아무튼 지금 중요한 건 그게 아니야!",
  ui_story_5036_50361502_8_dialog_content = "우로보로스를 진정시킬 다른 방법은 없어?",
  ui_story_5036_50361502_9_dialog_content = "안타깝지만 모든 암귀를 쓰러트리는 거 말곤, 나도 뾰족한 수가 없어.",
  ui_story_5036_50361502_10_dialog_content = "우로보로스가 날 수 있을 때까지 가만히 내버려 뒀다가,\n스스로 날아가게 만드는 건 어떨까?",
  ui_story_5036_50361502_11_dialog_content = "그렇게 낙관적인 상황은 아니야. 암귀의 공세가 너무 강해.",
  ui_story_5036_50361502_12_dialog_content = "저대로 내버려 두면, 나중에 비행 능력이 생긴다고 해도,\n그때쯤이면 온몸에 중상을 입어서 날고 싶어도 못 날게 될걸.",
  ui_story_5036_50361502_13_dialog_content = "그럴 수가...",
  ui_story_5036_50361502_14_dialog_content = "카렌 전하, 성주님께서 지시를 내리셨습니다.",
  ui_story_5036_50361502_15_dialog_content = "말해.",
  ui_story_5036_50361502_16_dialog_content = "대피 작업 쪽은 이미 막바지 상태이며, 백야성과 일루미나의 상부 역시\n이 콜로서스의 위험성에 대해 평가를 끝마쳤다고 합니다.",
  ui_story_5036_50361502_17_dialog_content = "상부에서 내린 결정은 우선 병사들이 이곳에 남아 암귀를 저지하고,\n최대한 저 용을 진정시켜 콜로서스의 안정을 유지하는 겁니다.",
  ui_story_5036_50361502_18_dialog_content = "그리고 콜로서스가 움브라톤을 벗어날 때까지 기다린 후에,\n이 콜로서스를 격추할 겁니다.",
  ui_story_5036_50361502_19_dialog_content = "이 콜로서스랑 우로보로스를 같이 없애 버리겠다는 소리야? 그건 안 돼!",
  ui_story_5036_50361502_20_dialog_content = "이 우로보로스는 이 세상에 딱 하나 남은 개체일 수도 있어.\n이 녀석이 죽으면 우로보로스라는 종 자체가 이 세상에서 멸종될지도 몰라.",
  ui_story_5036_50361502_21_dialog_content = "나도 칸타토르호를 잃고 싶진 않아!",
  ui_story_5036_50361502_22_dialog_content = "그렇다면 뜬구름 잡는 소리만 해대지 말고, 더 좋은 방법을 제시하지 그래?",
  ui_story_5036_50361502_23_dialog_content = "이 콜로서스 바로 아래에는 움브라톤에서 가장 큰 번화가가 있다.\n수많은 오로리안의 생명 따윈 안중에도 없는 모양이지?",
  ui_story_5036_50361502_24_dialog_content = "내가 이 콜로서스에서 끝까지 떠나지 않겠다고 하면 어쩔 건데?",
  ui_story_5036_50361502_25_dialog_content = "비크 씨, 설마...",
  ui_story_5036_50361502_26_dialog_content = "난 환상동물 마스터야. 그러니까 이 우로보로스를 이렇게 방치할 순 없어.",
  ui_story_5036_50361502_27_dialog_content = "만약 이 콜로서스를 격추하겠다면 그렇게 해. 나랑 같이 날려 버리면 되겠네~",
  ui_story_5036_50361502_28_dialog_content = "비크 씨?! 그건 너무 위험해!",
  ui_story_5036_50361502_29_dialog_content = "이 자식! 멋대로 굴지 마라!",
  ui_story_5036_50361502_30_dialog_content = "(어떻게 해야 하지? 어떻게 해야 우로보로스랑 콜로서스 둘 다 구할 수 있을까...)",
  ui_story_5036_50361502_31_dialog_content = "(분명히 뭔가 방법이 있을 텐데...)",
  ui_story_5036_50361502_32_dialog_content = "이 설비들이라면 내 노래가 지면에 있는 관객들의 귀까지 100% 전해질 거야~",
  ui_story_5036_50361502_33_dialog_content = "아이테르가 콜로서스를 조종할 때 사용하는 선율로\n이런 생명체와 교류할 수 있다니, 정말 놀랍군요.",
  ui_story_5036_50361502_34_dialog_content = "콜로서스를 기동하는 데 사용하는 선율로 노래를 만든 거니까,\n우로보로스한테는 알람 소리처럼 들렸을 수도 있어!",
  ui_story_5036_50361502_35_dialog_content = "방법이 하나 있어! 한번 해 보고 싶어!",
  ui_story_5036_50361502_36_dialog_content = "뭐?",
  ui_story_5036_50361502_37_dialog_content = "무슨 방법인데?",
  ui_story_5036_50361502_38_dialog_content = "샤미나드는 아이테르가 콜로서스를 조종할 때 쓰는 선율을\n우로보로스가 알아듣는다는 걸 발견했었어.",
  ui_story_5036_50361502_39_dialog_content = "그러니까 콜로서스의 작동을 멈추는 선율을 우로보로스한테 들려주면서,\n암귀를 막으면 우로보로스가 안정을 찾을 수 있을지도 몰라!",
  ui_story_5036_50361502_40_dialog_content = "오? 왠지 좋은 아이디어 같은데? PlayerName!",
  ui_story_5036_50361502_41_dialog_content = "PlayerName의 감응 능력도 우로보로스한텐 소용이 없었는데,\n노래로 정말 효과가 있을까?",
  ui_story_5036_50361502_42_dialog_content = "음... 소리가 충분히 크면 우로보로스도 주의를 기울일 거야.",
  ui_story_5036_50361502_43_dialog_content = "아무래도 무대에 있는 음향 장비를 써야 할 것 같아.",
  ui_story_5036_50361502_44_dialog_content = "응, 골디의 루미나틱스랑 음향 장비만 있으면 분명히 할 수 있을 거야!",
  ui_story_5036_50361502_45_dialog_content = "나?",
  ui_story_5036_50361502_46_dialog_content = "......",
  ui_story_5036_50361502_47_dialog_content = "알겠어.",
  ui_story_5036_50361502_48_dialog_content = "내 콘서트는 아직 끝나지 않았어. 아직 노래를 끝까지 부르지 못했으니까.",
  ui_story_5036_50361502_49_dialog_content = "앞으로 아이돌로서 무대에 오를 수 없게 되더라도, 당신이랑 내 팬들이 있어 준다면...",
  ui_story_5036_50361502_50_dialog_content = "모두가 날 필요하다고 생각해 주는 한, 난 계속 노래를 부를 거야.",
  ui_story_5036_50361502_51_dialog_content = "게다가 이 콜로서스 아래에 있는 건 움브라톤이야. 나랑 내 팬들의 고향이라고.",
  ui_story_5036_50361502_52_dialog_content = "PlayerName, 이 방법이 성공할지 얼마나 확신해?",
  ui_story_5036_50361502_53_option_content = "100% 확신하는 건 아니야...",
  ui_story_5036_50361502_54_option_content = "시도는 해 봐야지!",
  ui_story_5036_50361502_55_dialog_content = "알겠어.",
  ui_story_5036_50361502_56_dialog_content = "내가 도와줄게.",
  ui_story_5036_50361502_57_dialog_content = "카렌 전하?! 지금 진심으로 하시는 말씀입니까?!",
  ui_story_5036_50361502_58_dialog_content = "당연히 진심이야. 하지만 실패한 뒤에 필요한 후속 조치도 준비할 거야.",
  ui_story_5036_50361502_59_dialog_content = "모두에게 알린다! 전투 준비!",
  ui_story_5036_50361502_60_dialog_content = "...알겠습니다. 기사들이여! 대형을 갖춰라!",
  ui_story_5036_50361502_61_dialog_content = "카렌, 정말 고마워!",
  ui_story_5036_50361502_62_dialog_content = "나도 같이 도울 거야!",
  ui_story_5036_50361502_63_dialog_content = "근데 음향 장비 담당 스태프는 아까 비공정을 타고 대피한 것 같던데?",
  ui_story_5036_50361502_64_dialog_content = "나도 아직 여기 있다는 거 까먹지 마! 장비 쪽은 걱정 안 해도 돼.",
  ui_story_5036_50361502_65_dialog_content = "개조를 좀 하긴 했지만 사용 방법은 별 차이 없을 거예요. 그러니까 저희한테 맡겨요.",
  ui_story_5036_50361502_66_dialog_content = "그로누? 시오반 씨?!",
  ui_story_5036_50361502_67_dialog_content = "PlayerName, 너 지금 슈퍼 극악 난이도 업적에 도전하러 가는 거지?",
  ui_story_5036_50361502_68_dialog_content = "그렇게 재미있는 일에는 나도 당연히 끼워 줘야지!",
  ui_story_5036_50361502_69_dialog_content = "저, 저도요!",
  ui_story_5036_50361502_70_dialog_content = "며칠간 했던 인터뷰 중에는 무대 음향을 다루는 스태프들도 있었거든요.",
  ui_story_5036_50361502_71_dialog_content = "그러면서 음향 장비를 다루는 법도 조금 배웠어요!",
  ui_story_5036_50361502_72_dialog_content = "정말 위험해 보이긴 하지만, 저도 데리고 가 주세요!\n최선을 다해 두 사람의 힘이 되어 드릴게요!",
  ui_story_5036_50361502_73_dialog_content = "다들 고마워...",
  ui_story_5036_50361502_74_dialog_content = "모두를 한마음으로 만드는 건 쉬운 일이 아닌데. 대단한걸, PlayerName.",
  ui_story_5036_50361502_75_dialog_content = "이런 능력이 있었다니. 역시 아이테르라는 이름의 환상동물이란 건가?",
  ui_story_5036_50361502_76_dialog_content = "잠깐만! 난 환상동물이 아니거든!",
  ui_story_5036_50361502_77_dialog_content = "하하하, 논쟁은 거절할게.",
  ui_story_5036_50361502_78_dialog_content = "시간이 촉박하니까 얼른 가서 우로보로스를 구하자!",
  ui_story_5036_50361502_79_dialog_content = "응, 그럼 무대를 향해, 출발!",
  ui_story_5036_50361601_1_dialog_content = "골디, 아까 내가 가르쳐 준 멜로디 아직 기억하고 있지?",
  ui_story_5036_50361601_2_dialog_content = "물론이지! 아주 잘 기억하고 있어!",
  ui_story_5036_50361601_3_dialog_content = "근데 무대까지 가는 길에 암귀가 너무 많아...",
  ui_story_5036_50361601_4_dialog_content = "녀석들한테 신경 쓸 필요 없어. 내가 사람들을 데리고 무대로 향하는 길을 열어 줄게.",
  ui_story_5036_50361601_5_dialog_content = "맞아, 전투 쪽은 우리한테 맡기고 골디 씨는 노래에만 집중해!",
  ui_story_5036_50361601_6_dialog_content = "음~ 난 싸움에 전혀 도움이 안 되겠지만, 타래한테 두 사람을 도와주라고 할게.",
  ui_story_5036_50361601_7_dialog_content = "뀨우!",
  ui_story_5036_50361601_8_dialog_content = "선뜻 도와주겠다고 해 줘서 고마워, 골디.",
  ui_story_5036_50361601_9_dialog_content = "나한테 고마워하지 않아도 돼.",
  ui_story_5036_50361601_10_dialog_content = "며칠 동안 PlayerName 씨한테 계속 도움만 받았는걸.",
  ui_story_5036_50361601_11_dialog_content = "PlayerName 씨의 노력이 없었다면, 이번 콘서트는 개최할 수 없었을 거야.",
  ui_story_5036_50361601_12_dialog_content = "하지만, 콘서트는 실패해 버렸잖아...",
  ui_story_5036_50361601_13_dialog_content = "그래도 이번 콘서트를 위해 PlayerName 씨가 해 준 노력은 내가 다 봤으니까!",
  ui_story_5036_50361601_14_dialog_content = "설령 콘서트가 실패했다고 해도, 그 노력들은 사라지지 않아.",
  ui_story_5036_50361601_15_dialog_content = "그러니까 이제는 내가 그 보답을 할 때야!",
  ui_story_5036_50361601_16_dialog_content = "응!",
  ui_story_5036_50361601_17_dialog_content = "그럼, 출발하자!",
  ui_story_5036_50361601_18_dialog_content = "크오오──!",
  ui_story_5036_50361601_19_dialog_content = "암귀가 오고 있어! 모두 전투 준비!",
  ui_story_5036_50361602_1_dialog_content = "드디어 무대에 도착했어. 음향 장비는?",
  ui_story_5036_50361602_2_dialog_content = "문제없어요!",
  ui_story_5036_50361602_3_dialog_content = "음향 최대 출력──!",
  ui_story_5036_50361602_4_dialog_content = "크오오오──!",
  ui_story_5036_50361602_5_dialog_content = "꺄앗?!",
  ui_story_5036_50361602_6_dialog_content = "에잇!",
  ui_story_5036_50361602_7_dialog_content = "고, 고마워요!",
  ui_story_5036_50361602_8_dialog_content = "이런 걸로 뭘!",
  ui_story_5036_50361602_9_dialog_content = "암귀는 우리한테 맡기고 장비 조작에 집중해 줘!",
  ui_story_5036_50361602_10_dialog_content = "우리가 이곳을 지키고 있는 한, 암귀는 단 한 마리도 지나가게 하지 않을 거야.",
  ui_story_5036_50361602_11_dialog_content = "크오오!",
  ui_story_5036_50361602_12_dialog_content = "어딜 도망쳐!",
  ui_story_5036_50361602_13_dialog_content = "이때야, 타래! 녀석의 등 뒤를 공격해!",
  ui_story_5036_50361602_14_dialog_content = "뀨우!",
  ui_story_5036_50361602_15_dialog_content = "그어어!",
  ui_story_5036_50361602_16_dialog_content = "이런, 뛰는 게 나보다도 빠르잖아. 타래가 따라잡는 건 무리겠어.",
  ui_story_5036_50361602_17_dialog_content = "요리조리 도망 다녀서 상대하기가 쉽지 않아!",
  ui_story_5036_50361602_18_dialog_content = "조금만 버텨 줘. 최소한 골디가 노래를 부를 때만큼은 녀석들이 방해하지 못하게 해야 돼.",
  ui_story_5036_50361602_19_dialog_content = "응!",
  ui_story_5036_50361602_20_dialog_content = "(모두가 열심히 싸우고 있으니까, 나도 내가 해야 할 일을 해야지.)",
  ui_story_5036_50361602_21_dialog_content = "츄우─ 츄우─!",
  ui_story_5036_50361602_22_dialog_content = "<color=#e8d9bb>쿠구구구──!</color>",
  ui_story_5036_50361602_23_dialog_content = "우로보로스, 너도 많이 괴롭겠지...",
  ui_story_5036_50361602_24_dialog_content = "하지만 조금만 참아. 조금만 참으면 우리가 널 확실하게 지켜줄 테니까.",
  ui_story_5036_50361602_25_dialog_content = "여러분, 그럼 이제 노래를 시작할게!",
  ui_story_5036_50361602_26_dialog_content = "네!",
  ui_story_5036_50361602_27_dialog_content = "(침착하자, 골디.)",
  ui_story_5036_50361602_28_dialog_content = "(이 노래로 우로보로스의 공포를 다스려서, 진정할 수 있도록 만드는 거야.)",
  ui_story_5036_50361602_29_dialog_content = "(그리고 이 노래로 나의 아이돌 생활, 그리고 무대에 작별 인사를 하자.)",
  ui_story_5036_50361602_30_dialog_content = "우로보로스, 널 위해 이 노래를 불러 줄게!",
  ui_story_5036_50361602_31_dialog_content = "♪드넓은 세상에 일렁이는 별의 파도♪",
  ui_story_5036_50361602_32_dialog_content = "♪유성처럼 태어난 우리는 장난스러운 아이처럼♪",
  ui_story_5036_50361602_33_dialog_content = "♪즐겁게 뛰놀지만 고달플 때도 있기 마련이지♪",
  ui_story_5036_50361602_34_dialog_content = "♪따뜻한 보금자리로 이끄는 작은 오두막 속 불빛 하나♪",
  ui_story_5036_50361602_35_dialog_content = "모두 지시에 따라 차례대로 대피하세요!\n섀도우마스터께서 여러분을 안전하게 보호해 드릴 거예요!",
  ui_story_5036_50361602_36_dialog_content = "♪따뜻한 보금자리로 이끄는 작은 오두막 속 불빛 하나♪",
  ui_story_5036_50361602_37_dialog_content = "누나, 들려?",
  ui_story_5036_50361602_38_dialog_content = "어디서 노랫소리가 들려!",
  ui_story_5036_50361602_39_dialog_content = "아가씨, 모든 피난민이 비공정에서 내렸습니다.",
  ui_story_5036_50361602_40_dialog_content = "좋아! 그럼 다른 사람들을 구하러 다시 한번 가 보자!",
  ui_story_5036_50361602_41_dialog_content = "♪따뜻한 보금자리로 이끄는 작은 오두막 속 불빛 하나♪",
  ui_story_5036_50361602_42_dialog_content = "이건... 노랫소리?",
  ui_story_5036_50361602_43_dialog_content = "참 부드럽고 따뜻한 노랫소리네. 저 콜로서스에서 들려오는 걸까?",
  ui_story_5036_50361602_44_dialog_content = "♪이제 곤히 잠들렴 지치고 피곤한 아이야♪",
  ui_story_5036_50361602_45_dialog_content = "♪이 자장가를 읊어 너의 꿈을 지켜 줄게♪",
  ui_story_5036_50361602_46_dialog_content = "♪여기가 바로 너의 고향이야♪",
  ui_story_5036_50361602_47_dialog_content = "츄우─!",
  ui_story_5036_50361602_48_dialog_content = "(우로보로스가 반응하고 있어!)",
  ui_story_5036_50361602_49_dialog_content = "카렌, PlayerName! 우로보로스가 조금 얌전해졌어!",
  ui_story_5036_50361602_50_dialog_content = "좋았어! 노래가 효과가 있나 봐!",
  ui_story_5036_50361602_51_dialog_content = "콜로서스의 흔들림도 멎었어. 이 상태를 유지하면 돼!",
  ui_story_5036_50361602_52_dialog_content = "지금 이 틈에 암귀들의 공습을 반드시 버텨야 해!",
  ui_story_5036_50361602_53_dialog_content = "♪여기가 바로 너의 고향이야♪",
  ui_story_5036_50361602_54_dialog_content = "노랫소리네?",
  ui_story_5036_50361602_55_dialog_content = "이건 콜로서스를 멈추는 멜로디야. 자장가처럼 부드럽고 따뜻하네.",
  ui_story_5036_50361602_56_dialog_content = "골디가 부르고 있는 걸까? 하지만...",
  ui_story_5036_50361602_57_dialog_content = "♪이제는 존재하지 않는 고향♪",
  ui_story_5036_50361602_58_dialog_content = "(샤미나드가 부르고 있는 노랫소리가 들린 것 같아!)",
  ui_story_5036_50361602_59_dialog_content = "(지금 무척 슬퍼하고 있겠지. 게다가 내가 제대로 다독여주지도 않고 떠나 버렸으니까...)",
  ui_story_5036_50361602_60_dialog_content = "(비록 내가 만난 샤미나드는 진짜 샤미나드가 아니라, 꿈속의 환상일 수도 있겠지만.)",
  ui_story_5036_50361602_61_dialog_content = "(그 아이의 슬픔과 외로움만큼은 진짜였어.)",
  ui_story_5036_50361602_62_dialog_content = "(그러니까 네게 이 노래를 바칠게, 샤미나드.)",
  ui_story_5036_50361602_63_dialog_content = "(이 노래가 조금이라도 네 슬픔을 가져가 줄 수 있길 바랄게.)",
  ui_story_5036_50361602_64_dialog_content = "♪이제는 존재하지 않는 고향♪",
  ui_story_5036_50361602_65_dialog_content = "♪하지만 아직 여정에 나선 소년이 있어♪",
  ui_story_5036_50361602_66_dialog_content = "♪눈물이 기나긴 밤을 적시고♪",
  ui_story_5036_50361602_67_dialog_content = "♪기쁨과 슬픔, 만남과 헤어짐을 겪었지만♪",
  ui_story_5036_50361602_68_dialog_content = "♪아직도 희망의 서광을 볼 수 있을까♪",
  ui_story_5036_50361602_69_dialog_content = "♪이 앞에서 그대가 오길 바라는 그 빛♪",
  ui_story_5036_50361602_70_dialog_content = "받아라!",
  ui_story_5036_50361602_71_dialog_content = "대체 얼마나 더 나오려는 거야...!",
  ui_story_5036_50361602_72_dialog_content = "그어어어!",
  ui_story_5036_50361602_73_dialog_content = "조심해, 또 온다!",
  ui_story_5036_50361602_74_dialog_content = "다가오게 두진 않겠어!",
  ui_story_5036_50361602_75_dialog_content = "골디, 이게 바로 네 노래니?",
  ui_story_5036_50361602_76_dialog_content = "꼭 헤븐즈 밸리의 햇빛이랑 바람처럼 따뜻하고 부드럽네.",
  ui_story_5036_50361602_77_dialog_content = "그랬구나... 헤븐즈 밸리는 이미 파괴돼 버렸지만, 사라지진 않았어.\n고향은... 다시 일으켜 세울 수 있어.",
  ui_story_5036_50361602_78_dialog_content = "골디, 네 노래, 나한테 전해졌어.",
  ui_story_5036_50361602_79_dialog_content = "그러니까 나도...",
  ui_story_5036_50361602_80_dialog_content = "♪이제는 눈물을 거둘 시간♪",
  ui_story_5036_50361602_81_dialog_content = "♪눈물을 거두고 다시 날아오를 시간이야♪",
  ui_story_5036_50361602_82_dialog_content = "♪이 노래가 먼 곳으로 이끌어 주겠지♪",
  ui_story_5036_50361602_83_dialog_content = "고마워, 골디.",
  ui_story_5036_50361602_84_dialog_content = "미래에서 온 아이돌, 그럼 우로보로스와 다른 일들은 너한테 맡길게.",
  ui_story_5036_50361602_85_dialog_content = "샤미나드가... 완전히 사라진 것 같아.",
  ui_story_5036_50361602_86_dialog_content = "츄우──",
  ui_story_5036_50361602_87_dialog_content = "우로보로스가 드디어 진정됐어!",
  ui_story_5036_50361602_88_dialog_content = "성공이야! PlayerName 씨의 계획이 성공했어!",
  ui_story_5036_50361602_89_dialog_content = "살았다!",
  ui_story_5036_50361602_90_dialog_content = "이쪽은 더는 못 버텨!",
  ui_story_5036_50361602_91_dialog_content = "으윽!",
  ui_story_5036_50361602_92_dialog_content = "그어어어!",
  ui_story_5036_50361602_93_dialog_content = "받아라!",
  ui_story_5036_50361602_94_dialog_content = "크오... 크오오!",
  ui_story_5036_50361602_95_dialog_content = "대체 얼마나 튼튼한 거야? 공격을 이렇게나 했는데 어떻게 아직 버틸 수 있는 거지?!",
  ui_story_5036_50361602_96_dialog_content = "이 콜로서스에서 지금까지 살아남은 걸 보면, 상대하기 쉬운 녀석은 아닐 거야.",
  ui_story_5036_50361602_97_dialog_content = "우로보로스가 곧 날아오를 거야, 그러니까 조금만 더 버텨!",
  ui_story_5036_50361602_98_dialog_content = "크오오──!",
  ui_story_5036_50361602_99_dialog_content = "카렌! 조심해!",
  ui_story_5036_50361602_100_dialog_content = "츄우!",
  ui_story_5036_50361602_101_dialog_content = "<color=#e8d9bb>퍼억──!</color>",
  ui_story_5036_50361602_102_dialog_content = "크아아!",
  ui_story_5036_50361602_103_dialog_content = "우와?! 방금 그거 뭐였어?!",
  ui_story_5036_50361602_104_dialog_content = "우로보로스가 꼬리로 저 암귀를 날려버렸어!",
  ui_story_5036_50361602_105_dialog_content = "츄우, 츄우~",
  ui_story_5036_50361602_106_dialog_content = "이젠 허둥지둥하지도 않고, 오히려 엄청 기뻐하고 있는 것 같아!",
  ui_story_5036_50361602_107_dialog_content = "정말 다행이야. 저 암귀가 날뛰는 것만 없으면 나머지는 잔챙이라 별문제가 안 돼.",
  ui_story_5036_50361602_108_dialog_content = "얼어붙어라!",
  ui_story_5036_50361602_109_dialog_content = "크오오...",
  ui_story_5036_50361602_110_dialog_content = "츄우─!",
  ui_story_5036_50361602_111_dialog_content = "<color=#e8d9bb>쿠르릉──</color>",
  ui_story_5036_50361602_112_dialog_content = "콜로서스가 또 흔들리는데?!",
  ui_story_5036_50361602_113_dialog_content = "우로보로스는 이제 진정된 거 아니야?",
  ui_story_5036_50361602_114_dialog_content = "꽉 잡아! 우로보로스가 아마 날아오르려는 것 같아!",
  ui_story_5036_50361602_115_dialog_content = "츄우──",
  ui_story_5036_50361602_116_dialog_content = "츄우우!",
  ui_story_5036_50361602_117_dialog_content = "저기 좀 봐! 콜로서스에 있던 용이 날아올랐어!",
  ui_story_5036_50361602_118_dialog_content = "진짜네! 그 언니는 아직 저 콜로서스에 있는 거지? 괜찮을까?",
  ui_story_5036_50361602_119_dialog_content = "그 아이는 대단한 아이돌인걸.",
  ui_story_5036_50361602_120_dialog_content = "어떤 어려움이라도 반드시 극복할 수 있어.",
  ui_story_5036_50361602_121_dialog_content = "그러니까... 그 아이를 믿어 주자.",
  ui_story_5036_50361602_122_dialog_content = "응!",
  ui_story_5036_50361602_123_dialog_content = "저도 언니를 믿을게요!",
  ui_story_5036_50361602_124_dialog_content = "좋아, 그럼 너희 둘도 얼른 다른 사람들이랑 같이 여기서 피하도록 하렴.",
  ui_story_5036_50361602_125_dialog_content = "(저 용이 떠났으니, 이제 다 끝난 건가?)",
  ui_story_5036_50361602_126_dialog_content = "(어서 연락해서 상황을 확인해 봐야겠어.)",
  ui_story_5036_50361602_127_dialog_content = "표류하는 콜로서스에서 철수한 인원 모두 준비된 장소로 이동했어요.",
  ui_story_5036_50361602_128_dialog_content = "몇몇 사람이 찰과상을 입은 것 빼곤 중상자나 사망자는 없었어요!",
  ui_story_5036_50361602_129_dialog_content = "성주님께서 때마침 비공정을 타고 표류하는 콜로서스를 따라\n비행하고 계셔서 정말 다행이었어요.",
  ui_story_5036_50361602_130_dialog_content = "덕분에 백야성에서 발 빠르게 대처해서 부상자를 최소화할 수 있었어요.",
  ui_story_5036_50361602_131_dialog_content = "콜로서스와 용의 상태는 어떻지?",
  ui_story_5036_50361602_132_dialog_content = "용은 이미 콜로서스를 떠났지만, 카렌 언니 일행은 아직 콜로서스에 남아 있어요.",
  ui_story_5036_50361602_133_dialog_content = "......",
  ui_story_5036_50361602_134_dialog_content = "바이스 언니랑 PlayerName도 같이 있으니까, 카렌 언니는 무사할 거예요!",
  ui_story_5036_50361602_135_dialog_content = "비공정 쪽에 전해라. 콜로서스에 있는 사람들의 철수를 계속 지원하도록.",
  ui_story_5036_50361602_136_dialog_content = "네!",
  ui_story_5036_50361602_137_dialog_content = "<color=#e8d9bb>콰르르릉!</color>",
  ui_story_5036_50361602_138_dialog_content = "으앗?!",
  ui_story_5036_50361602_139_dialog_content = "콜로서스가 기울고 있는 것 같은데?!",
  ui_story_5036_50361602_140_dialog_content = "꺄앗?!",
  ui_story_5036_50361602_141_dialog_content = "우로보로스가 날아가서 콜로서스의 무게 중심이 영향을 받았나 봐요!",
  ui_story_5036_50361602_142_dialog_content = "콜로서스가 더 높은 곳을 향해 날아오르기 시작했어요!",
  ui_story_5036_50361602_143_dialog_content = "작전 대성공이네!",
  ui_story_5036_50361602_144_dialog_content = "저희도 서둘러 철수하죠. 여긴 암귀가 너무 많아서\n지금 이 정도 병력으론 대처가 불가능해요!",
  ui_story_5036_50361602_145_dialog_content = "PlayerName 씨!",
  ui_story_5036_50361602_146_dialog_content = "우로보로스가 날아갔어! 우리가 성공한 거야!",
  ui_story_5036_50361602_147_dialog_content = "이걸로 해피 엔딩이네!",
  ui_story_5036_50361602_148_option_content = "샤미나드는?",
  ui_story_5036_50361602_149_dialog_content = "아까 샤미나드가 부르는 것 같은 노랫소리가 들렸어.\n게다가 너랑 같이 노래도 불렀고.",
  ui_story_5036_50361602_150_dialog_content = "지금은 사라져 버린 것 같아...",
  ui_story_5036_50361602_151_dialog_content = "우로보로스랑 같이 떠난 게 아니라, 완전히 사라져 버렸어.",
  ui_story_5036_50361602_152_dialog_content = "그렇구나...",
  ui_story_5036_50361602_153_dialog_content = "응. 그리고 샤미나드가 마지막엔... 앞으로의 일은 나한테 맡기겠다고 했어.",
  ui_story_5036_50361602_154_dialog_content = "아마 샤미나드도 이 노래를 아스트라 대륙의 모든 사람들에게 들려주고 싶은 거겠지.",
  ui_story_5036_50361602_155_option_content = "이제 칸타토르호를 어떻게 하지?",
  ui_story_5036_50361602_156_dialog_content = "이제 아무 일도 없을 거예요.\n하지만 우로보로스가 떠나면서 항로가 조금 틀어지긴 했어요.",
  ui_story_5036_50361602_157_dialog_content = "그래서 이 콜로서스는 더 높은 곳을 향해 날아오를 거예요.",
  ui_story_5036_50361602_158_dialog_content = "PlayerName, 다른 이야기할 시간이 없어.\n일단 서둘러 여기서 철수하자!",
  ui_story_5036_50361602_159_dialog_content = "우로보로스가 날아가 버리면서 칸타토르호의 항로에 변화가 생겼고,\n무게도 가벼워져서 비행 속도도 훨씬 빨라졌어.",
  ui_story_5036_50361602_160_dialog_content = "맞아. 지금 이 속도대로면 앞으로 10분 정도 후에 호흡에 문제가 생길 정도로\n산소가 희박한 곳까지 올라가게 될 거야.",
  ui_story_5036_50361602_161_dialog_content = "그러니까 빨리 여기서 떠나야 해!",
  ui_story_5036_50361602_162_dialog_content = "그럼 칸타토르호는...",
  ui_story_5036_50361602_163_dialog_content = "칸타토르호랑은... 여기서 작별해야 할 것 같아.",
  ui_story_5036_50361602_164_dialog_content = "아무리 그로누 선배라도 이렇게 짧은 시간 안에 칸타토르호의 제어 시스템을\n전부 다 수리하는 건 불가능하니까.",
  ui_story_5036_50361602_165_dialog_content = "그럼 우리가 했던 노력들은? 다 물거품이 되는 거잖아?",
  ui_story_5036_50361602_166_dialog_content = "그렇지 않아!",
  ui_story_5036_50361602_167_dialog_content = "비록 콘서트는 실패해 버렸지만,\n우린 모두에게 칸타토르호에서 열린 이 콘서트를 보여 줬어.",
  ui_story_5036_50361602_168_dialog_content = "그리고 이번 여행을 통해 칸타토르호와 샤미나드의 이야기도 알게 됐어.",
  ui_story_5036_50361602_169_dialog_content = "그러니까 우리가 잊지 않으면, 칸타토르호와 샤미나드는 영원히 존재할 거야.",
  ui_story_5036_50361602_170_dialog_content = "......",
  ui_story_5036_50361602_171_option_content = "가자.",
  ui_story_5036_50361602_172_option_content = "칸타토르호와 샤미나드를 잊지 않을 거야.",
  ui_story_5036_50361602_173_dialog_content = "응!",
  ui_story_5036_50361602_174_dialog_content = "PlayerName, 이제 시간이 없어.",
  ui_story_5036_50361602_175_dialog_content = "돌아가자.",
  ui_story_5036_50361602_176_dialog_content = "응.",
  ui_story_5036_50361602_177_dialog_content = "칸타토르호, 미안해...",
  ui_story_5036_50361602_178_dialog_content = "그리고... 안녕.",
  ui_story_5036_50361701_1_dialog_content = "스카이워커, 기동!",
  ui_story_5036_50361701_2_dialog_content = "<color=#e8d9bb>콰르르릉!</color>",
  ui_story_5036_50361701_3_dialog_content = "칸타토르호가 저 멀리 별들이 있는 곳을 향해 점점 더 높이 날아오르고 있어.",
  ui_story_5036_50361701_4_dialog_content = "별들한테 샤미나드의 노래를 들려주고 싶어서 그러는 거겠지.",
  ui_story_5036_50361701_5_dialog_content = "어쨌든 우리도 이제 안전해졌어.",
  ui_story_5036_50361701_6_dialog_content = "콘서트도 실패하고, 칸타토르호도 지켜주지 못했지만.",
  ui_story_5036_50361701_7_dialog_content = "그래도 모두가 안전하고, 움브라톤 사람들이 더는 두려움에\n떨지 않아도 되니까, 그걸로 됐어.",
  ui_story_5036_50361701_8_dialog_content = "근데 아직도 잘 모르겠어. 우로보로스가 왜 갑자기 부화한 거지?",
  ui_story_5036_50361701_9_dialog_content = "조금만 늦게 부화했더라면, 일이 이렇게 되지 않았을 수도 있는데...",
  ui_story_5036_50361701_10_dialog_content = "PlayerName 씨, 그 부분에 대해선 내가 좀 생각해 봤는데,\n왠지 나 때문인 것 같기도 해.",
  ui_story_5036_50361701_11_dialog_content = "내 꿈속에서... 아니, 정확히 말하면 우로보로스의 꿈속에서 샤미나드를 만났거든.",
  ui_story_5036_50361701_12_dialog_content = "「만났다」고? 그냥 「본」게 아니고?",
  ui_story_5036_50361701_13_dialog_content = "응, 「만났다」가 정확해.",
  ui_story_5036_50361701_14_dialog_content = "샤미나드는 어떤 존재였어?",
  ui_story_5036_50361701_15_dialog_content = "진짜 오래전에 숨을 거둔 사람이 계속 이 세상에\n남아 있을 수 있는 방법 같은 게 있던 거야?",
  ui_story_5036_50361701_16_dialog_content = "그렇다고 하면 조금 소름 돋는데...",
  ui_story_5036_50361701_17_dialog_content = "내가 꿈에서 만난 샤미나드는 어쩌면 우로보로스가 만들어낸 존재였을지도 몰라.",
  ui_story_5036_50361701_18_dialog_content = "어? 그럼 그 샤미나드가 진짜 샤미나드가 아니란 거야?",
  ui_story_5036_50361701_19_dialog_content = "응. 샤미나드가 꿈속에서 이런 말을 했었거든...",
  ui_story_5036_50361701_20_dialog_content = "「우로보로스는 내가 집으로 돌아가고 싶어 한다는 소망을 느끼곤,\n자기 꿈속에 이 헤븐즈 밸리랑 지금 골디가 보고 있는 날 만들었어.」",
  ui_story_5036_50361701_21_dialog_content = "그래서 난 그 꿈속의 헤븐즈 밸리도, 내가 만난 샤미나드도\n전부 다 우로보로스가 만들어 낸 거라고 생각해.",
  ui_story_5036_50361701_22_dialog_content = "우리가 며칠 전에 칸타토르호에서 계속 꿈을 꿨던 것도,\n우로보로스가 정신을 다루는 능력이 있기 때문이기도 하겠지만.",
  ui_story_5036_50361701_23_dialog_content = "아마 우로보로스 스스로가 계속 꿈을 꾸고 있어서이기도 할 거야.",
  ui_story_5036_50361701_24_dialog_content = "그러니까 우린 그 며칠 동안 사실은 같은 꿈을 꾼 게 아니라,\n우로보로스가 꾸는 꿈을 본 거라고 하는 편이 맞을 거야.",
  ui_story_5036_50361701_25_dialog_content = "근데 우로보로스는 왜 그런 꿈을 만든 걸까?",
  ui_story_5036_50361701_26_dialog_content = "그리움과 후회 때문 아닐까...",
  ui_story_5036_50361701_27_dialog_content = "알로 변해 있는 동안에도 우로보로스는 샤미나드가 위험에 빠졌다는 걸 느낄 수 있었어.",
  ui_story_5036_50361701_28_dialog_content = "우로보로스는 위험에 빠진 샤미나드를 돕진 못했지만,\n집으로 돌아가고 싶어 하는 그 아이의 마지막 소망은 느꼈을 거야.",
  ui_story_5036_50361701_29_dialog_content = "그래서 샤미나드가 그리웠던 녀석은 샤미나드가 집으로 돌아가고 싶다는\n소망을 이룬 그런 세계를 만들어 냈겠지.",
  ui_story_5036_50361701_30_dialog_content = "그리고 그 꿈속 세계를 지키기 위해서 계속 눈을 뜨지 않았던 거고.",
  ui_story_5036_50361701_31_dialog_content = "그랬던 거구나, 어쩐지 왜 계속 부화하지 않는 건지 이상했어!",
  ui_story_5036_50361701_32_dialog_content = "근데 계속 그러고 있다가 왜 하필이면 이번에 갑자기 부화한 거야?\n그 이유도 설마 그 꿈이랑 관련이 있어?",
  ui_story_5036_50361701_33_dialog_content = "내가 말실수를 해 버렸거든...",
  ui_story_5036_50361701_34_dialog_content = "나 때문에 샤미나드는 헤븐즈 밸리가 파괴됐다는 걸 알곤 슬픔에 빠져 버렸어.",
  ui_story_5036_50361701_35_dialog_content = "그리고 나서는 꿈속 세상이 붕괴하기 시작했고,\n아무리 애를 써도 원래대로 돌아가지 않았어.",
  ui_story_5036_50361701_36_dialog_content = "난 무너지는 꿈속에서 서둘러 빠져나오느라 샤미나드한테 제대로 사과할 시간도 없었어.",
  ui_story_5036_50361701_37_dialog_content = "하지만 샤미나드는 마지막에 내가 모두에게 아까 그 노래를 들려줬으면 좋겠다고 했어.",
  ui_story_5036_50361701_38_dialog_content = "그러니까 앞으로 다시는 아이돌 생활을 하지 못하게 된다 하더라도,\n난 샤미나드의 부탁을 끝까지 들어 주고 싶어.",
  ui_story_5036_50361701_39_dialog_content = "<color=#e8d9bb>삐비빅──</color>",
  ui_story_5036_50361701_40_dialog_content = "윽! 샤엘 씨가 통신을 보내왔어!",
  ui_story_5036_50361701_41_dialog_content = "어, 어떡하지? 받아야 하나?",
  ui_story_5036_50361701_42_dialog_content = "안 좋은 예감이 드는데~",
  ui_story_5036_50361701_43_dialog_content = "잠깐만, 머리핀을 던져서 받을지 말지 결정해 보자!",
  ui_story_5036_50361701_44_dialog_content = "<color=#e8d9bb>팅──</color>",
  ui_story_5036_50361701_45_dialog_content = "언제나처럼 탄두가 아래쪽이니까, 나쁘지 않은 징조야!",
  ui_story_5036_50361701_46_dialog_content = "그럼 진짜 받는다?",
  ui_story_5036_50361701_47_dialog_content = "얼른 받아 봐, PlayerName 씨.",
  ui_story_5036_50361701_48_dialog_content = "회피하는 건 아무 도움도 안 돼.\n정면에서 마주해야 상황을 뒤집을 기회도 생기는 거야!",
  ui_story_5036_50361701_49_dialog_content = "그럼 받아 볼게...",
  ui_story_5036_50361701_50_dialog_content = "PlayerName?",
  ui_story_5036_50361701_51_dialog_content = "샤엘 씨, 듣고 있어요!",
  ui_story_5036_50361701_52_dialog_content = "다들 지금 어디야? 상황은 어때?",
  ui_story_5036_50361701_53_dialog_content = "저희는 지금 스카이워커호에 있어요. 다 여기 있고, 다친 사람도 없어요.",
  ui_story_5036_50361701_54_dialog_content = "아무도 안 다쳤어? 그거 다행이네. 그럼...",
  ui_story_5036_50361701_55_dialog_content = "골! 디!",
  ui_story_5036_50361701_56_dialog_content = "으앗──!",
  ui_story_5036_50361701_57_dialog_content = "그렇게 자신만만해하던 콘서트가 어쩌다 이 모양이 됐는지,\n제대로 설명해 주지 않을래?",
  ui_story_5036_50361701_58_dialog_content = "그, 그게...",
  ui_story_5036_50361701_59_dialog_content = "죄송해요. 제가 다 망쳤어요...",
  ui_story_5036_50361701_60_dialog_content = "콘서트장을 세심하게 둘러보지 않아서, 콜로서스에 우로보로스의 알이란\n위험 요소가 있다는 사실을 미처 몰랐어요.",
  ui_story_5036_50361701_61_dialog_content = "그리고 우로보로스가 제 노랫소리에 반응해 부화해 버릴 줄도 예상하지 못했구요...",
  ui_story_5036_50361701_62_dialog_content = "에이, 그래도 우리 사정을 좀 더 해명해야 하는 거 아냐?\n우로보로스한테 책임을 떠넘겨 버려도 되잖아~",
  ui_story_5036_50361701_63_dialog_content = "아니, 이 모든 건 다 내 책임이야. 그러니까 책임도 내가 져.\n샤엘 씨, 처음에 맺었던 계약대로 투자금을 배상해 드릴게요.",
  ui_story_5036_50361701_64_dialog_content = "하아... 이번 손실은 정말 말도 아니야.",
  ui_story_5036_50361701_65_dialog_content = "엄청난 돈을 들여서 홍보까지 했는데, 콜로서스가 날아가 버렸으니\n설비 수리 비용이랑 무대 세팅 비용도 다 공중분해됐어.",
  ui_story_5036_50361701_66_dialog_content = "더군다나 공연에 차질이 생기는 바람에 관객들을 잡아 둔다고 쓴\n추가 비용 같은 건 아직 투자금에 포함시키지도 않았어.",
  ui_story_5036_50361701_67_dialog_content = "죄송해요...",
  ui_story_5036_50361701_68_dialog_content = "하지만 걱정하지 마세요. 그 비용들도 전부 다 갚을게요.",
  ui_story_5036_50361701_69_dialog_content = "앞으로 다시는 아이돌을 못 하게 되더라도, 아르바이트랑 다른 일이라도 해서...",
  ui_story_5036_50361701_70_dialog_content = "음? 배상하라는 얘기는 한 적 없는걸?",
  ui_story_5036_50361701_71_dialog_content = "...네?",
  ui_story_5036_50361701_72_dialog_content = "콘서트는 확실히 실패했지만, 홍보 효과는 의외로 굉장히 좋았어!",
  ui_story_5036_50361701_73_dialog_content = "골디의 노래에 담긴 감정들이 우로보로스뿐만 아니라, 모든 관객에게 전해졌거든!",
  ui_story_5036_50361701_74_dialog_content = "아이돌에 전혀 관심이 없던 사람도 이번 일 때문에 골디라는 이름을 알게 됐고.",
  ui_story_5036_50361701_75_dialog_content = "많은 사람이 「아이돌」에 대해 문의해 오기 시작했어!",
  ui_story_5036_50361701_76_dialog_content = "네?!",
  ui_story_5036_50361701_77_dialog_content = "처음에 했던 약속을 완벽하게, 아니 그 이상으로 해내 줬어.",
  ui_story_5036_50361701_78_dialog_content = "제, 제가 잘못 들은 거 아니죠?!",
  ui_story_5036_50361701_79_dialog_content = "못 믿겠어? 그럼 직접 확인해 봐.",
  ui_story_5036_50361701_80_dialog_content = "골디 누나! 내 목소리 들려?",
  ui_story_5036_50361701_81_dialog_content = "너구나! 너희 누나랑 잘 지내고 있니?",
  ui_story_5036_50361701_82_dialog_content = "우린 잘 지내고 있어! 골디 누나! 누나 진짜 대단했어!",
  ui_story_5036_50361701_83_dialog_content = "노래만 잘하는 게 아니라, 그 용도 얌전하게 만들었잖아!",
  ui_story_5036_50361701_84_dialog_content = "다들 골디 누나의 용감한 모습을 봤어. 진짜 진짜 멋있었어!",
  ui_story_5036_50361701_85_dialog_content = "정말? 후훗, 그렇게 말해 주니까 정말 기뻐!",
  ui_story_5036_50361701_86_dialog_content = "그리고 누가 누나한테 하고 싶은 말이 있대!",
  ui_story_5036_50361701_87_dialog_content = "당신이 골디인가요?",
  ui_story_5036_50361701_88_dialog_content = "네, 맞아요. 누구시죠?",
  ui_story_5036_50361701_89_dialog_content = "혹시 제 전속 가수가 될 생각 있나요?",
  ui_story_5036_50361701_90_dialog_content = "네?!",
  ui_story_5036_50361701_91_dialog_content = "당신의 활약상을 모두 봤어요.\n당신은 고결하고 용감하면서 믿을 수 있는 사람이란 생각이 들었죠.",
  ui_story_5036_50361701_92_dialog_content = "제 전속 가수가 돼 주세요!\n제 능력으로 당신이 백야성 최고의 무대에서 노래할 수 있도록 만들어 줄게요!",
  ui_story_5036_50361701_93_dialog_content = "제안은 정말 감사하지만...",
  ui_story_5036_50361701_94_dialog_content = "더 바라는 게 있나요? 그렇다면 다 맞춰 줄 테니 조건을 말해 봐요.",
  ui_story_5036_50361701_95_dialog_content = "조, 조건 쪽에 문제가 있다는 게 아니에요.\n저는 전속 가수보다는 계속 아이돌을 하고 싶어요.",
  ui_story_5036_50361701_96_dialog_content = "아이돌은 청중의 신분에 구애받지 않고 사람들에게\n즐거움과 희망을 줄 수 있으니까요.",
  ui_story_5036_50361701_97_dialog_content = "게다가 전 이미 정말 소중한 아이돌 선배한테 우리 노래를\n모든 사람에게 들려주겠다고 약속도 했어요.",
  ui_story_5036_50361701_98_dialog_content = "그런가요? 그래도 참 아쉽네요...",
  ui_story_5036_50361701_99_dialog_content = "부디 당신의 꿈을 이룰 수 있길 빌어요.\n그리고 다음에 콘서트를 열면 제가 꼭 가서 볼게요.",
  ui_story_5036_50361701_100_dialog_content = "좋게 봐주셔서 감사해요!",
  ui_story_5036_50361701_101_dialog_content = "어때, 이제 믿을 수 있겠지?",
  ui_story_5036_50361701_102_dialog_content = "네! 이젠 속이 시원해졌어요!",
  ui_story_5036_50361701_103_dialog_content = "좋아, 그럼 정신 바짝 차리고 다음 도전을 시작하자.",
  ui_story_5036_50361701_104_dialog_content = "네가 움브라톤에 돌아오면 해야 할 한 달 치 스케줄을 가득 준비해 뒀거든.",
  ui_story_5036_50361701_105_dialog_content = "좋아요, 지금 당장 돌아갈게요!",
  ui_story_5036_50361701_106_dialog_content = "그러고 보니까 굉장한 잠재력을 가지고 있는 비크라는\n신인을 발견했다고 들었는데, 그 사람도 거기 같이 있어?",
  ui_story_5036_50361701_107_dialog_content = "나 불렀어?",
  ui_story_5036_50361701_108_dialog_content = "당신, 우리 공중상회 전속 아이돌이 되지 않을래?",
  ui_story_5036_50361701_109_dialog_content = "뭐? 아하하하, 그건 역시 사양할게!",
  ui_story_5036_50361701_110_dialog_content = "사람들한테 주목받는 삶은 나랑 안 맞더라고.\n난 동물들이랑 같이 지내는 게 더 좋아.",
  ui_story_5036_50361701_111_dialog_content = "정말 안 할 거야?",
  ui_story_5036_50361701_112_dialog_content = "보수도 업계 최고 수준으로 충분히 줄 거고,\n움브라톤에서 생산되는 최고급 샴페인도 제공해 줄 수 있어.",
  ui_story_5036_50361701_113_dialog_content = "듣다 보니까 구미가 당기는걸.\n그렇게 되면 매일 타래들을 돌볼 필요도 없이 그냥 술이나 홀짝거려도...",
  ui_story_5036_50361701_114_dialog_content = "뀨우?!",
  ui_story_5036_50361701_115_dialog_content = "뀨우!!",
  ui_story_5036_50361701_116_dialog_content = "으앗?! 타래? 날 어디로 끌고 가려는 거야? 빨리 풀어 줘! 타래야!",
  ui_story_5036_50361701_117_dialog_content = "동의할 수 없다는 의지를 확실히 표현하고 있네요.",
  ui_story_5036_50361701_118_dialog_content = "어쩔 수 없지. 그럼 이 일은 나중에 다시 얘기하지 뭐.",
  ui_story_5036_50361701_119_dialog_content = "그럼 이따 움브라톤에서 보자.",
  ui_story_5036_50361701_120_dialog_content = "살았어! 정말 다행이야!",
  ui_story_5036_50361701_121_dialog_content = "앞으로도 계속 아이돌을 할 수 있게 됐어!",
  ui_story_5036_50361701_122_dialog_content = "축하해, 골디!",
  ui_story_5036_50361701_123_dialog_content = "이번 콘서트는 여러 가지 우여곡절이 많았지만,\n다음번엔 반드시 순조롭게 콘서트를 치러 내고 말겠어.",
  ui_story_5036_50361701_124_dialog_content = "내가 가장 좋은 자리도 남겨 놔 줄 테니까,\n그때가 되면 잊지 말고 들으러 와 줘야 해, PlayerName 씨!",
  ui_story_5036_50361701_125_dialog_content = "물론이지, 약속할게!",
  ui_story_5036_50361701_126_dialog_content = "그렇지만 시간이 좀 걸릴 수도 있어!",
  ui_story_5036_50361701_127_dialog_content = "돌아가고 나면 우선은 이번 경험을 담은 신곡부터 하나 작성해야 하거든!",
  ui_story_5036_50361701_128_dialog_content = "상황을 보니까 모든 게 다 순조롭게 마무리된 모양이네.",
  ui_story_5036_50361701_129_dialog_content = "그러게. 긴장이 탁 풀리니까 바로 피곤한 느낌이야.",
  ui_story_5036_50361701_130_dialog_content = "저는 벌써부터 졸려요. 하암...",
  ui_story_5036_50361701_131_dialog_content = "흥, 일이 이렇게 많지만 않았다면 진작 뜨거운 물에\n들어가서 목욕이나 하고 있었을 텐데.",
  ui_story_5036_50361701_132_dialog_content = "목욕은 그렇게 큰 문제가 아니야.",
  ui_story_5036_50361701_133_dialog_content = "해도 안 해도 별 차이 없어.",
  ui_story_5036_50361701_134_dialog_content = "그렇지만 칸타토르호에서 좀처럼 보기 힘든 고대 기술을\n볼 수 있어서 나쁘지 않았어!",
  ui_story_5036_50361701_135_dialog_content = "거기서 봤던 스크린이랑 음향 장치들이 너무 재미있어서 영감이 계속 떠올라!",
  ui_story_5036_50361701_136_dialog_content = "지금 당장 그 원리를 연구해서 모방품을 몇 개 만든 다음에 왕좌에 설치해 둘까?",
  ui_story_5036_50361701_137_dialog_content = "설마...",
  ui_story_5036_50361701_138_dialog_content = "그러면 언제 어디서든 게임을 플레이할 수 있잖아!",
  ui_story_5036_50361701_139_dialog_content = "역시나.",
  ui_story_5036_50361701_140_dialog_content = "아무튼 일단 다들 땅에 내려 줄게!",
  ui_story_5036_50361701_141_dialog_content = "<color=#e8d9bb>얼마 후</color>",
  ui_story_5036_50361701_142_dialog_content = "날이 밝으려고 하네, 시간이 이렇게 많이 지났을 줄은 몰랐어.",
  ui_story_5036_50361701_143_dialog_content = "드디어 두 다리로 땅을 밟는구나~ 쉽지 않았어. 내 말 맞지, 타래?",
  ui_story_5036_50361701_144_dialog_content = "뀨!",
  ui_story_5036_50361701_145_dialog_content = "전투는 우리가 다 하고, 비크 씨는 옆에서 보기만 했으면서!",
  ui_story_5036_50361701_146_dialog_content = "그렇게 말하면 섭섭하지~\n나도 우로보로스를 보호하려고 엄청나게 노력했단 말이야~",
  ui_story_5036_50361701_147_dialog_content = "그래. 열심히 한 건 맞으니까 그냥 그렇다고 해 줄게.",
  ui_story_5036_50361701_148_dialog_content = "그럼 난 먼저 가 볼게. 피아랑 시라가 이 사부님이 돌아가서\n우로보로스에 대한 지식을 전수해 주길 기다리고 있거든.",
  ui_story_5036_50361701_149_dialog_content = "그럼 다음에 또 보자.",
  ui_story_5036_50361701_150_dialog_content = "잘 가, 비크 씨.",
  ui_story_5036_50361701_151_dialog_content = "또 저번처럼 납치당하지 않게 조심해서 가!",
  ui_story_5036_50361701_152_dialog_content = "걱정하지 마. 난 믿음직한 어른이니까!",
  ui_story_5036_50361701_153_dialog_content = "우리도 이제 비공정을 타고 백야성으로 돌아가야겠군.",
  ui_story_5036_50361701_154_dialog_content = "(정말이지... 다음번에는 목욕물을 준비해 놓으라고 꼭 미리 연락해 둬야겠어...)",
  ui_story_5036_50361701_155_dialog_content = "너희 레디젤 렌치 녀석들. 다음에 만나면 감옥에 잡아넣어 줄 테니 그렇게 알아라.",
  ui_story_5036_50361701_156_dialog_content = "뭐? 말본새 봐라? 자신 있으면 어디 해 보든가!",
  ui_story_5036_50361701_157_dialog_content = "아이테르, 잘 있어.",
  ui_story_5036_50361701_158_dialog_content = "잘 가!",
  ui_story_5036_50361701_159_dialog_content = "다들 가 버리는 거야? 바니, 우리도 돌아가자!",
  ui_story_5036_50361701_160_dialog_content = "네. 휴가도 이제 끝났으니 돌아가서 일할 시간이네요.",
  ui_story_5036_50361701_161_dialog_content = "그로누 선배, 우리랑 같이 콜로서스 타고 안 갈 거예요?",
  ui_story_5036_50361701_162_dialog_content = "그럴 거 없어~ 나랑 바니는 차 타고 돌아가면 돼.\n그럼 너희도 이제부터 하려던 거 하면 되니까.",
  ui_story_5036_50361701_163_dialog_content = "그리고 차 안에서 바니랑 같이 왕좌에 스크린이랑 게임기를\n설치할 방법에 대해서 같이 연구해 볼 생각이야.",
  ui_story_5036_50361701_164_dialog_content = "네? 방금 뭐라고 하셨죠?!",
  ui_story_5036_50361701_165_dialog_content = "바~니~ 이제 가자.",
  ui_story_5036_50361701_166_dialog_content = "사...살려주세요!",
  ui_story_5036_50361701_167_dialog_content = "시오반 씨처럼 믿음직해 보이는 사람한테도 해결할 수 없는 문제가 있구나.",
  ui_story_5036_50361701_168_dialog_content = "그럼 우리도 돌아가자.",
  ui_story_5036_50361701_169_dialog_content = "응... 가자!",
  ui_story_5036_50361701_170_dialog_content = "결정했어!",
  ui_story_5036_50361701_171_dialog_content = "뭐? 또 무슨 못 미더운 짓을 꾸미려는 거야?",
  ui_story_5036_50361701_172_dialog_content = "이따 돌아가면 대장을 설득해서 트래블러호의 머리 쪽에도\n무대를 하나 만들어 달라고 할래!",
  ui_story_5036_50361701_173_dialog_content = "...뭐야, 제법 괜찮은 생각이잖아?!",
  ui_story_5036_50361701_174_dialog_content = "내가 생각해 낸 거야!\n지금 당장 가서 대장한테 무대를 아이돌 스타일로 개조해 달라고 할 거야!",
  ui_story_5036_50361701_175_dialog_content = "잠깐만! 로큰롤만이 답이라고!",
  ui_story_5036_50361701_176_dialog_content = "저 두 사람은 정말 기운이 넘치네!",
  ui_story_5036_50361701_177_dialog_content = "우리도 여기서 헤어지자, PlayerName 씨.",
  ui_story_5036_50361701_178_dialog_content = "이번에 정말 고생 많았어!",
  ui_story_5036_50361701_179_dialog_content = "골디도 콘서트 준비하랴, 오랜 시간 싸우랴 정말 수고 많았어.\n돌아가면 제대로 푹 쉬어.",
  ui_story_5036_50361701_180_dialog_content = "난 프로 아이돌이라 조금만 쉬어도 금방 기운차게 회복할 수 있어!",
  ui_story_5036_50361701_181_dialog_content = "그럼 내 다음 콘서트를 기대해 줘!",
  ui_story_5036_50361701_182_dialog_content = "응! 그럼 연락 기다릴게!",
  ui_story_5036_50361701_183_dialog_content = "다음에 봐!",
  ui_story_5036_50361701_184_dialog_content = "역시 골디 씨가 폭력을 휘두르는 사람이란 건 헛소문이었어.\n골디 씨의 결백을 증명하기 위해 이번 일을 기사로 써야겠어.",
  ui_story_5036_50361701_185_dialog_content = "여보세요? 편집장님?",
  ui_story_5036_50361701_186_dialog_content = "<size=45>브랜디! 대체 연락이 왜 이렇게 늦은 거냐!</size>",
  ui_story_5036_50361701_187_dialog_content = "내가 만족할 만한 특종 뉴스가 없으면, 바로 와서 네 책상 빼!",
  ui_story_5036_50361701_188_dialog_content = "고, 골디 씨가 폭력을 휘두르는 사람이라는 소문을 조사해 봤더니,\n그건 가짜 뉴스였어요!",
  ui_story_5036_50361701_189_dialog_content = "......",
  ui_story_5036_50361701_190_dialog_content = "콜로서스가 움브라톤을 날아가는 그 오랜 시간 동안 조사한 게 고작 그거냐?",
  ui_story_5036_50361701_191_dialog_content = "그게 가짜 뉴스였다고 해도, 사람들이 그런 뉴스에 눈길이나 주겠어?\n그런 재미없는 기사만 쓰다간 신문사가 망할 거다.",
  ui_story_5036_50361701_192_dialog_content = "브랜디, 너한테 정말 실망했다. 그러니까 넌 내일부터 안 나와도...",
  ui_story_5036_50361701_193_dialog_content = "잠깐만요! 이거 말고도 저한테는 표류하는 콜로서스의 콘서트 사건에\n관한 독점 자료들이 있어요!",
  ui_story_5036_50361701_194_dialog_content = "뭐? 그게 사실이냐? 빨리 가지고 와!",
  ui_story_5036_50361701_195_dialog_content = "가지고 갈 순 있지만, 대신 조건이 있어요.",
  ui_story_5036_50361701_196_dialog_content = "뭔데?",
  ui_story_5036_50361701_197_dialog_content = "골디 씨의 무고함을 밝히는 기사와 콜로서스에 관한 기사를 나란히 실어 주세요!",
  ui_story_5036_50361701_198_dialog_content = "저는 모두가 그 가짜 뉴스 때문에 골디 씨를 오해하고 있다는 사실을 알리고 싶어요!",
  ui_story_5036_50361701_199_dialog_content = "그, 그게 무슨...",
  ui_story_5036_50361701_200_dialog_content = "<size=45>좋아!</size>",
  ui_story_5036_50361701_201_dialog_content = "그렇게 해 줄 테니까, 지금 당장 그 자료들 가지고 와.",
  ui_story_5036_50361701_202_dialog_content = "지금 바로 갈게요!",
  ui_story_5036_50361701_203_dialog_content = "그니까 허접 사부가 동물 쿠키로 드라코리온을 유인해서,\n몰래 표류하는 콜로서스에 탄 다음에 조사를 했는데,\n결국엔 그게 다 물거품이 됐다는 거야?!",
  ui_story_5036_50361701_204_dialog_content = "내가 드라코리온을 얼마나 오래 찾아 다녔는지 알아?\n하마터면 암귀한테 기습까지 당할 뻔했다구!",
  ui_story_5036_50361701_205_dialog_content = "사부, 그래서 어떻게 보상해 줄 거야?",
  ui_story_5036_50361701_206_dialog_content = "에이~ 우로보로스를 철저하게 조사하지 못한 건 맞지만,\n우리가 그 녀석을 깨웠고, 정보도 꽤 많이 얻었다니까~",
  ui_story_5036_50361701_207_dialog_content = "우로보로스의 귀환은 이 아스트라 대륙에 새로운 변화를 가져다줄 거야!",
  ui_story_5036_50361701_208_dialog_content = "사부를 믿어. 이 정보들이 있으면 다음엔 더 쉽게 우로보로스를 찾을 수 있을걸~",
  ui_story_5036_50361701_209_dialog_content = "어디서 많이 들어본 말인데?",
  ui_story_5036_50361701_210_dialog_content = "저번에도 말했잖아.",
  ui_story_5036_50361701_211_dialog_content = "「사부를 믿어. 사부가 다음엔 꼭 큰돈을 벌어 올게.」",
  ui_story_5036_50361701_212_dialog_content = "시라 선배, 선배는 어떻게 그렇게 기억력이 좋아?",
  ui_story_5036_50361701_213_dialog_content = "왜냐하면 저저번에도 똑같은 소릴 했으니까.",
  ui_story_5036_50361701_214_dialog_content = "하지만 지금까지도 재정 상태는 나아지기는커녕, 마이너스를 향해 달리고 있어.",
  ui_story_5036_50361701_215_dialog_content = "그러네. 환상동물의 저번 달 식비도 아직 다 못 냈잖아!",
  ui_story_5036_50361701_216_dialog_content = "흑흑, 둘 다 사부를 그렇게나 쓸모없다고 생각하는 거니?",
  ui_story_5036_50361701_217_dialog_content = "아니면 뭐겠어?",
  ui_story_5036_50361701_218_dialog_content = "이 사부는 너무 슬퍼!",
  ui_story_5036_50361701_219_dialog_content = "설마 다들 내가 차라리 아이돌을 하는 게 낫다고 생각하는 거야?",
  ui_story_5036_50361701_220_dialog_content = "누가 당신한테 박수를 쳐 주는 건 불쌍해서 그러는 거야.\n은혜를 원수로 갚을 생각 마.",
  ui_story_5036_50361701_221_dialog_content = "으윽!",
  ui_story_5036_50361701_222_dialog_content = "근데 이번엔 허접 사부가 드디어 하나 맞혔어.\n우로보로스가 진짜로 그 표류하는 콜로서스에 있었잖아.",
  ui_story_5036_50361701_223_dialog_content = "그걸 어떻게 확신했던 거야?",
  ui_story_5036_50361701_224_dialog_content = "음, 어쩌면 우로보로스한텐 「콜로서스로 간다」는 일이\n일종의 「회귀」일지도 모르거든.",
  ui_story_5036_50361701_225_dialog_content = "「회귀」? 그게 무슨 소리야?",
  ui_story_5036_50361701_226_dialog_content = "그러니까 우로보로스라는 생물은 얼마나 오래 살았든, 몇 번이나 다시 부화했든...",
  ui_story_5036_50361701_227_dialog_content = "가장 처음에는 다른 우로보로스가 낳은 알이었다는 거지.",
  ui_story_5036_50361701_228_dialog_content = "유년기의 동물들은 본능적으로 자기 자신을 보호하고,\n의지할 대상을 찾기 위해 자기 부모를 따르기 마련이야.",
  ui_story_5036_50361701_229_dialog_content = "그건 끊임없는 삶을 반복하면서 차츰 유년기로 회귀하는 우로보로스도 마찬가지고.",
  ui_story_5036_50361701_230_dialog_content = "그렇지만 우로보로스는 너무 희귀해서,\n대부분의 경우에는 자기 원래 부모를 찾지 못하지.",
  ui_story_5036_50361701_231_dialog_content = "그래서 그 녀석들은 자기들이랑 깊은 인연이 있는 콜로서스를 찾을 수밖에 없는 거야.",
  ui_story_5036_50361701_232_dialog_content = "콜로서스를 부모라고 여긴다는 거잖아. 불쌍하네...",
  ui_story_5036_50361701_233_dialog_content = "그럼 사부도 우로보로스랑 혈통상 관계가 있으니까,\n언젠간 콜로서스로 회귀하게 되는 거야?",
  ui_story_5036_50361701_234_dialog_content = "이 사부의 출신은 아직 수수께끼투성이니까, 꼬마 마음대로 추측하면 안 돼요~",
  ui_story_5036_50361701_235_dialog_content = "하긴, 사부는 이렇게 허접하고, 무슨 초능력도 쓸 줄 모르니까\n우로보로스의 혈통을 가지고 있단 것도 그냥 허풍이겠지.",
  ui_story_5036_50361701_236_dialog_content = "그건 진짜야!",
  ui_story_5036_50361701_237_dialog_content = "그게 진짜면 왜 우로보로스가 사부를 안 찾아오는 건데?",
  ui_story_5036_50361701_238_dialog_content = "그것도 좋은 연구 과제가 될 것 같지 않아? 우선 둘 다...",
  ui_story_5036_50361701_239_dialog_content = "츄우─!",
  ui_story_5036_50361701_240_dialog_content = "?!"
}
return config
